window.MM_DATA = {"palette": {"indigo": "#6366f1", "emerald": "#10b981", "fuchsia": "#d946ef", "amber": "#f59e0b", "sky": "#0ea5e9", "rose": "#f43f5e", "violet": "#8b5cf6", "teal": "#14b8a6"}, "order": ["判断推理", "常识应用", "数量关系", "言语理解", "资料分析"], "subjects": {"判断推理": {"color": "indigo", "modules": {"图形推理": "indigo", "定义判断": "emerald", "类比推理": "fuchsia", "逻辑判断": "amber", "科学推理": "sky"}, "root": {"name": "判断推理", "signal": "图形看规律/定义抓要件/类比辨关系/逻辑转会翻译；广东省考有科学推理"}, "branches": [{"name": "图形推理", "star": false, "children": [{"name": "位置类", "star": false, "children": [{"name": "平移", "star": false, "children": [{"name": "方向：锁定移动元素，看上下左右/对角线轨迹", "star": false, "examples": [{"q": "从所给的四个选项中，选择最合适的一个填在问号处，使之呈现一定的规律性（　　）。", "src": "2025广东省考真题 第49题", "hit": true, "ans": "B", "opts": ["A.A", "B.B", "C.C", "D.D"], "solve": "方块平移：**内外两圈各自走**——内圈黑块顺时针移 1 格；外圈两块一左一右各移 1 格 → ==B==。", "analysis": "**识别信号**：图形**元素相同、只有位置变**，问「填问号」、无加减无色变 → 位置类平移。\n**核心规律**：**黑块分内圈/外圈各自平移**——内圈顺时针 1 格、外圈两块一左一右各 1 格，逐图验步长恒定。打法：元素相同→**拆圈层**→逐圈定「方向＋步长」，首图→次图只验一格即锁定。\n**易混·易错链**：最像=**旋转**（整体绕轴、无元素更换；平移是整块位移）｜撞坑链：当整体找规律→越看越乱；内外圈混数；漏看外圈两块反向；拐角「反弹/循环」未定。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/1-15b1fb25c0.png"}]}, {"name": "步长：步长常为恒定/等差/周期循环，逐格验证", "star": false}]}, {"name": "旋转", "star": false, "children": [{"name": "角度：看45°/90°/180°固定角，顺次递增或恒定", "star": false, "examples": [{"q": "下列选项中最符合所给图形规律的是（　　）。", "src": "2025广东省考真题 第48题", "hit": true, "ans": "D", "opts": ["A.A", "B.B", "C.C", "D.D"], "solve": "两组图**同构**：第一组 图1、图2 是同一图形的两种**旋转摆位**，**叠合**后互补拼成图3（两块黑三角落对角）；第二组照此叠合 → ==D==。", "analysis": "**识别信号**：图1、图2 是**同一图形**的两种摆放，问第三个图形 → 旋转/叠合。\n**核心规律**：图1、图2＝同一图形两旋转摆位 → **旋转后叠合/互补**得图3；两组同构套用。打法：同形两摆放→先定**旋转方向/角度**，再定叠合方式，两头都对才秒杀。\n**易混·易错链**：最像=**翻转**（产生镜像，旋转不产生）｜撞坑链：旋转误判成翻转；只转不拼/拼错叠合方式；逐角度硬算费时。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/2-157bf67fbe.jpg"}]}, {"name": "方向：先定转动方向再看角度，方向判定错则全错", "star": false}]}, {"name": "翻转", "star": false, "children": [{"name": "左右/上下翻转会产生镜像（如\"P\"变\"q\"），旋转不产生镜像", "star": false}]}]}, {"name": "样式类", "star": false, "children": [{"name": "遍历", "star": false, "children": [{"name": "每行/每列元素集合相同，缺啥补啥", "star": false}]}, {"name": "求同", "star": false, "children": [{"name": "去异存同，只保留两图共有的线与形", "star": false, "examples": [{"q": "下列选项中最符合所给图形规律的是（　　）。", "src": "2025广东省考真题 第47题", "hit": false, "ans": "D", "opts": ["A.A", "B.B", "C.C", "D.D"], "solve": "求同去异：取两图**公共部分**——图1（圆＋十字）与图2（菱形＋内十字）公共的只有中间==横线＋向上竖线==，外框圆/菱形都不公共→去掉，得 ==D==。", "analysis": "**识别信号**：两图**元素相似/有重叠线与形**，问叠加结果 → 样式类。\n**核心规律**：两图叠加，**只留两图都有的线/形**；各自独创的外框（圆、菱形）一律去掉。打法：样式题逐条线问「两图都有吗？」，都有才留（**先对齐叠加再取同**）。\n**易混·易错链**：最像=**求异**（去同存异）｜撞坑链：把「都有外框」当共性→外框全留（误选 B）；忘了先对齐再取同。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/3-69515e405c.jpg"}]}]}, {"name": "求异", "star": false, "children": [{"name": "去同存异，只保留两图不同的部分", "star": false}]}, {"name": "黑白运算", "star": false, "children": [{"name": "先由已给格归纳运算表（黑+黑/黑+白/白+白各得什么），再套用", "star": false}]}]}, {"name": "属性类", "star": false, "children": [{"name": "轴对称", "star": false, "children": [{"name": "数对称轴条数与方向，或判是否轴对称", "star": false}]}, {"name": "中心对称", "star": false, "children": [{"name": "图形旋转180°后与原图重合即中心对称", "star": false}]}, {"name": "对称轴关系", "star": false, "children": [{"name": "看两轴平行/垂直/成夹角，角度常成规律", "star": false}]}, {"name": "曲直性", "star": false, "children": [{"name": "判全直线/全曲线/曲直混合是否成规律", "star": false}]}, {"name": "开闭性", "star": false, "children": [{"name": "判开放(有缺口)/封闭(无缺口)是否成规律", "star": false}]}]}, {"name": "数量类·点线角面素", "star": false, "children": [{"name": "点", "star": false, "children": [{"name": "交点：数线条交叉点，常呈等差/递增", "star": false}, {"name": "端点：数线段尽头端点，注意与交点区分", "star": false}]}, {"name": "线", "star": false, "children": [{"name": "直线数：只数直线段条数，勿混入曲线", "star": false}, {"name": "曲线数：只数曲线条数，注意一段平滑曲线算 1", "star": false}, {"name": "笔画数：数奇点(引出奇数条线)，0 或 2 个奇点→一笔画", "star": false}, {"name": "曲直关系：比较直线数 vs 曲线数（差/和/倍数）", "star": false}]}, {"name": "角", "star": false, "children": [{"name": "直角数：数90°角个数，注意拐点处直角", "star": false}, {"name": "锐角/钝角数：分别数锐角与钝角，勿含直角", "star": false}]}, {"name": "面", "star": false, "children": [{"name": "封闭区域数：数封闭空间；开放折线计 0，带缺口/缺角多边形算 1", "star": false}, {"name": "区域面积比：比各封闭区域面积比例（如 1:1、1:2）", "star": false}]}, {"name": "素", "star": false, "children": [{"name": "元素个数：数小图形个数总数", "star": false, "examples": [{"q": "下列选项中最符合所给图形规律的是（ ）。", "src": "2026广东省考真题 第46题", "hit": false, "ans": "A", "opts": ["A", "B", "C", "D"], "solve": "数射线（带箭头线段）条数：3→4→5→6→(7) 等差递增；A/C 均为 7 条，再用「射线不交叉」排除 C。选 A。坑：B/D 是 8 条，别多数。", "analysis": "**识别信号**：图形**零散/元素不同**、数不清形状，问规律 → 数量类。\n**核心规律**：**数射线（带箭头线段）条数**＝3→4→5→6→(7) 等差递增；A/C 均 7 条，再用「射线不交叉」排除 C 定 A。打法：数量类先分流（点线角面素）→本题数「素/线」个数→**等差递增**求下一项；同值项用二级特征排除。\n**易混·易错链**：最像=**线**（直线/曲线条数）｜撞坑链：B/D 是 8 条别多数；忽略「射线不交叉」这层二级排除。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/4-a6c066fdfa.jpg"}]}, {"name": "元素种类：数不同种类数（同形算一种）", "star": false}, {"name": "部分数：数互不相连的部分（连在一起算 1 部分）", "star": false}]}]}, {"name": "立体 / 题型技巧", "star": false, "children": [{"name": "六面体", "star": false, "children": [{"name": "相对面：展开图中同行隔一个/同列隔一个、Z字两端为相对面，二者不能同现", "star": false}, {"name": "相邻面：按公共顶点/公共边定向，判断相邻面方位箭头是否一致", "star": false, "examples": [{"q": "下列选项中，可以由给定平面图折叠而成的是（ ）。", "src": "2026广东省考真题 第50题", "hit": false, "ans": "D", "opts": ["A", "B", "C", "D"], "solve": "六面体折叠·相邻面定向：三面汇于同一公共顶点，比对展开图与立体图中图案的相对方位（朝向/箭头）是否一致，方位不符即排除。答案 D。", "analysis": "**识别信号**：给**平面展开图**问「能折成哪个立体」 → 折叠题。\n**核心规律**：三面汇于同一**公共顶点**，比对展开图与立体图中图案的**相对方位（朝向/箭头）**，方位不符即排除（答案 D）。打法：折叠题→先找公共顶点/公共边→按方位箭头逐面定向，错一个即排。\n**易混·易错链**：最像=**相对面**（同行/列隔一个、Z字两端，二者不能同现）｜撞坑链：只看面图案不看朝向；忽略箭头/指向的方位一致性。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/5-eafcb6afc7.png"}]}, {"name": "展开图类型：识别141/231/222/33型，排除\"田字/凹字\"型", "star": false}]}, {"name": "截面图", "star": false, "children": [{"name": "由切割面与几何体的交线推截面，逐个排除不可能", "star": false, "examples": [{"q": "左边为给定的多面体，现用经P、Q、R三个顶点的平面对其进行切割，问哪个选项是其切面？", "src": "26年省考34季 第49题", "hit": true, "ans": "C", "opts": ["A.A", "B.B", "C.C", "D.D"], "solve": "截面只由「切割平面与多面体各面的交线」围成——三点定平面后，看这平面切过哪几条棱、轮廓走向与哪一项吻合，不合的立排。", "analysis": "- 体系定位：判断推理 → 图形推理 → 立体 / 题型技巧 → 截面图（清单原名「截面图」）；上位＝立体图形类，本题＝过三点的平面切割求截面，下级变式＝三视图、六面体折叠、立体拼合。\n- 识别信号：题干出现「多面体 / 平面切割 / 哪个是切面 / 截面」→ 立刻切「截面图」，抓「三点定面 + 交线定形」。\n- 本质：一句话——截面形状 = **切割平面与几何体所有表面的交线围成的封闭多边形**，截面顶点必落在几何体的棱（或顶点）上（原判分点：由切割面与几何体的交线推截面，逐个排除不可能）。\n- 通式：截面 = { 平面 ∩ 各面 } 的边集合，顶点 ∈ 棱；三点定面后「找交点 → 连轮廓 → 对选项」三步走；无固定公式，按「交线定形 + 排除」思路。\n- 易混·易错链：最像的是「三视图」（正投影规则 vs 斜截交线）；撞坑链：三点共线却当成能定面 → 混淆「截面」与「投影」→ 只看轮廓不看顶点是否在棱上 → 被「凹凸相同但边数不符」的选项骗。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/1-ba67e41177.png"}]}]}, {"name": "三视图", "star": false, "children": [{"name": "按正投影规则从三个方向看，注意被挡的线", "star": false, "examples": [{"q": "如图所示，四棱锥的底面为矩形，其中一条棱垂直于底面，那么该四棱锥的俯视图最有可能是（　　）。", "src": "2025广东省考真题 第46题", "hit": true, "ans": "C", "opts": ["A.A", "B.B", "C.C", "D.D"], "solve": "俯视＝正投影：一条侧棱垂直底面 → 只看该棱下影点与底面矩形轮廓，选 ==C==。", "analysis": "**识别信号**：给立体图问俯视/正视/侧视 → 三视图。\n**核心规律**：俯视＝从上往下**正投影**；**垂直底面的侧棱在俯视图里收缩为一点/重合线**，认住它即锁定（C）。打法：三视图三步——定视向→各顶点正投影落底→连可见棱、辨虚实。\n**易混·易错链**：最像=**截面图**（切面）｜撞坑链：当立体透视图画→多出斜线；忽略垂棱投影重合→虚实线判错。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/6-6cc867ce09.jpg"}, {"q": "下图为给定的立体图形，从任一角度看，下列选项最不可能是该立体图形视图的是（ ）。", "src": "2024广东省考真题 第49题", "hit": false, "ans": "C", "opts": ["A.A", "B.B", "C.C", "D.D"], "solve": "三视图题按**正投影**从主/左/俯逐项还原轮廓与可见棱线，四选项只有 **C** 与任一方向的投影都对不上，故 C。", "analysis": "- 体系定位：判断推理 → 图形推理 → 立体 / 题型技巧 → 三视图（清单原名：**三视图**）；体系位置：上位＝立体类图形推理，本题＝三视图（正投影判读），下级变式＝主/左/俯视图互换、与截面图对比。\n- 识别信号：题干出现\"**立体图形** + 从某一/任一**角度**看 / **视图** / 主视图 / 俯视图\" → 先做三视图（正投影），不要当成透视图想象。\n- 本质：内核＝**正投影**——把一个方向上的所有点投到一个平面上，只保留外轮廓与\"看得见的棱线\"，被挡的线不画；判分点＝按**正投影**规则从三个方向看，注意被挡的线。\n- 通式：无固定式，按\"**定方向 → 正投影还原轮廓 → 逐项比对棱线**\"三步走；口诀\"投影看轮廓，遮挡不出线\"。\n- 易混·易错链：最像的是**截面图**——截面图是\"切一刀看断面\"，三视图是\"从一个方向看投影\"（\"看\"→投影，\"切\"→截面）；常见撞坑链：把视图当透视图（多画被挡线）→ 漏画/多画棱线 → 选错。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/2-1735c13ac8.png"}]}]}, {"name": "分组分类", "star": false, "children": [{"name": "答案须同时解释两组，先找共同点再验证另一组反向成立", "star": false}]}, {"name": "元素组成入口", "star": false, "children": [{"name": "元素相同→位置；相似→样式；不同→属性→数量，按此分流", "star": false}]}, {"name": "属性优先", "star": false, "children": [{"name": "属性(对称/曲直/开闭)判断快、抗干扰，优先于数量；数不清就回属性", "star": false}]}, {"name": "立体拼合", "star": false, "children": [{"name": "补形法：定正方体棱长→数图1/图2 的方块数与位置→算缺口（个数＋形状），选项须能旋转嵌入", "star": false, "examples": [{"q": "下列选项中，最有可能与所给的两个不规则立体图形形成正方体的是（　　）。", "src": "2025广东省考真题 第50题", "hit": true, "ans": "C", "opts": ["A.A", "B.B", "C.C", "D.D"], "solve": "**补形法**：先定目标正方体棱长 → 数图1、图2 的方块数与占位 → 算**缺几个、缺口什么形状** → 选项方块数吻合且能旋转嵌入者即 ==C==。", "analysis": "**识别信号**：给**两个不规则立体**问「补成正方体」 → 立体拼合。\n**核心规律**：**体积（单位块数）守恒 ＋ 形状互补** 双条件——缺口＝目标体积−两图块体积，凹凸须互补。打法：立体重构先「数」再「比」——读目标体积→数两块→缺口＝差→扫选项挑形状吻合且能旋转嵌入者。\n**易混·易错链**：最像=**展开图**（2D↔3D折叠，涉面朝向）｜撞坑链：只看长相不数块；把缺口当凸块（漏互补）；漏算两块自身重叠/留空。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/7-c7a7ef5d83.jpg"}]}]}]}]}, {"name": "定义判断", "star": false, "children": [{"name": "主体/客体要件", "star": false, "children": [{"name": "抓主体(谁做)与客体(对谁做)，错一个即不符", "star": false}]}, {"name": "行为/目的要件", "star": false, "children": [{"name": "抓方式状语(怎么做)与目的(为何做)，须齐全", "star": false}]}, {"name": "结果/条件要件", "star": false, "children": [{"name": "抓结果与前提条件，缺要件即不符", "star": false}]}, {"name": "要件齐全法", "star": false, "children": [{"name": "逐条列定义要点，选项须全部满足才算符合", "star": false}]}, {"name": "主体偷换陷阱", "star": false, "children": [{"name": "警惕选项把定义主体换成另一个对象（看似相关实为张冠李戴）", "star": false}]}, {"name": "定语忽略陷阱", "star": false, "children": [{"name": "注意定义中的限定语(如\"以营利为目的\")，勿漏", "star": false}]}, {"name": "范围扩大/缩小", "star": false, "children": [{"name": "核对选项是否把定义范围放大或缩小以凑合", "star": false}]}, {"name": "多定义慎防混淆", "star": false, "children": [{"name": "一问对应一指定定义，勿拿另一并列定义判断", "star": false}]}]}, {"name": "类比推理", "star": false, "children": [{"name": "近义/反义关系", "star": false, "children": [{"name": "判是否近义或反义，再看词性色彩是否一致", "star": false}]}, {"name": "种属关系", "star": false, "children": [{"name": "判是否A是B的一种（种属），注意与组成区分", "star": false}]}, {"name": "组成关系", "star": false, "children": [{"name": "判是否A是B的一部分（部分-整体）", "star": false}]}, {"name": "并列关系", "star": false, "children": [{"name": "判矛盾(非此即彼)还是反对(还有第三)并列", "star": false}]}, {"name": "交叉关系", "star": false, "children": [{"name": "判两类是否部分重合（有的A是B，有的B是A）", "star": false}]}, {"name": "因果关系", "star": false, "children": [{"name": "判A导致B，注意因果不可倒置", "star": false}]}, {"name": "条件关系", "star": false, "children": [{"name": "判充分必要（有A必有B；无A必无B）", "star": false}]}, {"name": "目的关系", "star": false, "children": [{"name": "判A是为了B（如\"锻炼：健康\"）", "star": false}]}, {"name": "对应关系", "star": false, "children": [{"name": "判材料/功能/属性/场所/人物/工具对应，取同一细分类型", "star": false}]}, {"name": "语法关系", "star": false, "children": [{"name": "判主谓/动宾/偏正结构，词性与语序须一致", "star": false}]}, {"name": "造句法", "star": false, "children": [{"name": "把题干词串成一句通顺话，代入选项须同样通顺", "star": false}]}]}, {"name": "逻辑判断", "star": false, "children": [{"name": "翻译推理", "star": false, "children": [{"name": "充分条件翻译", "star": false, "children": [{"name": "\"如果A那么B\"→A→B（前推后）；\"只要…就\"同", "star": false}]}, {"name": "必要条件翻译", "star": false, "children": [{"name": "\"只有A才B\"→B→A（后推前）；\"除非A否则B\"→非A→B", "star": false}]}, {"name": "且/或翻译", "star": false, "children": [{"name": "\"且\"为全真才真；\"或\"为一真即真，据词义转成逻辑符号", "star": false}]}, {"name": "逆否等价", "star": false, "children": [{"name": "\"A→B\"等价于\"非B→非A\"，只此一形等价", "star": false, "examples": [{"q": "建设社会主义现代化强国，关键在于科技自立自强。只有加强科技创新、推进科技自立自强，才能在大变局中把握主动而行稳致远。只要加强科技创新、推进科技自立自强，就能在未来发展中抓住先机和占领制高点。要想实现科技自立自强，就必须深入实施创新驱动发展战略。由此可以推出：", "src": "26年省考35季 第53题", "hit": false, "ans": "A", "opts": ["A.只有未能在大变局中把握主动而行稳致远，才会在未来发展中错失先机", "B.除非没有加强科技创新，否则会在大变局中把握主动而行稳致远", "C.如果想建设社会主义现代化强国，就要实现科技自立自强和在未来发展中占领制高点", "D.要想深入实施创新驱动发展战略，就必须加强科技创新、推进科技自立自强"], "solve": "三句先翻成箭头链 **M→S→P**（M＝把握主动行稳致远，S＝科技自立自强，P＝抓住先机占领制高点），再整体**逆否**得 ==¬P→¬M==，A「只有未把握主动，才会错失先机」正是此式。", "analysis": "- 体系定位：判断推理 → 逻辑判断 → 翻译推理 → 逆否等价（上位：假言命题翻译 → 本题：多句串链后整体逆否 → 下级变式：加入「且/或」的德摩根逆否）\n- 识别信号：题干出现「只有…才…」「只要…就…」「必须/要想…就…」→ 先全翻成箭头，串成链再逆否\n- 本质：考**条件句只能「肯前推肯后、否后推否前」**；答案必与箭头链同向或整体逆否\n- 通式：`只有A才B ⇒ B→A`；`只要A就B ⇒ A→B`；多条时串链 `X→…→Y`，逆否 `¬Y→¬X`；同类判别条件：看到「只有/除非/只要」就翻箭头再谈逆否\n- 易混·易错链：与「充分/必要」区分——必要（只有…才）是**后推前**、充分（只要/如果）是**前推后**；常见撞坑：把「肯后」当「肯前」（B）、把箭头写反（D）", "img": ""}]}]}, {"name": "德摩根定律", "star": false, "children": [{"name": "\"非(A且B)=非A或非B\"；\"非(A或B)=非A且非B\"", "star": false}]}, {"name": "选言命题", "star": false, "children": [{"name": "\"或者…或者\"相容（可都真）；\"要么…要么\"不相容（一真一假）", "star": false, "examples": [{"q": "近日，某省文旅部发布乡村文旅示范村落名单，全省共选出优质示范村落若干，涵盖农耕体验、民俗非遗、康养休闲、研学实践、露营度假五大类特色业态。某市有多座村落成功上榜，关于该市上榜村落对应的业态分布，已知：（1）农耕体验类村落和民俗非遗类村落至多有一类上榜；（2）露营度假类村落和研学实践类村落至少有一类上榜；（3）若民俗非遗类村落上榜，则康养休闲类村落上榜；（4）研学实践类村落和民俗非遗类村落至少有一类上榜。根据上述信息，可以推出以下哪项？", "src": "26年省考34季 第60题", "hit": false, "ans": "A", "opts": ["A.康养休闲类村落和研学实践类村落至少有一类上榜", "B.露营度假类村落和研学实践类村落至多有一类上榜", "C.康养休闲类村落一定上榜", "D.民俗非遗类村落、康养休闲类村落、露营度假类村落至少有一类上榜"], "solve": "由「研学或民俗至少一」（(4)）与「民俗→康养」（(3)）做**二难推理**，直接得 `研学∨康养`，即 ==A==。", "analysis": "- 体系定位：判断推理 → 逻辑判断 → 翻译推理 → 选言命题（清单原名「选言命题」）；上位＝形式逻辑翻译，本题＝「至多/至少 + 假言」复合推理，下级变式＝逆否等价、德摩根、递推。\n- 识别信号：题干出现「至多有一类 / 至少有一类 / 若…则…」并问「可以推出」→ 先翻译成 `∨ / →`，再用二难、逆否、递推串联。\n- 本质：一句话——把日常「至少/至多/如果」**翻译成符号**后做机械推理；「A 不成立则另一支必成立」是选言与假言联动的内核（原判分点：相容/不相容选择，据词义转成逻辑符号）。\n- 通式：至多一 ＝ `¬(A∧B)`（等价 `A→¬B`）；至少一 ＝ `A∨B`；二难式 `(A∨B)∧(B→C) ⟹ A∨C`；`A→B` 等价 `¬B→¬A`。\n- 易混·易错链：最像的是「逆否等价」（考等价 vs 本题考推出）；撞坑链：把「至少一」误读成「两者都真」→ 忽略二难、逐个假设硬试太慢 → 被 C 的「一定」拔高程度带偏。", "img": ""}]}]}, {"name": "递推", "star": false, "children": [{"name": "A→B 且 B→C ⟹ A→C，箭头方向首尾相接才可串", "star": false}]}]}, {"name": "真假 / 分析推理", "star": false, "children": [{"name": "矛盾关系", "star": false, "children": [{"name": "\"所有是\"与\"有的非\"、\"A→B\"与\"A且非B\"必一真一假", "star": false}]}, {"name": "反对关系", "star": false, "children": [{"name": "两个\"所有/都\"必有一假（可同假），据此推范围", "star": false}]}, {"name": "下反对关系", "star": false, "children": [{"name": "两个\"有的/有些\"必有一真（可同真）", "star": false}]}, {"name": "假设法", "star": false, "children": [{"name": "假设某句为真代回验证，矛盾则该假设为假，反之成立", "star": false, "examples": [{"q": "研究所计划从7名在读研究生中，推选2名男生、2名女生到企业实习。已知：（1）赵、钱、孙是男生；（2）李、刘、王、吴是女生；（3）如果推选刘、吴其中一人，那么孙也会被推选。根据上述陈述，可以得知（ ）。", "src": "2025广东省考真题 第53题", "hit": false, "ans": "B", "opts": ["A.赵、李中至少有1人被推选", "B.孙、王中至少有1人被推选", "C.钱、王中至少有1人被推选", "D.孙、刘中至少有1人被推选"], "solve": "反证：假设**孙、王都没选** → 男只能{赵,钱}；女从{李,刘,吴}取2**必含刘/吴** → 与(3)逆否\"没选孙→刘吴都不能选\"矛盾 ⇒ ==B 必真==。", "analysis": "**识别信号**：多条件＋「可以得知」（必然为真），含「如果…那么」＋数量约束 → 假设法。\n**核心规律**：①(刘∨吴)→孙，逆否＝**非孙→非刘∧非吴**；②抓「恰好 2 男 2 女」对选项**反证**；③其余项各给一条可行反例秒排。打法：条件＋定量混合题→抓「没选/边界」的逆否＋对恒真项反证（整句否定→推出矛盾→该句必真）。\n**易混·易错链**：最像=**翻译推理**（充分/必要方向不可倒，刘→孙≠孙→刘）｜撞坑链：把(3)方向读反→误选 D；只看逻辑不看 2 男 2 女→无从反证；逐项找反例比反证慢。", "img": ""}, {"q": "小陈计划假期前往某市旅游，他的设想如下：①欢乐世界，动物园至少会去一个；②艺术中心，欢乐世界和人民公园至少会去一个；③动物园，人民公园和博物馆至少会去两个；④如果去动物园，则不去艺术中心。根据上述设想，可以得出小陈（ ）。", "src": "2025广东省考真题 第64题", "hit": false, "ans": "C", "opts": ["A.一定会去博物馆", "B.动物园，艺术中心至少会去一个", "C.人民公园，欢乐世界至少会去一个", "D.至少会去3个景点"], "solve": "假设『人民公园、欢乐世界都不去』→①逼出去动物园、④逼出不去艺术中心、②全部落空 → 矛盾；故 R∨H 必真，锁 C。", "analysis": "**识别信号**：「至少一个/至少两个/如果…则」混排＋「可以得出」 → 假设法。\n**核心规律**：先符号化①H∨Z｜②A∨H∨R｜③Z+R+B≥2｜④Z→¬A（Z、A 互斥＝突破口）；对选项反面假设「¬R∧¬H」→①⇒Z、④⇒¬A、②全假→**矛盾**⇒ R∨H 必真。打法：见「至少…／如果…则」混排→先全部符号化，抓**否定式条件**当突破口，再用**反例**验「一定／至少」类选项。\n**易混·易错链**：最像=**翻译推理·且/或翻译**（只形式等价改写，不叠数量约束）｜撞坑链：不符号化凭语感；找到「某一组可行解」就当「必然」；被④绊住不敢反面假设。", "img": ""}]}]}, {"name": "排除法", "star": false, "children": [{"name": "用条件逐项划掉不可能项，剩者为真", "star": false}]}, {"name": "最大信息法", "star": false, "children": [{"name": "从出现次数最多的信息切入破题", "star": false, "examples": [{"q": "某次「特色示范村」评选活动设立了文化旅游、非遗传承、生态农业、数字农业示范村4个奖项，甲、乙、丙、丁4个村庄各获其中之一。已知：①文化旅游示范村的经济收入高于丙村；②甲村和数字农业示范村的经济收入相当，且都不是最高的；③生态农业示范村的经济收入比丁村高；④丙村的经济收入高于非遗传承示范村。根据上述条件，下列选项必然正确的是（ ）。", "src": "2026广东省考真题 第63题", "hit": false, "ans": "B", "opts": ["A.甲村的经济收入在4个村庄中位列第二", "B.乙村获评文化旅游示范村", "C.丙村获评数字农业示范村", "D.丁村获评非遗传承示范村"], "solve": "元素对应：先锁唯一确定值——甲乙丙丁皆非最高→乙必最高；再用不等式链+双射逐项排除，只认所有合法解都成立的项（B 必然、D 只是可能）。", "analysis": "**识别信号**：多对象↔多属性一一对应＋不等式链，问「必然正确」 → 元素对应。\n**核心规律**：先锁**唯一「最高收入者」**（甲/数村非最高、丙被文村压、丁被生态村压→只剩乙），再用不等式链＋双射逐项扫；问「必然」＝所有合法解都成立的项。打法：多条件元素对应→先找**唯一确定值**，锁定后用其排除其余；选项只认「所有解都成立」。\n**易混·易错链**：最像=**最大信息法**（信息最集中处切入）｜撞坑链：把「不是最高」误读成「第二/偏低」（A）；把「可能成立」当必然（C/D）；忽略**双射**（等收入的甲与数村不能是同一主体）。", "img": ""}, {"q": "在一次技能竞赛中，甲、乙、丙、丁4人排名前四且无人并列，已知甲和第三名是好友且名次比该好友高；丁和甲不是好友但和第一名是好友；乙的名次比丙高。根据上述信息，以下判断错误的是（ ）。", "src": "2025广东省考真题 第59题", "hit": true, "ans": "D", "opts": ["A.丙的名次不高于第三名", "B.甲的名次一定高于丙", "C.乙和丁是好友", "D.乙不可能是第一名"], "solve": "唯一解＝1乙·2甲·3丙·4丁（甲被两条夹击先定锚）→ 乙**恰是第一名** → ==D 错==。", "analysis": "**识别信号**：排名/名次唯一＋「以下判断错误的是」 → 分析推理。\n**核心规律**：唯一解＝1乙·2甲·3丙·4丁（甲被两条条件夹击先定锚）→ 乙**恰是第一名** → D 错。打法：先抓**约束最强的对象**定锚（甲被两条条件夹击→先卡甲）→滚动排除→**回代验证唯一解**。\n**易混·易错链**：最像=**真假推理**（看命题真假，本题看唯一解）｜撞坑链：把「未锁定」当「已排除」；把「比…高」读反（名次数字越小越高）；没圈出设问的「错/对/不能推出」。", "img": ""}, {"q": "甲、乙、丙、丁4人每人都会演奏钢琴、小提琴、二胡和古筝4种乐器中的2种，且每种乐器都有2人会演奏。已知：①甲不会演奏钢琴；②丁不会演奏古筝；③丙不会演奏钢琴和小提琴；④乙和丙会演奏的乐器中有且仅有1种相同。由此可以推出（ ）。", "src": "2024广东省考真题 第58题", "hit": false, "ans": "A", "opts": ["A.甲会演奏小提琴", "B.甲不会演奏二胡", "C.乙会演奏古筝", "D.甲和丁会演奏的乐器完全不同"], "solve": "先由丙推出 =={二胡,古筝}==、钢琴必归 **乙丁**，再对乙分类讨论，两种情形下甲都含小提琴，锁定 **A**。", "analysis": "- 体系定位：判断推理 → 逻辑判断 → 真假 / 分析推理 → 最大信息法（清单原名：**最大信息法**）；体系位置：上位＝逻辑判断，本题＝元素对应型分析推理，下级变式＝真假话、多人多物匹配。\n- 识别信号：题干给**多对象 + 多属性 + 数量约束**（\"每人…2 种\"\"每种…2 人\"）＋若干\"不会 / 不\" → 先找**确定信息**与**数量约束**，用最大信息法切入。\n- 本质：内核＝在多重约束下做**枚举 / 消解**，靠\"数量平衡（每种恰好 2 人）\"把自由度压到最小；判分点＝从**出现次数最多的信息**切入破题。\n- 通式：无固定式，按\"**确定信息 → 数量约束 → 分类讨论 → 代入选项**\"四步走；数量约束优先于逐句推理。\n- 易混·易错链：最像的是**真假话（矛盾关系）**——真假话围绕\"谁真谁假\"，本题围绕\"谁对应什么\"（元素对应）；撞坑链：漏用\"每种恰 2 人\"的数量约束 → 情形不全 → 误选 B/C。", "img": ""}]}]}, {"name": "列表法", "star": false, "children": [{"name": "画行列对应表，用√/×标出确定与否定关系", "star": false}]}, {"name": "一拖五材料题", "star": false, "children": [{"name": "先通读全部条件建约束，再逐问代入，勿孤立作答", "star": false}]}]}, {"name": "加强 / 削弱 / 前提", "star": false, "children": [{"name": "加强", "star": false, "children": [{"name": "搭桥：在论据与论点之间架桥（补充二者隐含联系）即为强加强", "star": false, "examples": [{"q": "研究团队开发了一种新型抗衰老水凝胶材料，为了验证这一材料的实际效果，研究团队开展了系列实验。结果发现，与未注入该材料的实验鼠相比，注入该材料的实验鼠肌肉组织中细胞的代谢水平显著提高，细胞端粒长度平均延长15%，且肌肉再生能力提升40%。由此可以推断，该材料能在一定程度上抗衰老。以下选项如果为真，最不能支持这一结论的是（ ）。", "src": "2026广东省考真题 第60题", "hit": false, "ans": "C", "opts": ["A.细胞的代谢水平往往与其衰老程度呈负相关", "B.老年动物的肌肉再生能力显著低于青壮年动物", "C.将该材料注入小鼠体内后，小鼠未产生明显的免疫反应", "D.端粒长度延长是细胞分裂激活的伴随现象，表明细胞恢复了「年轻」"], "solve": "问『最不能支持』＝找无关项/削弱项；C 的『无免疫反应』只证安全性，与抗衰老机制无关 → 最不能支持。记住『安全≠有效』。", "analysis": "**识别信号**：给研究结论＋证据，问「最能支持/最不能支持」 → 加强题（注意**反向问法**）。\n**核心规律**：三证据（代谢↑/端粒↑/再生↑）都指向抗衰老；C「无免疫反应」只证**安全性**、与衰老机制无关 → 无关项 → 最不能支持。打法：反向问法（最不能支持）→在选项中找**削弱或无关**项；识别搭桥＝秒杀；**安全感≠有效性**。\n**易混·易错链**：最像=**解释原理**（补机制）｜撞坑链：被「无免疫反应」的正面表述骗选；把「安全/生物相容性」当「有效」。", "img": ""}, {"q": "某研究者选取同一年级的两个班级进行教学实验，第一个班级的学生在听课过程中被鼓励随时提问，而第二个班级的学生没有受到同样的鼓励，结果显示，第一个班级学生的课堂专注度明显高于第二个班级。研究者据此建议在教学过程中学生应随时提问，以提升知识掌握效果。如果以下选项为真，最能支持研究者建议的是（ ）。", "src": "2025广东省考真题 第60题", "hit": true, "ans": "B", "opts": ["A.学生在课堂上随时主动提问能活跃课堂气氛", "B.课堂专注度是影响知识掌握效果的重要因素", "C.这两个班级的学生在实验前的学习成绩相当", "D.随时提问能帮助学生增强自我认同感和自信"], "solve": "论据落\"专注度\"、论点落\"知识掌握效果\"＝两套落脚词 → 补 B→C 的桥 → ==B==。", "analysis": "**识别信号**：论据落词≠论点落词（「专注度」vs「知识掌握」），问「最能支持」 → 搭桥题。\n**核心规律**：论据落「课堂专注度」、论点落「知识掌握效果」＝两套落脚词 → **最强加强＝补 B→C 的桥**（专注度影响知识掌握）。打法：先划**落脚词**（论点/论据）→落差即缺口；加强力度：**搭桥 ＞ 解释≈排除他因 ＞ 举例**。\n**易混·易错链**：最像=**排除他因**（只保实验可比、够不到论点）｜撞坑链：被「提问有益」常识带跑（A 活跃气氛/D 自信）；把 C 当最强加强。", "img": ""}, {"q": "某团队开展了一项关于预防中风的研究。研究对象分为两组，一组食用低钠盐（约75%的氯化钠和25%的氯化钾），一组食用普通盐（约97%的氯化钠）。在5年的跟踪调查中发现，食用低钠盐的群体，其中风发病率显著低于食用普通盐的群体。因此，减少钠的摄入有助于预防中风。以下各项如果为真，最不能支持这一结论的是（ ）。", "src": "2024广东省考真题 第64题", "hit": false, "ans": "A", "opts": ["A.食用低钠盐的中风患者的死亡率远低于食用普通盐的中风患者", "B.两组研究对象在性别、年龄等方面不存在明显差异", "C.研究期间，两组研究对象每日摄入的盐含量接近", "D.摄入氯化钾不会影响中风发病率"], "solve": "结论说\"**预防**中风（降发病率）\"，A 谈的却是\"中风患者**死亡率**（预后）\"，偷换了比较指标 → ==最不能支持==。", "analysis": "- 体系定位：判断推理 → 逻辑判断 → 加强 / 削弱 / 前提 → 加强（清单原名：**加强·排除他因**）；体系位置：上位＝逻辑判断，本题＝实验对比型加强（选最不能支持），下级变式＝最能削弱、前提假设。\n- 识别信号：题干是**实验 / 调查两组对比** → 先拆\"论据 → 论点\"；问\"最不能支持 / 最不能加强\"→ 找与论点**话题 / 指标不一致**的那项（多为偷换概念）。\n- 本质：内核＝**论证有效性**：论据（两组发病率差异）能否推出论点（钠 → 预防）；判分点＝排除他因使因果更可信，反之谈别的指标就不支持。\n- 通式：无固定式，按\"**拆论据/论点 → 找缺口(他因/概念) → 归类支持或无关**\"三步走；加强题优先看\"排除他因 / 搭桥\"，最不能支持题优先找\"偷换指标\"。\n- 易混·易错链：最像的是**削弱题**（本题方向是加强，别做反）；撞坑链：被\"发病率 / 患病率 / 死亡率\"三个近义指标带偏 → 忽略话题偷换 → 误选 B/C/D。", "img": ""}, {"q": "某古生物学研究小组在一处白垩纪晚期地层中发现了保存完整的恐龙皮肤化石。通过高分辨率显微镜，研究人员发现该恐龙皮肤表面存在大量微小的中空管状结构。由于这些结构类似于现代鸟类羽毛中用于体温调节的羽茎，研究人员推测，这些微小的中空管状结构是恐龙用于调节体温的特殊结构。以下选项如果为真，最能支持上述推测的是（ ）。", "src": "2026广东省考真题 第64题", "hit": true, "ans": "A", "opts": ["A.这些中空管状结构能够增强生物体表的散热能力", "B.其他恐龙化石之中也发现了类似的中空管状结构", "C.现代爬行类动物的皮肤表面不存在类似的中空管状结构", "D.由于白垩纪晚期气候异常，恐龙需要体温调节机制维持生存"], "solve": "论据靠「类似鸟类管体温的羽茎」**类比**推功能 → 缺口＝「像≠同用」；补「该结构能增强散热」把「结构↔体温调节」搭上桥 → ==A==。", "analysis": "- 体系定位：判断推理 → 逻辑判断 → 加强 / 削弱 / 前提 → 加强 → 搭桥（方法全名「搭桥：在论据与论点之间架桥（补充二者隐含联系）即为强加强」）；上位＝加强题，本题＝「类比论据推功能」的搭桥，下级变式＝排除他因、举例。\n- 识别信号：论据用「类似 / 类比 / 就像」推结论功能 → 问「最能支持」→ 优先找「补该功能」的搭桥项。\n- 本质：一句话——**类比只给「像」，加强要补「同用」**；论据与论点之间有跳跃（相似↔同功能），补上跳跃＝最强加强。\n- 通式：加强力度排序 **搭桥/解释（补跳跃）＞举例重复＞背景/无关**；反向问法（最不能支持）→ 找无关或削弱项。\n- 易混·易错链：最像＝「排除他因」（只保可比性、够不到功能）｜撞坑链：被 D 的「需要体温调节机制」带跑——「有需求」≠「这个结构做到了」。", "img": ""}]}, {"name": "解释原理：补充原理/机制说明为何论点成立", "star": false, "examples": [{"q": "某地共享单车采用阶段收费模式，第一小时收费1.5元，其后每半小时收费1元。最近，共享单车运营商调整了收费标准，第一小时收费不变，其后每半小时收费2元，涨幅高达100%，但当地共享单车月均使用人次并未因价格调整而减少。对上述现象，以下解释最为合理的是（ ）。", "src": "2025广东省考真题 第52题", "hit": true, "ans": "C", "opts": ["A.与多次换乘公交相比，使用共享单车的花费更低", "B.随着生活水平提高，人们的消费意愿逐步增强", "C.单次使用共享单车时长超过一小时的当地市民微乎其微", "D.当地仅有一家共享单车运营商，市场缺乏竞争"], "solve": "**涨幅只落在\"超过一小时\"那段**（1 小时内 1.5→1.5 分文不变）→ 找\"单次骑超一小时者极少\" → ==C==。", "analysis": "**识别信号**：题干出现**矛盾现象**（涨 100%↔人次不降），问「解释最合理」 → 解释型。\n**核心规律**：先锁「落差」；再算清「谁才会被涨价碰到」（>1 小时者：2h 从 3.5→5.5，且这部分人极少）→ 挑能**同时解释两端**的项（C）。打法：解释型先破包装（**局部单价涨幅≠总账单**），再挑「能同时闭合矛盾两端」的选项。\n**易混·易错链**：最像=**搭桥**（架联系）｜撞坑链：被「涨 100%」包装唬住；A 只说更省、B 泛谈意愿、D 换论题（只沾一边即错）。", "img": ""}, {"q": "网络购物平台的数据分析显示，网店为商品提供免费的运费险能够增加销量，但其商品退费率远高于不提供这项服务的网店，从而增加了运营成本。但提供免费运费险的很多网店仍未关闭这一服务。如果以下选项为真，最有可能解释这一现象的是（ ）。", "src": "2025广东省考真题 第57题", "hit": true, "ans": "A", "opts": ["A.提供这一服务的网店比其他网店获得了更高的净利润", "B.商品销量和运费成本是衡量网店经营状况的两项关键指标", "C.人工、场地等成本不受退货率影响，且占运营成本的比重不低", "D.提供免费的运费险能够显著提升消费者的信任度"], "solve": "矛盾＝\"成本↑却仍不关闭\" → 解释须让\"利＞弊\"成立：**净利润更高**（整体更赚）→ ==A==。", "analysis": "**识别信号**：理性主体矛盾（成本↑却仍不关闭），问「最可能解释」 → 解释型。\n**核心规律**：选项须**同时兼容「成本增加」与「商家保留」**两个事实；本题命门＝**利大于弊（净利润更高）**（A）。打法：理性主体矛盾→找「综合收益/隐性好处」；「单项损失与整体获利并存」是高频命题点。\n**易混·易错链**：最像=**削弱型**（削弱要否定结论；解释须**承认全部事实**只补中间原因）｜撞坑链：选 C（「弱化成本」≠解释「为何保留」）；选 D（信任度＝题干「增销量」复述）；试图否定题干。", "img": ""}]}, {"name": "排除他因：排除其他可能解释，使原因更可信", "star": false}, {"name": "举例/类比：举同类实例或类比支持，力度弱于搭桥", "star": false}]}, {"name": "削弱", "star": false, "children": [{"name": "削弱论点：直接否定论点（与结论相反的事实）力度最强", "star": false, "examples": [{"q": "研究表明，购物行为能够刺激大脑的多个区域，使人们感到幸福。进一步研究发现，在别人身上花的钱占购物支出的比例越大的人，其幸福感越强；但在自己身上花钱的多少和幸福感的关系则不那么明显。有人因此认为，为了提高个人幸福感，在购物时，应该给别人花更多的钱。下列选项如果为真，最能反驳这一结论的是（ ）。", "src": "2024广东省考真题 第59题", "hit": true, "ans": "D", "opts": ["A.向他人推荐的商品如果受到了他人的认可，人们也会感到幸福", "B.如果为他人购买的商品没有受到他人的喜爱，容易使人变得沮丧", "C.购物带来的快乐很短暂，个人所面对的困难和压力不会因为购物而消失", "D.与他人关系好的人往往更加幸福，且更愿意在购物时为他人花更多的钱"], "solve": "题干由「花得多人更幸福」推「多花→更幸福」，D 指出「更幸福的人本就更愿为他人花钱」——**因果倒置**，直接砍断因果链。", "analysis": "- 体系定位：判断推理 → 逻辑判断 → **削弱·因果倒置**（清单原名）；上位＝加强/削弱/前提的削弱分支 → 本题（因果倒置）→ 下级变式＝另有他因 / 拆桥。\n- 识别信号：题干出现「A 的比例越大，B 越强」＋结论「为了 B 应多 A」→ **相关被当因果**，先想因果倒置。\n- 本质：内核是**相关 ≠ 因果**，考能否识别把统计相关硬推为因果的跳跃，并用反向因果砍断。\n- 通式：削弱「因 A → 果 B」最强＝==因果倒置（其实 B → A）==；次选另有他因、拆桥；判据：能反转方向者力度最强。\n- 易混·易错链：最像「另有他因」（提第三因、不反转方向），分界看**是否反转方向**；撞坑链＝把相关数据当结论已成立→误选无关 A/C。", "img": ""}, {"q": "某研究团队对一块坠落在我国境内的新陨石展开研究后发现，其矿物晶体主要呈半自形粒状或自形柱状形式，该矿物产出于钙长石、铁辉石、氟磷灰石以及钛铁矿边部，与此前发现的月球矿物同属于陨磷钙钠石族。因此，团队认为该陨石是月球矿物。以下哪项如果为真，最能反驳上述论证？", "src": "26年省考35季 第52题", "hit": false, "ans": "B", "opts": ["A.该团队未对陨石整体岩相结构做全域检测，仅发现已检测区域物质与月球矿物相同", "B.陨磷钙钠石族矿物并非是月球独有，太阳系多类天体陨石中普遍存在该矿物族成员", "C.此前发现的月球矿物晶体粒径是10至20微米，而新陨石的晶体粒径是3至15微米", "D.月球表面存在大量环形山，主要由小行星撞击形成，与月球矿物的分布无直接关联"], "solve": "结论「该陨石是月球矿物」靠「矿物特征同属陨磷钙钠石族」作论据，**削弱只需打断隐含前提「该矿物族＝月球独有」**——一眼锁定 B「该矿物族并非月球独有」。", "analysis": "- 体系定位：判断推理 → 逻辑判断 → 加强 / 削弱 / 前提 → 削弱（拆桥式）\n- 识别信号：题干给「特征相同/同属某类 → 所以是某来源」，问「最能反驳」→ 找隐含前提里的**独有性/唯一对应**\n- 本质：考「论据→结论」之间**是否有桥**；削弱最狠＝拆桥（否定隐含前提），非拆论据本身\n- 通式：结论「A 是 X」+ 论据「A 具有 X（独有）特征」→ 削弱首选「该特征**并非 X 独有**」；同类判别条件：看到「同属/相同→所以是」就搜隐含的「独有/唯一」\n- 易混·易错链：与「削弱论据」（说检测有误）区分——拆桥力度＞拆论据；常见撞坑：被 A/C/D 的「细节瑕疵/无关话题」带偏", "img": ""}, {"q": "某大型电商平台近期全面上线了新一代AI客服系统。数据显示，在系统上线后的三个月内，平台的人工客服咨询量下降了40%，同时用户满意度评分从4.2分上升到了4.6分。因此，该平台的技术负责人得出结论：AI客服系统能够提高该平台用户的满意度。以下哪项如果为真，最能削弱上述技术负责人的观点？", "src": "26年省考35季 第57题", "hit": true, "ans": "A", "opts": ["A.该平台在AI客服系统上线的同时，还推出了“极速退款”和“一键换货”两项新功能，降低了消费者的沟通成本", "B.AI客服处理的都是物流查询、订单状态等标准化问题，而涉及售后纠纷、商品质量投诉等复杂场景仍需转接人工客服处理", "C.个别用户反映，虽然AI客服响应速度快，但在遇到需要灵活判断的问题时，AI客服的回复往往答非所问，导致问题反复升级", "D.同行业的另一家电商平台也在测试AI客服系统，但仅将其作为人工客服的辅助工具"], "solve": "题干是「上线 AI 客服 → 满意度 4.2→4.6」的**因果推断**，削弱首选**另有他因**——A 指出同期还上线「极速退款·一键换货」降低了沟通成本，即满意度上升另有原因，直接切断 AI 客服与满意度的因果。", "analysis": "- 体系定位：判断推理 → 逻辑判断 → 加强 / 削弱 / 前提 → 削弱（另有他因式）\n- 识别信号：题干「某措施上线后，指标变好 → 所以是它起作用」→ 削弱就找**同期别的变化**\n- 本质：考**因果推断的可信度**；论据只是「时间先后/同期共存」，不等于因果\n- 通式：结论「X 导致 Y」＋ 论据「X 与 Y 同期出现」→ 削弱首选「另有他因 Z 也导致 Y」；同类判别条件：看到「上线后/实施后…变好→所以有效」就找他因\n- 易混·易错链：与「因果倒置」区分——倒置是「其实是 Y 导致 X」，他因是「Z 才导致 Y」；常见撞坑：被 C 个例、D 别家平台带偏", "img": ""}]}, {"name": "拆桥：切断论据与论点的联系，即论据推不出论点", "star": false, "examples": [{"q": "某厂家用“除菌去残留，效果看得见”这一广告语，宣传其生产的果蔬清洗机，并展示该产品与其他果蔬清洗机清洗同一种水果的视频，视频显示，该清洗机清洗产生的泡沫最多。该厂家宣称泡沫是被清洗机清洗出来的有害残留，故其产品除菌去残留效果更好。如果下列选项为真，最能反驳上述推论的是（ ）。", "src": "2025广东省考真题 第63题", "hit": true, "ans": "D", "opts": ["A.用果蔬清洗机清洗食材，不管清洗多少遍，都会出现泡沫", "B.市面上绝大部分果蔬的农药残留均未超标，有害物质极少", "C.用普通烹饪方式加工肉类食材，或多或少也会产生泡沫", "D.专业化学检测是检验果蔬除菌去残留效果的唯一有效手段"], "solve": "论点＝『除菌去残留效果更好』；D 说检验效果只能靠专业化学检测→泡沫这套论据当场作废，一刀切在论据→论点的桥上。", "analysis": "**识别信号**：用现象 A 证明效果 B（「泡沫最多」→「除菌去残留更好」），问「最能反驳」 → 拆桥。\n**核心规律**：论点＝效果更好；论据＝泡沫最多＋中间前提「泡沫＝有害残留」；D「专业化学检测才是检验效果唯一手段」→ **切断论据→论点**的桥。打法：见「用现象 A 证明效果 B」→先画桥 A→B，**谁切断 A 能推出 B 谁就是答案**；力度序 **拆桥/否论点 ＞ 否论据/另有他因 ＞ 举反例**。\n**易混·易错链**：最像=**另有他因**（否定「原因唯一」；拆桥是「该论据推不出该论点」）｜撞坑链：被「泡沫＝有害残留」中间前提带跑当论点→误选 A；把 D 误叫「它因削弱」。", "img": ""}, {"q": "鉴于漂流项目偶尔会出现游客落水伤亡的情况，某旅游景区为每一位参加漂流项目的游客购买了意外保险，并要求游客必须穿上景区配备的救生衣，有游客对此提出疑问，既然景区已经购买了意外保险，游客出现意外伤亡由保险公司赔付，那么游客为寻求刺激的漂流体验，可以选择不穿救生衣。如果以下选项为真，最能反驳这一质疑的是（ ）。", "src": "2025广东省考真题 第65题", "hit": true, "ans": "A", "opts": ["A.如果未穿救生衣的游客出现意外伤亡，保险公司将不予赔付", "B.该景区为参加蹦极、过山车等项目的游客也购买了意外保险", "C.该景区在免费为游客提供了救生衣的同时，还配备了救生员", "D.保障游客的人身安全是景区经营方的基本职责之一"], "solve": "质疑靠『保险会赔』推出『可以不穿』；A 说『没穿就不赔』，一句话拆掉这条桥——保险的兜底在『不穿救生衣』这一情形下根本不成立。", "analysis": "**识别信号**：「既然…那么…」类质疑（保险会赔→可不穿救生衣），问「最能反驳」 → 拆桥。\n**核心规律**：质疑链＝「保险会赔→可以不穿」，默认前提＝「没穿也照样赔」；A「未穿救生衣出事→保险不赔」直接否掉默认前提→桥断。打法：见「既然…那么…」质疑→先把论据、结论分两行→抓二者默认**隐含前提**→谁推翻它选谁；命门词锚定（本题＝「赔不赔」）。\n**易混·易错链**：最像=**削弱论点**（直接抛相反事实；拆桥是打论据↔结论的默认前提）｜撞坑链：被「景区职责/配救生员」应然表述带跑（选 C/D）；没先还原两行就凭语感选。", "img": ""}]}, {"name": "因果倒置：指出因果方向相反（B导致A而非A导致B）", "star": false}, {"name": "另有他因：提出其他原因可解释结果，削弱原因唯一性", "star": false}, {"name": "举反例：举与结论相反的例子（力度较弱，但可削弱）", "star": false}]}, {"name": "前提型", "star": false, "children": [{"name": "搭桥前提：找论据→论点之间的缺口，夺定跳跃前提", "star": false, "examples": [{"q": "具身智能是能感知决策并与物理世界互动的人工智能系统，目前具身智能机器人强调“大脑”和“小脑”的协同工作，它能精准的完成细节操作，且能合理规划任务。因此，外科手术机器人“达芬奇”，虽具备精密操作能力，但仍不能算是具身智能机器人。要使上述结论成立，需要补充的前提是（ ）。", "src": "2025广东省考真题 第51题", "hit": true, "ans": "B", "opts": ["A.只有具备规划任务能力的机器人才是具身智能机器人", "B.外科手术机器人\"达芬奇\"不能做到合理规划任务", "C.具身智能机器人的核心特征体现在能够感知并作出决策", "D.具身智能赋予传统机器人\"大脑\"和\"小脑\"协同工作的能力"], "solve": "**搭桥前提**：论据\"具身智能须能规划任务\"↔结论\"达芬奇不是具身智能\"之间缺一环——==达芬奇不能合理规划任务== → B。", "analysis": "**识别信号**：给结论问「需要补充的前提是」 → 前提型。\n**核心规律**：论点是否定式（「不是具身智能」）→需证**某要件不满足**；题干要件＝精准操作＋合理规划（合取），达芬奇已知满足前者→缺口＝「缺规划能力」（B）。打法：否定式论点→译成「证明某要件不满足」→优先「补缺口＋主体一致」项；**先找缺口再挑主体**。\n**易混·易错链**：最像=**削弱·拆桥**（给「能规划」即拆桥）｜撞坑链：被 A 的「只有…才」搭桥语气迷惑（未涉达芬奇）；被原文词（感知决策/协同）带偏选 C/D。", "img": ""}, {"q": "某种贫血症属于遗传性疾病，患者的血红蛋白分子结构异常，从而影响红细胞正常功能。目前，科学家已能够利用基因组编辑技术，治疗因基因突变导致的遗传性疾病。因此，这种贫血症患者有望通过基因组编辑技术被治愈。要使上述结论成立，需要补充的前提是（ ）。", "src": "2025广东省考真题 第54题", "hit": true, "ans": "B", "opts": ["A.血红蛋白分子结构异常是这种贫血症的主要表现", "B.这种贫血症是一种由基因突变导致的遗传性疾病", "C.这种贫血症患者的红细胞可由直系亲属的代替", "D.血红蛋白基因是导致这种贫血症的相关基因"], "solve": "论据管\"基因突变致的遗传病\"（大类），论点管\"这种贫血症\"（个案）→ 缺\"小类⊆大类\"的**归属搭桥** → ==B==。", "analysis": "**识别信号**：论据管「大类」、论点管「个案」，问「需要补充的前提」 → 搭桥前提。\n**核心规律**：论据＝「基因突变致遗传病」（大类）、论点＝「这种贫血症」（个案）→缺「小类⊆大类」的**归属搭桥**（B）。打法：**论据管大类、论点管个案→补个「属于」就闭环**；前提型＝「否定即倒」。\n**易混·易错链**：最像=**加强型**（可充分不必必要；前提型取必要）｜撞坑链：选 D 把「相关基因」当「致病基因突变」（相关≠因果）；选 A 被「主要表现」带偏；选 C 偏题。", "img": ""}, {"q": "如果没有强健的体魄，就不会有好的学习状态；如果学习状态不好，学习成绩就不可能提升。因此，学校要提升学生的学习成绩，就必须开设体育课。要使上述结论成立，必需补充的前提是（　　）。", "src": "2025广东省考真题 第55题", "hit": false, "ans": "A", "opts": ["A.体育课是增强学生体魄的必要途径", "B.所有学生都能通过体育课强健体魄", "C.没有学生不希望提升自己的成绩", "D.学生在课余时间也会进行体育锻炼"], "solve": "题链止于\"强健体魄\"，结论却落在\"开设体育课\" → **缺 \"体魄←体育课\" 这一环（必要方向）** → ==A==。", "analysis": "**识别信号**：条件链（非体魄→非状态→非成绩）＋结论冒出**新概念**（体育课），问「必需补充的前提」 → 搭桥前提。\n**核心规律**：①非体魄→非状态、②非状态→非成绩 ⇒ 逆否＝**成绩→体魄**；结论要「成绩→体育课」→缺「体魄→体育课（必要）」这一环（A）。打法：**结论里冒出的新概念就是缺口**——新概念必被论据与前提共同覆盖；口诀「**否之则塌者即前提**」。\n**易混·易错链**：最像=**必要条件 vs 充分条件**（A「必要途径」对；B「都能通过」＝充分/有效，方向反且「所有」过强）｜撞坑链：被 B 全面语气带偏；选 D 课余锻炼（反而削弱开课必要）；误选 C（只谈动机）。", "img": ""}, {"q": "智能时代的创新生态，呈现出大企业建平台、小企业搞突破的鲜明特征。一人公司、小型团队得以快速推出轻量化应用，而大型企业则承担着搭建底层算力、核心芯片、技术框架的重任，由此便有了大企业赋能小企业，继而形成了大平台支撑、小前端创新的良性格局。据此有人认为，大企业赋能小企业的产业协同生态能够提升数字经济领域的整体创新效率。要使上述结论成立，需要补充的前提条件是（  ）。", "src": "26年省考34季 第65题", "hit": false, "ans": "C", "opts": ["A.大企业赋能小企业，能够为小企业指定方向、提供技术，降低其创新风险", "B.从全球视野看，数字经济已进入以通用人工智能为核心驱动的智能跃迁新周期", "C.数字经济领域整体创新效率的提升依赖大平台支撑和小前端创新的良性格局", "D.小企业面临技术、市场、融资、管理、团队等多重风险，难以生存"], "solve": "论据讲「良性格局」、结论落「整体创新效率」，中间少一座桥——凡把「良性格局」与「创新效率提升」连起来、且否定后结论即垮的，就是前提，选 ==C==。", "analysis": "- 体系定位：判断推理 → 逻辑判断 → 加强 / 削弱 / 前提 → 前提型（清单原名「前提型·搭桥前提」，并列「前提型·补全必要」）；上位＝论证评价，本题＝补充必要前提，下级变式＝加强搭桥、削弱拆桥。\n- 识别信号：题干出现「要使结论成立，需要补充的前提/假设是」→ 立刻切「前提型」，用「找缺口 + 否定代入」。\n- 本质：一句话——前提是**论证成立所必不可少**的条件，它补的是论据与论点之间被隐去的桥；否定它结论就站不住（原判分点：找论据→论点之间的缺口，锁定跳跃前提）。\n- 通式：必要前提 = 令「论据→论点」成立所缺的那一步 `论据 + 前提 ⟹ 论点`；验证用**否定代入法**（加「非前提」后论证若垮 → 即为前提）。\n- 易混·易错链：最像的是「加强·搭桥」（加强只需「更可信」、前提必须「不可少」，看「否定后是否垮」取舍）；撞坑链：把「支持性事实」当必要前提 → 选到只谈单方好处的项（A/D）→ 被背景项（B）带偏。", "img": ""}, {"q": "最近，市场上中药材的价格有所下降。据调查，中药材产量的增加是价格下降的主要原因。由于近年来中药材种植业蓬勃发展，而野生中药材的产量没有显著增加，因此中药材产量的增加主要缘于中药材种植业的蓬勃发展。要使上述推理成立，需要补充的前提条件是：", "src": "2024广东省考真题 第62题", "hit": true, "ans": "D", "opts": ["A.多种中药材的产量大幅增加", "B.一些消费者偏好野生中药材", "C.部分中药材已经实现规模化种植", "D.中药材只能通过种植和野外采集获得"], "solve": "题干默认「药材来源只有种植＋野生采集」，D 恰好补上这个被暗含的前提——**否定它（还有别的来源）则推理崩**，正是必要前提。", "analysis": "- 体系定位：判断推理 → 逻辑判断 → **前提型·补全必要**（清单原名）；上位＝加强/削弱/前提的前提分支 → 本题（补全必要）→ 相邻变式＝搭桥前提。\n- 识别信号：问「要使推理成立／需补充的前提／需假设」→ 前提型；再看论据与论点间是否把**来源/条件默认为唯一**。\n- 本质：内核＝找**论证成立的必要条件**，即「否定后论证即不成立」的隐含前提。\n- 通式：==否定代入法==——把选项逐个否定，谁使论证崩塌谁就是必要前提；模板＝论据→论点缺哪一环，选项补哪一环。\n- 易混·易错链：最像「加强·搭桥」，前提是**没它不行**（必要）、搭桥只是**有了更顺**（支持），分界看否定后是否崩；撞坑链＝误选只沾边却可被否定的 A/B/C。", "img": ""}, {"q": "某科研团队发现，特定种类的海洋微生物能以塑料为食，并将其转化为无害物质。有团队负责人提出，若将这些微生物大规模投放到受塑料垃圾严重污染的海域，将能有效加速海洋塑料垃圾的降解，从而显著改善海洋生态环境。上述论证的成立须补充以下哪项作为前提？", "src": "26年省考35季 第58题", "hit": true, "ans": "B", "opts": ["A.大规模投放这些微生物不会对海洋中的其他生物造成任何影响", "B.这些微生物在受塑料垃圾污染的海域中能够存活并进行有效繁殖", "C.目前已有多种化学方法可以分解塑料垃圾，但成本高且会产生二次污染", "D.海洋塑料垃圾的降解速度加快是改善海洋生态环境的唯一有效途径"], "solve": "论证靠「投放 → 加速降解」，缺了**投放后微生物能活下去**这一必要条件；**否定代入**：若该海域不能存活繁殖，投放即无效、结论崩塌 → B 是可行性前提。", "analysis": "- 体系定位：判断推理 → 逻辑判断 → 加强 / 削弱 / 前提 → 前提型（可行性假设）\n- 识别信号：题干问「须补充/必须假设/前提是」→ 立刻用**否定代入法**，取反后结论崩者入选\n- 本质：考「结论成立的**必要假设**」；不是问力度，而是问「没它行不行」\n- 通式：`论据→结论` 缺环处找必要假设；模板「要实施 X 达成 Y，须保证 X 在目标环境**可执行**」；同类判别条件：看到「投放/推行某措施→有效果」先查「能否实际发生」\n- 易混·易错链：与「加强项」区分——加强是「锦上添花」（不必要但有力），前提是「无之必崩」；常见撞坑：选 A/D 这类**过强**或**过强词（任何/唯一）**的伪前提", "img": ""}]}, {"name": "补全必要：答案取否定后论证即不成立的必要条件", "star": false}]}, {"name": "论证缺陷", "star": false, "children": [{"name": "单一归因自检：结论由「单一原因」推「全称结果」时，先查它是否默认该原因唯一——缺口多为「还有他因」", "star": false, "examples": [{"q": "作为高端羽毛球的必备原料，羽毛切片是鸭鹅养殖的副产品，其供应量上要取决于养殖规模，如果养殖规模有所下降，羽毛切片价格将会一路走高，进而导致高端羽毛球生产成本高企、厂家将因此被迫提高出厂价格，所以，如果近期鸭鹅养殖规模保持平稳，则高端羽毛球的出厂价格将不会明显上涨。上述论证的主要逻辑错误在于（ ）。", "src": "2025广东省考真题 第61题", "hit": false, "ans": "A", "opts": ["A.忽视了其他因素对高端羽毛球出厂价格的影响", "B.忽视了影响鸭鹅养殖规模的其他因素", "C.默认了高端羽毛球生产所需的羽毛切片没有替代品", "D.默认了鸭鹅养殖规模严重影响高端羽毛球的生产"], "solve": "单一因果链逆否外推（规模平稳→价不涨）→ 默认出厂价只由此链决定 → ==A（忽略他因）==。", "analysis": "**体系定位**：判断推理 → 逻辑判断 → 加强 / 削弱 / 前提 → **论证缺陷（单一归因 · 忽略他因）**。\n**识别信号**：题干是一条**线性因果链**＋逆否外推（「若规模下降→价格走高」，故「若规模平稳→价格不涨」），问「主要逻辑错误」→ 直接判**论证缺陷**。\n**本质**：论证把「规模↓→切片涨→成本高→价涨」当成**唯一通路**；要推出「规模平稳→价不涨」，得**堵死其他所有涨价路径**——题干既没做也做不到，缺口＝**忽略他因**。\n**通式**：结论由**单一原因**推**全称结果**（不会 / 一定 / 必然）→ 先查「是否默认该原因唯一」；答案多为「忽视其他因素」。\n**易混·易错链**：最像＝**削弱·另有他因**（方向相反：一个指缺、一个补刀）｜C 陷阱＝题干已把切片设为「**必备原料**」，讨论替代品偏离了「推出关系」｜D 陷阱＝「养殖规模」字面齐全，但说的是该默认**成立**、没指出错在哪。", "img": ""}]}]}]}, {"name": "相似结构", "star": false, "children": [{"name": "结构翻译比对", "star": false, "children": [{"name": "**只比结构不比内容**——先把题干译成符号（A→B／非A→非B），再逐项比对箭头方向与真假，不看话题是否相同", "star": false, "examples": [{"q": "古丝绸之路之所以举世闻名，靠的不仅是经济互利，更是丰富物产和多元文化交流，所以，只有经济互利，不可能重现古丝绸之路的辉煌。以下选项推理逻辑与题干最相似的是（　　）。", "src": "2025广东省考真题 第58题", "hit": true, "ans": "C", "opts": ["A.我国要实现高水平科技自立自强，归根结底是要靠高水平创新人才，所以，创新能力培养应该成为人才培养的核心", "B.粮食丰收，及时收割和晒干入库都是关键环节，所以，天气连续晴好有助于实现粮食丰收", "C.高水平大学不仅要有完整的设施设备，更要有高水平的教师队伍，因此，仅靠完善设施设备并不能成为高水平大学", "D.体育活动需要合适的运动场所，因此，如果城市缺少合适的运动场所，居民就难以积极参加体育活动"], "solve": "题干＝「目标需(B∧C∧…)；单件B不足→只B则非X」；C 三指纹全同 → ==C==。", "analysis": "**识别信号**：问「推理逻辑与题干最相似」 → 结构相似。\n**核心规律**：题干＝「目标需(B∧C∧…)；单件 B 不足→只 B 则非 X」，C 的**三指纹**全同（多条件并列＋否定单件）。打法：结构相似＝**先翻译、再对指纹**（①条件词/量词 ②推导方向 ③有无否定），三要素对不齐就换项。\n**易混·易错链**：最像=**必要条件缺失**（无B→非X，如 D）vs **单件不足**（有B仍非X，本题）｜撞坑链：被内容相关带跑（A 讲人才/B 讲农业觉得「贴近现实」就选）——形式题**内容毫无权重**。", "img": ""}, {"q": "小赵：我不生孩子有错吗？小钱：不能说有错，也不能说没错。主要是如今我国的生育率太低了。以下哪项的对话与上述对话最为相似？", "src": "26年省考35季 第61题", "hit": false, "ans": "C", "opts": ["A.小孙：校园霸凌者可以被原谅吗？小李：原谅还是不原谅，我觉得都有道理。不过受害者往往很难选择原谅", "B.小周：高薪但不喜欢的工作和低薪但很喜欢的工作，你选哪个？小吴：我不选不喜欢的工作，也不选低薪的工作。另外，工作环境也挺重要", "C.小郑：父母该不该告诉小朋友童话都是虚构的？小王：告诉或不告诉，都不太合适。小朋友接触虚构信息渠道多，真假辨别教育更值得重视", "D.小冯：如果有一瓶可以消除悲伤的水，你要不要喝？小陈：我不喝，劝你也不要喝。如果没有悲伤，快乐也将失去意义"], "solve": "原对话骨架＝**「是否判断（该不该/有没有错）」类提问 → 答「都不/都说不准」（模棱两可）→ 再甩出一句转移性的实质因素**；C「告诉或不告诉都不太合适 ＋ 转引真假辨别教育」逐字同构。", "analysis": "- 体系定位：判断推理 → 逻辑判断 → 相似结构 → 结构翻译比对\n- 识别信号：题干「与上述对话最为相似」→ 只抽「问句类型＋表态方向＋后续走向」骨架，别被话题内容带走\n- 本质：考两人对话的**逻辑骨架同构**（谁问什么类型、答方持何种立场、是否另起他因）\n- 通式：相似对话＝`问句类型一致（是否/二选一）＋ 表态方向一致（都肯/都否/两可/单方）＋ 有无转引一致`；同类判别条件：看到「对话相似」先画 问—答—转 三格\n- 易混·易错链：与「类比推理·关系类型」区分（那是词项关系，非对话结构）；撞坑：把「都有道理（双向肯定，A）」误当「都不说准（模棱两可，原/ C）」", "img": ""}]}]}, {"name": "三段论式", "star": false, "children": [{"name": "\"所有A是B，所有B是C ⟹ 所有A是C\"的**链式传递**，比对选项是否同为三段论", "star": false, "examples": [{"q": "庑殿顶是中国古代建筑的一种屋顶形式，由一条正脊和四条垂脊组成，而中国古代许多皇宫大殿有庑殿顶，因此许多皇宫大殿的屋顶只有一条正脊。以下选项的推理逻辑与题干最相似的是（　　）。", "src": "2025广东省考真题 第56题", "hit": true, "ans": "B", "opts": ["A.现代主义建筑通常没有复杂的装饰，追求功能属性与简约美，而西班牙的许多建筑造型奇特，装饰繁复，因此这些建筑不属于现代主义建筑", "B.哥特式建筑都有尖形拱门，而欧洲中世纪的建筑多数属于哥特式建筑，因此部分欧洲中世纪的建筑有尖形拱门", "C.古罗马时期的建筑多数都有穹顶，而同一时期的建筑多为砖石结构，因此有的砖石结构建筑有穹顶", "D.客家围屋都设有用于防御土匪侵扰的炮楼，因此有客家围屋的地区，都需要防御土匪侵扰"], "solve": "题干＝「所有A都是B；许多C是A；⟹许多C是B」，B 量词与方向**逐格同构** → ==B==。", "analysis": "**识别信号**：题干带「所有…都…、许多/多数」，问「推理逻辑最相似」 → 相似结构。\n**核心规律**：题干＝「所有 A 都是 B；许多 C 是 A；⟹ 许多 C 是 B」，B 的量词与方向**逐格同构**。打法：遇「推理逻辑最相似」→第一动作**符号化成 A/B/C 模板**，拿「量词＋方向＋否定」硬对。\n**易混·易错链**：最像=**类比推理**（看词语义关系）｜撞坑链：被陌生名词吓住凭语义选；把「许多/多数」当「全部」而漏判「缺前提」的选项。", "img": ""}]}]}, {"name": "传递式", "star": false, "children": [{"name": "条件链**首尾相接逐层传递**（A→B 且 B→C ⟹ A→C），比链长与方向", "star": false}]}, {"name": "逆否式", "star": false, "children": [{"name": "题干用**逆否等价**（非B→非A）时，选项须同为逆否结构，否则\"形似神不似\"", "star": false, "examples": [{"q": "根据法律，公共场所禁止吸烟，因此，如果有人在某个区域吸烟却不违法，说明该区域不属于公共场所。以下选项的推理逻辑与题干最相似的是（ ）。", "src": "2025广东省考真题 第62题", "hit": false, "ans": "B", "opts": ["A.长时间室内活动是近视的主要原因，因此近视的人都缺乏户外运动", "B.优秀的工匠在学徒时期就追求精益求精，如果某学徒自我要求不高，那他就无法成为优秀的工匠", "C.超过9层的楼房都会配建电梯，因此，如果某住宅楼低于9层，那么住户只能走楼梯", "D.织物表面的纳米涂层可以阻止液体渗入，因此，某种面料防水，说明它有纳米涂层"], "solve": "题干＝A→B、非B→非A（逆否，有效）；只有 B 同构（工匠→精益求精，要求不高→非优秀工匠），A/C/D 是因果倒推/否前/肯后。", "analysis": "**识别信号**：题干＝A→B、非B→非A（逆否，有效），问「最相似」 → 相似结构。\n**核心规律**：题干＝「A→B，非B→非A」（逆否，有效）；只有 B 同构；A/C/D 分别是因果倒推／**否前**／**肯后**，均无效。打法：结构相似＝先把题干压成 A→B，只看结论方向——**逆否（非B→非A）✓｜否前 ✗｜肯后 ✗**。\n**易混·易错链**：最像=**否前**（非A→非B，C）／**肯后**（B→A，D）／**因果倒推**（A）——与逆否只差一个位置｜撞坑链：只看选项「内容对称/生活通顺」就选，没核**被否定的是前件还是后件**。", "img": ""}]}]}, {"name": "充分必要条件式", "star": false, "children": [{"name": "定位**充分↔必要**（\"只要…就\"vs\"只有…才\"），方向相反即为干扰项", "star": false, "examples": [{"q": "不建立主体明确、要求清晰的责任体系，就不能压紧压实安全生产责任。当前主体明确、要求清晰的责任体系已经建立，因此安全生产责任已经压紧压实。下列选项与题干逻辑结构最为相似的是（ ）。", "src": "2026广东省考真题 第57题", "hit": false, "ans": "C", "opts": ["A.只有实行多元共治，才能构建和谐社区。某社区建成了和谐社区，因此该社区实行了多元共治", "B.不实现教育资源的公平分配，就无法提高全民素质。当前全民素质还有待提高，所以教育资源的公平分配还未实现", "C.如果某地区深入推进生态文明建设，那么该地区已经实现了资源循环利用。这是因为不深入推进生态文明建设，就无法实现资源循环利用", "D.如果合理开采资源，就能实现自然资源的可持续利用。多地政府已经出台法律法规禁止过度开采，因此许多地区已经实现了自然资源的可持续利用"], "solve": "题干＝「不A就不B，已知A∴B」＝**否定前件**式（把必要条件当充分条件用）；先给每个选项标「式名」，再找同名项。", "analysis": "**识别信号**：题干「不 A 就不 B，已知 A∴B」，问「逻辑结构最相似」 → 相似结构。\n**核心规律**：题干＝¬A→¬B，却由 A 推 B ⇒ **否定前件式（无效推理）**；逐项标式名对号（C 同款）。打法：**先标式名，再找同名**（肯前/否前/肯后/否后/传递）；本题题干式名＝**否定前件**。\n**易混·易错链**：最像=**翻译推理·必要条件翻译**（工具 vs 考法，翻译错式名就错）｜撞坑链：见「不…就…」就选同款项；被 A（有效式）／B（另一种无效式·肯定后件）迷惑。", "img": ""}]}]}, {"name": "选言式", "star": false, "children": [{"name": "\"**A或B**\"式二中择一，否定一支→析出另一支", "star": false, "examples": [{"q": "企业节能减排必须通过购买碳配额或自主开发减排项目实现。某企业未购买碳配额，因此该企业要节能减排需自主开发减排项目。下列选项与题干逻辑结构最为相似的是（ ）。", "src": "2026广东省考真题 第65题", "hit": false, "ans": "D", "opts": ["A.申请绿色产品认证的公司需通过专家评审或提交检测报告。某公司未提交过检测报告，因此该公司应当组织开展专家评审", "B.有的地区支持企业购买碳汇，有的地区则支持企业使用清洁能源。某地区支持企业使用清洁能源，因此该地区不支持企业购买碳汇", "C.企业申请创业补贴或者通过线上申请，或者通过线下窗口办理。某企业已经通过线上渠道提交了申请，因此无需前往线下窗口办理", "D.重点排放单位应通过安装监测设备或委托第三方核查排放情况。某企业属重点排放单位且未委托第三方核查排放情况，因此该企业需安装监测设备核查排放情况"], "solve": "题干＝「必须(A或B)，¬A ∴ B」的**否一推一**；同构项须同时满足「主体落入大前提 ＋ 否定一支⇒肯定另一支」。", "analysis": "**识别信号**：题干「必须(A或B)，¬A ∴ B」，问「逻辑结构最为相似」 → 相似结构。\n**核心规律**：题干＝(A 或 B) 且 ¬A ⇒ **B**（析取三段论，有效）；同构项须同时满足「**主体落入大前提**＋否定一支⇒肯定另一支」（D）。打法：**先验主体适用范围，再比「否定式」**；找「否一推一」同款骨架。\n**易混·易错链**：最像=**翻译推理·选言命题**（那里考「或/要么」相容性，这里考骨架是否同款）｜撞坑链：看选项也有「或」就选（A 句式最像却少主体承接）；被相容「或」vs 不相容「要么」混淆（C）。", "img": ""}]}]}, {"name": "否前/肯后陷阱", "star": false, "children": [{"name": "**否前、肯后**都是无效推理；选项若据此得结论即为同类结构陷阱", "star": false}]}]}, {"name": "解释型", "star": false, "children": [{"name": "矛盾现象定位", "star": false, "children": [{"name": "先找出**反差两方**（如\"涨价却未减销量\"），解释项须同时说明两侧", "star": false}]}, {"name": "补充新事实", "star": false, "children": [{"name": "正确项是**题干之外的补充事实**（成因/背景）；复述题干内容者不构成解释", "star": false}]}, {"name": "最不能解释（反向问法）", "star": false, "children": [{"name": "**先判问法方向**；选项中不触及矛盾点的即为答案（常为无关他因）", "star": false}]}, {"name": "反常识现象", "star": false, "children": [{"name": "答案须给出**隐性因果链**（如\"融水流入海洋而未留湖泊\"），点破预期与现实的错位", "star": false}]}]}, {"name": "论证缺陷（逻辑谬误）", "star": false, "children": [{"name": "充分必要混淆", "star": false, "children": [{"name": "把\"**只有A才B**\"误当\"**A→B**\"（必要条件当充分），由否定前件推否定后件", "star": false}]}, {"name": "因果倒置/强加因果", "star": false, "children": [{"name": "指出**因果方向相反**，或本无因果硬加因果", "star": false}]}, {"name": "以偏概全", "star": false, "children": [{"name": "**样本/个体特征**扩大为整体结论（部分→全部）", "star": false}]}, {"name": "偷换概念/偷换论题", "star": false, "children": [{"name": "同一关键词**前后含义漂移**，论证链条实则断裂", "star": false}]}, {"name": "不当类比", "star": false, "children": [{"name": "两类事物**本质属性不同**却强行类推", "star": false}]}]}]}, {"name": "科学推理", "star": false, "children": [{"name": "广东省考特色", "star": false, "children": [{"name": "力学", "star": false, "children": [{"name": "受力分析：按重力/支持力/摩擦力/拉力逐一画受力图，判平衡", "star": false, "examples": [{"q": "如图所示，几颗棋子叠放在一起，其中一颗突然被水平方向的外力击打，飞了出去。忽略空气阻力，则以下判断正确的有（ ）项。①棋子飞出的一瞬间，上方棋子所受合外力为0；②下方棋子所受的合外力始终为0；③棋子飞出的一瞬间，上方最下面的棋子受到了向下的压力；④在落地前，飞出去的棋子在水平方向上的速度恒定。", "src": "2026广东省考真题 第66题", "hit": false, "ans": "B", "opts": ["A.1", "B.2", "C.3", "D.4"], "solve": "①③错（上方棋子失重、无挤压）、②④对；选 B。判分点：①与③同源（都看上方是否失重），失重⇒①③必同错。", "analysis": "**识别信号**：情景题＋「判断正确的有几项」（棋子被击飞），问受力/运动 → 科学推理·力学。\n**核心规律**：①③**同源**——上方棋子失去支撑进入**完全失重** ⇒ 合外力＝重力≠0（否①）、内部无挤压（否③）；②下方棋子静止→合外力恒为 0；④水平不受力→水平速度恒定 → 对 2 项（B）。打法：受力分析→逐一画受力图判平衡；**「突然抽掉支撑⇒上方瞬间失重」⇒合外力=重力（不是 0）＋内部无挤压**；水平无外力⇒水平速度恒定。\n**易混·易错链**：最像=**平衡态**（合外力为 0；失重≠平衡）｜撞坑链：把「没飞出去的棋子看上去没动」判为合外力为 0；把「失重」误当「仍有叠压」；忘记「忽略空气阻力⇒水平匀速」。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/8-bc040bfbf1.jpg"}, {"q": "如图所示，实心铜方块放置在容器底部，沿容器内壁往容器内加入水，直至杯中完全装满水。下列选项中，最有可能正确反映方块对容器底部压力（p）随水深（h）变化情况的是（）。", "src": "2026广东省考真题 第67题", "hit": true, "ans": "D", "opts": ["A.A", "B.B", "C.C", "D.D"], "solve": "浮力随浸入增大 → 压力先减；没顶后浸入不变 → 浮力不变 → 压力恒定 → 先减后平，选 D。", "analysis": "**识别信号**：实心金属（铜/铁）块沉底、往容器加水、问「对底压力 p 随水深 h」的图象 → 先判浮力（水能否进到物体底面）。\n**核心规律**：p＝重力 G − 浮力 F浮；没顶前 F浮＝ρgSh 随浸入线性增大 → p 线性减小；没顶后 F浮＝ρgSH 恒定 → p 恒定，即**先减后平**。打法：先定「有无浮力」，再分「没顶前 / 没顶后」两段。\n**易混·易错链**：最像「贴底无浮力」变体（物体与底紧密接触、水进不去 → 无浮力 → 先平后升）；分法：看水能否到达底面——沿内壁加水/未密封→有浮力→先减后平；密封贴底→无浮力→先平后升。撞坑：漏掉「没顶后浮力不变」这段 → 误选一直下降。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/9-dd046a0230.jpg"}, {"q": "如图所示，通过夹物器匀速夹起表面粗糙的木块M1、M2、M3，木块M1、M2、M3始终保持相对静止，关于M1、M2、M3的受力情况，下列说法不正确的是（ ）。", "src": "2025广东省考真题 第67题", "hit": false, "ans": "C", "opts": ["A.木块M2受到的摩擦力的方向竖直向上", "B.木块M1、M3受到的摩擦力数量相等", "C.木块M1、M2、M3都受到两个方向相同的摩擦力", "D.木块M2作用于M1、M3的摩擦力方向与重力方向相同"], "solve": "中间块 M2 受两侧摩擦都向上（同向）；M1、M3 各受「夹爪向上＋邻块向下」两次反向摩擦 →「三个都同向」不成立，选 C。", "analysis": "**体系定位**：判断推理 → 科学推理（广东省考特色）→ 力学·受力分析（清单原单元）\n**识别信号**：题干见「夹起 / 夹住 / 匀速 / 相对静止 / 关于受力方向」⇒ 走**受力平衡＋逐块隔离**\n**本质**：竖直方向外部力**只有重力**，托力只能由**摩擦**承担；判方向要隔离到「某一块由谁托住」\n**通式**：整体 Σf(上)＝Σmg；隔离第 i 块 Σf(上,来自相邻接触面)＝mᵢg；界面摩擦方向＝与之平衡所需的方向\n**易混·易错链**：误把夹爪当「万能固定」（忘托力来自摩擦）→ 误判摩擦方向 → 混淆「数量 / 方向」→ 掉进 C", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/1-508f1e4571.png"}, {"q": "如图1所示，物体M在力F的作用下开始移动，其F-t图像、v-t图像如图2、图3所示，则下列说法正确的是（ ）。", "src": "2024广东省考真题 第68题", "hit": true, "ans": "D", "opts": ["A.在0-2s，力F对物体做正功", "B.在4-6s，物体所受的摩擦力不做功", "C.在4-6s，物体所受的合外力大于零", "D.物体所受的摩擦力在2-4s做的功与在6-8s做的功相等"], "solve": "先读 v-t 定运动状态（斜率=加速度、面积=位移），再看 4-6s 是否匀速——匀速⇒F合=0 但摩擦力仍做负功，随后比 2-4s 与 6-8s 位移即可，只有 D 成立。", "analysis": "- 体系定位：判断推理 → 科学推理 → **力学·受力分析**（清单原名）；上位＝广东省考特色·力学 → 本题（F-t/v-t 图求功与受力）→ 下级变式＝压强、匀变速。\n- 识别信号：题干给 F-t、v-t 图像并问「做功 / 合外力」→ 先读 v-t 定运动状态，再配 F-t 定受力。\n- 本质：内核＝**由运动图像反推受力**，再用功的定义判功；匀速 ⇒ F合=0 但摩擦力仍做功。\n- 通式：`W = F·s·cosθ`（摩擦力恒做负功）；v-t **斜率=加速度 a、面积=位移 s**；匀速段 `F合=0`。\n- 易混·易错链：最像「运动·匀变速」——分界：由 v-t 求位移/加速度→运动；由 F-t 结合受力求功/合外力→力学·受力分析；撞坑链＝把「匀速」当「不受力/不做功」，把「开始移动」当整段都有位移。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/3-c95b09ade0.png"}, {"q": "小明将一个小球竖直向上抛出，空气阻力不可忽略，小球的速度—时间图像如下图所示，在 0～t₂ 时间段内，下列说法正确的是（ ）。", "src": "26年省考35季 第66题", "hit": false, "ans": "D", "opts": ["A.小球受到的空气阻力不断减小", "B.空气阻力的方向始终向下", "C.小球的速度不断减小", "D.小球的加速度不断减小"], "solve": "小球在 0~t₂ 内先上升后下降，唯独「加速度」全程单调减小（上升 a=g+f/m 随 v↓而↓，下降 a=g−f/m 随 v↑而↓），其余三项都栽在「只有一段」。", "analysis": "- 体系定位：科学推理 → 广东省考特色 → 力学（受力分析与牛顿第二定律）；上位「受力分析」，本题＝**速度相关变力下的分段加速度判断**，下级变式＝恒定阻力/浮力/压强等定力场景。\n- 识别信号：出现「空气阻力 / 与运动方向相反 / 一段时间内 / v-t」且运动含往返 → 先分段再逐段判方向与大小。\n- 本质：阻力 f 大小随速率变、方向随速度反向翻转，代入 a=(mg±f)/m 后两段都令 a 单调减小——考的是变力动力学的定性分析。\n- 通式：上升 a=g+f/m（v↓→a↓）；下降 a=g−f/m（v↑→a↓）；全程 a 单调递减。同类判别：看到「空气阻力与速度有关＋先升后降」就分两段判 a。\n- 易混·易错链：最像「恒定阻力（如固定摩擦力）」题——恒力下加速度分段为定值；分界＝阻力是否随速率变化。常见撞坑：把「速度减小」误当全程（漏掉下降段）。", "img": "data:image/jpeg;base64,"}]}, {"name": "压强：P=F/S，据面积变化比较压强", "star": false}]}, {"name": "运动", "star": false, "children": [{"name": "匀变速：v=at、s=½at²，据加速度与时间定量", "star": false}, {"name": "平抛：竖直分量定时、水平分量定距，两分量独立", "star": false}]}, {"name": "电学", "star": false, "children": [{"name": "串并联：串联电流相等、并联电压相等，据欧姆定律算", "star": false, "examples": [{"q": "某款电热毯有3个档位，由一个开关控制。其中，0档为关机，1档为低功率加热，2档为高功率加热，则以下选项最可能是该款电热毯电路示意图的是（ ）。", "src": "2026广东省考真题 第68题", "hit": true, "ans": "A", "opts": ["A.A", "B.B", "C.C", "D.D"], "solve": "纯电阻负载、U 一定 → P=U²/R，高档必须电阻小；一个开关要凑出 0/1/2 三档，只能「断开 / 串阻 / 短阻」——只有 A 的开关跨在电阻上且能断开。", "analysis": "**体系定位**：判断推理 → 科学推理（广东省考特色）→ 电学·电功率与档位（体系位置：电学主干，紧邻欧姆定律 / 串并联）\n**识别信号**：电器「多档（高/低功率、调速、调光）＋一个开关控制＋给电路图问哪个最可能」→ 走「串并联＋电功率＋开关短接」\n**本质**：用开关改变接入回路的总电阻来改变功率——U 固定时，电阻大→低档、电阻小→高档、断开→关机\n**通式**：P=U²/R；档位数 = 开关能造出的接入状态数（断开算一档）；被短接的电阻「并入 = 0」\n**易混·易错链**：最像「电学·欧姆定律 / 串并联」（同用 I=U/R）；撞坑链：①误以为「高档=电阻大」（方向反）②把开关并到发热元件上（对象错）③只用通/断两态就以为凑齐三档（缺档）", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/1-7c09c06521.png"}]}, {"name": "欧姆定律：I=U/R，注意各量对应同一元件", "star": false}]}, {"name": "光学", "star": false, "children": [{"name": "反射/折射：反射入射角=反射角；折射从空气入水靠近法线", "star": false}]}, {"name": "化学", "star": false, "children": [{"name": "物质性质：据金属活动性/酸碱中和判反应能否发生，记特征现象", "star": false, "examples": [{"q": "有一种传统的制墨工艺：把冷碟子放在蜡烛火焰的上方，蜡烛燃烧一段时间后，冷碟子底部会有黑色物质生成，黑色物质经过进一步加工可以变成墨，则以下说法有误的是（ ）。", "src": "2024广东省考真题 第66题", "hit": false, "ans": "A", "opts": ["A.所使用的蜡烛由该黑色物质和其他材料混合制成", "B.该黑色物质具有还原性", "C.冷碟子会影响蜡烛燃烧过程中氧气的补充，导致蜡烛不完全燃烧", "D.冷碟子能冷却底部的黑色物质，使其无法燃烧"], "solve": "蜡烛是**石蜡**做的，黑色物质是**不完全燃烧生成的炭黑**（原料 vs 生成物）→ A 说反了，==有误==。", "analysis": "- 体系定位：判断推理 → 科学推理 → 广东省考特色 → 化学（清单原名：**化学·物质性质**）；体系位置：上位＝科学推理，本题＝燃烧 / 物质推断，下级变式＝物质鉴别、反应现象判断。\n- 识别信号：题干出现**生活工艺 / 燃烧现象**（变黑、冒烟、有气体生成）→ 先判断**生成物是什么**，再据其性质（可燃 / 还原 / 助燃）逐条验证。\n- 本质：内核＝**物质的性质与变化**：弄清\"原料是什么、生成物是什么、反应条件（氧气是否充足）\"；判分点＝据物质性质判反应能否发生、记特征现象。\n- 通式：无固定式，按\"**认原料 → 定生成物 → 用性质验证**\"三步走；\"有误 / 不正确\"题＝找出与事实相反的那一条。\n- 易混·易错链：最像的是**物理变化 vs 化学变化**（燃烧属化学变化）；撞坑链：把\"不完全燃烧的炭黑\"误当蜡烛原料 → 判错 A，或把\"碳的还原性\"错记成氧化性 → 误判 B。", "img": ""}, {"q": "下列有关实验现象的表述，正确的是（ ）。", "src": "26年省考35季 第68题", "hit": false, "ans": "C", "opts": ["A.打开盛有浓硫酸的试剂瓶，瓶口立即出现大量白雾", "B.向酚酞溶液中加入氢氧化铝，溶液变红", "C.向澄清石灰水中通入过量二氧化碳，溶液最终呈现澄清状态", "D.铁丝在空气中点燃会剧烈燃烧、火星四射、生成黑色固体"], "solve": "过量 CO₂ 把不溶的 CaCO₃ 转成可溶 Ca(HCO₃)₂，石灰水「先浑后清」；其余三项现象都是张冠李戴。", "analysis": "- 体系定位：科学推理 → 广东省考特色 → 化学（常见物质的性质与实验现象）；上位「物质性质」，本题＝现象真伪判断，下级变式＝气体鉴别/除杂/离子检验。\n- 识别信号：出现「试剂瓶 / 白雾 / 酚酞 / 澄清石灰水 / 铁丝燃烧」等实验描述 → 逐项套物质性质口诀。\n- 本质：考「挥发性·酸碱性·溶解性·燃烧条件」与现象的对应，错项多把某物质的现象挪到另一物质上。\n- 通式：现象判断＝「物质性质 → 现象」。同类判别：看「白雾」先查挥发性（盐酸/硝酸才有）、看「变红」先查碱性、看「浑浊后又澄清」想 CO₂ 过量、看「火星四射」必是纯氧。\n- 易混·易错链：最像「浓盐酸白雾 ↔ 浓硫酸无白雾」；撞坑＝把「铁丝在氧气中」火星四射套到「空气中」。", "img": ""}]}]}, {"name": "地理", "star": false, "children": [{"name": "天气系统（锋面雨）：暖湿空气沿锋面抬升、冷却凝结致雨——下冷上暖、暖升冷垫", "star": false, "examples": [{"q": "锋面雨的形成与夏季风的暖湿气流和冬季风干冷气流相遇有关，是冷暖空气交汇形成的降雨现象，主要在每年的4到5月影响我国华南地区。下列示意图最有可能正确反映锋面雨形成原理的是（ ）。", "src": "2026广东省考真题 第69题", "hit": true, "ans": "D", "opts": ["A.A", "B.B", "C.C", "D.D"], "solve": "锋面雨＝暖湿空气被抬升冷却凝结；图中应「暖空气沿倾斜锋面往上爬、冷空气贴地当楔子」——只有 D 符合。", "analysis": "**体系定位**：判断推理 → 科学推理 → 地理·天气系统（锋面雨）（体系位置：自然地理气象分支；清单暂无此单元，待核）\n**识别信号**：题干「……的形成/原理」「气流相遇」「示意图最可能正确反映」→ 原理—示意图匹配题\n**本质**：暖气团被抬升到冷气团之上、冷却凝结致雨——**下冷上暖、暖升冷垫**\n**通式**：判谁被抬升（轻/湿/暖）→ 谁在下（重/干/冷）→ 锋面朝冷气团一侧倾 → 云雨落在抬升处 / 冷气团一侧\n**易混·易错链**：最像「对流雨 / 地形雨」（都靠抬升成雨）；撞坑链：①抬升方画成冷空气（方向反）②冷暖上下画反 ③雨区画到暖侧或远离锋面（位置错）", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/1-3dfbb45abe.png"}, {"q": "根据某地等高线地形图，下列说法最不可能属实的是（ ）。", "src": "2024广东省考真题 第67题", "hit": false, "ans": "B", "opts": ["A.图中A处是海拔400米以上露营的最佳选择地", "B.图中B处发展耕作业比发展林业更合适", "C.图中C处可能发育河流", "D.图中D处适合攀岩活动"], "solve": "等高线密集＝坡陡，陡坡**宜林不宜耕**；B 却说\"耕地比林业更合适\"→ 与坡地利用原理相反，==最不可能属实==。", "analysis": "- 体系定位：判断推理 → 科学推理 → 广东省考特色 → 地理（清单未列具体单元，本题可记 **地理·等高线地形图**；建议在〈广东省考特色〉下新增〈地理·等高线地形图〉（待核））；体系位置：上位＝科学推理，本题＝等高线地形判读，下级变式＝地形部位判定、河流 / 攀岩 / 露营选址。\n- 识别信号：题干出现**等高线地形图 + 选址**（露营 / 耕地 / 攀岩 / 河流）→ 先按\"**密陡疏缓、凸高等谷、重合陡崖**\"读地形部位，再套选址常识。\n- 本质：内核＝由**等高线疏密与凸向**读地形部位，再据\"陡坡宜林、谷地有河、陡崖可攀、缓坡可营\"做选址；判分点＝地形部位与人类活动是否匹配。\n- 通式：无固定式，按\"**读疏密/凸向 → 定地形部位 → 套选址常识**\"三步走；\"最不可能属实\"题＝找违背原理的那一条。\n- 易混·易错链：最像的是**山脊 vs 山谷**（等高线凸向低处为山脊、凸向高处为山谷，只有山谷可能发育河流）；撞坑链：把陡坡当缓坡 → 误判耕地条件 → 错选 B 以外的项。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/4-d5387dc56a.png"}, {"q": "如果某地一年中只有一次太阳直射，则该地可能位于（ ）。", "src": "26年省考35季 第70题", "hit": false, "ans": "B", "opts": ["A.赤道上", "B.北回归线上", "C.北极圈以内", "D.南温带区域"], "solve": "太阳直射只发生在南北回归线及其之间——回归线上一年**一次**、回归线之间（含赤道）一年**两次**、回归线以外**零次**；「只有一次」只能锁定回归线。", "analysis": "- 体系定位：科学推理 → 广东省考特色 → 地理（地球运动与太阳直射）；上位「地球运动」，本题＝直射频次判断，下级变式＝昼夜长短/正午太阳高度/极昼极夜。\n- 识别信号：出现「太阳直射 / 回归线 / 极圈 / 温带 / 一年几次」→ 先画「回归线之间」的直射带。\n- 本质：太阳直射点只在南北回归线间往返，某地直射次数**仅由纬度**决定，与经度、季节无关。\n- 通式：直射次数 `n`：回归线之间（不含回归线）`n=2`；回归线上 `n=1`；回归线以外 `n=0`。同类判别：看到「一年只有一次直射」→ 直接锁定回归线。\n- 易混·易错链：最像「赤道 ↔ 回归线」——赤道一年两次、回归线一年一次；撞坑＝把赤道当成一次直射、或误以为极圈内有直射。", "img": ""}]}]}, {"name": "生物", "star": false, "children": [{"name": "食物网与营养级：食物链只含生产者+消费者；营养级＝该环在链中的位次，逐条数清", "star": false, "examples": [{"q": "下图为海洋生态系统中部分生物之间的捕食关系，则以下有关说法正确的是（ ）。", "src": "2026广东省考真题 第70题", "hit": true, "ans": "C", "opts": ["A.磷虾大量减少会对该系统产生毁灭性的影响", "B.该食物网中包括了生产者、消费者以及分解者", "C.图中最短的食物链有3个营养级", "D.该食物网共涉及6条食物链"], "solve": "食物网＝多条食物链交织；按图逐条数链——共 5 条，最短链（藻类→鳕鱼→海豹）恰 3 个营养级；分解者不进入食物链 → C。", "analysis": "**体系定位**：判断推理 → 科学推理 → 生物·食物网与营养级（体系位置：清单暂无生物单元，建议新增）\n**识别信号**：出现「捕食关系图 / 食物网 / 食物链 / 营养级 / 生产者 / 消费者 / 分解者」任一 → 锁定本单元\n**本质**：食物网＝多条食物链交织成的网；营养级＝该生物在某条链中的进食层级（生产者＝第 1 级，逐级 +1）\n**通式**：食物链＝生产者→初级消费者→…→最高营养级；营养级号＝该环在链中的位次；相邻环用「—被吃→」连接\n**易混·易错链**：①食物链**不含分解者**（最常与「生态系统成分」混）②同一生物不同链营养级可能不同（鳕鱼：吃藻＝2 级／吃磷虾＝3 级）③求「最短链」必须先逐条数清 ④「6 条」数量词陷阱", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/1-88b1dfb127.png"}, {"q": "下图为某草原生态系统中的食物网的示意图，下列说法正确的是（  ）。", "src": "26年省考34季 第69题", "hit": true, "ans": "C", "opts": ["A.该食物网中共有8条食物链", "B.该生态系统中的能量最终来源于草", "C.蛇与狐狸之间既存在捕食关系，也存在竞争关系", "D.蛇在该食物网的所有食物链中均属于第三营养级"], "solve": "抓两条生态铁律——能量**最终**来源是太阳能（排 B），同一对生物可「既捕食又竞争」（C 对），营养级要按链具体数、不能说「均」（排 D），食物链数须从生产者逐条数（排 A）。", "analysis": "- 体系定位：判断推理（科学推理）→ 科学推理 → 广东省考特色 → 生物（清单「科学推理（广东省考特色）」现列 力学/运动/电学/光学/化学，**生物**未列，建议在〈科学推理·广东省考特色〉下新增〈生物·生态系统（食物网/营养级）〉（待核））；上位＝科学推理定性判断，本题＝生态系统结构关系辨析，下级变式＝能量流动、物质循环、种间关系。\n- 识别信号：题干出现「食物网 / 食物链 / 营养级 / 能量来源 / 捕食、竞争」→ 立刻切「生物·生态系统」，先标生产者再逐链分析。\n- 本质：一句话——考「食物网的结构规则」：链必自生产者、营养级按环计、能量最终源太阳能、同种间关系可并存（原判分点：据图解与生态学基本规律逐项定性判断）。\n- 通式：食物链条数 = 从每条起点(生产者)到每个终点的路径数；营养级 = 该生物在链中的序位（生产者=第一营养级）；能量最终来源 = 太阳能；全程定性判断，无需计算。\n- 易混·易错链：最像的是「能量流动」中的能量来源/去向（源是太阳能、逐级递减，非「来源于草」）；撞坑链：把「捕食」与「竞争」对立、认为只能取其一 → 营养级按某种生物死记固定级别 → 数链时把不完整的链也算进去。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/pd/5-babe9cbe3a.png"}, {"q": "胰岛素是一种蛋白质，可以用于治疗糖尿病。以下有关胰岛素的说法，正确的是（ ）。", "src": "2024广东省考真题 第70题", "hit": false, "ans": "D", "opts": ["A.胰岛素能够抑制血糖分解", "B.人体中的胰岛素由肝脏分泌", "C.一般通过口服胰岛素治疗糖尿病", "D.血液中的胰岛素浓度过高会导致低血糖"], "solve": "胰岛素**降血糖**（促糖摄取、合成糖原），过量则血糖过低 → 浓度过高致低血糖，==D 正确==。", "analysis": "- 体系定位：判断推理 → 科学推理 → 广东省考特色 → 生物（清单未列具体单元，本题可记 **生物·人体生理**；建议在〈广东省考特色〉下新增〈生物·人体生理〉（待核））；体系位置：上位＝科学推理，本题＝人体激素与生理，下级变式＝激素功能、消化吸收、代谢紊乱。\n- 识别信号：题干出现**人体器官 / 激素 / 代谢**（胰岛素、血糖、消化）→ 先回忆该物质的**分泌器官 + 核心功能**，再逐条核对。\n- 本质：内核＝**激素的分泌源与生理功能**（谁分泌、起什么作用、过量 / 不足的后果）；判分点＝功能方向（升糖 / 降糖、升高 / 降低）与给药途径。\n- 通式：无固定式，按\"**定物质 → 查分泌源 → 用功能与性质逐条验证**\"三步走；\"正确的是\"题＝找出与生理事实相符的那一条。\n- 易混·易错链：最像的是**胰高血糖素 vs 胰岛素**（前者升血糖、后者降血糖，作用相反）；撞坑链：把\"降糖\"误解成\"抑制分解\"→ 误选 A，或忽略\"蛋白质口服易失活\"→ 误选 C。", "img": ""}]}]}]}]}]}, "常识应用": {"color": "indigo", "modules": {"马克思主义": "indigo", "毛泽东思想": "emerald", "中国特色社会主义理论体系": "fuchsia", "习近平新时代中国特色社会主义思想": "amber", "政策文件": "sky", "党的建设": "rose", "经济": "violet", "民生 / 生态 / 科技 / 安全 / 军队 / 文化 / 外交": "teal", "法律": "indigo", "经济常识": "emerald", "科技常识": "fuchsia", "人文常识": "amber", "地理常识": "sky", "生活常识": "rose", "广东省情": "violet"}, "root": {"name": "常识应用", "signal": "政治理论抓表述与时间线；常识靠积累与排除；广东省情要专门记"}, "branches": [{"name": "马克思主义", "star": false, "children": [{"name": "唯物辩证法", "star": false, "children": [{"name": "矛盾（对立统一规律）：矛盾即对立统一，双方相互依存、相互转化；\"危中有机\"\"居安思危\"\"变压力为动力\"＝对立统一", "star": false, "examples": [{"q": "（多选题）矛盾是反映事物内部或者事物之间对立统一关系的哲学范畴。矛盾的同一性是指矛盾着的对立面相互依存、相互贯通的性质和趋势。关于矛盾的同一性，以下表述正确的有（ ）。", "src": "2024广东省考真题 第12题", "hit": false, "ans": "ABC", "opts": ["A.在矛盾双方中，一方的发展以另一方的发展为条件", "B.矛盾双方相互吸取有利于自身的因素，在相互作用中各自得到发展", "C.事物的发展方向、趋势不是随意的，而是有规律地向自己的对立面转化", "D.矛盾双方的统一是一种矛盾统一体向另一种矛盾统一体过渡的决定性力量"], "solve": "题干已给死定义——同一性＝**相互依存＋相互贯通（转化）**；A（互为发展条件）＝依存，B（相互吸取共同发展）＝贯通，C（向对立面转化）＝贯通，皆属同一性；D 把\"矛盾统一体过渡的**决定性力量**\"（其实是**斗争性**的作用）安给同一性，直接毙。", "analysis": "- 体系定位：常识判断 → 马克思主义 → 唯物辩证法 → 矛盾（对立统一规律）（清单原名）｜体系位置：上位＝对立统一规律（同一性＋斗争性）→ 本题＝同一性的两大表现（依存＋贯通/转化）→ 下级变式＝矛盾普遍性与特殊性、主次矛盾/主次方面、质量互变、否定之否定。\n- 识别信号：题干直接给\"××的性质/内涵……以下表述正确的有\"＝**概念内涵辨析题**；看到\"决定性力量/根源/动力/推动\"就追问\"这到底是同一性还是斗争性的作用\"。\n- 本质：考**同一性与斗争性的分工**——同一性管\"相互依存、相互贯通(转化)\"，斗争性管\"相互排斥、推动统一体分解转化、是矛盾发展的决定性力量\"（判分点：A/B/C 属同一性，D 属斗争性）。\n- 通式：无固定式；按\"**先锁题干定义 → 逐项比对是否落在定义表现内 → 凡讲'决定性力量/根源/动力'的，先查归属（同一性 or 斗争性）**\"三步判。\n- 易混·易错链：最像＝**矛盾的斗争性**（同一性讲\"联结、依存、转化\"；斗争性讲\"排斥、推动分解转化、是发展动力\"）；撞坑链：①把\"发展的决定性力量\"误安给同一性；②把\"矛盾双方相互转化\"误当斗争性；③同一性相对有条件 vs 斗争性绝对无条件搞反。", "img": ""}]}, {"name": "矛盾的普遍性与特殊性：普遍性寓于特殊性之中，通过特殊性表现；\"试点先行、逐步推广\"\"中国特色\"＝普遍性与特殊性统一", "star": false}, {"name": "主要矛盾与次要矛盾：主要矛盾决定事物发展进程，要集中力量抓主要矛盾；\"牵牛鼻子\"\"集中力量办大事\"＝抓主要矛盾（办事层面）", "star": false}, {"name": "矛盾的主要方面与次要方面：主要方面决定事物性质；\"主流\"\"总体是好的，但也有…\"＝抓矛盾主要方面（看性质层面；与\"主要矛盾\"易混）", "star": false}, {"name": "质量互变规律：量变是质变的必要准备，质变是量变的必然结果；\"积土成山\"\"千里之堤溃于蚁穴\"\"一棒一棒接着干\"＝量变到质变", "star": false}, {"name": "否定之否定规律：辩证否定＝既克服又保留（扬弃），非全盘否定；\"取其精华去其糟粕\"\"推陈出新\"＝辩证否定", "star": false}, {"name": "联系观（普遍联系 / 整体与部分）：联系具普遍性、客观性、多样性；整体与部分相互影响；\"牵一发而动全身\"\"系统观念\"\"下好全国一盘棋\"＝普遍联系/整体与部分", "star": false}, {"name": "发展观：发展的实质是新事物取代旧事物，前途光明、道路曲折；\"沉舟侧畔千帆过，病树前头万木春\"＝新事物必然战胜旧事物", "star": false}]}, {"name": "唯物论", "star": false, "children": [{"name": "物质与意识：物质决定意识，意识具有能动作用；\"从实际出发\"\"因地制宜\"＝物质决定意识；\"发挥主观能动性\"\"精神力量\"＝意识反作用", "star": false, "examples": [{"q": "（多选题）物质范畴是一切唯物主义哲学的理论基石。马克思主义的物质范畴是一个高度抽象的哲学概念，是对世界上客观存在的各种事物共同本质的概括。关于马克思主义的物质范畴，下列选项正确的有（　　）。", "src": "2026广东省考真题 第10题", "hit": false, "ans": "ACD", "opts": ["A.物质的根本属性是运动", "B.世界的本原是多种物质的集合", "C.物质是标志客观实在的哲学范畴", "D.物质资料的生产方式构成了人类社会存在的基础"], "solve": "B 以「集合」偷换「本原」：世界的本原是**物质**这一哲学范畴（一元论），不是「多种物质形态的集合」（多元论）。", "analysis": "**识别信号**：题干点明「物质范畴是……高度抽象的哲学概念」；选项出现「本原/根本属性/唯一特性/客观实在」等定性词 ＋ 一个「多种……集合」类偷换。\n**核心规律**：哲学物质＝标志客观实在的哲学范畴（列宁定义）；**本原只能是「物质」这一哲学范畴（一元论），不是具体物质形态的加总**；根本属性＝运动、唯一特性＝客观实在性（判分点并入：逐词对位，凡把「本原」说成「具体东西之和」即错）。打法：名词三连——物质＝「唯一特性·客观实在性」/「根本属性·运动」/「存在方式·运动」；凡表述出现「本原是各种具体东西的集合/总和」→ **直接判错**。\n**易混·易错链**：最像＝**唯物论·物质与意识**（问「意识能否反作用于物质 / 主观能动性」）；怎么分：问「物质是*什么*、本原/属性」→ 看物质观，问「意识能不能*反作用*」→ 看物质与意识。撞坑链：见「多种……集合」就选 B（没抓宾语）；把「根本属性」当「唯一特性」而犹豫不选 A；多选**错选即整题零分**。", "img": ""}]}, {"name": "规律的客观性与主观能动性：尊重客观规律是正确发挥主观能动性的前提，发挥主观能动性才能认识利用规律；\"按规律办事＋科学决策\"＝二者统一", "star": false}]}, {"name": "认识论", "star": false, "children": [{"name": "实践与认识：\"纸上得来终觉浅，绝知此事要躬行\"＝实践是认识的来源；认识随实践发展而深化", "star": false}, {"name": "真理的属性：真理具客观性、具体性、条件性，是绝对性与相对性的统一；\"真理多走半步即成谬误\"＝真理的条件性", "star": false}, {"name": "实践是检验真理的唯一标准：只有社会实践是检验真理的唯一标准（权威、多数、有用、经典都不是标准）", "star": false}]}, {"name": "历史唯物主义", "star": false, "children": [{"name": "社会存在与社会意识：社会存在决定社会意识，社会意识具相对独立性（可超前或滞后于社会存在）", "star": false, "examples": [{"q": "（多选题）马克思主义道德观认为，人类社会的实际情况是“物质生活的生产方式制约着整个社会生活、政治生活和精神生活的过程。”关于道德起源问题，以下认识正确的有（ ）。", "src": "2024广东省考真题 第14题", "hit": false, "ans": "ACD", "opts": ["A.劳动是道德起源的首要前提", "B.道德起源于人与生俱来的善性", "C.社会关系是道德赖以产生的客观条件", "D.人的自我意识是道德产生的主观条件"], "solve": "套\"马克思主义道德起源三要件\"——**劳动＝首要前提（A）＋社会关系＝客观条件（C）＋自我意识＝主观条件（D）**，三者齐对；B\"与生俱来的善性\"是先验天赋论，反马克思主义，直接毙。", "analysis": "- 体系定位：常识判断 → 马克思主义 → 历史唯物主义 → 社会存在与社会意识（清单原名）｜体系位置：上位＝社会存在决定社会意识 → 本题＝道德（一种社会意识）的起源机理 → 下级变式＝道德的客观条件/主观条件、社会意识的相对独立性。（清单暂无\"道德起源\"单元，建议在〈历史唯物主义〉下新增〈道德起源〉，待核）\n- 识别信号：题干出现\"**道德起源**\"\"××的来源/产生条件\"＋引马克思主义经典表述＝**唯物史观概念判断题**；看到\"与生俱来/天赋/善性\"先判**先验论=错**。\n- 本质：考**道德起源的马克思主义解释**——道德不是天生的、也不是神授的，而是**社会实践（劳动）的产物**；劳动为首要前提，社会关系为客观条件，自我意识为主观条件（判分点：三要件齐 A/C/D 对；先天善性 B 错）。\n- 通式：无固定式；按\"**先锚理论（是否唯物/实践立场）→ 再用'劳动—关系—意识'三要件对号 → 凡'天生/神授/善性'一律判错**\"三步判。\n- 易混·易错链：最像＝**社会存在与社会意识的关系**（本题是其在道德领域的应用：社会存在决定社会意识，故道德源于社会实践）；撞坑链：①把\"善性\"\"天赋\"当道德起源（唯心先验）；②只承认客观条件（社会关系）而漏掉主观条件（自我意识）；③把\"劳动\"作用弱化为一般因素，忽略其\"首要前提\"地位。", "img": ""}]}, {"name": "生产力与生产关系：生产力决定生产关系，生产关系反作用于生产力；生产关系一定要适合生产力状况", "star": false, "examples": [{"q": "（判断题）生产关系是人类社会发展的根本动力，也是一切社会变迁和政治变革的终极原因。", "src": "2026广东省考真题 第4题", "hit": false, "ans": "B", "opts": ["A.正确", "B.错误"], "solve": "根本动力归「社会基本矛盾」、终极原因归「生产方式（及交换方式）的变更」；单个「生产关系」只是反作用项 → 秒判错", "analysis": "**识别信号**：判断题给**一个对象挂两个最高头衔**（如「根本动力＋终极原因」）；题干出现「根本动力 / 终极原因 / 最终决定力量 / 根本标准」。\n**核心规律**：头衔与主体必须绑定核对——**根本动力＝社会基本矛盾；终极原因＝生产方式（及交换方式）的变更；最终决定力量/最高标准＝生产力；生产关系只被决定＋反作用**（判分点并入：本题把更大范围的「社会基本矛盾/生产方式」压成更小的「生产关系」，属张冠李戴＋以偏概全）。打法：见「X 是……的根本动力/终极原因/最终决定力量」→ 先做**头衔—主体绑定核对**，对不上表即判错；判断题把一句话拆成两半各自独立验，**任一半错整题即错**。\n**易混·易错链**：最像＝**生产力**（「最革命最活跃、最终决定力量」）；怎么分：根本动力标准答案＝社会基本矛盾、终极原因＝生产方式，生产力只承担「最终决定」角色，**表述不可互换**。撞坑链：生产力/生产关系高频并列 → 误当万金油把「根本动力」也划给生产关系；「根本动力 ≠ 最终决定力量」不区分；忘了马恩原话落点是「生产方式（及交换方式）的变更」。", "img": ""}]}, {"name": "经济基础与上层建筑：经济基础决定上层建筑，上层建筑反作用于经济基础（适合则促进、不适合则阻碍）", "star": false}, {"name": "人民群众是历史创造者：人民群众是物质财富、精神财富的创造者，是社会变革的决定力量；\"人民至上\"\"问需于民、问计于民\"＝群众观点", "star": false}]}, {"name": "政治经济学", "star": false, "children": [{"name": "商品二因素与劳动二重性：商品二因素＝使用价值＋价值；具体劳动创造使用价值，抽象劳动创造价值；劳动是价值的唯一源泉", "star": false}, {"name": "剩余价值：剩余价值由雇佣工人在剩余劳动时间创造、被资本家无偿占有，源于生产领域而非流通领域", "star": false}, {"name": "资本：资本是能带来剩余价值的价值；按在剩余价值生产中作用分不变资本/可变资本；资本积累加剧资本主义基本矛盾", "star": false}]}, {"name": "科学社会主义", "star": false, "children": [{"name": "从空想到科学：1848 年《共产党宣言》发表标志马克思主义诞生；唯物史观＋剩余价值学说使社会主义由空想变为科学", "star": false}]}, {"name": "古语/诗句蕴含哲理匹配", "star": false, "children": [{"name": "居安思危＝矛盾相互转化/忧患意识；积土成山＝量变到质变；纸上得来终觉浅＝实践是认识来源；沉舟侧畔千帆过＝新事物战胜旧事物", "star": false}]}]}, {"name": "毛泽东思想", "star": false, "children": [{"name": "活的灵魂", "star": false, "children": [{"name": "实事求是、群众路线、独立自主（实事求是＝精髓）", "star": false, "examples": [{"q": "（多选题）中国共产党在领导人民进行革命、建设、改革的长期实践中，逐步形成和确定了一条正确的思想路线……这条思想路线是中国共产党对马克思主义理论发展作出的重大贡献，其核心是实事求是。关于“实事求是”，以下表述正确的有（　　）。", "src": "2026广东省考真题 第9题", "hit": false, "ans": "BD", "opts": ["A.想问题、做决策、办事情，应当从本本出发", "B.实事求是是中国共产党人的基本思想方法、工作方法和领导方法", "C.坚持实事求是，最基础的工作在于“求是”，关键在于搞清楚“事实”", "D.实事求是是党领导人民推动中国革命、建设、改革事业不断取得胜利的重要法宝"], "solve": "两处一动即错：①谁把「本本」当出发点（A＝教条主义）②谁把「实事／求是」的定位对调（C）；B、D 是照抄本质表述，故全对。", "analysis": "**识别信号**：多选题谈「党的思想路线 / 实事求是」；选项出现成对概念定位词（基础/关键、前提/结果）顺序可疑，或「从本本出发」。\n**核心规律**：表述题＝**逐字对位题**；实事求是＝精髓/核心（判分点并入），是党的「基本思想方法、工作方法、领导方法」、是重要法宝——照抄本质表述的即对；改一字/换一位即错（「从本本出发」＝教条主义；「最基础＝搞清事实、关键＝求是」的先后不能对调）。打法：多选表述题专盯**成对概念**（基础/关键、前提/结果、手段/目的）的先后顺序，**顺序反了一切皆错**；教科书原句越像口号越可能是正确项。\n**易混·易错链**：最像＝**党建·树立和践行正确政绩观**；怎么分：问「是什么（思想路线核心/方法）」→ 活的灵魂，问「干部怎么干（反对形象工程、创造实绩）」→ 正确政绩观。撞坑链：凭语感把 B、D 当「像口号」优先排除；C 因「求是/事实」字面熟悉而漏做逐词对位；多选**少选/错选均不得分**。", "img": ""}]}]}, {"name": "新民主主义革命理论", "star": false, "children": [{"name": "新民主主义革命是无产阶级领导的、人民大众的、反帝反封建的资产阶级民主革命；道路＝农村包围城市、武装夺取政权", "star": false}]}, {"name": "三大法宝", "star": false, "children": [{"name": "统一战线、武装斗争、党的建设", "star": false}]}, {"name": "社会主义改造", "star": false, "children": [{"name": "一化三改（工业化＋对农业、手工业、资本主义工商业的社会主义改造）；对资本主义工商业实行和平赎买", "star": false}]}, {"name": "两类矛盾学说", "star": false, "children": [{"name": "敌我矛盾（对抗性，专政方法）＋人民内部矛盾（非对抗性，民主/团结—批评—团结方法）", "star": false}]}]}, {"name": "中国特色社会主义理论体系", "star": false, "children": [{"name": "邓小平理论", "star": false, "children": [{"name": "主题与精髓", "star": false, "children": [{"name": "主题＝什么是社会主义、怎样建设社会主义；精髓＝解放思想、实事求是；社会主义本质＝解放和发展生产力，消灭剥削、消除两极分化，最终达到共同富裕", "star": false}]}, {"name": "社会主义初级阶段基本路线", "star": false, "children": [{"name": "一个中心、两个基本点（以经济建设为中心，坚持四项基本原则、坚持改革开放）", "star": false}]}]}, {"name": "\"三个代表\"重要思想", "star": false, "children": [{"name": "要点", "star": false, "children": [{"name": "始终代表中国先进生产力的发展要求、先进文化的前进方向、最广大人民的根本利益（江泽民）", "star": false}]}]}, {"name": "科学发展观", "star": false, "children": [{"name": "要点", "star": false, "children": [{"name": "第一要义＝发展，核心立场＝以人为本，基本要求＝全面协调可持续，根本方法＝统筹兼顾（胡锦涛）", "star": false}]}]}]}, {"name": "习近平新时代中国特色社会主义思想", "star": false, "children": [{"name": "习近平新思想", "star": false, "children": [{"name": "\"十个明确\"", "star": false, "children": [{"name": "中国特色社会主义最本质特征＝中国共产党领导；含总任务、社会主要矛盾、总体布局等（是\"明确\"层面）", "star": false}]}, {"name": "\"十四个坚持\"基本方略", "star": false, "children": [{"name": "坚持党对一切工作的领导、坚持以人民为中心、坚持全面深化改革、坚持新发展理念等（是\"坚持\"层面，勿与\"十个明确\"混）", "star": false}]}, {"name": "\"两个确立\"\"两个维护\"", "star": false, "children": [{"name": "两个确立＝确立核心地位、确立指导思想指导地位；两个维护＝维护核心、维护党中央权威和集中统一领导", "star": false}]}, {"name": "\"三新一高\"", "star": false, "children": [{"name": "新发展阶段、新发展理念（创新协调绿色开放共享）、新发展格局（以国内大循环为主体、国内国际双循环相互促进）、高质量发展", "star": false}]}, {"name": "中国式现代化", "star": false, "children": [{"name": "本质特征＝中国共产党领导；中国特色五条＝人口规模巨大、全体人民共同富裕、物质文明和精神文明相协调、人与自然和谐共生、走和平发展道路", "star": false}]}, {"name": "\"六个必须坚持\"", "star": false, "children": [{"name": "必须坚持人民至上、自信自立、守正创新、问题导向、系统观念、胸怀天下", "star": false}]}, {"name": "社会主要矛盾", "star": false, "children": [{"name": "人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾", "star": false}]}, {"name": "社会主义核心价值观", "star": false, "children": [{"name": "国家＝富强、民主、文明、和谐；社会＝自由、平等、公正、法治；个人＝爱国、敬业、诚信、友善", "star": false}]}]}]}, {"name": "政策文件", "star": false, "children": [{"name": "二十届三中全会《决定》", "star": false, "children": [{"name": "总纲·原则", "star": false, "children": [{"name": "总目标与时间表：总目标＝继续完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化；到 2029 年（新中国成立 80 周年）完成本决定提出的改革任务", "star": false}, {"name": "六条原则：坚持党的全面领导、坚持以人民为中心、坚持守正创新、坚持以制度建设为主线、坚持全面依法治国、坚持系统观念", "star": false}, {"name": "\"七个聚焦\"：聚焦经济体制、国家治理、文化强国、民生、生态、国家安全、党的领导（勿混入\"原则\"\"板块\"）", "star": false}]}, {"name": "各板块", "star": false, "children": [{"name": "文化板块：优质文化资源直达基层、国际传播效能、中心环节＝激发全民族文化创新创造活力；\"社会效益放在首位、社会效益和经济效益相统一\"是正确原文", "star": false}, {"name": "经济体制板块：高水平社会主义市场经济体制是中国式现代化的重要保障；构建全国统一大市场；落实\"两个毫不动摇\"", "star": false}, {"name": "民生板块：在发展中保障和改善民生是中国式现代化的重大任务；健全社会保障体系；关注\"一老一小\"", "star": false}, {"name": "生态文明板块：完善生态文明基础体制、健全绿色低碳发展机制；加快完善落实\"绿水青山就是金山银山\"体制机制", "star": false}, {"name": "国家安全板块：推进国家安全体系和能力现代化；构建联动高效的国家安全防护体系", "star": false}, {"name": "党的领导板块：提高党对进一步全面深化改革的领导水平；坚持党中央对改革的集中统一领导", "star": false}]}]}, {"name": "二十届四中全会", "star": false, "children": [{"name": "\"十五五\"规划建议", "star": false, "children": [{"name": "2025 年 10 月二十届四中全会审议通过关于制定\"十五五\"规划的建议；\"十五五\"＝2026—2030 年（勿与《决定》混）", "star": false}]}]}, {"name": "\"十五五\"", "star": false, "children": [{"name": "科技自立自强", "star": false, "children": [{"name": "推动科技创新和产业创新深度融合；强化企业科技创新主体地位；提升研发经费投入强度（具体数字以权威发布核对）", "star": false}]}, {"name": "民生保障", "star": false, "children": [{"name": "加强普惠性、基础性、兜底性民生建设；构建房地产发展新模式、建设\"好房子\"；优化居家为主、社区为依托、机构为支撑、医养结合的养老格局", "star": false}]}]}, {"name": "二十大报告", "star": false, "children": [{"name": "主题与\"三个务必\"", "star": false, "children": [{"name": "大会主题含高举中国特色社会主义伟大旗帜、弘扬伟大建党精神等；\"三个务必\"＝不忘初心牢记使命、谦虚谨慎艰苦奋斗、敢于斗争善于斗争", "star": false}]}, {"name": "中心任务", "star": false, "children": [{"name": "团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴", "star": false, "examples": [{"q": "（多选题）党的二十大报告指出，要完善社会治理体系。关于完善社会治理体系，以下说法准确的有（ ）。", "src": "2024广东省考真题 第11题", "hit": false, "ans": "ABD", "opts": ["A.完善社会治理体系必须着力解决社会治安难题", "B.完善社会治理体系必须提高重大突发公共事件处置保障能力", "C.完善社会治理体系是一场广泛而深刻的经济社会系统性变革", "D.完善社会治理体系是推进国家治理体系特别是国家安全体系现代化的基础性工作"], "solve": "先定出处——题干锁定「党的二十大报告·完善社会治理体系」，凡属**治安＋应急＋国家治理/国家安全**口径的 A/B/D 皆对；把「广泛而深刻的经济社会系统性变革」（双碳等专属口径）安上来的 C 直接毙。", "analysis": "- 体系定位：常识判断 → 政策文件 → 二十大报告（清单原名）｜体系位置：上位＝党的二十大报告（推进国家安全体系和能力现代化板块）→ 本题＝「完善社会治理体系」的归属与口径 → 下级变式＝总体国家安全观、防灾减灾救灾、基层治理。（清单暂无「社会治理体系」单元，建议在〈二十大报告〉下新增〈社会治理体系〉，待核）\n- 识别信号：题干「××报告／文件指出……关于××，以下说法准确的有」＝**时政原文口径题**；看到「必须／唯一／基础性／系统性变革／根本」等**程度·绝对化词**先警觉。\n- 本质：考**概念归属＋原文专属口径**——某说法是不是该主题的「专用表述」（判分点：社会治理体系属国家治理／国家安全范畴；「经济社会系统性变革」属双碳等）。\n- 通式：无固定式；按「**先定出处与主体 → 再逐句核原文口径（主体／程度／范围／绝对化）→ 剔除张冠李戴项**」三步判。\n- 易混·易错链：最像＝**总体国家安全观**（同属安全板块，含社会治安、应急、政治安全，看是否落到「体系」定位）；撞坑链：①把双碳／改革的专属表述（经济社会系统性变革）误安到治理体系；②「基础性／战略性」程度词乱套。", "img": ""}]}]}, {"name": "\"两步走\"战略安排", "star": false, "children": [{"name": "2035 年基本实现社会主义现代化；本世纪中叶建成富强民主文明和谐美丽的社会主义现代化强国", "star": false}]}, {"name": "科教兴国与人才", "star": false, "children": [{"name": "教育、科技、人才是全面建设社会主义现代化国家的基础性、战略性支撑；科技是第一生产力、人才是第一资源、创新是第一动力", "star": false}]}]}, {"name": "中央经济工作会议", "star": false, "children": [{"name": "总基调与工作方针", "star": false, "children": [{"name": "坚持稳中求进工作总基调；\"稳中求进、以进促稳、先立后破\"；扩大内需既关系经济稳定也关系经济安全，是战略之举", "star": false}]}, {"name": "\"两新\"\"两重\"", "star": false, "children": [{"name": "\"两新\"＝大规模设备更新和消费品以旧换新；\"两重\"＝国家重大战略实施和重点领域安全能力建设", "star": false}]}, {"name": "财政货币政策取向", "star": false, "children": [{"name": "实施更加积极的财政政策和适度宽松的货币政策（\"适度宽松\"为十余年来首次转向）", "star": false}]}]}, {"name": "中央一号文件", "star": false, "children": [{"name": "主题与农业强国", "star": false, "children": [{"name": "历年聚焦\"三农\"，近年主题为深化农村改革、扎实推进乡村全面振兴；加快建设农业强国", "star": false}]}, {"name": "粮食安全", "star": false, "children": [{"name": "牢牢守住 18 亿亩耕地红线；防止耕地\"非农化\"\"非粮化\"；粮食安全党政同责、饭碗主要装中国粮", "star": false}]}]}, {"name": "政府工作报告", "star": false, "children": [{"name": "主要预期目标", "star": false, "children": [{"name": "GDP 增速、城镇新增就业、CPI、赤字率、单位 GDP 能耗等（每年以正式报告为准）", "star": false}]}]}, {"name": "\"一带一路\"倡议", "star": false, "children": [{"name": "要点", "star": false, "children": [{"name": "共商共建共享原则；\"五通\"＝政策沟通、设施联通、贸易畅通、资金融通、民心相通", "star": false}]}]}, {"name": "习近平总书记重要纪念/专题讲话", "star": false, "children": [{"name": "要点", "star": false, "children": [{"name": "如纪念江泽民同志诞辰 100 周年大会讲话（2026-08）涉及\"三个代表\"、港澳回归、加入世贸等", "star": false}]}]}]}, {"name": "党的建设", "star": false, "children": [{"name": "党建", "star": false, "children": [{"name": "新时代党的建设总要求：以党的政治建设为统领，全面推进政治、思想、组织、作风、纪律建设，把制度建设贯穿其中，深入推进反腐败斗争", "star": false}, {"name": "全面从严治党：全面从严治党永远在路上；以党的自我革命引领社会革命；把严的基调、严的措施、严的氛围长期坚持下去", "star": false}, {"name": "\"两个责任\"：党委（党组）负主体责任，纪委监委（纪检监察机关）负监督责任（\"纪检监察机关负主体责任\"是错误的偷换）", "star": false}, {"name": "新时代党的组织路线：以组织体系建设为重点，着力培养忠诚干净担当的高素质干部，集聚爱国奉献的优秀人才", "star": false}, {"name": "树立和践行正确政绩观：从实际出发、按规律办事；反对\"形象工程\"\"政绩工程\"；创造经得起实践、人民、历史检验的实绩", "star": false}, {"name": "党的自我革命：跳出治乱兴衰历史周期率的第一个答案＝人民监督，第二个答案＝自我革命", "star": false}, {"name": "中央八项规定与\"四风\"：八项规定改进工作作风、密切联系群众；\"四风\"＝形式主义、官僚主义、享乐主义、奢靡之风", "star": false}, {"name": "党的纪律与纪律建设：六项纪律＝政治纪律、组织纪律、廉洁纪律、群众纪律、工作纪律、生活纪律（政治纪律居首）；加强纪律建设是全面从严治党的治本之策；落实管党治党政治责任是\"牛鼻子\"", "star": false}]}]}, {"name": "经济", "star": false, "children": [{"name": "政策表述", "star": false, "children": [{"name": "经济", "star": false, "children": [{"name": "新质生产力：以科技创新为主导，特点是创新、关键在质优、本质是先进生产力；因地制宜发展，勿一哄而上、泡沫化", "star": false}, {"name": "实体经济：实体经济是一国经济的立身之本、财富创造的根本源泉；制造业是实体经济的基础；金融是实体经济的血脉、为实体经济服务是金融的天职", "star": false}, {"name": "全国统一大市场：统一市场基础制度规则、市场设施、政府行为尺度、市场监管、要素和资源市场；破除地方保护和市场分割", "star": false}, {"name": "扩大内需：牢牢把握扩大内需这一战略基点；消费成为拉动经济增长的主动力；以国内大循环为主体、国内国际双循环相互促进", "star": false}, {"name": "\"两个毫不动摇\"与国有经济：毫不动摇巩固和发展公有制经济、鼓励支持引导非公有制经济；做强做优做大国有资本和国有企业、增强核心功能提升核心竞争力", "star": false}, {"name": "区域协调发展战略：京津冀协同发展、长三角一体化、粤港澳大湾区、成渝双城经济圈、长江经济带、黄河流域生态保护和高质量发展", "star": false}, {"name": "共同富裕：共同富裕是社会主义本质要求；在高质量发展中促进共同富裕；构建初次分配、再分配、第三次分配协调配套的制度体系", "star": false}, {"name": "高水平对外开放：稳步扩大规则、规制、管理、标准等制度型开放；实施自由贸易试验区提升战略；以国内大循环吸引全球资源要素", "star": false}]}]}]}, {"name": "民生 / 生态 / 科技 / 安全 / 军队 / 文化 / 外交", "star": false, "children": [{"name": "民生", "star": false, "children": [{"name": "就业：就业是最基本的民生；实施就业优先战略；方针＝劳动者自主就业、市场调节就业、政府促进就业和鼓励创业（\"发展地摊经济\"为着力点是错误表述）", "star": false}, {"name": "健康中国：到 2035 年建成健康中国；坚持健康优先发展战略、基本医疗卫生事业公益性；从以治病为中心转向以人民健康为中心", "star": false}, {"name": "社会保障：覆盖全民、统筹城乡、公平统一、安全规范、可持续的多层次社会保障体系；兜底线、织密网、建机制", "star": false}, {"name": "乡村振兴与\"三农\"：推进农业农村现代化；产业、人才、文化、生态、组织五大振兴；守住粮食安全和不发生规模性返贫两条底线", "star": false}, {"name": "城市更新与人民城市：全面践行人民城市理念，问需于民、问计于民、问效于民；一刻钟便民生活圈；推进超大特大城市治理现代化", "star": false}]}, {"name": "生态", "star": false, "children": [{"name": "生态文明建设：绿水青山就是金山银山；山水林田湖草沙一体化保护和系统治理；双碳目标＝2030 年前碳达峰、2060 年前碳中和", "star": false, "examples": [{"q": "水是生存之本、文明之源，水安全是涉及国家长治久安的大事。为了解决好水安全问题，下列说法有误的是（　　）。", "src": "2026广东省考真题 第8题", "hit": false, "ans": "D", "opts": ["A.要按照“节水优先、空间均衡、系统治理、两手发力”的方针治水", "B.要统筹做好水灾害防治、水资源节约、水生态保护修复、水环境治理", "C.要树立节约用水就是保护生态、保护水源就是保护家园的意识，坚决抑制不合理用水需求", "D.要根据人口、城市和产业发展规划，因地制宜发掘更多水资源，避免水资源成为发展的约束条件"], "solve": "水是刚性约束：治水口径是「以水定城、以水定地、以水定人、以水定产」，D 把「发掘更多水资源去满足规划」说反了 → 选 D。", "analysis": "**识别信号**：找「有误」题、话题是「水安全 / 治水」；选项出现「发掘更多水资源 / 避免成为约束」等主客颠倒措辞，或「坚决/严格/一律」绝对化词。\n**核心规律**：治水口径＝「以水定城、以水定地、以水定人、以水定产」，**水是刚性约束——是发展规划服从水资源承载力，不是「找更多水去满足规划」**（判分点并入：主语—宾语方向反了即错，让规划当主语、水当被供给对象）。打法：判政策表述先问「谁被满足、谁被约束」——凡「资源去适配发展」多为错、「发展去适配资源/承载力」多为对；见绝对词先看搭配对象再判去留。\n**易混·易错链**：最像＝**安全·防灾减灾救灾**（人民至上、生命至上，基层第一线）；怎么分：防灾减灾看「抵御灾害的组织导向」，本题看「水资源与发展规划谁服从谁」。撞坑链：只看措辞不看方向（被「因地制宜」这个正面词骗）；把 C 的「坚决抑制不合理用水需求」当绝对化排除（官方口径确这么写，「坚决」不越界）。", "img": ""}]}, {"name": "美丽中国：协同推进降碳、减污、扩绿、增长；扎实推进\"三北\"工程攻坚战；健全生态产品价值实现机制", "star": false}]}, {"name": "科技", "star": false, "children": [{"name": "科技自立自强：关键核心技术自主可控；健全新型举国体制；基础研究是科技创新的源头活水；企业是创新主体", "star": false}, {"name": "人工智能：人工智能是引领新一轮科技革命和产业变革的战略性技术；实施\"人工智能+\"行动", "star": false}]}, {"name": "安全", "star": false, "children": [{"name": "总体国家安全观：以人民安全为宗旨、政治安全为根本、经济安全为基础、军事科技文化社会安全为保障、促进国际安全为依托", "star": false}, {"name": "政治安全：把捍卫政治安全摆在首位，坚定维护政权安全、制度安全、意识形态安全", "star": false}, {"name": "防灾减灾救灾：坚持人民至上、生命至上，坚持预防为主、社会共治；基层是抵御自然灾害的第一线（\"重在各级部门快速响应\"是错误导向）", "star": false}]}, {"name": "军队", "star": false, "children": [{"name": "新时代强军目标：建设一支听党指挥、能打胜仗、作风优良的人民军队，把人民军队全面建成世界一流军队", "star": false}, {"name": "建军一百年与政治建军：2027 年实现建军一百年奋斗目标；政治建军是人民军队立军之本（\"根本指向和检验标准是人民群众满意度\"错误）", "star": false}]}, {"name": "文化", "star": false, "children": [{"name": "文化强国建设：坚定文化自信；推动中华优秀传统文化创造性转化、创新性发展；\"两个结合\"＝同中国具体实际、同中华优秀传统文化相结合", "star": false, "examples": [{"q": "（多选题）在面对重重困难艰辛探索适合中国国情的社会主义建设道路过程中，涌现出大量先进典型和英雄模范人物，抒写了无数改天换地的壮丽诗篇，形成跨越时空、历久弥新的时代精神。下列词句关联人物的主要事迹，发生于社会主义建设时期的有（ ）。", "src": "2024广东省考真题 第13题", "hit": false, "ans": "BC", "opts": ["A.“清澈的爱，只为中国”", "B.“干惊天动地事，做隐姓埋名人”", "C.“生也沙丘，死也沙丘，父老生死系”", "D.“以青春之我，创建青春之家庭，青春之国家，青春之民族”"], "solve": "先立时间坐标——\"**社会主义建设时期**\"＝**1956 年三大改造基本完成至 1978 年改革开放前**；B（两弹一星元勋）、C（焦裕禄治沙）正落此期；A（陈祥榕，2020 戍边）属**新时代**、D（李大钊《青春》，1916）属**新民主主义革命时期**，时期不符 → 排除。", "analysis": "- 体系定位：常识判断 → 民生/生态/科技/安全/军队/文化/外交 → 文化 → 文化强国建设（清单原名）｜体系位置：上位＝党史分期与时代精神 → 本题＝英雄模范事迹的\"时期归属\" → 下级变式＝精神谱系（建党精神、焦裕禄精神、两弹一星精神）与人物—时期—名句配对。（清单暂无\"党史人物与时期\"单元，建议在〈文化〉下新增〈时代精神与英雄模范〉，待核）\n- 识别信号：题干出现\"**××时期**涌现的先进典型/英雄模范/名句\"＝**人物—时期配对题**；触发词\"XX 精神\"\"名句\"，看到名句先想**谁说的＋哪个年代**。\n- 本质：考**名句—人物—历史时期三对一**（判分点：社会主义建设时期＝1956—1978，涵盖两弹一星、焦裕禄、雷锋、王进喜等；1919 前属旧民主主义、1919—1949 新民主主义、1949—1978 社会主义革命和建设、1978 后改革开放、十八大后新时代）。\n- 通式：无固定式；按\"**先定题干时段 → 逐句认人（谁）→ 定时（哪期）→ 比对时段是否吻合**\"三步判；名句不确定时，用\"人物生卒/事迹年份\"回推。\n- 易混·易错链：最像＝**新民主主义革命时期 vs 社会主义建设时期**（分界 1949/1956）；撞坑链：①把新时代人物（陈祥榕）误当\"社会主义建设时期\"；②把建党前后（李大钊《青春》1916）误当社会主义建设时期；③只记名句不记人物年份，被\"壮丽诗篇\"式题干氛围带偏。", "img": ""}]}, {"name": "意识形态工作：意识形态工作是为国家立心、为民族立魂的工作；建设具有强大凝聚力和引领力的社会主义意识形态", "star": false}]}, {"name": "外交", "star": false, "children": [{"name": "人类命运共同体与三大全球倡议：推动构建人类命运共同体；共商共建共享的全球治理观；全人类共同价值＝和平、发展、公平、正义、民主、自由；三大全球倡议＝全球发展倡议、全球安全倡议、全球文明倡议", "star": false}]}, {"name": "时政", "star": false, "children": [{"name": "重要纪念与时间节点：抗战胜利 80 周年（2025）、\"十四五\"收官（2025）、2027 建军百年、2029《决定》任务完成、2035 基本实现现代化", "star": false}]}]}, {"name": "法律", "star": false, "children": [{"name": "宪法 / 法理", "star": false, "children": [{"name": "宪法", "star": false, "children": [{"name": "国家根本制度：社会主义制度是中华人民共和国的根本制度；中国共产党领导是中国特色社会主义最本质的特征", "star": false}, {"name": "国家机构职权：全国人大＝最高国家权力机关、行使国家立法权（基本法）；全国人大常委会解释宪法法律；国务院＝最高国家行政机关", "star": false}, {"name": "公民基本权利：平等权、政治权利和自由、人身自由、宗教信仰自由、社会经济权利（劳动、休息、物质帮助）等", "star": false}, {"name": "公民基本义务：维护国家统一和民族团结、遵守宪法法律、维护祖国安全荣誉利益、依法服兵役、依法纳税；劳动与受教育既是权利又是义务", "star": false}]}, {"name": "法理", "star": false, "children": [{"name": "法的效力位阶：宪法＞法律＞行政法规＞地方性法规/部门规章；下位法不得与上位法相抵触", "star": false}, {"name": "法律责任与归责：民事责任、行政责任、刑事责任、违宪责任；构成要件含主体、过错、违法行为、损害事实、因果关系", "star": false}]}]}, {"name": "民法", "star": false, "children": [{"name": "民事行为能力", "star": false, "children": [{"name": "不满 8 周岁＝无民事行为能力；8—18 周岁＝限制；18 周岁以上＝完全；16 周岁以上以自己劳动收入为主要生活来源者视为完全", "star": false}]}, {"name": "监护", "star": false, "children": [{"name": "父母、祖父母外祖父母、兄姐、其他愿意担任的个人或组织（后者需居委会/村委会/民政部门同意）", "star": false}]}, {"name": "诉讼时效", "star": false, "children": [{"name": "向人民法院请求保护民事权利的普通诉讼时效为 3 年；自权利受损害之日起最长 20 年", "star": false}]}, {"name": "建筑物区分所有权与共有部分", "star": false, "children": [{"name": "电梯、外墙、公共区域等属业主共有；改建、重建等重大事项需依法经参与表决面积和人数各 3/4 以上业主同意", "star": false}]}, {"name": "业主共有部分收益", "star": false, "children": [{"name": "利用业主共有部分产生的收入（扣除合理成本后）属全体业主共有，物业不得据为己有", "star": false}]}, {"name": "合同的成立与效力", "star": false, "children": [{"name": "要约与承诺一致合同成立；无民事行为能力人独立订立、虚假意思表示、违反法律强制性规定或公序良俗、恶意串通损害他人等无效", "star": false}]}, {"name": "保管合同", "star": false, "children": [{"name": "保管人负妥善保管义务；无偿保管中保管人仅因故意或重大过失致损才担责", "star": false}]}, {"name": "继承（法定继承顺序）", "star": false, "children": [{"name": "第一顺序＝配偶、子女、父母；第二顺序＝兄弟姐妹、祖父母、外祖父母；有第一顺序时第二顺序不继承", "star": false}]}, {"name": "遗嘱与遗赠", "star": false, "children": [{"name": "遗嘱形式含自书、代书、打印、录音录像、口头、公证；受遗赠人应在知道受遗赠后 60 日内作出接受表示，逾期视为放弃", "star": false}]}, {"name": "侵权责任归责原则", "star": false, "children": [{"name": "一般过错责任；环境污染、高度危险、产品责任等适用无过错责任；不可抗力原则上免责（环境污染等有特别规定）", "star": false}]}]}, {"name": "刑法", "star": false, "children": [{"name": "刑事责任年龄", "star": false, "children": [{"name": "已满 16 周岁负完全刑事责任；已满 14 不满 16 周岁对故意杀人等 8 种严重犯罪负责；已满 12 不满 14 周岁特定情形经核准追诉", "star": false}]}, {"name": "犯罪主观方面", "star": false, "children": [{"name": "直接故意、间接故意、疏忽大意的过失、过于自信的过失", "star": false}]}, {"name": "正当防卫与紧急避险", "star": false, "children": [{"name": "正当防卫针对正在进行的不法侵害、为保护合法权益、未明显超过必要限度；防卫过当应负刑责但应减轻或免除处罚", "star": false}]}, {"name": "犯罪形态", "star": false, "children": [{"name": "犯罪预备（为犯罪准备工具、制造条件）、犯罪未遂（已着手因意志以外原因未得逞）、犯罪中止（自动放弃或有效防止结果）", "star": false}]}, {"name": "共同犯罪与主从犯", "star": false, "children": [{"name": "主犯、从犯（应当从轻、减轻或免除处罚）、胁从犯（应当减轻或免除处罚）、教唆犯", "star": false}]}, {"name": "自首与坦白", "star": false, "children": [{"name": "自首＝自动投案＋如实供述（可从轻或减轻）；坦白＝如实供述自己罪行（可从轻）；立功可从轻或减轻（\"如实供述＝自首\"是常见错误）", "star": false}]}, {"name": "缓刑", "star": false, "children": [{"name": "判处拘役、三年以下有期徒刑且情节较轻、有悔罪表现、无再犯危险等；不满 18 周岁、怀孕妇女、已满 75 周岁且符合条件的应当宣告缓刑", "star": false}]}, {"name": "未成年人从宽与记录封存", "star": false, "children": [{"name": "犯罪时不满 18 周岁应当从轻或减轻处罚；不满 18 周岁被判五年以下有期徒刑的犯罪记录应当封存", "star": false}]}, {"name": "常见罪名构成", "star": false, "children": [{"name": "盗窃、抢劫、诈骗、贪污、受贿、渎职、危险驾驶等罪的核心行为与主体", "star": false}]}, {"name": "刑罚种类", "star": false, "children": [{"name": "主刑＝管制、拘役、有期徒刑、无期徒刑、死刑；附加刑＝罚金、剥夺政治权利、没收财产、驱逐出境（可独立适用）", "star": false}]}]}, {"name": "行政法 / 程序法 / 部门法", "star": false, "children": [{"name": "行政法", "star": false, "children": [{"name": "行政处罚：种类含警告、通报批评、罚款、没收违法所得财物、暂扣或吊销证照、行政拘留等；遵循处罚法定、一事不再罚", "star": false}, {"name": "行政复议：一般自知道行政行为之日起 60 日内申请；复议机关应审查申请人、请求和理由；撤回后不得以同一事实和理由再次申请；准予撤回应作出终止决定（非\"驳回决定\"）", "star": false}, {"name": "行政诉讼：审查行政行为合法性；被告对作出的行政行为负举证责任；起诉期限、复议前置等规则", "star": false}, {"name": "行政许可：公开、公平、公正、非歧视；信赖保护原则，行政机关不得擅自改变已生效的许可", "star": false}]}, {"name": "公务员法", "star": false, "children": [{"name": "公务员职务与职级并行；考核德、能、勤、绩、廉，突出政治素质；任职回避、地域回避；辞去公职的限制情形", "star": false}]}, {"name": "劳动法", "star": false, "children": [{"name": "劳动合同：试用期最长不超过 6 个月；用工满 1 个月不满 1 年未签书面合同的应支付双倍工资；经济补偿按工作年限计", "star": false}, {"name": "劳动争议处理：协商—调解—仲裁（前置）—诉讼；劳动争议申请仲裁时效为 1 年", "star": false}]}, {"name": "仲裁法", "star": false, "children": [{"name": "或裁或审、一裁终局；仲裁一般不公开进行（涉国家秘密等除外）；紧急情况可申请保全（注意 2026-03-01 新修订施行）", "star": false}]}, {"name": "民事诉讼法", "star": false, "children": [{"name": "管辖：一般地域管辖\"原告就被告\"（被告住所地）；合同纠纷可由被告住所地或合同履行地法院管辖", "star": false, "examples": [{"q": "根据《中华人民共和国民事诉讼法》，下列说法正确的是（ ）。", "src": "26年省考35季 第12题", "hit": false, "ans": "C", "opts": ["A.上级人民法院将本院管辖的第一审民事案件交下级人民法院审理的，应当直接移送", "B.人民法院审理人民群众广泛关注的案件时，可以由审判员一人独任审理", "C.人民法院对当事人提出的回避申请，可以以口头或者书面形式作出决定", "D.离婚案件有诉讼代理人的，一般本人可以不出庭"], "solve": "只盯**「应当 / 可以 / 一般」**等措辞与法定条件——离婚案本人**原则上必须出庭**（D 方向反）、独任制适用条件被**编造**（B 无中生有）、上级交下级审理须**报请上级批准**而非直接移送（A 偷换概念），淘汰三项，只剩 C。", "analysis": "- 体系定位：常识判断 → 法律 → 「行政法 / 程序法 / 部门法」子类 → 民事诉讼法（清单原名「民事诉讼法·管辖」，本题扩至程序规则）＋ 上位＝诉讼程序通则（管辖、回避、审级、出庭）→ 本题＝民诉**程序条件措辞判断** → 下级变式＝行政诉讼举证、仲裁一裁终局等程序规则。\n- 识别信号：题干出现「根据《××法》……说法正确的是」＋程序类名词（管辖/回避/独任/出庭/期限），触发词「应当 / 可以 / 一般 / 直接」→ 一律先按**措辞增减反**三面筛。\n- 本质：考的是**法条条件与题干的字面吻合度**——判「主体对不对、条件是加是减、方向是正是反」，不是考对法律精神的理解。\n- 通式：见「应当」比法定条件是否被**减**、见「可以/均/一律」比是否被**加**、见「一般/不」比方向是否被**反**；同类判别条件：看到程序法选项，先划出**条件词**再逐字对照法条。\n- 易混·易错链：最像的是**「可以」与「应当」**——一句话分：**「应当」＝强制义务、「可以」＝授权选择，凡把「可以」写成「应当」即错**；撞坑链＝句子通顺就选 → 忽略「直接移送」漏报批 → 把 D 的「一般不出庭」当常识认可。", "img": ""}]}]}, {"name": "社会团体登记", "star": false, "children": [{"name": "实行业务主管单位与登记管理机关双重管理；成立、变更、注销须依法登记", "star": false}]}, {"name": "通用语言文字法", "star": false, "children": [{"name": "国家推广普通话、推行规范汉字；国家机关以普通话和规范汉字为公务用语用字", "star": false}]}, {"name": "国家公园法", "star": false, "children": [{"name": "建立以国家公园为主体的自然保护地体系；国家公园实行统一管理、分级负责", "star": false}]}, {"name": "城市居民委员会组织法", "star": false, "children": [{"name": "居委会是基层群众性自治组织，协助政府开展工作；不以营利为目的，一般不得为他人提供担保", "star": false}]}, {"name": "全国农业普查条例", "star": false, "children": [{"name": "农业普查每 10 年进行一次（逢 6 的年份）；对象包括村民委员会、乡镇人民政府等", "star": false}]}, {"name": "生态环境相关法律", "star": false, "children": [{"name": "建设对环境有影响的项目须依法进行环境影响评价；污染者担责；因不可抗力造成污染损害时的责任规则特殊", "star": false}]}]}]}, {"name": "经济常识", "star": false, "children": [{"name": "经济", "star": false, "children": [{"name": "GDP 与 GNP：GDP 按国土（地域）原则核算，GNP 按国民（人员）原则核算", "star": false}, {"name": "通货膨胀：需求拉动型、成本推动型；以 CPI 衡量；治理用紧缩性政策（提高利率、减少财政支出）", "star": false}, {"name": "货币政策工具：存款准备金率、再贴现率、公开市场操作、基准利率；降低存款准备金率＝释放流动性", "star": false}, {"name": "财政政策工具：税收、国债、政府支出；扩张（积极）财政＝增加支出、减税", "star": false}, {"name": "市场失灵：垄断、外部性、公共物品、信息不对称；需政府干预或宏观调控", "star": false, "examples": [{"q": "下列经济学概念与其典型例子对应正确的是（ ）。", "src": "26年省考35季 第11题", "hit": false, "ans": "D", "opts": ["A.二手车市场上，买家因信息不足而买到故障车——道德风险", "B.购买了火灾保险后，住户放松了对火源的警惕——逆向选择", "C.企业通过技术创新降低生产成本，获得超额利润——公地悲剧", "D.化工厂排污殃及鱼塘，双方私下协商达成赔偿——科斯定理"], "solve": "道德风险在后（投保后行为变了）、逆向选择在前（交易前信息不对称）**，公地悲剧必伴**公共资源枯竭**，三个错项全排除，只剩 D。", "analysis": "- 体系定位：常识判断 → 经济常识 → 经济·市场失灵（清单原名）＋ 上位＝市场失灵总纲（垄断/外部性/公共物品/信息不对称）→ 本题＝信息不对称与外部性的**举例配对** → 下级变式＝货币/财政政策工具、GDP/GNP 等口径判断。\n- 识别信号：题干出现「概念—例子/现象对应」「正确的是」＋经济术语名词，看到「投保后」「交易前」→ 先量**时点**，看到「公共资源/牧场/鱼群枯竭」→ 想公地悲剧。\n- 本质：剥掉例子外壳，考的是把**经济学术语的中文名**映射到**真实行为的发生时点与资源属性**上，即「内核匹配」而非背定义。\n- 通式：判「信息不对称」→ 事前＝逆向选择、事后＝道德风险；判「外部性」→ 有产权＋可协商＝科斯定理、无产权＋公共资源＝公地悲剧；同类判别条件：看到实例就抓**时点（事前/事后）**与**资源属性（私有/公共）**两个坐标。\n- 易混·易错链：最像的是**道德风险 vs 逆向选择**——一句话分：**事前挑卖家＝逆向选择，事后松警惕＝道德风险**；撞坑链＝背名词不辨时点 → 把 C 的「创新获利」误当「公地悲剧」→ 忽略 D 缺一要件而乱选。", "img": ""}]}, {"name": "国际贸易与汇率：关税、贸易顺差/逆差；本币升值→进口增加、出口减少，本币贬值反之", "star": false}, {"name": "金融机构职能：中国人民银行＝中央银行（制定货币政策、不办理个人储蓄业务）；商业银行办理存贷；直接融资与间接融资", "star": false}, {"name": "恩格尔系数与基尼系数：恩格尔系数越低生活越富裕；基尼系数介于 0—1，越大越不平等，0.4 为国际警戒线", "star": false}]}]}, {"name": "科技常识", "star": false, "children": [{"name": "物理", "star": false, "children": [{"name": "浮力与压强：浮力＝ρ液·g·V排，与浸没深度无关；液体压强随深度增大而增大（\"完全浸没后浮力随深度增大\"错误）", "star": false}, {"name": "杠杆与压强：杠杆平衡条件 F₁·L₁＝F₂·L₂；压力一定时受力面积越小压强越大", "star": false}, {"name": "物态变化：熔化凝固（固—液）、汽化液化（液—气）、升华凝华（固—气）；熔化、汽化、升华吸热，反之放热", "star": false}, {"name": "声与光：声音传播需要介质；光沿直线传播、可反射折射；海水对电磁波衰减远大于声波，故水下常用水声通信", "star": false}, {"name": "电与磁：欧姆定律、串联并联规律；电磁感应；电流的磁效应", "star": false}, {"name": "能源分类：可再生＝水能、风能、太阳能、生物质能等；不可再生＝煤、石油、天然气、核燃料", "star": false}]}, {"name": "化学", "star": false, "children": [{"name": "物质结构与性质：官能团决定性质（氨基、羧基、羟基、碳碳双键）；碳碳双键是天然橡胶老化诱因；羟基间氢键使纤维素分子链结合紧密", "star": false}, {"name": "常见物质成分：石灰石/大理石＝CaCO₃；纯碱＝Na₂CO₃；烧碱＝NaOH；生石灰＝CaO；小苏打＝NaHCO₃", "star": false}, {"name": "生活化学原理：调味、去污、防腐、除垢等生活化学原理及其对应物质", "star": false}, {"name": "分离与提纯方法：重结晶（溶解度差异）、升华、膜分离（分子大小与电荷）、萃取各自的适用范围", "star": false}]}, {"name": "生物", "star": false, "children": [{"name": "细胞与遗传：DNA 双螺旋结构、基因与性状；细胞器的功能分工", "star": false}, {"name": "人体健康与生态系统：疫苗接种＝刺激机体产生抗体；血常规一般无需空腹、血糖血脂需空腹；生态系统的生产者/消费者/分解者与食物链；植被的涵养水源、保持水土功能", "star": false}]}, {"name": "科技", "star": false, "children": [{"name": "前沿技术对应：人工智能、量子信息、5G/6G、北斗导航、载人航天、深海潜水器（\"奋斗者\"号）等", "star": false, "examples": [{"q": "下列关于近年来我国重要科技成就，说法有误的是（ ）。", "src": "26年省考35季 第13题", "hit": false, "ans": "D", "opts": ["A.“嫦娥七号”计划前往月球南极开展环境与资源勘查，重点寻找月球水冰资源", "B.我国“人造太阳”EAST实现1066秒稳态长脉冲高约束模式放电，刷新世界纪录", "C.首艘国产大型邮轮“爱达·魔都号”可搭载6500余名乘客和船员，已完成首次国际航线航行", "D.“墨子号”成功实现星地量子密钥分发，是全球首颗量子导航卫星"], "solve": "抓**「主体—功能」对应**——「墨子号」是**量子通信（科学实验）卫星**，干的活是星地量子密钥分发，题里却说它是**量子导航卫星**，功能被偷换，故有误项＝D。", "analysis": "- 体系定位：常识判断 → 科技常识 → 科技（清单原名「科技·前沿技术对应」）＋ 上位＝前沿技术成果谱系（人工智能／量子信息／5G-6G／北斗／载人航天／深海）→ 本题＝**成果与主体/功能配对** → 下级变式＝北斗导航、奋斗者号深潜、嫦娥探月等同类配对题。\n- 识别信号：题干出现「我国重要科技成就」「说法有误/正确的是」＋成果名（嫦娥／EAST／墨子号／爱达·魔都号），触发词「有误」→ 立刻切到**选错**模式，逐项核主体。\n- 本质：考的是把**成果名称**精确锚定到**所属领域与功能**上——「谁/哪个领域/干什么活」，即**主体—功能匹配**，而非记新闻热度。\n- 通式：见成果先问「**哪个领域＋干什么**」两端对齐；量子信息三线＝通信（墨子号·星地密钥）、计算（九章/祖冲之）、导航/测量（北斗、量子测量）；同类判别条件：看到题干把成果和数据/功能并列，就逐字核**领域词与数据**是否对得上。\n- 易混·易错链：最像的是**「墨子号（量子通信）」与「北斗（导航）」**——一句话分：**墨子号只做量子密钥分发、不导航，导航是北斗**；撞坑链＝把「量子＋卫星」顺口读成量子导航 → 忽略「北斗才是导航卫星」→ 反把正确项当有误项。", "img": ""}]}]}]}, {"name": "人文常识", "star": false, "children": [{"name": "人文", "star": false, "children": [{"name": "中国古代史：夏商周—秦汉—三国两晋南北朝—隋唐—宋元明清的主要事件与先后", "star": false}, {"name": "中国近代史：鸦片战争（1840）、甲午中日战争（1894）、辛亥革命（1911）、五四运动（1919）、抗日战争（1931—1945）", "star": false}, {"name": "诸子百家：儒家（孔孟荀）、道家（老庄）、墨家（兼爱、非攻）、法家（韩非）、名家、阴阳家", "star": false}, {"name": "古代文学：《诗经》《楚辞》源头；唐诗宋词代表作家；四大名著及其作者", "star": false, "examples": [{"q": "关于诗句中所涉及的人物典故，下列解释错误的是（ ）。", "src": "26年省考35季 第15题", "hit": false, "ans": "C", "opts": ["A.“地崩山摧壮士死，然后天梯石栈相钩连”中的“壮士”是指战国时期的五位力士", "B.“但使龙城飞将在，不教胡马度阴山”中的“飞将”是指西汉时期抵御匈奴的名将李广", "C.“此地别燕丹，壮士发冲冠”中的“燕丹”是指战国时期荆轲的燕国友人", "D.“群山万壑赴荆门，生长明妃尚有村”中的“明妃”是指西汉时期和亲的王昭君"], "solve": "识典故本体**——「燕丹」＝**燕太子丹**（遣荆轲刺秦的燕国**太子**），C 却说成「荆轲的燕国友人」，把人**降格/换身份**，故解释错误项＝C。", "analysis": "- 体系定位：常识判断 → 人文常识 → 人文（清单原名「人文·古代文学」）＋ 上位＝古典诗词用典（作家—作品—人物）→ 本题＝**诗句典故与人物身份配对** → 下级变式＝四大名著作者、唐诗宋词代表作家等同类配对。\n- 识别信号：题干出现「诗句／典故／人物」＋「解释正确的是/错误的是」，触发词「有误」→ 立刻切**选错**模式，逐句抠**人物身份**。\n- 本质：考的是把**诗句里的称呼**精确锚定到**历史人物及其身份**上——「谁＋什么身份＋干什么」，即**用典主体匹配**，而非背诗句。\n- 通式：见诗句先问「**这个称呼是谁、什么身份**」，两端对齐；同类判别条件：凡选项出现「友人／同伴／力士」等**泛称**去对应**有名有姓的历史人物**，优先怀疑**主体被降格或偷换**。\n- 易混·易错链：最像的是**「燕太子丹（遣荆轲者）」与「荆轲（被遣者）」**——一句话分：**丹是主使的太子、轲是执行的刺客**；撞坑链＝只记「易水送别＝荆轲」→ 把「燕丹」误当荆轲同伴 → 忽略其太子身份而放过 C。", "img": ""}]}, {"name": "现当代文学：鲁迅、茅盾、巴金、老舍、莫言等及其代表作", "star": false}, {"name": "艺术门类：书法（楷、行、草、隶、篆）、京剧四大行当（生、旦、净、丑）、民乐与绘画门类", "star": false}, {"name": "传统文化与科技史：二十四节气、传统节日、兄弟排行（伯仲叔季）、科举制度；《本草纲目》李时珍、《天工开物》宋应星、《九章算术》、张衡地动仪", "star": false}]}]}, {"name": "地理常识", "star": false, "children": [{"name": "地理", "star": false, "children": [{"name": "中国地形：地势三级阶梯；四大高原、三大平原、四大盆地的位置与特征", "star": false}, {"name": "气候与秦岭—淮河线：季风气候、温带大陆性气候、高原山地气候；秦岭—淮河一线≈800mm 年等降水量线、1 月 0℃ 等温线", "star": false}, {"name": "河流湖泊：长江、黄河的源头与流经、内外流河；五大淡水湖；京杭大运河", "star": false}, {"name": "自然灾害成因：地震、泥石流、台风、沙尘暴、洪涝的成因机制", "star": false}, {"name": "天文与世界地理：太阳系八大行星；地球自转（昼夜、时差）与公转（四季、二十四节气）、月相变化；七大洲四大洋、重要海峡运河与\"世界之最\"", "star": false}]}]}, {"name": "生活常识", "star": false, "children": [{"name": "生活", "star": false, "children": [{"name": "食品安全：保质期与储存条件、食品添加剂、生熟分开；碘盐应避光密封存放（碘易受热、光照挥发）", "star": false}, {"name": "健康养生：均衡膳食、适量运动、规律作息；不同体检项目的空腹要求", "star": false}, {"name": "安全急救：心肺复苏、烫伤处理、溺水与中暑急救、触电处置；常用药禁忌", "star": false}, {"name": "消防/居家/环保：燃气泄漏处置（不开灯、不通电、开窗通风）、灭火器使用、高层逃生；垃圾分类、节能减排、低碳生活方式", "star": false}]}]}, {"name": "广东省情", "star": false, "children": [{"name": "省考专用", "star": false, "children": [{"name": "省情", "star": false, "children": [{"name": "\"百千万工程\"：百县千镇万村高质量发展工程，县镇村三级联动，破解城乡区域发展不平衡", "star": false}, {"name": "粤港澳大湾区：大湾区\"9+2\"城市群；横琴、前海、南沙、河套等重大合作平台", "star": false}, {"name": "绿美广东：绿美广东生态建设，实施森林质量精准提升等行动", "star": false}, {"name": "制造业当家：坚持制造业当家、发展新质生产力；打造战略性产业集群", "star": false}, {"name": "广东地理人文：珠三角、潮汕、客家三大民系；省花木棉花；主要港口与城市定位", "star": false}]}]}]}]}, "数量关系": {"color": "indigo", "modules": {"数字推理": "indigo", "计算技巧": "indigo", "和差倍比": "indigo", "日期周期": "indigo", "工程问题": "emerald", "行程问题": "emerald", "经济利润": "emerald", "溶液问题": "emerald", "排列组合": "fuchsia", "概率问题": "fuchsia", "几何问题": "amber", "最值问题": "amber", "容斥原理": "sky", "植树问题": "indigo"}, "root": {"name": "数量关系", "signal": "先「看信号判型」→ 套模型公式 → 工具箱兜底"}, "branches": [{"name": "数字推理", "star": false, "children": [{"name": "等差", "star": false, "children": [{"name": "一阶差恒定，直接补缺", "star": false, "examples": [{"q": "12，13，25，37，49，（ ）", "src": "2025广东省考真题 第32题", "hit": true, "ans": "C", "opts": ["A.46", "B.57", "C.61", "D.78"], "solve": "相邻差 1,12,12,12——除首差外恒为 12 → 公差 12 的等差 → 49+12=61。", "analysis": "**识别信号**：数列单调递增、相邻差看起来恒定（允许首差为干扰项）。\n**核心规律**：自第 2 项起相邻差恒为常数（公差 12）的等差数列；「前两项和＝第三项」只是假象（差 1,12,12,12——除首差外恒为 12 → 49+12=61；验 13+25=38≠37，和数列假象证伪）。打法：aₙ＝a₁＋(n−1)d → 49+12=**61**；第一步==永远先作差==（差定生死），疑似递推必再验一组。\n**易混·易错链**：最像「递推/和数列」（a₁+a₂=a₃ 的假象）——分法：再验一组 a₂+a₃=a₄，本题 13+25=38≠37 一验即破；撞坑链：被 12+13=25 的和数列假象带走 → 被首差 1 带跑去做二阶差空转。", "img": ""}]}]}, {"name": "等比", "star": false, "children": [{"name": "相邻项比值恒定", "star": false, "examples": [{"q": "8/15，2/5，3/10，9/40，（  ），81/640", "src": "2024广东省考真题 第33题", "hit": true, "ans": "C", "opts": ["A.12/55", "B.21/80", "C.27/160", "D.49/240"], "solve": "相邻两项比值恒为 `3/4`**（分子逐项 ×3、分母逐项 ×4），故缺项 = `9/40 × 3/4 = 27/160`。", "analysis": "- 体系定位：数量关系 → 数字推理 → 等比数列（清单原名「数字推理·等比数列」，判分点：相邻项比值恒定）；体系位置：数字推理 → **分数形式的等比** → 二级等比 / 递推变式。\n- 识别信号：**整串都是分数** → 先分子分母分开看；分不出独立规律就立刻**相邻项做比**，比值恒定即等比。看到「分数」要同时想到「做比」。本题比值一眼可见 → **值得做，30 秒内秒杀**。\n- 本质：考「相邻项比值是否恒定」——分数只是外壳，内核是公比 `3/4` 的等比数列（分子逐项×3、分母逐项×4）。\n- 通式：`aₙ = a₁ × q^(n-1)`，公比 `q = a₂ / a₁`；本题 `q = 3/4`，缺项 = 前一项 × q。\n- 易混·易错链：最像「数字推理·分数数列」（分子、分母分别成规律）——本题分子分母**单独看无规律**，只有比值为定值，故归**等比**；撞坑链：见到分数只会通分硬算 → 漏掉做比 → 误选按近似值凑出的 D。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/sl/1-60fee3a64e.png"}]}]}, {"name": "二级", "star": false, "children": [{"name": "做一次差（或比）后，新数列呈等差/等比", "star": false, "examples": [{"q": "21，17，25，9，（ ），-23", "src": "26年省考35季 第31题", "hit": false, "ans": "D", "opts": ["A.-32", "B.-26", "C.18", "D.41"], "solve": "做一次差得 **-4、+8、-16、+32、-64**（公比 -2 等比），故空项 = 9 + **32** = **41**，末项 41 + (-64) = -23 吻合。", "analysis": "- 体系定位：数量关系 → 数字推理 → 二级（清单原名：数字推理·二级数列）；上位「数字推理」→ 本题「做一次差后差列成等比」→ 下级变式「做和/做积、三级差」。\n- 识别信号：数列**忽增忽减、无单调** → 先做一次差，再看差数列是否等差/等比。\n- 本质：把\"相邻两项之差\"当成一个新数列来找规律（**做差降维**），考的是差列规律识别力。\n- 通式：`aₙ₊₁ = aₙ + dₙ`，其中 `dₙ = d₁·q^(n-1)`；本题 d₁=-4、q=-2。同类判别条件：看到无单调波动 → 先做差看是否等比。\n- 易混·易错链：与「递推」(aₙ=aₙ₋₁+aₙ₋₂×k) 区分——递推看的是项与项的组合，二级看的是差列自身成规律；撞坑链：忽略公比负号 → 符号连错 → 末项验不上。", "img": ""}]}]}, {"name": "递推", "star": false, "children": [{"name": "形如 aₙ=aₙ₋₁+aₙ₋₂×k，用多组验证再推", "star": false, "examples": [{"q": "3，7，17，43，113，（ ）", "src": "2025广东省考真题 第31题", "hit": false, "ans": "A", "opts": ["A.307", "B.373", "C.417", "D.437"], "solve": "相邻比值稳定逼近 2.7（×2 系）；后项＝2×前项＋修正，修正项 1,3,9,27（3 的幂）→ 113×2+3⁴=307（等价 3×113−2⁵=307）。", "analysis": "**识别信号**：数列递增、相邻比值稳定逼近 2~3、一阶差快速膨胀却不成规律。\n**核心规律**：后项＝k×前项＋修正项，内核是「修正项自成规律才立得住」（相邻比值逼近 2.7；一阶差 4,10,26,70 不成规律 → 转递推，修正项＝1,3,9,27 即 3⁰…3³）。打法：aₙ₊₁＝**2aₙ＋3ⁿ⁻¹**（等价 3aₙ−2ⁿ、通项 2ⁿ+3ⁿ⁻¹）；修正项按 ==2的幂→3的幂→等差→平方数== 顺序试，命中后逐项回代。\n**易混·易错链**：最像「二级等差/等比」（一次作差后新数列本身成规律）——本题差不成规律须转「递推＋修正项」；撞坑链：在一阶差/二阶差上死磕 → 凑「×2＋前一项」这类只碰巧对个别项的假规律（如 2×17+7=41≠43）→ 修正确认到 1,3,9,27 却不敢外推 3⁴=81。", "img": ""}, {"q": "94，87，174，257，424，677，（ ）", "src": "26年省考34季 第33题", "hit": true, "ans": "C", "opts": ["A.734", "B.897", "C.1094", "D.1254"], "solve": "相邻两项之和＝下一项＋交替常数（奇数项减**7**、偶数项减**4**）；424+677=**1101**，减 7 得 ==1094==。", "analysis": "- 体系定位：数量关系 → 数字推理 → **递推数列**（清单原名「数字推理·递推数列」）；体系位置：上位「数字推理（找规律）」→ 本题「相邻两项之和 − 交替常数(7/4) 的变式递推」→ 下级变式「纯和递推(Fibonacci 型) / 和×系数±修正 / 隔项和递推」。\n- 识别信号：6 项以上长数列、整体递增但**增幅忽大忽小**、相邻倍数不恒定；题干尾部留空括号求下一项；一阶差（−7、87、83、167、253）不成等差/等比。\n- 本质：考查「相邻前几项的稳定线性组合」——剥掉数字外壳，就是验证 `aₙ ≈ aₙ₋₁ + aₙ₋₂` 是否成立，再找其固定（或周期性）修正项。\n- 通式：`aₙ = aₙ₋₁ + aₙ₋₂ − cₙ`，其中 cₙ 按奇偶取 **7、4**（等价写法 `aₙ₋₁ + aₙ₋₂ = aₙ + cₙ`）；任取两组代入成立，即可前推末项。\n- 易混·易错链：最像**「数字推理·二级等差/等比」**——本题必须先做一阶差确认无规律，才能转向「和递推」；常见撞坑链：① 只试差分→误判无规律而放弃；② 试「和」时忘记修正常数，直接取 1101（选项里没有）；③ 交替常数 7、4 记反或漏减→落到 1254 一类偏大值。", "img": ""}, {"q": "-18，9，3，6，7，（ ）", "src": "26年省考35季 第33题", "hit": false, "ans": "B", "opts": ["A.8", "B.9", "C.12", "D.13"], "solve": "试递推 `aₙ=aₙ₋₁+aₙ₋₂×k`，由 `3=9+(-18)k` 解得 **k=1/3**，回验 `6=3+9/3`、`7=6+3/3` 均成立，故 `a₆=7+6/3=`**9**。", "analysis": "- 体系定位：数量关系 → 数字推理 → 递推（清单原名：数字推理·递推数列）；上位「数字推理」→ 本题「aₙ=aₙ₋₁+aₙ₋₂×k，k=1/3」→ 下级变式「三项递推、加减乘混合式」。\n- 识别信号：数列含**负数**、忽大忽小**无单调**、项数偏少 → 优先试递推 `aₙ=aₙ₋₁+aₙ₋₂×k`。\n- 本质：每一项由**前两项线性组合**生成（考项与项的组合规律），核心是**系数反解 + 多组回验**。\n- 通式：`aₙ = aₙ₋₁ + aₙ₋₂ × k`，k 由前几项反解；同类判别条件：看到含负项且无单调 → 先设递推式反解 k，再用≥2 组验证。\n- 易混·易错链：与「二级(做差)」区分——二级看**差列**成规律，递推看**项的组合**；撞坑链：只验 1 组就下结论 → 系数假象 → 后续全错。", "img": ""}]}]}, {"name": "幂次", "star": false, "children": [{"name": "n²、n³ 加修正项 c，分别找底数与修正项规律", "star": false}]}, {"name": "分数", "star": false, "children": [{"name": "分子、分母分别成规律；或通分后统一观察", "star": false, "examples": [{"q": "1/6，3/21，5/36，7/51，（ ）", "src": "2025广东省考真题 第34题", "hit": true, "ans": "B", "opts": ["A.1/17", "B.3/22", "C.3/44", "D.9/57"], "solve": "第2项 1/7 是 3/21 的约分伪装；还原后分子 1,3,5,7,9（+2）、分母 6,21,36,51,66（+15）→ 9/66=3/22。", "analysis": "**识别信号**：分数形式；某项不规整或与邻居不同频（疑似被约分）。\n**核心规律**：分子、分母两栏各自成规律，先通分还原、==解锁被约分折叠的真值==（第 2 项 1/7 实为 3/21 的约分伪装；还原后分子 1,3,5,7,9（+2）、分母 6,21,36,51,66（+15））。打法：拆两栏分别找规律再拼合；本题通项 (2n−1)/(15n−9) → 9/66＝**3/22**。\n**易混·易错链**：最像「等差/等比数列」——纯等差能一眼到底、分数数列必须拆两栏分别看，不能整体做差；撞坑链：不还原被 1/7 骗（分子成 1,1,5,7 无规律就判「不是分数数列」乱试）→ 分母 +6/+12 跳到 57 命中 D（分子对分母错）→ 整体暴力通分费时易错。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/sl/1-f9b042e9b1.png"}, {"q": "21.98，18.77，17.49，14.55，（ ）", "src": "2024广东省考真题 第34题", "hit": false, "ans": "A", "opts": ["A.12.26", "B.13.66", "C.14.26", "D.15.66"], "solve": "小数数列看数位——每项都满足「整数部分＝小数两位数字之和＋4」（21=9+8+4、18=7+7+4…），四选项中唯有 12.26 满足（2+6=8，12−8=4），秒选 A。", "analysis": "- 体系定位：数量关系 → 数字推理 → 分数（清单原名；本题实为「小数数列」，与「分子分母分别成规律」同宗，建议在〈数字推理〉下新增〈小数(数位)数列〉（待核)）；上位＝数字推理，本级＝小数/数位数列，下级变式＝纯小数数列、整数小数交叉递推。\n- 识别信号：数列各数带小数点、或像「整数段＋小数段」两截 → **先拆段、先算整数与小数各位数字之差/和，别急着做差**。\n- 本质：剥掉小数外壳，考的是「数位之间逐项的固定运算关系」（本题：整数＝小数两位数字和＋4），不是相邻项递推；做差只是干扰。\n- 通式：先拆「整数段 / 小数段」，验证是否存在 `整数段 = 小数段各位数字之和 ± c`、`各位数字之积 = 常数` 等逐项恒等关系；再用该恒等式代入选项筛唯一，辅以数列递减/递增趋势排除。\n- 易混·易错链：最易与「二级等差」混（做差后 3.21/1.28/2.94 看似有值）；区别：二级等差的二级差会呈等差/等比，本题二级差无规律 → 必转数位。撞坑链：只顾做差 → 卡死 → 乱蒙。", "img": ""}]}]}, {"name": "多重(交叉)", "star": false, "children": [{"name": "奇偶项分开成规律，或两两、三三分组观察", "star": false, "examples": [{"q": "1，4，27，16，125，36，（ ）", "src": "2025广东省考真题 第33题", "hit": true, "ans": "D", "opts": ["A.271", "B.512", "C.400", "D.343"], "solve": "奇偶拆列：奇位 1,27,125＝1³,3³,5³（奇数立方）→ 第7位＝7³=343；偶位 4,16,36＝2²,4²,6² 作旁证。", "analysis": "**识别信号**：项间量级忽升忽降、差与比都不定（小大交错）。\n**核心规律**：先按奇偶位拆两条子列，各子列自成幂次规律（奇位立方、偶位平方）（奇位 1,27,125＝1³,3³,5³→第 7 位＝7³＝343；偶位 4,16,36＝2²,4²,6² 作旁证）。打法：奇位＝(2k−1)³ 即 1³,3³,5³,7³…；偶位＝(2k)² 即 2²,4²,6²… → 第 7 位＝**7³＝343**。\n**易混·易错链**：最像「幂次数列」——分法：幂次数列是整条都近同一族幂次、底数成规律，多重数列先按奇偶位拆两条子列再各找规律；撞坑链：只对整条找幂次/等差、漏掉 4,16,36 干扰致底数断档 → 把 125 误当「5 的 5 次方」、把立方说成平方（**指数混淆**）→ 差/比不成立后乱试。", "img": ""}]}]}, {"name": "多级运算", "star": false, "children": [{"name": "依次试一阶差、和、积、商，找稳定运算规律", "star": false, "examples": [{"q": "1，3/2，2，3，6，18，（ ）", "src": "26年省考34季 第31题", "hit": false, "ans": "B", "opts": ["A.88", "B.78", "C.68", "D.58"], "solve": "一阶差 = 1/2、1/2、1、3、12，差值相邻相除恰为 **1、2、3、4**，故下一差 = 12×**5** = **60**，末项 = 18+60 = ==78==（B）。`", "analysis": "- 体系定位：模块〈数字推理〉→ 子类〈多级运算〉→ 单元〈依次试一阶差、和、积、商，找稳定运算规律〉（清单原名：数量关系·数字推理·多级运算）；体系位置：上位〈多级运算：差/和/积/商逐级试（含做一次差）〉→ 本题〈一阶差 = 1/2、1/2、1、3、12，再取相邻商得 1·2·3·4 等差〉→ 下级变式〈差数列本身成等比 / 差数列再取差（二阶差）/ 差与积交替〉。\n- 识别信号：一串**整体递增、增幅持续变大**的数（可含分数如 3/2），且**选项尾数相同、只差十位**（88/78/68/58）→ 先做**一阶差**；看到「差数列自己还在剧烈变化」→ 立刻在差上**再做一层运算（商或差）**。\n- 本质：考的不是「这是什么数列」，而是**把混杂的「底数＋增量」逐层剥离**的能力——先差（去底数）再商（锁倍率），内核是「多级递推的逐层降维」，判分点落在**能否想到做完一次差之后还要再运算一层**。\n- 通式：`aₙ = a₁ + Σbᵢ`，其中差数列 `b` 满足 `b_{i+1} = b_i × i`（i=1,2,3,4…）；本题 `b = 1/2, 1/2, 1, 3, 12, 60`，等价于 `bᵢ = (i−2)!/2`（i≥2）。同类题固定动作：写一阶差 → 对差取比或取差 → 找「倍率等差」或「二阶恒量」。\n- 易混·易错链：最像〈数字推理·二级等差/等比〉——区别只在**做一次差后差数列本身是否「定值」**：差数列自身等差/等比才叫二级，本题差数列是「**商递增**」（1·2·3·4），故归**多级运算**；常见撞坑链：①误走「乘积递推」(a_{n+2}=a_n·a_{n+1}) 得 108（不在选项，且第 3 项 1×3/2=3/2≠2 即已崩）②差数列规律找到后**忘记回加末项**，直接把 60 当答案（60 不在选项，可自检）③把「倍率递增」误当「倍率恒定=4」而落 C。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/sl/2-d183678646.png"}]}]}, {"name": "数阵", "star": false, "children": [{"name": "按行、列、对角、外围找和积差商关系", "star": false, "examples": [{"q": "【数阵】每行三列：第1行 5、5、2.5；第2行 24、12、8；第3行 54、18、13.5；第4行 ？（ ）", "src": "2025广东省考真题 第35题", "hit": true, "ans": "D", "opts": ["A.55，11，5.5", "B.40，10，2.5", "C.75，15，10", "D.60，15，12"], "solve": "每行：第一数÷第二数＝行号 n、第一数÷第三数＝n+1（第4行：60÷15＝4、60÷12＝5）。", "analysis": "**识别信号**：数阵/表格按行成组，出现 2.5、13.5 这类小数（倍数 / 商的强信号）。\n**核心规律**：行内两两相除得连续自然数——==行号参与规律==（商型数阵）（每行「第一数÷第二数＝行号 n」且「第一数÷第三数＝n+1」双约束 → 第 4 行只有 60、15、12）。打法：第 n 行 a÷b＝n、a÷c＝n+1，即 a:b:c＝n(n+1):(n+1):n → 第 4 行 **60:15:12**。\n**易混·易错链**：最像「和/差/积型数阵」（换运算而已）；撞坑链：只在单列找规律就作答 → 忽略第三列除数是 n+1（只核 a÷b=n 会误选 B）→ 只纵向做差找不到统一规律、陷入逐个试算。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/sl/2-c299a7218c.jpg"}, {"q": "〔图:题干/35_1.png〕", "src": "26年省考35季 第35题", "hit": true, "ans": "B", "opts": ["A.6", "B.8", "C.9", "D.10"], "solve": "按行验 `右 = 3×左 + 中`：`13=3×3+4`、`39=3×11+6` 双行成立，故 `35=3×9+?` ⇒ `? = 35-27 = `**8**。", "analysis": "- 体系定位：数量关系 → 数字推理 → 数阵（清单原名：数字推理·数阵／图形数阵）；上位「数字推理」→ 本题「3×3 行关系 右=3×左+中」→ 下级变式「列/对角关系、四则混合、外围运算」。\n- 识别信号：题干为**九宫格/3×3 表格含问号**、无文字描述 → 依次试行、列、对角、外围的和积差商。\n- 本质：把线性关系藏在**数阵的行/列组合**里，考的是**定位关系式并反解系数**。\n- 通式：先试 `第3列 = k·第1列 + 第2列`（行内 `c = k·a + b`），用两行反解 k 再代其余行；同类判别条件：看到九宫格问号 → 优先按行试 c=k·a+b。\n- 易混·易错链：与「递推」区分——递推是**一维相邻项**，数阵是**二维行列**；撞坑链：只验一行就定系数 → 系数假象 → 全盘错。", "img": "data:image/png;base64,"}]}]}]}, {"name": "计算技巧", "star": false, "children": [{"name": "尾数", "star": false, "children": [{"name": "只算末位数字（0–9），末位唯一对应选项", "star": false}]}, {"name": "首数", "star": false, "children": [{"name": "分子分母各取前 1–2 位估算，定出首位", "star": false}]}, {"name": "等差求和", "star": false, "children": [{"name": "和=(首项+末项)×项数/2；项数=(末−首)/公差+1", "star": false, "examples": [{"q": "老师将一些糖果分给7位小朋友，每人所得糖果数构成等差数列，此时还剩14颗糖果，若将剩余糖果全部分给其中1位小朋友后，7人所得糖果数仍构成等差数列，且最多者是最少者的2倍。则老师原来共有多少颗糖果？", "src": "26年省考34季 第43题", "hit": false, "ans": "C", "opts": ["A.146", "B.136", "C.126", "D.116"], "solve": "总数−剩余14 = 7×中项，**必为7的倍数**；四选项只有 126（126−14=112=7×**16**）满足 → 直接锁 C。", "analysis": "- 体系定位：数量关系 → 计算技巧 → 等差求和（清单原名）；体系位置：上位「等差数列识别」→ 本题「等差应用题·中项×项数」→ 下级变式「已知总和反求公差/首末项」。\n- 识别信号：题干出现「构成等差数列/每人所得成等差/最多者是X的k倍」＋给出「剩余/多出」的确定数 → 优先想「和=中项×项数」的整除口；「两个状态都等差」→ 先抓不变量（剩余数、总和）。\n- 本质：奇数项等差数列 和=n×中间项，故「总数−余数」必被 n 整除；再叠加极端约束（最多=最少×2）保证新数列唯一。考的是**等差中项性质＋整除排除**。\n- 通式：n项等差（n为奇数）和=n×中项；本题 `总数 = 7×中项 + 14` ⇒ 先用 `(总数−余数) mod 7 = 0` 砍选项，再回验极端条件。\n- 易混·易错链：最像「数字推理·等差」（那是纯数列补缺、无应用题外壳，看有无「剩余/倍数」外壳即可分）；撞坑链：① 直接按平均数算、忘验整除；② 只验整除不回验「最多=最少×2」，误留多解。\n- 体系定位补充：清单无「数列应用题」独立单元，建议在〈计算技巧〉下新增〈等差数列应用〉（待核）。", "img": ""}]}]}, {"name": "等比求和", "star": false, "children": [{"name": "S=a₁(1−qⁿ)/(1−q)（q≠1）", "star": false}]}, {"name": "平方差", "star": false, "children": [{"name": "a²−b²=(a+b)(a−b)", "star": false}]}, {"name": "裂项相消", "star": false, "children": [{"name": "1/[n(n+1)]=1/n−1/(n+1)，逐项相消", "star": false}]}, {"name": "凑整换元", "star": false, "children": [{"name": "把重复出现的部分设为 t，提取公因式凑整", "star": false}]}]}, {"name": "和差倍比", "star": true, "children": [{"name": "定序求值", "star": true, "children": [{"name": "整数约束的和差倍比：先列方程消元得差值关系，再用大小序列不等式夹逼，锁定唯一整数解后回验", "star": false, "examples": [{"q": "甲、乙、丙、丁四人参加知识竞赛，得分均为正整数，得分从高到低依次是甲、乙、丙、丁。如果甲和乙的总得分为100分，乙和丙的总得分为96分，丙和丁的总得分为80分，则丁的得分为：", "src": "2026广东省考真题 第43题", "hit": false, "ans": "A", "opts": ["A.33", "B.36", "C.39", "D.不能确定"], "solve": "解题方法：整数约束的和差倍比——先列方程做差消元：甲+乙=100、乙+丙=96、丙+丁=80 → 甲−丙=4、乙−丁=16；再按 甲>乙>丙>丁 列不等式夹逼：46<丙<48 → 丙=47 → 丁=80−47=33。选 A。坑：解不唯一时要回来验不等式。", "analysis": "**识别信号**：题干＝几人（多量）两两求和＋「从高到低/从大到小」＋「均为正整数」，求某量；出现「两两之和 ＋ 大小顺序」即切「先做差、再夹逼」。\n**核心规律**：==三式相减消元得差值关系，再用大小序列不等式把连续自由度夹成单点==；「正整数」是收窄区间的最后一道闸。打法：①−②得甲−丙＝4、①−③得乙−丁＝16；由 甲>乙>丙>丁 → 46<丙<48 → 丙＝47 → 丁＝80−47＝33。\n**易混·易错链**：最像「和差倍比·方程法」——分法：方程法解出唯一值即可，本题方程不够、必须借定序不等式封口；撞坑链：只列三式就判「不能确定」（漏定序）→ 代选项不回头验大小关系（甲乙颠倒）→ 忘「正整数」不夹逼、拿连续解。", "img": ""}, {"q": "某社区计划组织志愿者为社区内的独居老人提供服务。按已有志愿者的数量，如果每位志愿者服务10位老人，则有5位老人无人提供服务；如果增加2位志愿者，则每位志愿者最多服务8位老人，则社区独居老人共有（ ）位。", "src": "2024广东省考真题 第45题", "hit": false, "ans": "B", "opts": ["A.50", "B.55", "C.60", "D.65"], "solve": "设志愿者 **n** 人、老人 **N** 位 → `N = 10n+5`；增加2人每人最多8位 ⇒ `8(n+2) ≥ N = 10n+5` ⇒ `2n ≤ 11` ⇒ **n ≤ 5**；选项须同时满足\"个位为5\"与 `n≤5`，唯 **55**（n=5）。", "analysis": "- 体系定位：数量关系 → 和差倍比 → 定序求值（清单原名；判分点：整数约束下先列方程、再用不等式夹逼锁定唯一整数解）；上位＝和差倍比，本级＝整数约束求值，下级变式＝盈亏型、\"最多/至少\"人数-件数应用题。本题属\"盈亏＋整数约束\"，建议在〈和差倍比〉下新增〈盈亏/整数约束〉（待核)。\n- 识别信号：题干出现\"每人分 X 还剩/差 Y\"＋\"再增/减几人则每人最多/至少 Z\" → 列等式 `总量 = 每人分配 × 人数 ± 余数`，把\"最多/至少\"翻译成不等式，夹逼人数。\n- 本质：等式定出总量与人数的关系，不等式把人数的取值收窄到唯一整数——核心是\"方程＋不等式＋整数\"三件套。\n- 通式：设人数 n、总量 N → 由第一条件 `N = a·n ± b`；由\"加 k 人后每人不超过 c\"列 `c(n+k) ≥ N` → 解 n 上界 → 在选项中挑唯一满足 `N = a·n ± b` 者 → 回验不等式。本题 `N=10n+5`、`8(n+2) ≥ N` → `n ≤ 5`。\n- 易混·易错链：最易与「盈亏（假设）法」混；区别：假设法靠\"总差额÷单项差额\"求人数/单价，本题还叠加了\"最多服务\"型不等式，必须回验上界。撞坑链：只列方程得\"疑似值\"就选，忘用不等式剔除 65。", "img": ""}, {"q": "某科研所招聘400多名博士，涉及电子、光学、机械、物理四类专业。其中电子类招聘人数比光学类多50%，机械类招聘人数是物理类的2倍，光学类招聘人数是物理类的5倍，那么机械类招聘人数可能比物理类多多少人？", "src": "26年省考35季 第45题", "hit": false, "ans": "B", "opts": ["A.25", "B.30", "C.40", "D.50"], "solve": "设物理 = p，则四类 `2p、5p、7.5p、p`，总量 `15.5p∈(400,500)` 且 p 为偶数 ⇒ p ∈ {26,28,30,32}；所求 = `2p−p=p`，选项里只 **30** 落此区间。", "analysis": "- 体系定位：数量关系 → 和差倍比 → 定序求值；上位「和差倍比」→ 本题「整数约束＋不等式夹逼锁定唯一解」→ 下级变式「比例分配、抓不变量、占比求总量」。\n- 识别信号：题干给**多个倍数关系**＋\"总数共 N 多名/人数为整数\" → 整数约束和差倍比，列总和不等式夹逼。\n- 本质：把各量化为同一基准的倍数，用**总量取值范围＋整除约束**夹出唯一整数，再回代所求差值。\n- 通式：设基准 = p，各量 = `kᵢp`，`Σkᵢp ∈ 区间` 且各 `kᵢp` 为整数 → 夹逼 p；同类判别条件：看到\"共 N 多名 + 倍数关系\" → 列 `Σkᵢ·p` 的不等式再取整。\n- 易混·易错链：与「比例分配」区分——比例分配总量已知可直接算，本题总量是**范围**需夹逼；撞坑链：漏掉\"人数为整数\"约束 → 多解或错解。", "img": ""}]}]}, {"name": "比例分配", "star": false, "children": [{"name": "总份数求和，每份=总量÷总份数，再乘各自份数", "star": false}, {"name": "设一份为 x，按倍数关系列出各量，再代入和差", "star": false, "examples": [{"q": "某企业组织A、B两个部门全体人员参与培训。已知A部门人数比B部门多20%，B部门人均培训费用是A部门的1.3倍。若A部门的总培训费用比B部门少325元，则A部门人数与人均培训费用分别可能为多少？", "src": "26年省考34季 第36题", "hit": true, "ans": "B", "opts": ["A.25人 100元", "B.30人 130元", "C.36人 100元", "D.40人 169元"], "solve": "解题方法：比例归一——两个比例同以 A 为参照，全换成 A 的倍率（B 人数 5/6、B 人均 13/10），两总量之比＝倍率之积＝13/12；差额 325＝差 1 份 → A总＝12×325＝3900，回代选项 30×130 成立。选 B。", "analysis": "- 体系定位：数量关系 → 数学运算 → 和差倍比 → 单元「和差倍比·比例分配」（清单原名）；体系位置：上位「和差倍比·基础关系」（设一份为 x、按倍数列量再代入和差）→ 本题（两量各含一层倍数，先化成两部门总量之比、再配实际差）→ 下级变式（差改和、两个倍数换成三个部门、\"多 20%\"改写为\"少 1/5\"或分数比）。\n- 识别信号：题干长相＝\"甲比乙多/少百分之几\"＋\"人均/单价是…的几倍\"＋给\"总费用（总量）相差 …元\"；触发词：\"多 20%\"\"是…的 1.3 倍\"\"总共少 325 元\"。\n- 本质：剥掉\"人数—人均—总费用\"外壳，内核就是 **比例＋差值定份**——把两个各含倍数关系的量先约简成总量之比，再用真实差额锚定\"一份\"。\n- 通式：若 `X量 = m·Y量`、`Y的单位量 = n·X的单位量`，则 `Y总 : X总 = n : m`；令份数比 = `n : m`，用 `实际差 ÷ |n−m| = 一份`，再乘各自份数得总量，最后回代校验整数/选项。\n- 易混·易错链：最像「和差倍比·基础关系」（同样靠\"列量＋和差\"求解）；常见撞坑链：①\"A比B多20%\"写成 B = 1.2A（**方向反**）→ 比值颠倒；②把 B人均 169 当成 A人均（**主体错**）；③算出 13:12 就急着选，忘了回代验\"人数为整数 且 `a×p` 与总量一致\"。", "img": ""}, {"q": "某企业在展销会上销售甲、乙两种产品。已知甲产品的库存比乙产品多100件，展销会结束后，甲产品全部售完，乙产品售出库存的60%，两种产品共售出1260件，则甲、乙两种产品原有总库存（ ）件。", "src": "2024广东省考真题 第39题", "hit": false, "ans": "C", "opts": ["A.1450", "B.1500", "C.1550", "D.1600"], "solve": "设乙库存为 **x**，则甲为 **x+100**，售出总量 `(x+100)+0.6x = 1260` → 解得 x = 725，原总库存 = `2x+100 = ` ==1550==。", "analysis": "- 体系定位：数量关系 → 和差倍比 → 方程法（清单原名；见〈和差倍比·方程法〉判分点：设关键量为 x，其余用 x 表示，列等量关系解方程）；上位＝和差倍比，本级＝方程法，下级变式＝多量方程组、含百分比售出/占比反推。\n- 识别信号：题干给\"甲比乙多/少 N\"＋\"某部分按比例售出/用掉\"＋\"合计某数，求总量\" → 直接**设小量为 x**，列一元一次方程。\n- 本质：把\"两量间关系 + 一个合计条件\"翻译成含 x 的一元一次方程；命门在**设哪个量为 x 最省事**（设小量，避免出现 x−100）。\n- 通式：设小量 = x → 另一量用 `x±c` 表示 → 按合计/差列方程 `k·x + b = 合计` → 解 x → 回代求目标。本题：`(x+100)+0.6x = 1260`。\n- 易混·易错链：最易与「占比求总量」混；区别：占比求总量是\"总量=部分量÷占比\"，本题是\"两量关系+合计\"，列方程更稳。撞坑链：设元设成甲 → 式子出 x−100 易漏加 → 误选 1450。", "img": ""}, {"q": "某工厂的1号、2号两条生产线生产同款电池。1号线总产量是2号线的80%，1号线次品率为12.5%，2号线次品率为10%。经统计，两条生产线合格电池总量比1号线总产量多200件，则2号线电池总产量为多少件？", "src": "26年省考35季 第36题", "hit": true, "ans": "B", "opts": ["A.210", "B.250", "C.320", "D.360"], "solve": "设2号线总产量为 x → 合格量 `0.8x×0.875 + x×0.9 = 1.6x`，与1号线 `0.8x` 之差 `0.8x = 200` ⇒ ==x = 250==。", "analysis": "- 体系定位：数量关系 → 和差倍比 → 比例分配；上位「和差倍比」→ 本题「设一份为x、按倍数列各量再代入和差」→ 下级变式「占比求总量、加权平均、抓不变量」。\n- 识别信号：题干给**百分数/比例关系**并出现「A比B多/少 N 件」→ 和差倍比，设一份为 x 列和差。\n- 本质：把多个比例量**统一到同一变量（一份）**，再用**和差条件**建一元方程求解。\n- 通式：设基准量 = x，其余量 = kᵢx，代入 `Σkᵢx − k₀x = Δ` 求 x；同类判别条件：看到\"X 是 Y 的 p%、合格量比…多 m\" → 设 Y = x 列差。\n- 易混·易错链：与「抓不变量」区分——抓不变量靠**和/差不变**，本题靠**倍数关系＋和差条件**；撞坑链：次品率/合格率混用 → 比例取反 → 全盘错。", "img": ""}]}]}, {"name": "年龄", "star": false, "children": [{"name": "年龄差恒定不变，倍数关系随时间改变", "star": false, "examples": [{"q": "小王参加工作时的年龄，和他弟弟现在的年龄相同，小王工作两年后，弟弟也正式参加工作，现在兄弟俩的年龄之和，正好是他们工龄之和的8倍。如果弟弟20岁正式参加工作，则小王比弟弟大（ ）岁。", "src": "2025广东省考真题 第44题", "hit": false, "ans": "B", "opts": ["A.3", "B.4", "C.5", "D.6"], "solve": "设年龄差 d：兄入职年龄＝弟现龄 → 兄工龄＝d；弟工龄＝d−2、弟现龄＝d+18；年龄和 3d+36＝8×(2d−2) → d=4", "analysis": "**识别信号**：题干出现「现在 / 若干年前后」「年龄之和 / 之差」「参加工作 / 入学某年」＋一个年龄节点 → 先写「年龄差 d 恒定」，再把「某人的年龄节点」换算成「工龄 / 年份差」。\n**核心规律**：剥掉「参加工作」外壳只剩两句——①年龄差永远不变；②两人工龄之差＝参加工作的时间差（本题＝2）。命门＝「小王参加工作时的年龄＝弟弟现在年龄」→ **小王工龄恰等于年龄差 d**。打法：设年龄差 d → 由「兄入职年龄＝弟现龄」得兄工龄＝d；弟工龄＝d−2、弟现龄＝d+18；年龄和＝3d+36、工龄和＝2d−2；代「年龄和＝8×工龄和」→ 3d+36＝16d−16 → **d＝4**。\n**易混·易错链**：最像「和差倍比·抓不变量」——分法：抓不变量统一份数，本题把「年龄」直接翻译成「工龄 / 差」；撞坑链：把「弟弟20岁」当成「现在20岁」（两个时间点对调）→ 误以为两人工龄相等（漏掉 2 年差）→ 设两个年龄未知数硬解、把「小王参加工作年龄」代成「小王现在年龄」。", "img": ""}]}]}, {"name": "抓不变量", "star": false, "children": [{"name": "找不变量（和不变/差不变/某量不变），统一其份数", "star": false}]}, {"name": "占比求总量★", "star": true, "children": [{"name": "总量=部分量÷占比；占的是剩余部分时先算剩余量再反推", "star": false, "examples": [{"q": "未来五年，某市计划新增风电装机容量占新能源总装机容量的40%，光伏装机容量占新能源总装机容量的35%，其余为生物质能，已知光伏装机容量比生物质能多120兆瓦，则未来五年，该市新能源总装机容量为（ ）兆瓦。", "src": "2026广东省考真题 第36题", "hit": false, "ans": "D", "opts": ["A.600", "B.800", "C.1000", "D.1200"], "solve": "解题方法：占剩余部分时先算剩余再反推。补齐生物质能占比=100%−40%−35%=25%；光伏比生物质能多 35%−25%=10% =120 兆瓦 → 总量=120÷10%=1200 兆瓦。选 D。", "analysis": "**识别信号**：题干＝「A 占 X%、B 占 Y%、其余为 C」＋「A 比 C 多/少 m」；出现「占…%」「其余」＋一个绝对量差，即切「补全占比 → 差值占比换算」。\n**核心规律**：占比未给全时先补全（其余＝100%−已知占比和），再用 ==占比差↔量差== 反推总量；与占比绝对值无关、也不算别的占比。打法：==总量＝占比差对应的量 ÷ 占比差==（本题 120÷(35%−25%)＝1200）。\n**易混·易错链**：最像「和差倍比·比例分配」——分法：比例分配是已知总量分份数，本题是已知「部分量之差」反求总量；撞坑链：把 120 直接对光伏 35%（→120÷35%）→ 忘补生物质能 25% → 心算占比差出错，滑入 600/800/1000 整百诱饵。", "img": ""}]}]}, {"name": "算术平均", "star": false, "children": [{"name": "平均数=总和÷个数", "star": false}]}, {"name": "中位众数", "star": false, "children": [{"name": "中位数=排序后居中数（偶数取中间两数平均）；众数=出现次数最多", "star": false}]}, {"name": "加权(混合)平均", "star": false, "children": [{"name": "总总量÷总份数；或十字交叉求各部分权重比", "star": false, "examples": [{"q": "某服务大厅设有若干个服务窗口，其中1个是快捷服务窗口，某日服务窗口的平均业务量为29单，其中快捷服务窗口的业务量为41单，其余窗口的平均业务量为28单，则服务大厅共有（ ）个窗口。", "src": "2025广东省考真题 第37题", "hit": true, "ans": "A", "opts": ["A.13", "B.14", "C.15", "D.16"], "solve": "总量守恒：设 n 个窗口，29n＝41+28(n−1)＝28n+13 → n＝13（快捷 1＋其余 12）。", "analysis": "**识别信号**：题干出现「(部分平均) + (另一部分平均) → 整体平均」且求份数/总量（如\"服务窗口有几个\"）。\n**核心规律**：总分守恒——整体总分＝各部分总分之和；忌「平均的平均」。打法：总量＝整体平均×总份数＝Σ(各部分平均×份数)；或 **十字交叉**：权重比＝(整体−低):(高−整体)（本题 (41−29):(29−28)＝12:1 → 其余 12＋快捷 1＝13）。\n**易混·易错链**：误把快捷窗也算进\"其余\"（29n＝41+28n 也有 n=13 但式错）；「平均数的平均 ≠ 总平均」；撞坑——先分清 n 与 n−1。", "img": ""}, {"q": "某助农电商企业销售柠檬、蜜柚两种水果，由于季节变化，这个月蜜柚的销量比上月增加了40%，而柠檬的销量降低了20%，最终当月这两种水果的总销量比上个月增加4%，则蜜柚上月销量占这两种水果上月销量的（ ）。", "src": "2025广东省考真题 第43题", "hit": false, "ans": "C", "opts": ["A.60%", "B.50%", "C.40%", "D.30%"], "solve": "十字交叉：蜜柚:柠檬＝|4−(−20)|:|40−4|＝24:36＝2:3 → 蜜柚占 2/5＝40%。", "analysis": "**识别信号**：「总量由 A、B 两部分构成」＋各部分增/降百分数＋整体增/降百分数 → **三率同框** → 立刻十字交叉，别设未知数。\n**核心规律**：内核＝**两组在基期的权重比**；两个条件（分率、合率）都已知，这就是加权平均权重的反解。打法：十字交叉——`量A:量B ＝ |c−b| : |a−c|`（**差之比＝量的反比**）；本题 `|4−(−20)| : |40−4| ＝ 24:36 ＝ 2:3` → 蜜柚占 2/5 ＝ **40%**。\n**易混·易错链**：最像＝**资料分析·混合增长率**（同一套交叉，但问「整体率落哪」）与**统计·加权平均**；撞坑链＝① 用**现期量**当权重（必须用基期量）② 算出差 36:24 后**忘记取反**、直接当量比（→ 得 60%）③「涨得多≠占比大」方向判反。", "img": ""}, {"q": "某厂家在广交会期间获得了大量的订单，其中，周六签约的客户数量是周日的1.5倍，签约总金额是周日的80%，如果周六、周日共与40家客户定成了签约，订单总金额为720万元（没有重复签约的客户），则周日平均每家客户的签约金额为（ ）万元。", "src": "2026广东省考真题 第37题", "hit": true, "ans": "C", "opts": ["A.15", "B.20", "C.25", "D.10"], "solve": "设周日客户x、金额y：1.5x+x=40→x=16家；0.8y+y=720→y=400万；周日均值=400÷16=25万", "analysis": "**识别信号**：题干＝两天（两组）各给「倍数/百分比」＋一个总数（人数 40、金额 720），问「某组平均」。出现「…是…的 k 倍」「…的 p%」＋总量＋「平均每家」，即切「分子分母须同组配对」。\n**核心规律**：两个比例条件各配一个总量，分别成方程求出周日的人数与金额，再做除法；==命门在分子分母同组配对==，与谁大谁小无关。打法：周日人数＝总量÷(1+k)、周日金额＝总量÷(1+p)，均值＝金额÷人数（40÷2.5＝16、720÷1.8＝400 → 400÷16＝25）。\n**易混·易错链**：最像「和差倍比·方程法」——分法：方程法只求某量、本题两条比例线交叉后要「配对相除」；撞坑链：分子分母错配（用周六 320÷周日 16＝20）→ 拿总人数当分母（400÷40＝10）→ 误当两天金额各半（360÷24＝15）。", "img": ""}, {"q": "某车间甲、乙、丙三条生产线效率之比为2：3：5，甲生产线的次品率为5%，乙生产线的次品率是丙的2倍，对某段时间内三条生产线生产的产品进行检验，总体次品率为3.2%。问乙生产线的次品率是多少？", "src": "26年省考34季 第45题", "hit": true, "ans": "D", "opts": ["A.1%", "B.2%", "C.3%", "D.4%"], "solve": "产量比=效率比=2:3:5，整体率=(2×5%+3×2x+5×x)÷10=3.2% → 11x=22 → x=2%，乙=2x=**4%**。", "analysis": "- 体系定位：数量关系 → 和差倍比 → 加权(混合)平均（清单原名）；体系位置：上位「加权平均/十字交叉」→ 本题「已知总体率反求部分率」→ 下级变式「给总率求权重比」。\n- 识别信号：出现「效率/人数/产量之比」＋「各部分比率」＋「总体比率」→ 判为加权平均，权重=各部分的量（产量∝效率×时间）。\n- 本质：整体比率是「总量÷总份数」，权重是各部分的**产量**，绝非各部分比率的算术平均；本题只是把「浓度/成绩」换成「次品率」外壳。\n- 通式：`总率 = Σ(权重ᵢ×分率ᵢ) ÷ Σ权重ᵢ`；本题 Σ权重=2+3+5=10，解一元一次即得。\n- 易混·易错链：最像「溶液·混合」（同一模型换外壳，看单位是「浓度」还是「率」）；撞坑链：① 用算术平均 (5%+…)/3；② 把「乙是丙的2倍」做成「丙是乙的2倍」（方向反）。", "img": ""}]}]}, {"name": "平均数变化", "star": false, "children": [{"name": "新总和=原总和±加入数，再除以新个数", "star": false}]}]}, {"name": "日期周期", "star": false, "children": [{"name": "星期推算", "star": false, "children": [{"name": "n mod 7；平年 365≡1、闰年 366≡2", "star": false, "examples": [{"q": "只有在星期六，小王才会去图书馆。如果某年3月小王一共有5天去过图书馆，则当年4月1日可能是（ ）。", "src": "2024广东省考真题 第40题", "hit": false, "ans": "A", "opts": ["A.星期二", "B.星期三", "C.星期五", "D.星期六"], "solve": "只周六去图书馆、3月去了5天 → 3月恰有**5个星期六**；周六必落在3月**1/2/3日**之一 → 4月1日 = 3月1日星期 **+3**，可能为 日/一/二，选项中只有**星期二**。", "analysis": "- 体系定位：数量关系 → 日期周期 → 星期推算（清单原名；判分点 `n mod 7`）；上位＝日期周期，本级＝星期推算，下级变式＝跨年星期推进、\"某月有5个周X\"定位月初。\n- 识别信号：题干出现\"星期几\"＋\"某月共N天做了什么/某月有5个周X\" → 立即用 `n mod 7` 和\"31天月有3个星期几出现5次\"。\n- 本质：把\"某星期X出现几次\"翻译成\"星期X落在月初前几天的位置\"（31天月→前3天，30天月→前2天），再用总天数 `mod 7` 推到目标日期。\n- 通式：31天月 = `4周+3天` → 月初3天的星期各出现5次；30天月 = `4周+2天` → 月初2天各5次。推进：`星期(目标日) = (星期(起点日) + 相隔天数) mod 7`。\n- 易混·易错链：最易与「闰年判断」混；区别：闰年只改2月天数，本题不跨2月，无需判闰。撞坑链：只算出\"5个周六\"就直接答周六，忘了要用 `mod 7` 定位月初、再推4月1日。", "img": ""}]}]}, {"name": "闰年判断", "star": false, "children": [{"name": "能被 4 整除，且（不能被 100 整除 或 能被 400 整除）", "star": false}]}, {"name": "周期循环", "star": false, "children": [{"name": "n mod 周期长度，余数对应项（余 0 为周期最后一项）", "star": false, "examples": [{"q": "小张每周六都会和朋友们玩一局桌游，桌游类型为狼人杀和璀璨宝石交替进行。某年2月小张和朋友们共玩了3局璀璨宝石。则小张和朋友们在该年3月最后一次玩狼人杀的日期是：", "src": "26年省考34季 第40题", "hit": false, "ans": "C", "opts": ["A.3月7日", "B.3月14日", "C.3月21日", "D.3月28日"], "solve": "某月要出现5个周六必须\"≥29天且1号是周六\"，而2月只有5个周六时交错才可能凑出3局璀璨宝石 → 故2月1日是璀璨宝石，沿周期顺推，3月狼人杀只落在7日与21日，==最后一次即3月21日==。", "analysis": "- 体系定位：数量关系 → 数学运算 → 日期周期 → 周期循环（清单原名「日期·周期循环」）｜体系位置：与\"日期·星期推算\"\"日期·日期间隔天数\"同属日期周期家族，专解\"某日期落在循环序列第几项／是哪一种\"。\n- 识别信号：题干出现\"每周六／每隔／交替／轮流\"＋\"某月共n次／共n局\"＋最后问\"某日是哪一种、最后一次是哪天\"。\n- 本质：把日历上的日期折算成循环序列的序号；交替序列的相位由\"区间内总次数＋起手类型\"唯一确定，答案再折算回日历日期。\n- 通式：设周期长`T`，区间内总次数`N`、目标类型出现`k`次 → `k`与`N−k`之差不超过1，取较大者即为起手类型；末项类型由`N`的奇偶决定。日期桥接式：==某月出现5个某星期 ⟺ 该月≥29天且1号恰为该星期==（28天的月份每种星期必为4个）。\n- 易混·易错链：最像\"日期·星期推算\"（同样用mod 7与日期）→ 常见撞坑链：①漏判\"2月须闰年（29天）才可能有5个周六\"就无从下手 → ②相位判反，把起手当成狼人杀 → ③把\"最后一次\"读成\"第一次\" → 误选A → ④3月日期错位，把28日（璀璨宝石）当成狼人杀 → 误选D。", "img": ""}]}]}, {"name": "钟表夹角", "star": false, "children": [{"name": "分针 6°/分、时针 0.5°/分，夹角=|30h−5.5m|（取 ≤180°）", "star": false}]}, {"name": "间隔天数", "star": false, "children": [{"name": "按月累加，注意大小月与 2 月天数；同日期用年差换算", "star": false}]}]}, {"name": "工程问题", "star": false, "children": [{"name": "给定时间", "star": false, "children": [{"name": "总量设为 t₁、t₂ 的最小公倍数（或 1），效率=总量÷时间，合作效率相加再求时间", "star": false, "examples": [{"q": "一条道路，如果由甲队单独铺设30天可完成；如果由甲队先铺设12天，再由乙队铺设24天即可完成。现甲、乙两队合作，一起铺设8天后，甲队、乙队的效率分别提升10%和20%，问这条道路还需多少天可完成铺设？", "src": "26年省考35季 第43题", "hit": true, "ans": "A", "opts": ["A.8", "B.6", "C.10", "D.9"], "solve": "设总量 **120**，甲效 **4**；由 `12×4+24×乙=120` 得乙效 **3**；合作8天做 56，余 64，提效后合效 `4.4+3.6=8` → `64÷8 = `==8== 天。", "analysis": "- 体系定位：数量关系 → 工程问题 → 给定时间；上位「工程问题」→ 本题「设总量＋分段求效率、提效后反算时间」→ 下级变式「给定效率比、中途加减、交替工作」。\n- 识别信号：题干给**单独完成时间**＋\"先做 A 天再由 B 做 C 天\" → 工程·给定时间，设总量（LCM 或 1）。\n- 本质：把工作总量虚拟化为可整除的数，用 **效率×时间 = 工作量** 分段守恒求和。\n- 通式：设总量 = 时间的最小公倍数；`效率 = 总量÷时间`；合作合效相加；`剩余量 ÷ 新合效 = 剩余天数`；同类判别条件：看到多个完成时间 → 设总量为这些时间的最小公倍数。\n- 易混·易错链：与「中途加减」区分——中途加减是**参与主体变化**，本题是**同一主体效率变化**；撞坑链：提效后仍用旧效率，或总量取 1 致分数连算失误。", "img": ""}]}]}, {"name": "给定效率比", "star": false, "children": [{"name": "总量一定时时间与效率成反比：效率 3:2 → 时间 2:3", "star": false}]}, {"name": "效率比例", "star": false, "children": [{"name": "只给人数/机器数比例时，设人数或效率为特值 1，总量=效率×时间", "star": false, "examples": [{"q": "某蓄电池可以同时供20台设备运行5天，在供20台设备运行12小时后，又新增了5台设备。如果所有设备每天的耗电量相等，则该蓄电池还可以供这些设备运行（ ）天。", "src": "2026广东省考真题 第38题", "hit": false, "ans": "B", "opts": ["A.3.5", "B.3.6", "C.3.8", "D.4.0"], "solve": "解题方法：总量归一——电量按「台·天」计，总量=20×5=100 台·天；已耗=20×0.5=10（12h=0.5 天）；剩 90；新增 5 台后共 25 台 → 90÷25=3.6 天。选 B。坑：小时须折天（12h=0.5 天）。", "analysis": "**识别信号**：题干＝「可同时供 n 台运行 T 天，先运行 t，又新增 Δn 台，还可运行几天」；出现「台·天」「中途新增」「还可运行」即切「总量归一、扣已耗」。\n**核心规律**：把抽象电量化为「台·天」总量（总量＝台数×天数），==先按原台数扣已耗、再按新台数均分剩余==；时间须先折成天。打法：剩余天数＝==n₁·(T−t) ÷ (n₁+Δn)==（20×(5−0.5)÷25＝3.6），12h 须折 0.5 天。\n**易混·易错链**：最像「工程·中途加入/离开」——分法：本题定量是「消耗型总量」、扣耗必须在新增之前、时点不能错位；撞坑链：12 小时漏折算成 0.5 天 → 把「新增 5 台」当电量直接扣（→3.8）→ 忽略已耗（100÷25＝4.0 整数诱饵）→ 扣耗按新增后 25 台算（→3.5）。", "img": ""}, {"q": "甲工程队有x名工人，用y天可完成一项工程。乙工程队比甲工程队多24名工人，两队合作完成这项工程的时间比甲工程队单独完工时间的一半还少3天。已知每名工人效率相同，则x和y的关系式为：", "src": "26年省考34季 第39题", "hit": false, "ans": "D", "opts": ["A.x=6-y", "B.x=12-2y", "C.x=y-6", "D.x=2y-12"], "solve": "必做·列一式即得——设每人效率为 1，总工程量为 `x·y`，合作式 `(x+x+24)(y/2−3)=xy` 一次展开化简即 `x=2y−12`。", "analysis": "- 体系定位：数量关系 → 工程问题 → 效率比例（清单原名：工程·效率比例型）；坐落于「数学运算·工程问题」之下，与「给定时间」「给定效率比」并列，是靠人数／效率关系直接列式的一支。\n- 识别信号：出现「x 名工人」「y 天完成」「每名工人效率相同」「乙比甲多 24 人」「时间比…的一半还少 3 天」，且选项是 x、y 的关系式——题干把人数代数式与时间关系直接交出，考的就是把文字翻成等式。\n- 本质：同一工程量在「甲单干」与「两队合作」两条路径下守恒，一个守恒等式消去总量，直接解出 x、y 的一次关系。\n- 通式：设每人效率为 1，总量 = 人数 × 天数；合作型 `(x + (x+Δ))(y/2 − d) = x·y`（Δ=乙队多出人数、d=合作比一半少的天数），展开后含 xy 的项两侧相消 → 得 x、y 的一次关系式。\n- 易混·易错链：最像「工程·给定完成时间」（设最小公倍数求合作时间），但本题合作时间是含 y 的式子而非已知数；常见撞坑链 ①漏加乙队多出的 24 人 → ②合作时间忘减 3 天（写成 y/2+3）→ ③展开后没把 xy 项消掉 → ④移项整理把 x 与 y 的系数符号弄反（正是 B 的坑）。", "img": ""}]}]}, {"name": "中途加减", "star": false, "children": [{"name": "分段列式，各段工作量=该段参与主体效率之和×该段天数，总量守恒", "star": false, "examples": [{"q": "甲、乙两个工程队合作实施某项工程，原计划30天完成，但工作5天后甲被抽调到其他工程，又过了15天该工程正好完成一半，此时丙工程队加入，3天后甲工程队返回，最终该工程比原计划提前2天完成，则丙工程队的效率是甲工程队的（ ）倍。", "src": "2025广东省考真题 第39题", "hit": false, "ans": "D", "opts": ["A.1.5", "B.2", "C.2.5", "D.3"], "solve": "半程双视角：5(甲+乙)+15乙＝15(甲+乙)→乙＝2甲；后半 3(乙+丙)+5(甲+乙+丙)＝45甲 → 丙＝3甲 → D。", "analysis": "**识别信号**：「被抽调／加入／返回」＋「完成一半（几分之几）」＋「提前/推迟完成」→ 中途加入或离开型；**「完成一半」＝半程节点信号** → 优先「双视角列等」。\n**核心规律**：总量守恒下，按人员变动**切段求和**；破题核心是**找节点**（半程点 / 加入点 / 返回点 / 终点），而不是逐日硬算。打法：W＝30(甲+乙)（原计划）→ 半程双表示 `5(甲+乙)+15乙＝15(甲+乙)` → 得 **乙＝2甲** → 后半段 `3(乙+丙)+5(甲+乙+丙)＝45甲` → **丙＝3甲**。手法＝**特值化（设甲=1）＋比例化（先推效率比）**。\n**易混·易错链**：最像＝**「给定效率比型」**（本题效率比要自己推，不是给定）；连环坑：把 **乙＝2甲 误当丙**（→B）、**漏算丙在甲返回后仍在场**（→丙无解/错值）、后半段天数乱取（拿 28−15 之类）。", "img": ""}]}]}, {"name": "牛吃草", "star": false, "children": [{"name": "总量=(牛吃速−草生长速)×天数；列两式相减先求生长速，再求牛吃速", "star": false}]}, {"name": "交替工作", "star": false, "children": [{"name": "一个周期工作量=各主体效率之和，总量÷周期量求整周期数，余量按顺序分配", "star": false}]}]}, {"name": "行程问题", "star": false, "children": [{"name": "相遇", "star": false, "children": [{"name": "相遇：①相遇时间 t=路程和÷速度和；②相遇点距任一端=该端出发者速度×t（同时出发时）", "star": false, "examples": [{"q": "父子两人在百米赛道上匀速跑步，两人从赛道起点同时出发，父亲跑到终点时，儿子距离终点还有40米，若父亲立即折返跑向赛道起点，则两人相遇时，儿子距离终点还有（ ）米。", "src": "2025广东省考真题 第38题", "hit": false, "ans": "C", "opts": ["A.35", "B.30", "C.25", "D.15"], "solve": "v父:v儿=100:60=5:3；折返后相距40m相向相遇，儿再走=40×3/8=15m → 位置60+15=75 → 距终点100−75=25。", "analysis": "**识别信号**：两人同时同向出发 → 一人到点折返 → 问再相遇位置/时间（\"折返＋相遇\"同现）。\n**核心规律**：同向段先定**速度比**（同时同地出发，同时间路程比＝速度比）；折返后切**相向相遇**，合走距离＝原来的路程差。打法：v父:v儿＝s父:s儿（同时间）；折返后相遇：合走＝父折返点−儿位置；儿再走＝合走×v儿÷(v父+v儿)；新位置＝儿原位置＋儿再走，距终点＝100−新位置。\n**易混·易错链**：①把\"儿子距终点40\"误当追及路程差直接套追及公式；②折返后忘了变\"相向·合走\"（仍按同向算）；③速度比用反（儿:父＝5:3）→ 错位到 D=15。", "img": ""}, {"q": "某电力公司使用甲、乙两架无人机对一条输电线路的某覆冰区段进行除冰，甲的除冰效率是乙的1.25倍。原计划甲、乙分别从覆冰区段两端向中间同时开始除冰，完成除冰任务时的位置距离覆冰区段中点60米；现将甲的除冰效率提高一倍，并由其单独除冰，完成除冰任务用时比原计划少了2.4分钟。问甲效率提高后的除冰效率为多少？", "src": "26年省考34季 第38题", "hit": true, "ans": "C", "opts": ["A.25米/分钟", "B.30米/分钟", "C.50米/分钟", "D.60米/分钟"], "solve": "甲:乙效率**=5:4** → 甲比乙多走全程的**1/9**、即距中点**60米**⇒多走120米⇒全长`S=18×60=`**1080米**；原合作**9份**、甲提速后单干**10份**，用时差`S/9份−S/10份=1080/(90份)=2.4`⇒**1份=5**⇒甲提速后`10×5=`==**50米/分钟**==。", "analysis": "- 体系定位：数量关系 → **行程问题** → **相遇**（清单原名「行程·相遇（相向）」，判分点：路程和=速度和×时间）＋ 体系位置：行程·比例关系（上位，路程比=速度比）→ **本题**（两端向中间＋距中点定全长）→ 下级变式（一端出发多次相遇、环形反向相遇）。第二段\"单主体效率变化\"属「工程·效率变化」，是嵌套，不是主考。\n- 识别信号：看到\"**两端 / 相向 / 同时出发**\"＋\"**距中点 x 米**\"→ 立刻做『路程比=速度比，离中点偏差 = (快份−总份一半)×S』定全长；看到\"效率是…的 **1.25 倍**\"→ 直接读作 **5:4** 设份，别用小数。\n- 本质：相向而行的核心不变量是\"**时间相同 ⇒ 路程比 = 速度比**\"；题眼是\"距中点\"把抽象的速度比翻译成具体的全程长度，再用\"**时间差**\"把速度份数一次锁定。一句话：考的是\"速度比 ⇄ 路程比\"的翻译与\"用时间差反推速度\"。\n- 通式：设甲:乙=`a:b`、距中点 `d`，则 **全长 `S = 2d(a+b)/(a−b)`**（本题 `2×60×9/1=1080`）；甲提速一倍单独干的场景，**提速后效率 `= 2a·k`**，其中 **`k = (S/ΔT)·[1/(a+b) − 1/(2a)]`**（本题 `(1080/2.4)×(1/9−1/10)=450/90=5`）。\n- 易混·易错链：最像的是“**工程·给定效率比**”（只问时间反比、无中点无全程）——分辨一句话：**有\"距中点 / 位置偏移\"就按行程相遇定全长，只有\"谁几天干完\"才是纯工程**。常见撞坑链：把\"距中点60米\"当成甲比乙多走60米（实为**多走120米=2×60**）→ 全长算错 → 全盘皆错；把\"提高一倍\"误读为\"提高0.25倍 / 变成1.25倍\"；最终问\"提速**后**\"却回了\"提速前\"的25。", "img": ""}]}, {"name": "两端同时出发，第 n 次相遇总路程=(2n−1)S；一端出发用单程往返规律", "star": false}]}, {"name": "追及", "star": false, "children": [{"name": "追及：①追及时间 t=路程差÷速度差；②追上点位置=快者速度×t（快者比慢者多走的正好是路程差）", "star": false, "examples": [{"q": "甲、乙两人在小区内晨跑，速度分别是140米/分钟和100米/分钟。他们同时从小区跑道的起点向终点匀速跑步，各自不停地在起点和终点往返。如果该跑道的长度为200米，则当甲第二次追上乙时，距离起点（ ）米。", "src": "2026广东省考真题 第45题", "hit": false, "ans": "A", "opts": ["A.0", "B.50", "C.100", "D.200"], "solve": "往返追及：同向追上即甲比乙多跑一整圈（往返 2×200=400 米）；第二次追上=多跑 800 米 → 用时 800÷(140−100)=20 分；甲跑 140×20=2800、乙跑 100×20=2000，均为 400 的整数倍 → 两人同在起点，距起点 0 米。选 A。坑：把相向「相遇」（100 米处）当追上；把「第一次追上」（终点）当第二次。", "analysis": "**识别信号**：题干＝「两人同起点、不停往返」，问「第 n 次追上时距起点多少米」；出现「往返/折返 ＋ 追上」即切「追上＝多跑整圈（往返 2L）」。\n**核心规律**：==同向「追上」＝快者比慢者多跑一整圈（往返 2L）==，与「相向相遇」（合跑整圈）严格区分；追上时刻落点随次数在两端交替。打法：第 k 次追上＝多跑 ==2L·k==，t＝(2L·k)÷(v快−v慢)（本题 400×2÷40＝20 分）；甲 140×20、乙 100×20 均为 400 的整数倍 → 同在起点 0 米。\n**易混·易错链**：最像「行程·多次相遇 / 环形跑道」——分法：相遇按「路程和」、追上按「路程差」，往返一圈＝2L；撞坑链：把「相向相遇」（100 米处）当追上 → 把「第一次追上」（终点）当第二次 → 忽略折返用直线距离硬算。", "img": ""}]}, {"name": "往返追及：①追上＝快者比慢者多跑一整圈（往返 2S）；②第 k 次追上用时 t=k·2S÷速度差；③位置＝某人路程 L=v·t 对 2S 取余 r：r=0 距起点 0 米（起点）、r=S 距起点 S 米（另一端）、0<r<S 距起点 r 米、S<r<2S 距起点 2S−r 米", "star": false}]}, {"name": "流水行船", "star": false, "children": [{"name": "顺=船+水、逆=船−水；船速=(顺+逆)/2，水速=(顺−逆)/2", "star": false}]}, {"name": "火车过桥/错车", "star": false, "children": [{"name": "过桥路程=桥长+车长；错车路程=两车长之和，相向用速度和、同向用速度差", "star": false}]}, {"name": "平均速度", "star": false, "children": [{"name": "等距离平均速度=2v₁v₂/(v₁+v₂)，≠ 速度的算术平均", "star": false, "examples": [{"q": "小李从山脚开始登顶，匀速走了1小时后到达一个凉亭，并在凉亭休息了半小时。继续走500米后，恰好完成登顶路程的一半。从山顶沿原路匀速返回时，他走了1小时又到了这个凉亭，继续走半小时回到了山脚。则登顶路程为（ ）米。", "src": "2024广东省考真题 第44题", "hit": false, "ans": "B", "opts": ["A.2000", "B.3000", "C.3600", "D.4000"], "solve": "设山脚→凉亭 = **d** 米，则上山速 `v_up = d`（1小时的路）、下山速 `v_down = d÷0.5 = ` **2d**；下山\"山顶→凉亭\"走1小时 ⇒ `D−d = 2d` ⇒ `D = 3d`；再由\"亭+500米=半程\" `d+500 = D/2` ⇒ **d = 1000** ⇒ `D = ` ==3000==。", "analysis": "- 体系定位：数量关系 → 行程问题 → 平均速度（清单原名；本题实为\"匀速往返·分段行程\"，建议在〈行程问题〉下新增〈基本行程（匀速·往返分段）〉（待核)）；上位＝行程问题，本级＝往返两速度，下级变式＝上下坡往返、走走停停求时间。\n- 识别信号：题干出现\"去/回、上山/下山、往返、中途休息、恰好走了全程一半\"＋\"匀速\" → 设路程与两速度，用 `路程 = 速度×时间` 列方程。\n- 本质：把\"同一段路（或往返）在两种速度下用时不同\"翻译成多个\"速度×时间=路程\"等式；命门是**用同一路段的两次用时定出两速度之比**。\n- 通式：设某段 = d、全程 = D；`v_up = d/t₁`、`v_down = d/t₂`；由另一段用时列 `D−d = v_down × t`，再由\"是全程几分之几\"列 `d + Δ = k·D`，联立求解。本题 `v_up=d, v_down=2d` → `D=3d` → `d=1000`。\n- 易混·易错链：最易与「平均速度」混；区别：平均速度题求\"全程平均速度=2v₁v₂/(v₁+v₂)\"，本题求路程，走\"速度-时间-路程方程\"。撞坑链：把\"亭在山脚侧某处\"当成\"亭在半程\"，或把休息时间代入，导致 D 算成 2d。", "img": ""}]}]}, {"name": "环形", "star": false, "children": [{"name": "同向追及：路程差=n×周长（速度差）；反向相遇：路程和=n×周长（速度和）", "star": false, "examples": [{"q": "在一个周长为400米的环形跑道上，林、李、江三人同时同向出发匀速跑步。林与李从跑道起跑线出发，江从起跑线后方一段距离处出发。当李跑完1圈时，林落后其150米，而江超过林70米。若李跑完2圈时，江恰好追上李，则江起跑时距离起跑线多远？", "src": "26年省考35季 第41题", "hit": false, "ans": "C", "opts": ["A.80米", "B.120米", "C.160米", "D.200米"], "solve": "以李1圈为基准时刻 t₁，t₂=2t₁（李2圈）；江两次行程 `s+320`、`s+800` 同比 → `2(s+320)=s+800` ⇒ `s = `**160**。", "analysis": "- 体系定位：数量关系 → 行程问题 → 环形；上位「行程问题」→ 本题「同向追及＋时间倍数设基准」→ 下级变式「相遇、往返追及、流水行船」。\n- 识别信号：题干出现**环形跑道/同向/追上**并给某时刻的位置差 → 环形同向追及，用**时间基准＋同位置等量**。\n- 本质：同一时刻各人位置 = 初位 + 速度×时间；匀速下用两个时刻列**行程比 = 时间比**，反解起点差。\n- 通式：`位置 = 起点差 + v·t`；两时刻给定位移或同位置 → 列 `(s+Δ₁)/t₁ = (s+Δ₂)/t₂`（t₂/t₁ 由圈数定）；同类判别条件：看到环形＋两时刻距离/圈数 → 列行程同比解起点差。\n- 易混·易错链：与「追及」区分——追及求时间/追上点，环形题常求**起点差**；撞坑链：把\"超林70米\"当速度差位移或漏起点差 → 方程无解或错根。", "img": ""}]}]}, {"name": "发车间隔", "star": false, "children": [{"name": "车身间距=车速×发车间隔，用车速±人速的相对速度列式", "star": false}]}]}, {"name": "经济利润", "star": false, "children": [{"name": "基本互求", "star": false, "children": [{"name": "利润=售价−成本；利润率=利润/成本；售价=成本×(1+利润率)", "star": false}]}, {"name": "打折", "star": false, "children": [{"name": "最终价=原价×(1+涨幅)×折扣率；利润率一律对成本计算", "star": false, "examples": [{"q": "某商场在售的四款家电产品能效、标价及折扣等信息如下表所示。根据补贴规则，二级能效的家电产品可获得最终销售价格15%的补贴，一级能效的家电产品可获得最终销售价格20%的补贴，如果家电产品的最终销售价格＝标价×折扣，则购买以下家电中的（ ）获得的补贴金额最多。", "src": "2025广东省考真题 第41题", "hit": false, "ans": "D", "opts": ["A.甲冰箱", "B.乙油烟机", "C.丙电视", "D.丁空调"], "solve": "补贴＝标价×折扣×率：210/270/270/288 → 丁 288 最大（基数与高档率双中）→ D。", "analysis": "**识别信号**：「标签价/原价」＋「折扣（几折）」＋「补贴/率/百分比」同现 → 立刻写 `结果＝标价×折扣×率`；「以下…最多/最少/最省」→ 多对象**同模板比较** → 「**同因子分组淘汰 → 决赛比值**」；「七折/八折」→ 先转小数 0.7/0.8（绝不当 ×7）。\n**核心规律**：三层连乘、单因子可分离的**双因子比较**——最终量＝基数(标价×折扣)×比率；多对象比较先固定一块、只比另一块，并列者再比值裁决。剥掉外壳内核就是「哪个 a×b 最大」。打法：`补贴/优惠＝标价×折扣率×补贴率`；比较 i、j：`K＝(基数ᵢ/基数ⱼ)×(率ᵢ/率ⱼ)`，K>1 则 i 大。**快写**：先给每件算「有效系数＝折扣×率」（本题 0.105/0.18/0.09/0.16），再乘标价，只做一次乘法/件。\n**易混·易错链**：最像＝**保证利润率求折扣**（同骨架、反求折扣，方向相反）；撞坑链：七折→×7 → 标价直接×率（漏折扣）→ 一级/二级率对调 → 只看标价最高选丙 / 只看率最高选乙 → 乙丙并列 270 误判「无唯一解」。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/sl/3-3c40758dc6.jpg"}]}]}, {"name": "多件", "star": false, "children": [{"name": "总利润=Σ(单件利润×数量)，或=总销售额−总成本", "star": false, "examples": [{"q": "某水果店新进了40箱水果，每箱售价80元。卖出20箱后，开始打8折促销，待该批水果全部售完后，发现销售的后20箱水果获得的利润较前20箱少〔图:题干/37_1.png〕。问每箱水果的进价为多少元？", "src": "26年省考35季 第37题", "hit": false, "ans": "D", "opts": ["A.40", "B.45", "C.48", "D.50"], "solve": "前20箱利润 `20(80−x)`、后20箱 `20(64−x)`，由\"后比前少 8/15\"得 `20(64−x)=20(80−x)×7/15`，两边约 20 → `x = `**50**。", "analysis": "- 体系定位：数量关系 → 经济利润 → 多件；上位「经济利润」→ 本题「总利润=Σ(单件利润×数量)，两批对比」→ 下级变式「打折、分段计价、保利润求折扣」。\n- 识别信号：题干含**进价/售价/折扣/利润**且分**批次或数量** → 经济利润·多件，按批次列总利润。\n- 本质：把\"每箱利润\"乘数量得**批次总利润**，再用比例/差值条件建方程（利润率一律对成本算）。\n- 通式：单件利润 = 售价−成本；批次总利润 = `n×(售价−成本)`；打折售价 = `原价×折扣率`；同类判别条件：看到\"打折+数量+利润差\" → 分批列 `n(单价−成本)` 再比。\n- 易混·易错链：与「打折」子类区分——打折只求最终价，本题要**按数量汇总利润再对比**；撞坑链：折扣基数用错 → 利润差方向写反 → 全盘错。", "img": "data:image/png;base64,"}]}]}, {"name": "分段计价", "star": false, "children": [{"name": "分段累加：各段单价×各段用量（水电、停车、话费阶梯）", "star": false}]}, {"name": "盈不足", "star": false, "children": [{"name": "假设全为一种，总差额÷单项差额=另一类数量", "star": false}]}, {"name": "保利润求折扣", "star": false, "children": [{"name": "最低售价=成本×(1+目标利润率)，折扣=最低售价÷标价", "star": false}]}]}, {"name": "溶液问题", "star": false, "children": [{"name": "基础", "star": false, "children": [{"name": "浓度=溶质/溶液；溶质=溶液×浓度", "star": false}]}, {"name": "混合", "star": false, "children": [{"name": "混合浓度=溶质之和/溶液之和（≠ 浓度的简单平均）", "star": false}]}, {"name": "加水蒸发", "star": false, "children": [{"name": "溶质守恒、溶液量改变，列守恒式求新浓度", "star": false}]}, {"name": "等量交换", "star": false, "children": [{"name": "交换后两杯溶质总量不变，逐杯按溶质/溶液重算浓度", "star": false}]}, {"name": "十字交叉", "star": false, "children": [{"name": "质量比=(混合浓度−低浓度):(高浓度−混合浓度)", "star": false}]}]}, {"name": "排列组合", "star": false, "children": [{"name": "分类分步", "star": false, "children": [{"name": "分类用加法原理，分步用乘法原理", "star": false, "examples": [{"q": "巨人之旅-TOR330是全球难度顶尖的超长距离越野跑赛事，全程约330公里，累计爬升超24000米。2026年，赵家驹斩获该赛事总冠军，创造中国选手最佳战绩。比赛途中的某处补给站设有甲、乙两个休息帐篷，某时段共有6位选手进入该补给站休整，若6人全部安排进这两个帐篷，每个帐篷至少1人，则共有多少种不同的安排方式？", "src": "26年省考34季 第41题", "hit": true, "ans": "B", "opts": ["A.64", "B.62", "C.32", "D.24"], "solve": "每人独立二选一 → **2⁶＝64**，再剔掉全挤一篷的 **2** 种（全甲、全乙）＝ **62**。", "analysis": "- 体系定位：数量关系 → 数学运算 → 排列组合 → **排列组合·分类分步**（清单原名）｜体系位置：上位＝计数两大原理（加法/乘法）→ 本题＝互异元素进互异位置的\"非空分配\" → 下级变式＝允许空盒（mⁿ）、每组至少 k 个（预借/容斥）、先分组再分配。\n- 识别信号：题干出现「每人/每件独立可选」「分到几个**不同**的对象」「每个…至少 1 个 / 随时」→ 先算放开约束的 `mⁿ`，再用\"全集−越界\"处理非空；看到\"至少 1\"不慌，就是减掉集中到一处的那几种。\n- 本质：n 个**互异**元素各自独立落入 m 个**互异**位置的方案数——乘法原理定总数，非空约束用全集减非法集。判分点＝**先判人/盒子是否互异**：互异走乘法原理，相同才走隔板。\n- 通式：两篷非空 `2ⁿ−2`；一般 m 个互异盒至少 1 个：`mⁿ − C(m,1)(m−1)ⁿ + C(m,2)(m−2)ⁿ − …`（容斥）；若允许空盒则直接 `mⁿ`。\n- 易混·易错链：最像**排列组合·相同元素分配（隔板法）**——一句话分：元素**互异**→乘法原理（本题 `2⁶−2`）；元素**相同**→隔板法 `C(n−1, m−1)`。撞坑链：①忘剔\"全挤一篷\"→得 64（A）；②把两篷当同组去对称 →÷2 得 32（C）；③把互异当相同套隔板 →`C(5,1)=5`。", "img": ""}]}]}, {"name": "A/C", "star": false, "children": [{"name": "A(n,m)=n!/(n−m)! 与顺序有关；C(n,m)=n!/[m!(n−m)!] 与顺序无关", "star": false}]}, {"name": "捆绑", "star": false, "children": [{"name": "相邻元素捆成一个整体参与排列，整体内部再排序", "star": false}]}, {"name": "插空", "star": false, "children": [{"name": "n天选k场两两不相邻：C(n−k+1,k)（折叠 k−1 个必隔天）；隔 m 天变式 C(n−(m+1)(k−1),k)", "star": false, "examples": [{"q": "某街道计划在本周的周一至周日中选取3天开展社区活动。如果要求每次活动之间至少间隔1天，则可行的活动时间安排有（ ）种。", "src": "2026广东省考真题 第42题", "hit": true, "ans": "C", "opts": ["A.3", "B.5", "C.10", "D.15"], "solve": "插空/挪位：7天选3天不相邻→2个必隔天折叠→从5个位置选3=C(5,3)=10。验证：挪位后一一对应共10种（如1,3,5↔1,3,5号；2,4,6↔2,4,7号）。选C", "analysis": "**识别信号**：题干＝「从 n 天（位置）中选 k 个，两两不相邻 / 至少间隔 1 天」；出现「不相邻 / 至少间隔」即切插空公式。\n**核心规律**：==不相邻 ⇔ 先折叠 k−1 个必隔位，再从剩余位里选 k 个==（顺序无关用组合）。打法：==C(n−k+1, k)==（本题 C(7−3+1,3)＝C(5,3)＝10）；隔 m 天变式 C(n−(m+1)(k−1),k)。\n**易混·易错链**：最像「排列组合·排列 A / 组合 C」——分法：本题顺序无关用 C，且须先把「不相邻」折成位次数；撞坑链：忽略相邻限制直接 C(7,3)＝35 → 把「间隔 1 天」误解为「必须等距」漏解 → 用 A 而非 C → 套错公式得 15。", "img": ""}]}]}, {"name": "隔板", "star": false, "children": [{"name": "n 个相同球入 m 盒至少 1 个：C(n−1,m−1)；允许空盒先每盒预借 1 个再减", "star": false}]}, {"name": "定序去重", "star": false, "children": [{"name": "总排列数 ÷ 固定顺序元素的内部排列数", "star": false}]}, {"name": "错位", "star": false, "children": [{"name": "Dₙ=(n−1)(Dₙ₋₁+Dₙ₋₂)；D₄=9、D₅=44（全不配对）", "star": false}]}, {"name": "环形", "star": false, "children": [{"name": "圆排列=(n−1)!（先固定一个位置破环）", "star": false}]}, {"name": "涂色", "star": false, "children": [{"name": "从相邻最多的区域入手，分类讨论或总排列去重", "star": false}]}, {"name": "分组分配", "star": false, "children": [{"name": "均匀分组先除以组数阶乘，再乘分配对象数", "star": false, "examples": [{"q": "某企业技术部门有7名员工，其中，有3人只能提供软件支持，有2人只能提供硬件支持，另外2人能同时提供软、硬件支持。现该部门向甲、乙两个客户派驻技术团队，要求每个团队中正好有2人能提供软件支持、2人能提供硬件支持。则不同的派驻方式共有（ ）种。", "src": "2025广东省考真题 第42题", "hit": true, "ans": "A", "opts": ["A.30", "B.42", "C.70", "D.144"], "solve": "硬件供需恰好相等(4＝4)→锁死必派4人；再按多面手同队(6)＋分居(24)＝30。", "analysis": "**识别信号**：「分成几组／派驻到不同对象，每组各含 X 个 A、Y 个 B」＋出现「能同时做两件事／兼职／**两用**」的人 → 先做**需求总量 vs 供给总量**盘点，再分类。\n**核心规律**：带能力交叉的**定额分组分配**——把每人技能看成「可用份额」，先用「需求＝配额×对象数」掐出**必用集合**，再对「可两用者」的落位分类枚举。打法：①需求总量＝每对象配额×对象数；②供＝求 → 该技能持有者**全派**；供>求 → 多出者留用待选；③对多面手设位置变量两类：**同队**＝单面人补满另一队×对象排列数，**分居**＝多面手排列×各队单面人被选排列 → 两类**相加**。\n**易混·易错链**：最像＝**分类分步**（只考加/乘原理）；撞坑链：忘两队有编号（漏 ×2）→ 均匀分组惯性**除组数阶乘**（本题对象不同、不需除，易多除）→ 把多面手两种技能**各算一人**致队伍人数虚增 → 漏掉「多面手同队」这一边界分类。", "img": ""}, {"q": "巨人之旅-TOR330是全球难度顶尖的超长距离越野跑赛事，全程约330公里，累计爬升超24000米。2026年，赵家驹斩获该赛事总冠军，创造中国选手最佳战绩。比赛途中的某处补给站设有甲、乙两个休息帐篷，某时段共有6位选手进入该补给站休整，若6人全部安排进这两个帐篷，每个帐篷至少1人，则共有多少种不同的安排方式？", "src": "26年省考34季 第41题", "hit": true, "ans": "B", "opts": ["A.64", "B.62", "C.32", "D.24"], "solve": "6 人各自\"进甲/进乙\"独立二选一，**`2^6=64`**，再扣掉\"全进甲、全进乙\"这 2 种空帐篷，得 ==62==。", "analysis": "- 体系定位：数量关系 → 排列组合 → **排列组合·分组分配**（考点清单原名）；位于「排列组合」大类末端，承接\"分类分步/隔板法\"之后，专治\"先分堆、再分给不同对象\"这一类。\n- 识别信号：题干出现\"n 位（不同）人 / n 个（不同）物，**全部**安排进 m 个（不同）帐篷/房间/岗位，**每个至少 1 个**\"——见到\"全部安排 ＋ 至少 1\"就条件反射：分步乘法取全集 ＋ 补集减空。\n- 本质：每个元素独立做一次\"选哪个对象\"的决策，总方案＝各元素选择数的连乘；再剔掉\"有对象空着\"的非法态。剥掉越野赛外壳，内核就是 6 次二选一减 2。\n- 通式：n 个不同元素入 m 个不同对象、每个至少 1 → `m^n − C(m,1)(m−1)^n + C(m,2)(m−2)^n − …`（容斥）；**m=2 时退化为 `2^n − 2`**，本题 n=6 直接 `64−2=62`；若题目改说\"两个帐篷不分甲乙\"，才在此结果上 `÷2!`。\n- 易混·易错链：最像的是**隔板法（相同元素分配）**——撞坑链：①人是不同元素却套 `C(n−1,m−1)`（错成 C(5,1)=5 之类）；②帐篷有标号却 ÷2! 当成无标号分堆（落到 32）；③记得减空帐篷方向对、但把\"空的恰好 2 种\"记成\"每人一种\"乱减；④`(3,3)` 均匀分组忘除 2!，复核时对不上 62。", "img": ""}]}]}]}, {"name": "概率问题", "star": true, "children": [{"name": "基本概型", "star": false, "children": [{"name": "古典：P=满足条件的情况数 ÷ 总情况数", "star": false, "examples": [{"q": "3名求职者参加某企业的面试，每人在6道面试题中随机抽取2道题作答，则有且仅有1道题没有被任何人抽到的概率（ ）。", "src": "2025广东省考真题 第45题", "hit": true, "ans": "D", "opts": ["A.不到20%", "B.在20%到25%之间", "C.在25%到30%之间", "D.超过30%"], "solve": "3 人共 6 次抽取覆盖 6 题、恰 1 题落空：C(6,1)×[5×C(3,2)×(4×3)] / 15³ = 1080/3375 = 32%", "analysis": "**识别信号**：「随机抽取 ＋ 每人固定抽 m 道 ＋ 问恰好 k 题…的概率」→ 先写分母 `C(n,m)^人数`，再把「恰好 / 覆盖」一律转成计数占位，不硬套公式。\n**核心规律**：3 人 6 次抽取 ＝ 用 6 个槽位覆盖 6 道题、**恰好 1 题落空**；即「其余 5 题被 6 次抽取全覆盖、且每人两题互不相同」的方案数 ÷ 15³。打法：P ＝ C(题数, 空题数) × 覆盖计数 ÷ C(题数, m)^人数；本题覆盖计数 ＝ 5 × C(3,2) × (4×3) ＝ 180 → P ＝ 6×180 / 15³ ＝ **8/25 ＝ 32%**。\n**易混·易错链**：最像「独立重复（二项）」——分法：本题 3 人各自独立从 6 题抽（等价独立重复），与「抽签不放回」同一票池依次抽不同；撞坑链：① 分母算成 15×3（应 15³）② 漏乘落空题的 C(6,1)=6 ③ 漏「同一人两题互不相同」约束（分子得 270 而非 180）。", "img": ""}]}, {"name": "几何概型：P=满足条件的长度/面积 ÷ 总长度/面积", "star": false}]}, {"name": "事件关系", "star": false, "children": [{"name": "独立", "star": false}, {"name": "互斥：P(A∪B)=P(A)+P(B)（不能同时发生）", "star": false}, {"name": "对立(逆向)：P(至少1)=1−P(全不发生)", "star": false}, {"name": "条件：P(B|A)=P(AB)/P(A)", "star": false}]}, {"name": "模型应用", "star": false, "children": [{"name": "比赛获胜：逐场独立概率相乘、分类求和；注意提前结束不补赛", "star": false}, {"name": "抽签：不放回用条件概率连乘；放回用独立同分布", "star": false}, {"name": "二项：n 次独立重复恰 k 次成功：C(n,k)·pᵏ·(1−p)^(n−k)", "star": false}]}, {"name": "综合", "star": false, "children": [{"name": "期望：E(X)=Σ(取值×对应概率)", "star": false}, {"name": "全概率★：P(结果)=Σ(各来源占比×该来源下条件概率)；占比≠条件概率，勿漏乘占比", "star": false, "examples": [{"q": "雨季期间，某市单日的暴雨发生率为30%，暴雨出现时当地市区主干道拥堵的概率为70%，其余时间拥堵的概率为20%，则雨季期间当地市区主干道拥堵的平均概率为（ ）。", "src": "2026广东省考真题 第40题", "hit": false, "ans": "B", "opts": ["A.25%", "B.35%", "C.45%", "D.55%"], "solve": "解题方法：全概率 P(结果)=Σ(各来源占比×该来源下条件概率)：P=0.3×0.7+0.7×0.2=21%+14%=35%。选 B。坑：占比≠条件概率，勿漏乘占比（只取 70% 或只取 0.3×0.7 都是丢权重）。", "analysis": "**识别信号**：题干＝「某情形发生率为 p，该情形下 A 概率为 q，其余情形下 A 概率为 r，求 A 的总概率」；出现「占比＋条件概率」＋「平均概率」即切「加权求和」。\n**核心规律**：==按占比分流、对各情形条件概率加权求和==；占比与条件概率是两回事、都不可漏（P＝0.3×0.7＋0.7×0.2）。打法：==P(结果)＝Σ(各来源占比×该来源下结果的条件概率)==；可用反面 1−Σ(占比×不发生的条件概率) 复核。\n**易混·易错链**：最像「统计·加权（混合）平均」——分法：加权平均是「量×权重求均值」，本题是「事件概率按占比加权」；撞坑链：漏乘占比只取 70%（→70%）→ 对两条件概率简单平均 (70%+20%)/2（→45%）→ 权重与条件概率张冠李戴（0.7×0.7＋0.3×0.2，→55%）。", "img": ""}]}]}]}, {"name": "几何问题", "star": true, "children": [{"name": "平面面积", "star": false, "children": [{"name": "三角形=底×高/2；梯形=(上底+下底)×高/2；圆=πr²", "star": false}]}, {"name": "立体体积", "star": false, "children": [{"name": "柱体=底面积×高；锥体=底面积×高/3；球=4πr³/3", "star": false}]}, {"name": "相似缩放(k/k²/k³)", "star": false, "children": [{"name": "相似比 k → 面积比 k² → 体积比 k³", "star": false}]}, {"name": "周长面积最值", "star": false, "children": [{"name": "周长一定时正方形面积最大；面积一定时正方形周长最小", "star": false}]}, {"name": "勾股", "star": false, "children": [{"name": "a²+b²=c²；常用 3-4-5、5-12-13、6-8-10", "star": false, "examples": [{"q": "某单位计划在一块直角三角形的绿地周边栽种树木，先在3个顶点各栽种1棵，再从顶点开始每隔4米栽种1棵，如果两条直角边（包含顶点）分别栽种4棵和5棵，则该绿地周边一共栽种了（ ）棵树。", "src": "2025广东省考真题 第40题", "hit": true, "ans": "A", "opts": ["A.12", "B.13", "C.14", "D.15"], "solve": "两直角边反推 12m/16m → 勾股(3-4-5×4)得斜边 20m → 周长 48 → 48÷4＝12（封闭环不加减）。", "analysis": "**识别信号**：「**直角三角形**」＋可反推的两条边 → 先**勾股补第三边**；「**周边／一圈／四周／每隔…栽（摆/插）**」→ 立刻判「**封闭环**」，棵数＝周长÷间距（**不加不减**）；「一条边栽 n 棵（含两端）」→ 边长 L＝(n−1)×间距。\n**核心规律**：封闭环上的等分点计数 ＝ **总长度÷间距**（与形状无关，圆/方/三角皆同）；本题把总长藏在斜边里，需先借勾股补齐周长。打法：直角边 a,b → 斜边 **c＝√(a²+b²)**（优先 3-4-5 / 5-12-13 / 6-8-10 倍数）；一边栽 n 棵 → L＝(n−1)×间距；**封闭**：棵数＝周长÷间距；**开放**：两端栽＝段数+1、只一端＝段数、两端不栽＝段数−1。\n**易混·易错链**：最像＝**开放路线植树（两端栽：段数+1）**；撞坑链＝①把周边当开放多算 1（→13）；②三边树数直接相加、不减公共顶点（→15）；③反推边长把「n 棵」当「n 段」。", "img": ""}, {"q": "甲、乙、丙三艘船在海上航行。某一时刻，甲观测到乙位于它的北偏西30°方向，甲、乙相距6千米；甲观测到丙位于它的正西方向，甲、丙相距6千米，则乙与丙之间的距离为（ ）千米。", "src": "2024广东省考真题 第38题", "hit": false, "ans": "D", "opts": ["A.3", "B.4", "C.5", "D.6"], "solve": "甲看乙为「北偏西30°」、看丙为「正西」，两方向夹角 = 90°−30° = **60°**；又甲、乙与甲、丙都相距 **6**，两边等、夹角60° → △乙甲丙为**等边三角形** → 乙丙 = 6。", "analysis": "- 体系定位：数量关系 → 几何问题 → 勾股（清单原名；本题实为「方位角·解三角形」，建议在〈几何问题〉下新增〈方位角/解三角形〉（待核)）；上位＝几何问题，本级＝解三角形，下级变式＝坐标系两点距、余弦定理求第三边。\n- 识别信号：题干出现「北偏西/南偏东…°」＋两段已知距（千米/米）→ 立刻建系（正东为x、正北为y）写出各点坐标，或先算两方向夹角。\n- 本质：把「方位描述」翻译成**夹角**：正西与本方向夹角 = 90°−偏角；再在△甲乙丙中用「两边夹一角」定第三边。\n- 通式：两边 a、b 夹 θ → 第三边 `c = √(a²+b²−2ab·cosθ)`；特例：a=b 且 θ=60° → 等边 `c=a`；θ=90° → 勾股 `c=√(a²+b²)`。方位换算：`夹角 = |对方位角 − 本方位角|`。\n- 易混·易错链：最易与「勾股」混——但本题夹角是 60° 非 90°，用勾股属巧合（30-60-90）；区别：只有夹角 90° 才直接勾股，其余角度先用余弦定理/等边判定。撞坑链：把方位当坐标直接用 → 算错夹角 → 误选 3。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/sl/3-09064b025e.png"}]}]}, {"name": "三边关系", "star": false, "children": [{"name": "两边之和>第三边，两边之差<第三边", "star": false}]}, {"name": "网格最短路", "star": false, "children": [{"name": "只能朝目标方向走，走法数=C(总步数, 横向步数)", "star": false}]}, {"name": "展开最短", "star": false, "children": [{"name": "把相关面展开成平面，两点连线取直线距离", "star": false}]}, {"name": "对角线分块(对角积相等★)", "star": true, "children": [{"name": "对角线交点把四边形分成四块，对角两块乘积相等：S₁·S₃=S₂·S₄", "star": false, "examples": [{"q": "某块不规则的四边形菜地被沿着对角线分为四个区域，分别种上青菜、毛豆、番茄和茄子。已知青菜的种植面积比毛豆多40%，番茄的种植面积比茄子多40平方米，比青菜少了140平方米。则毛豆的种植面积比茄子多了（ ）平方米。", "src": "2026广东省考真题 第41题", "hit": false, "ans": "D", "opts": ["A.60", "B.70", "C.90", "D.100"], "solve": "解题方法：对角线交点把四边形分四块，对角两块面积乘积相等：青菜×茄子=毛豆×番茄。设毛豆=x、茄子=y：青菜=1.4x，番茄=y+40=1.4x−140 → x=200、y=100 → 毛豆−茄子=100。选 D。", "analysis": "**识别信号**：题干＝「四边形沿对角线分四块（种四种作物）」，给「某块比某块多 X%」「某块比某块多 m ㎡」；出现「不规则四边形＋对角线分块」即切「对角积相等」。\n**核心规律**：对角线交点把四边形分成四块，==对角两块面积乘积相等==（S₁·S₃＝S₂·S₄），再与比例/差值联立；图形形状与命名全是噪音。打法：设毛豆 x、茄子 y → 青菜 1.4x、番茄 y+40＝1.4x−140 → 套 1.4x·y＝x·(y+40) → y＝100、x＝200 → 差 100。\n**易混·易错链**：最像「几何·平面面积公式」——分法：面积公式是直接算，本题靠「对角积相等」这一隐含性质联立；撞坑链：被「不规则」和四个菜名带偏、忽略图形关系 → 把「多 40%」当面积差直接加减 → 想不起对角积相等、方程不够只能硬凑选项。", "img": "data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22400%22%20height%3D%22260%22%20viewBox%3D%220%200%20400%20260%22%20font-family%3D%22sans-serif%22%3E%0A%3Crect%20width%3D%22400%22%20height%3D%22260%22%20fill%3D%22%230b1220%22%20rx%3D%2212%22%2F%3E%0A%3Cpolygon%20points%3D%2270%2C40%20320%2C50%20340%2C220%2050%2C200%22%20fill%3D%22%23fef3c7%22%20stroke%3D%22%2394a3b8%22%20stroke-width%3D%222%22%2F%3E%0A%3Cline%20x1%3D%2270%22%20y1%3D%2240%22%20x2%3D%22340%22%20y2%3D%22220%22%20stroke%3D%22%2364748b%22%20stroke-width%3D%221.4%22%20stroke-dasharray%3D%225%204%22%2F%3E%0A%3Cline%20x1%3D%22320%22%20y1%3D%2250%22%20x2%3D%2250%22%20y2%3D%22200%22%20stroke%3D%22%2364748b%22%20stroke-width%3D%221.4%22%20stroke-dasharray%3D%225%204%22%2F%3E%0A%3Ccircle%20cx%3D%22195%22%20cy%3D%22130%22%20r%3D%223%22%20fill%3D%22%23f59e0b%22%2F%3E%0A%3Ctext%20x%3D%22168%22%20y%3D%2288%22%20font-size%3D%2217%22%20fill%3D%22%23166534%22%20font-weight%3D%22bold%22%3E%E9%9D%92%E8%8F%9C%3C%2Ftext%3E%0A%3Ctext%20x%3D%22243%22%20y%3D%22155%22%20font-size%3D%2217%22%20fill%3D%22%23dc2626%22%20font-weight%3D%22bold%22%3E%E7%95%AA%E8%8C%84%3C%2Ftext%3E%0A%3Ctext%20x%3D%22172%22%20y%3D%22195%22%20font-size%3D%2217%22%20fill%3D%22%237c3aed%22%20font-weight%3D%22bold%22%3E%E8%8C%84%E5%AD%90%3C%2Ftext%3E%0A%3Ctext%20x%3D%2258%22%20y%3D%22150%22%20font-size%3D%2217%22%20fill%3D%22%23b45309%22%20font-weight%3D%22bold%22%3E%E6%AF%9B%E8%B1%86%3C%2Ftext%3E%0A%3Ctext%20x%3D%2260%22%20y%3D%22248%22%20font-size%3D%2211%22%20fill%3D%22%2364748b%22%3E%E7%A4%BA%E6%84%8F%E5%9B%BE%20%C2%B7%20%E5%AF%B9%E8%A7%92%E7%BA%BF%E4%BA%A4%E7%82%B9%E5%88%86%E5%9B%9B%E5%9D%97%EF%BC%8C%E5%AF%B9%E8%A7%92%E4%B8%A4%E5%9D%97%E9%9D%A2%E7%A7%AF%E4%B9%98%E7%A7%AF%E7%9B%B8%E7%AD%89%3C%2Ftext%3E%0A%3C%2Fsvg%3E"}]}]}]}, {"name": "最值问题", "star": false, "children": [{"name": "和定积最大", "star": false, "children": [{"name": "两数越接近积越大，相等时最大（均值不等式）", "star": false}]}, {"name": "二次函数", "star": false, "children": [{"name": "y=ax²+bx+c 在顶点 x=−b/(2a) 取极值", "star": false}]}, {"name": "抽屉", "star": false, "children": [{"name": "最不利情况数 + 1", "star": false, "examples": [{"q": "箱子里装有红、蓝、绿、白、黑五种颜色的小球各20个。如果从箱子里取出若干个小球，且确保其中有10个小球颜色相同，则至少要取出（ ）个小球。", "src": "2025广东省考真题 第36题", "hit": false, "ans": "D", "opts": ["A.56", "B.51", "C.50", "D.46"], "solve": "「保证」＝先凑最坏不达标态：每色各取 9 个（5×9＝45）仍未凑齐 10 同色，再取 1 个必达标 → 46。", "analysis": "**识别信号**：题干＝「至少取…才能==保证==…」；出现「保证 / 至少」触发词即切「最不利」心智。\n**核心规律**：先构造最坏的不达标态再 +1 越过阈值；存量（20）只是「管够」的噪音、不进公式（先凑**最坏不达标态**每色各取 9 个＝5×9＝45，再 +1 → 46）。打法：保证某类达 m → 每类都卡在 m−1 再 +1，即 ==种类×(m−1)+1==（本题 5×9+1＝46）。\n**易混·易错链**：最像「最值·和定求积最大 / 构造数列」——它求**极值**、本题求**保证临界数**，且存量是否参与是分水岭；撞坑链：直接 10×5＝50（把「达标需多少」当「保证需多少」，漏掉 −1 与 +1）→ 拿 20 参与运算 → 只取 45 忘 +1。", "img": ""}, {"q": "一个箱子中装有红、黄、蓝三种颜色的小球各3个，每次从中随机取出1个小球且不放回，若要保证所取小球中出现2个红球或同时出现红球与黄球，则至少需取出多少个小球？", "src": "26年省考34季 第42题", "hit": false, "ans": "D", "opts": ["A.4", "B.5", "C.6", "D.7"], "solve": "抓「不满足」的最大规模——**红球最多留 1 个（甚至 0 个）**，黄蓝各自独立：0 红 时可全取 **3 黄 + 3 蓝 = 6** 个仍不满足；故 **6 + 1 = 7**。", "analysis": "- 体系定位：数量关系 → 最值问题 → 单元「最值·抽屉原理（最不利）」（清单原名）｜体系位置：上位「最值问题（求极值）」→ 本题「多条件『或』型最不利」→ 下级变式：n 色球、编号连续、手套/袜子配对、\"至少几个数字才出现重复\"。\n- 识别信号：题干见「**至少**…才能**保证 / 确保 / 一定**」→ 立刻落**抽屉·最不利**；本题多一层——条件是复合的「A **或** B」，兼收规律：**看到\"或\"的保证题 → 先取反面变成\"且\"，再去凑反面能取的最大组合**。\n- 本质：求\"让目标事件必然发生的最小抽取数\"，等于求\"目标不发生时的最大世界规模\"+1（原判分点并入：**最不利情况数 + 1**）。本题内核＝**给\"坏结果\"留出最大生存空间，然后一把戳破它**。\n- 通式：`最少保证数 = max{目标不成立时可取的最大个数} + 1`。复合条件的模板：`非(A 或 B) = 非A 且 非B`，先各自算出「非A 且 非B」的**可行上限**，取最大再 +1。本题即 `红≤1 且 (红=0 或 黄=0)` 的最大可行数 = 3+3 = **6**，答案 **6+1=7**。\n- 易混·易错链：最像「**容斥·极值**（反向最不利）」——容斥里算的是\"集合交集的人数上下界\"，抽屉算的是\"抽取个数\"，同为\"最不利\"思路但**对象的单位不同**（人 vs 个）。撞坑链：① 忘 +1 → 误选 **6**（最高频）；② 把\"或\"读成\"且\"→ 误取 4 或算成小值；③ 把\"随机取\"当\"按顺序取\"→ 多绕弯；④ 误用古典概率硬算 P，浪费时间还可能算错。", "img": ""}]}]}, {"name": "构造数列", "star": false, "children": [{"name": "其余项按大小取边界极端值，据总和倒推目标项", "star": false, "examples": [{"q": "甲、乙、丙3人参加专业测试，考试包含10道题，答对每题得10分，不答或答错不得分。已知每道题3人中至少有2人答对，没有人得100分且任意2人总分都不相同。则最多有（ ）道题3人都答对。", "src": "2024广东省考真题 第42题", "hit": false, "ans": "B", "opts": ["A.3", "B.4", "C.5", "D.6"], "solve": "设 3 人都答对的题数为 **x**，则三人答对总题数 = `3x+2(10−x) = x+20`；\"无人满分\"限每人答对数 ≤ **9**，\"三人分数互异\"→三人答对数互异 → 总题数 ≤ `9+8+7 = 24` → `x+20 ≤ 24` → **x ≤ 4**，且 4 可构造 → 最多 **4**。", "analysis": "- 体系定位：数量关系 → 最值问题 → 构造数列（清单原名；判分点：其余项按大小取边界极端值，据总和倒推目标项）；上位＝最值问题，本级＝构造/极端假设，下级变式＝得分/排名型极值、多约束取顶点。\n- 识别信号：题干出现\"最多/最少有几个\"＋一组数\"互不相同、无人满分/不超过某值\"等边界约束 → 立刻上\"极端假设 + 总和倒推\"。\n- 本质：把\"最多\"翻译成\"取一组互异且各不超上界的极端值，使其和最大\"，再用总量等式卡出目标量的上界。\n- 通式：目标量 x → 由题设写出总量 `T(x)` → 对\"其余项\"取边界极端值求上界 `T_max` → 令 `T(x) ≤ T_max` 解出 x 上界 → 给一组可行构造验证可达。本题：`x+20 ≤ 9+8+7 = 24`。\n- 易混·易错链：最易与「抽屉原理（最不利）」混；区别：抽屉是\"至少取多少保证某结果（最不利+1）\"，本题是\"最多有多少（构造极端值）\"。撞坑链：只看\"每题至少 2 人对\"就当总量=20，漏掉全对题每题多贡献 1 个答对。", "img": ""}]}]}, {"name": "非典型最值", "star": false, "children": [{"name": "约束最优化：找绑定约束（如碳配额 y≥4x）与产能 x+y≤2000 联立 → 产量取可行域顶点，利润=Σ产量×单价", "star": false, "examples": [{"q": "某企业每生产一台能耗高的服务器，能获得5万元的利润，但要扣除4单位碳配额；每生产一台能耗低的终端，能获得2万元的利润，并增加1单位碳配额。若该企业每月最多生产服务器和终端共2000台，且每月的碳配额总量不低于零，则该企业每月最大利润为（ ）万元。", "src": "2026广东省考真题 第39题", "hit": true, "ans": "C", "opts": ["A.4800", "B.5000", "C.5200", "D.6000"], "solve": "碳约束配平：1服务器=4终端（y≥4x）；x+y≤2000 → x≤400 → 利润=5×400+2×1600=5200万", "analysis": "**识别信号**：题干＝两种产品各给「利润＋消耗/产出某资源」，再给「产能上限＋资源总量≥0」；出现「利润最大」＋「约束条件」即切「画可行域找顶点」。\n**核心规律**：把资源约束翻译成不等式（碳 ⇒ y≥4x）、与产能上限联立，==目标函数在可行域顶点取最优==。打法：设 x、y → 目标 P＝Σ(单价×产量)，约束取等号求交点（y＝4x 与 x+y＝2000 → x＝400）→ P＝5×400＋2×1600＝5200。增量视角：1 台终端换 1 台服务器，利润 +3、碳 −5，余碳 2000 最多支撑 400 次替换。\n**易混·易错链**：最像「最值·和定求积最大 / 构造数列」——分法：本题是「约束域顶点」而非「极值点/边界极端」，且要两支约束联立；撞坑链：只盯利润高的服务器猛产（无视碳约束，→6000）→ 碳不为负就收手、未推到边界（→4800）→ 抵消比例记反（→5000）。", "img": ""}]}]}, {"name": "统筹", "star": false, "children": [{"name": "能并行则并行，识别瓶颈环节、压缩关键路径", "star": false, "examples": [{"q": "有4批原材料存放在同一个仓库，工厂每次会从仓库中运出一整批原材料进行加工，加工完成后才能从仓库提取下一批原材料。已知一批原材料在仓库内每存放满1小时需要支付100元的费用，且工厂加工这4批原材料需要的时间分别为4、6、7、8小时，则工厂为这些原材料支付的仓库存放费用至少为（ ）元。", "src": "2026广东省考真题 第44题", "hit": false, "ans": "B", "opts": ["A.2800", "B.3100", "C.3300", "D.3500"], "solve": "串行加工排序优化：总存放小时=3t₁+2t₂+t₃（系数大者配耗时短）→ 升序 4→6→7→8 → 3×4+2×6+1×7=31 小时 → 3100 元。坑：以为先加工耗时长的更省（方向反）；加工时长≠存放时长。", "analysis": "**识别信号**：题干＝「多批任务串行处理（一次一批/加工完才提下一批）＋每批耗时＋单位时间费用/等待」，求「至少/最小」；出现「串行＋排序＋总费用最小」即切「短时优先」。\n**核心规律**：==总占用时间＝Σ(系数×加工时长)，系数大者配耗时短 → 升序排序最优==；末批耗时不计入收费。打法：4 批总存放小时＝==3t₁+2t₂+t₃==，升序 4,6,7,8 → 3×4＋2×6＋1×7＝31 h → ×100＝3100；n 批系数依次 n−1…1,0。\n**易混·易错链**：最像「最值·运输配比 / 空瓶换水」——分法：本题优化对象是「串行排序」、抓手是顺序而非资源分配；撞坑链：以为「先加工耗时长」更省（方向反）→ 把「加工时长」当「存放时长」→ 随便给个顺序落进次优 3300/3500 → 用总和 25 h 硬凑 2800。", "img": ""}]}]}, {"name": "运输配比", "star": false, "children": [{"name": "比较单位载重成本，尽量满载、避免空驶", "star": false}]}, {"name": "空瓶换水", "star": false, "children": [{"name": "先买后喝再换，递归计算或用总量公式（允许借瓶时更快）", "star": false}]}]}, {"name": "容斥原理", "star": false, "children": [{"name": "两集合", "star": false, "children": [{"name": "|A∪B|=|A|+|B|−|A∩B|", "star": false, "examples": [{"q": "某公司有职工69人，其中男职工35人，党员职工23人，男性非党员职工数与女性非党员职工数相同。新入职6名职工后，男职工增加了4人，女性非党员职工增加了1人，则该公司女性党员职工现有多少人？", "src": "26年省考35季 第39题", "hit": false, "ans": "B", "opts": ["A.11", "B.12", "C.13", "D.14"], "solve": "初始女=69−35=34、非党员=46 均分得女性非党员 **23** → 女性党员 = 34−23 = **11**；新增2女中1人非党员 → 女性党员 +1 = ==12==。", "analysis": "- 体系定位：数量关系 → 容斥原理 → 两集合；上位「容斥原理」→ 本题「性别×党籍二维分类，交叉项推女性党员」→ 下级变式「三集合、文氏图、极值」。\n- 识别信号：题干出现**两个属性交叉分类**（性别/党籍）＋\"某项与某项相同\" → 先补全总数，再对交叉格列式。\n- 本质：二维分类中**任一格 = 行合计 − 同行其余格**，靠\"男非党=女非党\"锁定唯一分解。\n- 通式：目标格 = 该行总数 − 同行已知格；同类判别条件：看到\"两类属性交叉 + 相等/差值条件\" → 先凑总数再反解交叉格。\n- 易混·易错链：与「三集合」区分——三集合要减两两交集再加三交，本题是**二属性分类**；撞坑链：漏掉新增人员或把新增全按一种身份算 → 差 1。", "img": ""}, {"q": "某短视频账号本周互动数据统计如下：点赞视频的访客有312人，收藏视频的访客有247人，既点赞又收藏的访客有95人，浏览过视频但既没点赞也没收藏的访客有680人。问该账号本周视频访客总量为多少人？", "src": "26年省考35季 第40题", "hit": true, "ans": "A", "opts": ["A.1144", "B.1156", "C.1098", "D.1210"], "solve": "至少做过一项 = `312+247−95 = 464`，再加两者都没的 680 → 总量 = `464+680 = `**1144**。", "analysis": "- 体系定位：数量关系 → 容斥原理 → 两集合；上位「容斥原理」→ 本题「两集合并集 + 圈外（都没）」→ 下级变式「三集合、文氏图、极值」。\n- 识别信号：题干给两种行为（点赞/收藏）各自人数＋\"两者都\"＋\"两者都没\" → 用 `|A∪B|+|都没|`。\n- 本质：**全集 = 至少属于一类的人数 + 两类都不属的人数**，考的是并集去重后补全全集。\n- 通式：`总 = |A| + |B| − |A∩B| + |都没|`；同类判别条件：看到\"两种行为 + 都做 + 都没做\" → 直接套此式。\n- 易混·易错链：与「三集合」区分——三集合需减两两交集再加三交；撞坑链：忘减交集 +95，或漏加圈外 680 → 结果偏移。", "img": ""}]}]}, {"name": "三集合", "star": false, "children": [{"name": "|A∪B∪C|=Σ|A|−Σ|A∩B|+|A∩B∩C|", "star": false}]}, {"name": "文氏图", "star": false, "children": [{"name": "画文氏图，从三交区向外交逐层求出各区域", "star": false}]}, {"name": "极值", "star": false, "children": [{"name": "交集最大=各项之和−总数；最小用反向最不利法", "star": false}]}]}, {"name": "植树问题", "star": false, "children": [{"name": "间隔与端点", "star": false, "children": [{"name": "间隔与端点公倍数重合", "star": false, "examples": [{"q": "为营造春节节日氛围，某社区准备在一条长324米的步行街两侧悬挂中国结，道路起点与终点均需悬挂，且同侧相邻两个中国结间距为12米。节前为进一步增强节日氛围，该社区决定增加中国结的数量，将同侧相邻两个中国结间距改为9米。则共有多少个中国结无需移动位置？", "src": "26年省考34季 第44题", "hit": true, "ans": "A", "opts": ["A.20", "B.18", "C.16", "D.14"], "solve": "不动点=**36**（9与12的最小公倍数）的倍数位置，单侧 324÷36+1=**10**，两侧 **×2=20**。", "analysis": "- 体系定位：数量关系 → 日期周期 → 周期循环（清单原名）；体系位置：上位「周期/公倍数计数」→ 本题「等距端点重合计数」→ 下级变式「环形植树、单侧改两侧」。\n- 识别信号：出现「每x米一个/间距为x」「改为y米」「多少个无需移动/重合」→ 立即找**两种间隔的最小公倍数**，重合点=公倍数的整数倍位置。\n- 本质：两种等距排布的重合点=两间距的 lcm 的倍数位置；题目只考「lcm 倍数在区间内的个数」，与移动/施工过程无关。\n- 通式：单侧个数=`长度÷间距 + 1`（两端都放）；不移动个数=`长度 ÷ lcm(旧间距,新间距) + 1`；两侧再 ×2。植树三口径：两端都放**+1**、只放一端**不加**、两端都不放**−1**。\n- 易混·易错链：最像「行程·发车间隔」（那是相对速度推间隔时间，与公倍数无关）；撞坑链：① 端点口径（+1/−1）混用；② 忘记两侧 ×2；③ 把 lcm 误算成 gcd。\n- 体系定位补充：清单无「植树问题」单元，建议在〈日期周期〉或新增〈计数问题〉下新增〈植树问题·间隔与端点公倍数重合〉（待核）。", "img": ""}, {"q": "某个障碍跑项目需要在100米长的跑道上布置障碍（起点和终点均不布置）。如果从起点开始，每隔4米布置一个甲障碍，每隔6米布置一个乙障碍，甲、乙障碍的重合点则不布置甲障碍。则跑道上总共布置（ ）个甲障碍。", "src": "2024广东省考真题 第43题", "hit": false, "ans": "A", "opts": ["A.16", "B.17", "C.24", "D.25"], "solve": "甲的候选点 = `100÷4 − 1 = ` **24**（终点100不布置）；甲乙重合处 = `lcm(4,6)=12` 的倍数，共 `96÷12 = ` **8** 个 → `24 − 8 = ` ==16==。", "analysis": "- 体系定位：数量关系 → 植树问题 → 间隔与端点（清单原名；判分点：间隔与端点公倍数重合）；上位＝植树问题，本级＝两端布置＋重合剔除，下级变式＝单侧/双侧植树、环形植树、不同间隔重合。\n- 识别信号：题干出现\"每隔 a 米布一个、每隔 b 米布另一个、重合处不布/重复处减去\"＋求某一种数量 → 先数总位，再减去 `lcm(a,b)` 的倍数个数。\n- 本质：样本点计数 + 集合去重——甲的样本点里剔除\"甲乙重合\"（即 12 的整数倍）的子集。\n- 通式：`甲数 = (总长÷4 − 1) − (末位÷lcm(4,6))`。通用：单侧不封口植树 `n = 全长÷间隔 − 1`；重合点 = 两间隔公倍数的位置，个数 = `范围÷lcm`。\n- 易混·易错链：最易与「行程·环形跑道」混；区别：环形重合按周长取模，直线重合看公倍数落点。撞坑链：只算甲不扣重合（→24）、把终点也算进去（→25）。", "img": ""}, {"q": "园林工人沿着一块直角三角形花圃边缘打木桩建设围栏，每隔5米打入1根木桩且三个顶点各有1根木桩，两条直角边包含顶点分别打入7根、9根木桩。若将木桩间隔改成2米，则需要新增木桩多少根？", "src": "26年省考35季 第44题", "hit": false, "ans": "D", "opts": ["A.24", "B.28", "C.32", "D.36"], "solve": "7、9 根桩 ⇒ 两边长 `(7−1)×5=30`、`(9−1)×5=40`，勾股得斜边 **50**、周长 **120**；5米时 `120÷5=24` 根、2米时 `120÷2=60` 根 → 新增 `60−24 = `**36**。", "analysis": "- 体系定位：数量关系 → 植树问题 → 间隔与端点；上位「植树问题」→ 本题「闭合环植桩＋换间距作差」→ 下级变式「两端植树、单端点、封闭环、不同间距公倍数重合」。\n- 识别信号：题干出现**沿边缘每隔 x 米打桩/种树**＋给某一间距的根数 → 先反推边长再换间距作差。\n- 本质：闭合线路植桩数 = **周长÷间距（不加1）**；给某间距根数时先 `边长=(根数−1)×间距` 反推。\n- 通式：闭合环 `桩数 = 周长÷间距`；直线两端植 `桩数 = 长度÷间距 + 1`；同类判别条件：看到\"每隔 x 米、共 n 根\" → 直线用 n−1 反推，闭合用整除。\n- 易混·易错链：与「两端植树」区分——两端植树要 +1、闭合环不加；撞坑链：忘闭合环不加1，或斜边没算对导致周长错。", "img": ""}]}]}]}]}, "言语理解": {"color": "indigo", "modules": {"逻辑填空": "indigo", "片段阅读": "emerald", "语句表达": "fuchsia"}, "root": {"name": "言语理解与表达", "signal": "先看语境与结构 → 再比对选项；主题词守恒、逐项验尸干扰项"}, "branches": [{"name": "逻辑填空", "star": false, "children": [{"name": "语境分析", "star": false, "children": [{"name": "转折呼应", "star": false, "children": [{"name": "抓住转折词，空格义与转折前相反或相对", "star": false}]}, {"name": "因果呼应", "star": false, "children": [{"name": "找因果标志词，空格是\"结果\"或\"原因\"，方向需一致", "star": false}]}, {"name": "并列呼应", "star": false, "children": [{"name": "并列成分语义相近或同向（\"也/又/和/既…又\"）", "star": false, "examples": [{"q": "创新从来都是九死一生，但我们必须有“亦余心之所善兮，虽九死其犹未悔”的豪情。我国广大科技工作者要有强烈的创新信心和决心，既不______，也不妄自尊大，勇于攻坚克难、追求卓越、赢得胜利，积极抢占科技竞争和未来发展制高点。填入画横线部分最恰当的一项是：", "src": "2026广东省考真题 第16题", "hit": true, "ans": "C", "opts": ["A.固步自封", "B.骄傲自满", "C.妄自菲薄", "D.甘居人后"], "solve": "**C. 妄自菲薄**", "analysis": "**识别信号**：\"既不……也不……\"\"既……又……\"\"和/也\" → 并列\n**核心规律**：并列项语义同向；但\"既不A也不B\"里 A、B 常是**同类毛病的一体两面**（不要求同义）；打法：见\"既不…也不…\"→ 先定后项性质，再在**同一维度另一端**取词\n**易混·易错链**：并列呼应 ≠ 转折呼应（\"既不…也不\"是并列，非转折）；妄自菲薄（贬，自轻）≠ 自谦", "img": ""}, {"q": "繁杂问题、苗头问题、偶然问题都是问题的具体形态，背后隐藏着不同类型的矛盾。从繁杂问题中把握事物的    ______        、从苗头问题中发现事物的  ______          、从偶然问题中认识事物的______，才能看清本质，抓住解决问题的根本。依次填入画横线处最正确的一项是：", "src": "2025广东省考真题 第16题", "hit": true, "ans": "D", "opts": ["A.必然性 趋势性 规律性", "B.规律性 必然性 趋势性", "C.趋势性 规律性 必然性", "D.规律性 趋势性 必然性"], "solve": "", "analysis": "", "img": ""}, {"q": "“招商”变“招伤”，伤的不仅是财政资金，更是政府公信力和市场信心。应坚决摒弃“唯签约额”“唯引资额”的粗放指标，大幅______项目落地率、企业存活率、税收真实贡献度、产业链契合度等质量型指标的权重。推行“全生命周期”管理，将考核延伸至项目运营阶段，并建立重大决策责任追溯与问责机制，防止前紧后松、______。依次填入画横线部分最恰当的一项是：", "src": "26年省考34季 第18题", "hit": false, "ans": "D", "opts": ["A.提升 头重脚轻", "B.优化 有始无终", "C.调整 半途而废", "D.增加 虎头蛇尾"], "solve": "第二空与「前紧后松」并列，「虎头蛇尾」＝虎头（前紧）+蛇尾（后松）逐字对应，直接锁 D。", "analysis": "**体系定位**：言语理解与表达 → 逻辑填空（语境分析）→ **并列呼应**（清单原名，判分点：并列成分**语义相近或同向**）；第二空兼跨 逻辑填空（成语辨析）→ **成语·词义侧重**（判分点：比对近义成语**侧重点与程度**，选贴合语境者）。\n**识别信号**：题干长相＝一句话里同一位置并列两个四字词或近义表达；触发词＝**顿号\"、\"、逗号并列、\"也/又/和/既…又\"**。本题就是「前紧后松、______」用顿号拉出的并列信号。\n**本质**：剥掉\"招商/招伤\"的时政外壳，内核只有一句——**在一个并列槽里，拿已知项的内部结构去反推未知项**；已知项\"前紧后松\"是\"时前-时后／紧-松\"的二元对仗，未知项必须复刻同一对仗。\n**通式**：`并列项 A + 顿号 + 空格 B` → 判 A 的**内部结构**（如\"前紧后松\"＝时间对仗）→ 找结构同构、指向同类的成语/词代入 → 逐字回验对仗是否成立。\n**易混·易错链**：最像的考点是 **成语·词义侧重**（近义成语\"有始无终/半途而废/虎头蛇尾\"三分）。一句话分法：**\"半途而废\"看\"断\"，\"有始无终\"看\"无尾\"，\"虎头蛇尾\"看\"前紧后松\"的力度变化**——题干讲的是力度由紧转松，只认虎头蛇尾。常见撞坑链：把\"前紧后松\"读成\"没做完\"→误选半途而废/有始无终；把并列读成\"结构失衡\"→误选头重脚轻。", "img": ""}, {"q": "从高校里培养和走出的一大批“大科学家”“大先生”，为救亡图存、祖国建设、科学发展、人才培育______，留下许多可歌可泣的感人故事。到高校研学，可以带上一本“大师图谱”，按图索骥，研究这些大师的逐梦之路和奋斗历程，也可以走进不同院系的讲堂“蹭”名家讲座，聆听各位学者的学术洞见，感受大学里的______，体会大师的风采，感悟大师的精神。依次填入画横线部分最恰当的一项是：", "src": "26年省考35季 第17题", "hit": true, "ans": "C", "opts": ["A.砥节砺行 群英荟萃", "B.筚路蓝缕 侃侃而谈", "C.呕心沥血 百家争鸣", "D.鞠躬尽瘁 风云际会"], "solve": "先攻第二空——\"聆听各位学者的学术洞见\"提示\"多种学术观点并存\"，直接锁定==百家争鸣==；含\"群英荟萃/风云际会（喻人物聚集）、侃侃而谈（说谈吐）\"的项即刻出局。", "analysis": "- 体系定位：言语理解与表达 → 逻辑填空（语境分析）→ 并列呼应（清单原名）；上位\"语境分析（六类呼应）\"→ 本题\"并列呼应·双空联动\"→ 下级变式\"转折/因果/解释说明呼应\"。\n- 识别信号：题干出现**四联并列**（\"救亡图存、祖国建设、科学发展、人才培育\"）或**同向铺陈句**，两空之间可互证 → 先做**区分度最大的那一空**（本题第二空）。\n- 本质：剥掉\"大师/研学\"的外壳，考的是**空格义与相邻呼应句是否同向**——不背词义，只看\"落点对不对（人？观点？行为？）\"。\n- 通式：`定并列结构 → 划呼应词/呼应句 → 先攻命门空 → 反向复核另一空`；同类判别条件：**看到\"并列排比 + 双空成语\"就先比语义落点，再比程度轻重**。\n- 易混·易错链：最像的是\"递进呼应\"（程度加重，如\"不仅…而且\"）——二者分界：**并列＝同向同级**，递进＝**同向后一级更重**。常见撞坑链：把\"群英荟萃/风云际会\"当\"学术\"→ 把\"鞠躬尽瘁\"当\"呕心沥血\"（程度过强）→ 忽略搭配对象。", "img": ""}, {"q": "政绩观是党员干部从政、谋事、创业的“总开关”。当前，改革发展稳定任务艰巨繁重，有的须主动靠前、快速处置，______出实效；有的则需沉心静气、深耕细作，______固长远。依次填入画横线部分最恰当的一项是：", "src": "26年省考35季 第19题", "hit": false, "ans": "D", "opts": ["A.一鼓作气 驰而不息", "B.标本兼治 持之以恒", "C.有的放矢 厚积薄发", "D.立竿见影 滴水穿石"], "solve": "抓\"有的…有的…\"两组对照——**快处置**呼应==立竿见影==、**慢深耕**呼应==滴水穿石==，两空各自锁定，一击命门。", "analysis": "- 体系定位：言语理解与表达 → 逻辑填空（语境分析）→ 并列呼应（清单原名）；上位\"语境分析（六类呼应）\"→ 本题\"并列呼应·反义对照双空\"→ 下级变式\"同向并列（近义互证）\"。\n- 识别信号：题干出现 **\"有的…有的…\"\"一方面…另一方面…\"** 等对照句式，或一快一慢/一实一虚的**两极铺陈** → 先各归其句、再逐空呼应。\n- 本质：剥掉\"政绩观/改革发展\"外壳，考的是**两个空格是否各自贴合其所在分句的语义落点，且彼此构成对照**——不背词义，先判\"每空落点是快还是久\"。\n- 通式：`定对照结构 → 各分句找落点 → 逐空套近义成语 → 验证两空是否成对`；同类判别条件：**看到\"有的…有的…\"式反义铺陈，就把两空当成一组反义来配**。\n- 易混·易错链：最像\"解释说明呼应\"——分界：**并列对照＝两空彼此对立/成对**，解释说明＝**后句直接解释前句**。常见撞坑链：只看第一空\"快\"就选\"一鼓作气\"→ 只顾第二空\"坚持\"忽略\"渐进\"→ 漏看\"对照\"导致两空不匹配。", "img": ""}]}]}, {"name": "解释说明", "star": false, "children": [{"name": "标志词后内容是空格的解释，取同义", "star": false, "examples": [{"q": "规律深藏于纷繁复杂的现象背后，不会______呈现在人们面前。“明者因时而变，知者随事而制。”认识规律，不是对表象的简单感知，体现的是通过现象看本质的______，是从历史进程与世界格局的推进中把握趋势的判断力。变化并非是______的，它反映的是事物内部矛盾运动的趋势。依次填入画横线部分最恰当的一项是：", "src": "26年省考35季 第20题", "hit": false, "ans": "B", "opts": ["A.完整 洞察力 随机", "B.自动 穿透力 偶然", "C.直接 观察力 突发", "D.轻易 领悟力 孤立"], "solve": "三空都有解释说明——\"通过现象看本质\"秒==穿透力==、\"内部矛盾运动的趋势\"反衬==偶然==，B 一击命中两个命门。", "analysis": "- 体系定位：言语理解与表达 → 逻辑填空（语境分析）→ 解释说明（清单原名）；上位\"语境分析（六类呼应）\"→ 本题\"解释说明·三空联动\"→ 下级变式\"转折/因果/并列呼应\"。\n- 识别信号：题干出现**\"通过现象看本质\"\"反映的是…趋势\"**等**对空格作解释或定性的句子**，或空格前后有**\"不是…而是…\"**式界定 → 先把空格旁边的解释句圈出来。\n- 本质：剥掉\"规律/认识论\"外壳，考的是**空格义必须与相邻解释句的落点严丝合缝**——先判每空\"在解释什么\"，再比对近义词语义的**侧重方向**。\n- 通式：`圈解释句 → 定每空落点 → 逐空比对近义词侧重 → 验证三空是否配套`；同类判别条件：**看到\"____的是…\"或\"____的表现\"，就把冒号/判断句后的短语当作答案的对照句**。\n- 易混·易错链：最像\"并列呼应\"——分界：**解释说明＝后句直接给空格作定义**，并列＝**两空彼此同向/对照**。常见撞坑链：被\"洞察力/领悟力\"这类近义惑项带走（都近\"看透\"）→ 忽略\"穿透\"的比喻更贴 → 第三空漏看\"必然趋势\"的对立。", "img": ""}]}]}, {"name": "指代照应", "star": false, "children": [{"name": "指代词回指前文对象，空格须与该对象呼应", "star": false}]}, {"name": "递进/假设呼应", "star": false, "children": [{"name": "递进后程度加重，假设句空格随条件逻辑走", "star": false, "examples": [{"q": "党员干部的政绩观与事业发展的成效紧密相关，党员干部树立什么样的政绩观，就会产生什么样的发展观。如果一开始政绩观没有摆正，从政的“第一粒扣子”没有系好，做决策、抓发展、促改革就会错位偏离，甚至会        ______      。填入画横线处最正确的一项是:", "src": "2025广东省考真题 第19题", "hit": true, "ans": "A", "opts": ["A.失之毫厘，谬以千里", "B.缘木求鱼，水中捞月", "C.得不偿失，因小失大", "D.胜地不常，盛筵难再"], "solve": "==递进词\"甚至\"＋假设前提＝后果由轻到重、由小误差到大偏离，\"失之毫厘，谬以千里\"正合\"小因误 → 大后果\"==。", "analysis": "**识别信号**：题面含 **\"如果……\"＋\"甚至/更/乃至\"** 这类\"假设＋递进\"双标志词。看到\"甚至\"→ 先做\"**定程度**\"：把空格前那半句的程度当基准线，只留**比它更重**的选项；看到\"如果\"→ 空格方向随条件逻辑走（是\"条件不成立的下场\"，不是对策）。\n**核心规律**：剥掉\"政绩观\"的外壳，内核只有一句——**在\"假设＋递进\"语境里，选一个\"方向与上文一致、程度比上文更重\"的词**。考的不是成语背得多，而是\"能不能读出递进尺度并当标尺用\"。打法：**圈关联词（如果/甚至/不仅…而且）→ 定方向（顺/反）→ 定程度（比基准更重/更轻）→ 拿两把尺子卡选项**。凡空格前后有关联词，一律先找\"呼应点原句\"再比对，**勿凭语感硬选**。\n**易混·易错链**：最像的是 **并列呼应**（\"也/又/既…又\"，要求**同向、程度相当**）——一旦把\"甚至\"误当并列，就会去选与\"错位偏离\"**程度相当**的 C/B。撞坑链：递进误当并列 → 程度选平 → 排除掉唯一\"更重\"的 A → 落入\"看字面有'大/小'字眼就选\"的 C 陷阱。", "img": ""}]}]}]}, {"name": "实词辨析", "star": false, "children": [{"name": "实词", "star": false, "children": [{"name": "搭配对象：看搭配对象是否匹配（人/物、抽象/具体）", "star": false, "examples": [{"q": "如同蒸汽时代既改造手工作坊又产生蒸汽船、蒸汽机车和无数新的商业机会，电气时代既重构蒸汽时代的制造业同时也发展出化学工业、内燃机等新的产业一样，通过数字经济和实体经济的深度融合重构既有经济体系，是一个______又______的创造性破坏过程。依次填入画横线部分最恰当的一项是：", "src": "2024广东省考真题 第19题", "hit": false, "ans": "D", "opts": ["A.简短 迅速", "B.简易 短暂", "C.繁杂 冗长", "D.复杂 漫长"], "solve": "抓空前的**类比呼应**——\"如同蒸汽时代…电气时代…一样\"，说明数字经济重构经济体系是**与蒸汽/电气同级、体量宏大、跨时代**的过程，唯有\"**复杂又漫长**\"贴得住\"创造性破坏\"；\"简短/短暂\"太轻、\"繁杂/冗长\"带贬义，均毙。", "analysis": "- 体系定位：言语理解与表达 → 逻辑填空 → 实词辨析 → 实词（清单原名）｜体系位置：上位＝逻辑填空（语境＋词义双线索）→ 本题＝两空实词辨析 → 下级变式＝实词搭配、成语辨析（唯一）、语境分析（转折/因果/并列呼应）。\n- 识别信号：题干\"依次填入画横线部分最恰当的一项\"＝**逻辑填空**；出现\"如同……一样\"即**并列/类比呼应**信号，空格词须与前文**同级同体量**。\n- 本质：考**语境定方向＋近义词辨微**——先由\"如同…一样\"的类比定出\"体量大、历时长\"的语义场，再从近义词中挑色彩、轻重最贴合者（判分点：重构既有经济体系＝宏大而长久的过程，用中性色彩的\"复杂/漫长\"）。\n- 通式：逻辑填空两步式：① **找呼应点定语义方向**（本题＝类比呼应→\"宏大、长久\"）；② **近义词辨微**（比搭配对象＋感情色彩＋程度轻重），两空均由①的方向唯一锁定。\n- 易混·易错链：最像＝**成语辨析**（同为逻辑填空，仅看空处是成语还是实词）；撞坑链：①只凭\"简短/简易\"字面顺口，忽略修饰对象的体量；②被\"繁杂/冗长\"的字面义吸引，忽略其**贬义色彩**与中性语境的冲突。", "img": ""}]}, {"name": "语义轻重：比对语境的程度强弱，选轻重相当者", "star": false}, {"name": "感情色彩：先判语境褒贬中立，再选色彩一致的词", "star": false}, {"name": "语体色彩：看语体，公文书面语境选书面词（如\"予以/商洽\"）", "star": false}, {"name": "词义侧重：拆出不同语素的侧重义，对照语境落点", "star": false}, {"name": "语素差异：拆词素逐字比较，差异语素决定用法", "star": false}, {"name": "语法功能：看该词能否带宾语、能否作状语，词性搭配要通", "star": false}, {"name": "固定搭配：核对是否为约定俗成的固定搭配（如\"履行职责\"）", "star": false}]}, {"name": "实词搭配", "star": false, "children": [{"name": "搭配对象/对象数量/语义重复", "star": false, "examples": [{"q": "从广袤的海洋到无垠的天空，从复杂的陆地战场到神秘的电磁空间，每一个角落都______着高科技的较量。其中，数据链宛如一条无形却坚韧的纽带，将各个作战单元紧密相连，成为现代战争中______的关键要素，深刻地影响甚至决定着战争的走向与胜负。依次填入画横线处最正确的一项是：", "src": "2026广东省考真题 第17题", "hit": false, "ans": "C", "opts": ["A.弥漫 举足轻重", "B.交织 毋庸置疑", "C.充斥 当之无愧", "D.遍布 不可偏废"], "solve": "第一空\"每一个角落都______着较量\"——\"弥漫\"搭配对象错、\"交织\"需≥2个对象、\"遍布\"与\"每一个角落都\"语义重复，只有\"充斥\"（充满、到处都是）成立，直接排除 A/B/D 锁 C。", "analysis": "**核心规律**：逻辑填空·实词辨析（搭配对象／对象数量／语义重复）＋成语搭配（\"当之无愧\"合格 vs \"不可偏废·对象误用\"）。\n**易混·易错链**：①搭配对象不符（弥漫配较量）；②对象数量不符（交织、不可偏废均需两个以上对象）；③语义重复（遍布≈每一个角落都、举足轻重≈关键）。", "img": ""}, {"q": "全球发展倡议提出以来，理念内涵不断______，落实机制不断健全，推进路径更加______，务实合作逐步落地，推动国际社会聚焦发展问题，培育面向未来的高质量发展动能，为全球南方国家______发展鸿沟、共建美好世界提供中国方案。依次填入画横线部分最恰当的一项是：", "src": "2026广东省考真题 第20题", "hit": false, "ans": "B", "opts": ["A.升华 明确 修补", "B.丰富 清晰 弥合", "C.扩展 宽阔 跨越", "D.深化 通达 消弭"], "solve": "第三空\"______发展鸿沟\"——\"鸿沟\"固定搭配为\"弥合\"（补合、使差距消除），A\"修补\"只配具体物件、C\"跨越\"是主体自身跨过而非消除差距、D\"消弭\"多配\"隐患/战乱\"，唯\"弥合\"最搭，直锁 B。", "analysis": "**核心规律**：逻辑填空·实词搭配（固定动宾/定中搭配：内涵丰富、路径清晰、弥合鸿沟）＋语境递进与感情色彩判断。\n**易混·易错链**：①搭配对象不符（修补只配具体物、宽阔只形容物理宽度）；②固定搭配错位（应为\"弥合鸿沟\"，误用跨越/消弭）；③语意/色彩偏差（深化·通达与\"健全\"递进不协、消弭语义过重）。", "img": ""}, {"q": "在南粤大地，一场场深入群众的宣传宣讲，一个个扎根基层的思政课堂，都在______着广东牢记嘱托、感恩奋进的生动实践。填入画横线部分最恰当的一项是：", "src": "2024广东省考真题 第16题", "hit": true, "ans": "A", "opts": ["A.诉说", "B.倾诉", "C.倾听", "D.传达"], "solve": "抓空格前后\"方向\"——主语是\"宣传宣讲/思政课堂\"（向外讲述方），宾语是\"…生动实践\"，须填\"向外·可接抽象宾语\"的动词；四个选项里只有\"**诉说**\"方向对，秒排\"倾听(听)/倾诉(需情感宾语)/传达(公文下行)\"。", "analysis": "- 体系定位：言语理解与表达 → 逻辑填空 → 实词辨析（清单单元原名：实词·搭配对象、实词·词义侧重）；体系位置：语境分析（凭\"但/因为/即\"等标志词）→ **本题（无标志词·纯近义实词对比）** → 下级变式（成语辨析、虚词）\n- 识别信号：四个选项是**同一义群的近义动词**（说/听/传），且题干**无**\"但/然而/因为/即\"等语境标志词 → 判为实词辨析；看到四同义动词 → 先比\"词义方向＋搭配对象\"\n- 本质：逻辑填空的落点永远是\"**空格与语境骨架（主语-宾语-色彩）的匹配**\"；本题考的是**动词的方向＋被搭配对象**——\"谁讲给谁、能接什么宾语\"\n- 通式：无固定式，按三步走：①定主宾、判方向 ②拆差异语素辨词义侧重 ③对搭配对象/语体色彩筛定\n- 易混·易错链：最像\"语境分析\"——**有标志词才用呼应法**，本题无标志词故走实词辨析；撞坑链：见\"深入群众\"误选\"倾听/倾诉\"（错当面向群众），或把\"宣传宣讲\"当成在\"传达\"（忽视公文下行语体）", "img": ""}]}]}]}, {"name": "成语辨析", "star": false, "children": [{"name": "成语", "star": false, "children": [{"name": "望文生义：按本义/出处理解，警惕按字面想当然（如\"首当其冲\"）", "star": false, "examples": [{"q": "星间链路技术，让北斗系统实现了“一星通，星星通”。从一片空白、奋力追赶，再到和世界领先的全球导航系统______，一代代科研人员自立自强、自主创新、拼搏超越，蹚出了一条______的卫星导航探索之路。依次填入画横线处最恰当的一项是：", "src": "2026广东省考真题 第18题", "hit": true, "ans": "D", "opts": ["A.不分伯仲 别无二致", "B.不期而遇 独具匠心", "C.并行不悖 别开生面", "D.并驾齐驱 独具一格"], "solve": "**D. 并驾齐驱 独具一格**", "analysis": "**识别信号**：空格前后有**递进/时间线**（一片空白→追赶→？）+ 需辨析近义成语\n**核心规律**：近义成语差别在**侧重点**——并驾齐驱(齐平)≠并行不悖(不冲突)；独具一格(风格独有)≠别无二致(完全相同)；打法：先定每空的语义方向，再拆成语**关键语素**（驱/悖、格/致）比对\n**易混·易错链**：并驾齐驱 vs 不分伯仲（一讲\"齐头并进\"、一讲\"实力相当\"）；匠心(构思) vs 一格(风格)", "img": ""}, {"q": "树立正确的政绩观，既要以“立说立行”的锐气抢抓机遇，又要以“久久为功”的韧劲夯实发展根基。“立说立行”强调机遇______的紧迫感，“久久为功”则注重______的战略定力，二者看似矛盾，实则统一于高质量发展的实践逻辑中。依次填入画横线部分最恰当的一项是：", "src": "2026广东省考真题 第19题", "hit": true, "ans": "B", "opts": ["A.白驹过隙 稳扎稳打", "B.稍纵即逝 持之以恒", "C.千载难逢 坚如磐石", "D.时不我待 安之若素"], "solve": "**B. 稍纵即逝 持之以恒**", "analysis": "**识别信号**：空格有明确**搭配对象**（机遇/战略定力）+ 前后形成\"急 vs 稳\"对照\n**核心规律**：近义成语差别在**语义落点**——稍纵即逝落\"易失\"、千载难逢落\"难得\"、白驹过隙落\"时光\"；打法：先看空格**修饰的对象**，再挑落点与之吻合的词\n**易混·易错链**：持之以恒(坚持) vs 坚如磐石(坚定不动摇)；时不我待(时间催人) vs 稍纵即逝(机会易失)", "img": ""}, {"q": "实现博物馆业高质量发展，需要做好藏品推介。______自身资源，讲好文化故事，才能让博物馆里______的典籍珍宝绽放风采，受到更多观众的喜爱。依次填入画横线部分最恰当的一项是：", "src": "2024广东省考真题 第20题", "hit": true, "ans": "B", "opts": ["A.改造 凤毛麟角", "B.盘活 浩如烟海", "C.发掘 车载斗量", "D.优化 寥若晨星"], "solve": "第二空\"典籍珍宝\"语境要\"**多**\"→先秒排\"凤毛麟角/寥若晨星\"（少）；再比专用对象——\"**浩如烟海**\"专配典籍书籍、\"车载斗量\"多指可数之物，锁定 B（第一空\"盘活资源\"亦为固定搭配）。", "analysis": "- 体系定位：言语理解与表达 → 逻辑填空 → 成语辨析（清单单元原名：成语·词义侧重、成语·对象误用）；体系位置：实词辨析（比词语搭配）→ **本题（成语定\"数量义＋专用对象\"）** → 下级变式（实词＋成语的混合型选词）\n- 识别信号：选项里出现**成组成语**且语义呈\"多/少\"两极（凤毛麟角↔浩如烟海、寥若晨星↔车载斗量）→ 先做**语义方向（多/少）**一票否决，再比**专用对象**\n- 本质：成语填空就考两点——①**语义方向**（褒贬/多寡/轻重）是否与语境一致；②**专用对象**是否匹配（浩如烟海→典籍、豆蔻年华→少女）；本题两空配合＝\"盘活资源\"（实词固定搭配）＋\"浩如烟海典籍\"（成语对象）\n- 通式：无固定式，按**两空三步**：①先做**语义方向**一票否决 ②剩项比**搭配对象/专用对象**定音 ③回填另一空验证\n- 易混·易错链：最像\"实词搭配\"——若把第二空换成实词即为搭配题；本题靠**成语专属对象**定音故归成语辨析；撞坑链：只盯\"车载斗量也表多\"而忽视其对象为可数物，或只见\"发掘资源\"似通顺而误选 C", "img": ""}]}, {"name": "对象误用：核对该成语专用对象（如\"豆蔻年华\"仅指少女）", "star": false}, {"name": "褒贬误用：判语境褒贬，成语色彩须一致（如\"处心积虑\"贬义）", "star": false}, {"name": "语义重复：找句中已含同义表达的赘余（如\"忍俊不禁地笑\"）", "star": false}, {"name": "词义侧重：比对近义成语侧重点与程度，选贴合语境者", "star": false, "examples": [{"q": "浪费与消费一字之差，含义却   ______           。反对餐饮浪费行为，并不是反对正常的、健康的餐饮消费，而是倡导取之有度、用之有节的健康餐饮文化。填入画横线处最正确的一项是：", "src": "2025广东省考真题 第17题", "hit": false, "ans": "C", "opts": ["A.截然相反", "B.南辕北辙", "C.大相径庭", "D.求同存异"], "solve": "「一字之差」提示形式近、「却」提示语义反 → 要「差异大而非对立」→ 大相径庭。", "analysis": "**识别信号**：题干出现「一字之差／却（转折）」，空格前有**近义/易混**关系；选项为**一组近义成语**（大相径庭｜截然相反｜南辕北辙｜求同存异）→ 必考「程度分寸 ＋ 语义方向 ＋ 搭配对象」。\n**核心规律**：成语题先定**语境方向**（转折「却」→ 取差异义），再用**程度分寸**筛——是「差异大」还是「完全对立」；同时核对**搭配对象**能否适配空格主语（此处主语＝「含义」）。打法：①抓提示语（「一字之差」提示形式近、「却」提示语义反）定方向 → ②语义场筛，先剔**方向背离**的 D（求同存异）→ ③三把尺子精筛：程度（对立 / 差异）· 对象（能否接「含义」）· 感情色彩 → ④代回读顺验证。\n**易混·易错链**：==大相径庭==＝相差很远，**可不同但非对立**（本题正解）；**截然相反**＝完全对立，程度最重（后文「反对浪费≠反对消费」说明二者可并存 → 过重，排除）；**南辕北辙**＝行动与目的相反（搭配对象错，此处主语是「含义」不是「行动」）；**求同存异**＝找共同点、保留不同点（方向相反）。凡遇「一字之差／略有不同／相距甚远」→ 首选 **大相径庭**。", "img": ""}, {"q": "一个人的能力有大小，做不了 ______ 的大事，或做些 ______ 的小事。只要每个人都发挥潜能，为自己的梦想努力奋斗，国家和社会也会因此变得更加美好。依次填入画横线处最正确的一项是：", "src": "2025广东省考真题 第18题", "hit": false, "ans": "B", "opts": ["A.开天辟地 微不足道", "B.惊天动地 力所能及", "C.名垂青史 默默无闻", "D.轰轰烈烈 无关紧要"], "solve": "先读总纲句「能力有大小」定轴 → 攻第二空：唯「力所能及」含「力」直扣能力轴。", "analysis": "**识别信号**：一组**成对近义成语**（大词↔小词）＋**对举结构**（\"做不了…大事 ／ 做些…小事\"）→ 先找**总纲句／对举结构**定「语境轴」。\n**核心规律**：内核＝在「**能力有大小**」这一语境轴下，为「超出能力」与「能力之内」两端各挑一个**侧重／对象／色彩俱合拍**的成语；即 语境轴 × 成语{侧重·对象·色彩} 三重匹配。打法：双空题＝**先定轴 → 攻区分空 → 验锥空**；正解＝语境轴 ∩ 选项{词义侧重·适用对象·感情色彩}。本题第一空四选**几乎全可通**、区分度≈0 → 命门在**第二空**。\n**易混·易错链**：最像＝**词义侧重 vs 褒贬误用**——看「轴」落在**语义侧重点**（能力／名声／重要性）还是**色彩褒贬**；撞坑链：**只凭第一空语感挑**（四个第一空全通）→ 漏看第二空「**力**」字直扣总纲「能力有大小」。", "img": ""}, {"q": "从全局看“形”，要克服认识论上的碎片化倾向。在实际工作中，有的党员干部“______”，研判外部客观形势时，只凭个人经验、经历以偏概全；有的党员干部“______”，审视自身能力定位时，盲目自信或者妄自菲薄。这些不良作风根源在于缺乏系统思维，将局部等同于整体。党员干部要自觉树立大局意识，站在全局和战略的高度想问题、做工作。依次填入画横线部分最恰当的一项是：", "src": "26年省考34季 第17题", "hit": false, "ans": "B", "opts": ["A.管中窥豹 刚愎自用", "B.盲人摸象 坐井观天", "C.我行我素 夜郎自大", "D.断章取义 一叶障目"], "solve": "两空共享总括句「将局部等同于整体」，抓这句当唯一判据，凡内核不是「以局部代整体」的成语直接砍，剩盲人摸象＋坐井观天严丝合缝。", "analysis": "体系定位：言语理解与表达 → 逻辑填空（成语辨析）→ 成语·词义侧重（近义成语辨析，比对侧重点与程度）；体系位置＝上位【逻辑填空·语境呼应：找呼应点/解释说明】→ 本题【近义成语按\"对象＋内核\"二择】→ 下级变式【同空近义实词·搭配对象/语义轻重/感情色彩辨析】。\n识别信号：题干长相＝\"依次填入画横线部分最恰当\"＋两个引号内成语空格＋空格后紧跟解释句（\"只凭…以偏概全\"\"盲目自信或者妄自菲薄\"）；规律感＝看到多空＋后文有解释 → 先抓总括句、再逐空划呼应，绝不逐词查典。\n本质：剥掉外壳＝\"用后文解释句给空格成语下定义，再从近义成语里挑对象与侧重完全吻合的那一个\"；判分点并入此条——两空都须同时满足\"各自呼应句\"＋\"总括句（将局部等同于整体）\"双向吻合。\n通式：正确项 = argmax_选项 [ 对象匹配语境 × 内核呼应总括 ]；操作式＝呼应句 → 抽内核关键词（局部/整体、以偏概全、对己片面）→ 对象尺 + 内核尺逐项排除。\n易混·易错链：最像单元＝【成语·对象误用】（专管对象，如\"豆蔻年华只指少女\"）——本题\"断章取义\"只对文本、\"我行我素\"只对行为即对象误用，故先辨对象、再辨侧重；撞坑链＝\"盲人摸象↔管中窥豹↔一叶障目\"三词都含\"局部\"，靠动作方式分：摸象＝凭经验摸、窥豹＝借管看、障目＝被叶遮。", "img": ""}]}, {"name": "谦敬错位：对己用谦辞、对他人用敬辞（如\"蓬荜生辉\"）", "star": false}]}]}, {"name": "虚词", "star": false, "children": [{"name": "关联词搭配", "star": false, "children": [{"name": "核对固定配对（如\"不但…而且\"\"与其…不如\"）", "star": false}]}, {"name": "关联词位置", "star": false, "children": [{"name": "前后分句主语一致→关联词在主语后；不一致→在主语前", "star": false}]}, {"name": "递进关系", "star": false, "children": [{"name": "后句程度/范围高于前句才配递进词", "star": false}]}]}, {"name": "通用技巧", "star": false, "children": [{"name": "找呼应点", "star": false, "children": [{"name": "先读题干划呼应词/呼应句，再拿选项比对（勿凭语感硬选）", "star": false}]}]}]}, {"name": "片段阅读", "star": false, "children": [{"name": "主旨概括", "star": false, "children": [{"name": "总分结构", "star": false, "children": [{"name": "首句总起提观点，后文分述都为支撑，主旨取首句", "star": false, "examples": [{"q": "改革不可能一蹴而就，特别是许多重大改革任务需要一年接着一年推进。党员干部特别是领导干部对于前任领导推进的改革任务，只要是贯彻党中央精神的、切合实践要求的、符合人民群众愿望的，就要坚持一张蓝图绘到底，一茬接着一茬干。对于改革任务的落实，不能“新官不理旧账”，这是确保干一件成一件的内在要求。新时代，许许多多改革任务的落实，都是一茬接着一茬干的结果。以下干事创业精神，最贴合上文要求的是（ ）。", "src": "2026广东省考真题 第23题", "hit": true, "ans": "C", "opts": ["A.时不我待、只争朝夕", "B.抓铁有痕、踏石留印", "C.功成不必在我、功成必定有我", "D.踏平坎坷成大道，斗罢艰险又出发"], "solve": "**C. 功成不必在我、功成必定有我**", "analysis": "**识别信号**：文段反复出现同一义表述（一茬接一茬、绘到底）→ 即主旨\n**核心规律**：题面问\"最贴合的精神\"，实为**主旨在选项中的转述**；打法：找**高频复现词**→提炼核心义→到选项找**同义转述**\n**易混·易错链**：接续奋斗(功成不必在我) vs 攻坚克难(踏平坎坷) vs 抢抓时间(只争朝夕)——三者易混，抓住\"长远/接续\"锚点", "img": ""}, {"q": "从“村BA”到“村超”，从乡村博物馆到美术馆、音乐会，一批乡村文体活动开展得有声有色。这些乡村公共文化服务衍生出的新业态，正在成为推动乡村全面振兴的重要动力。乡村公共文化服务提升和乡村文化产业发展要充分考虑乡土特征，聚焦乡村资源优势和文化特色，提炼乡村的文化主题和品牌定位，打造集村史馆、乡村书屋等功能于一体的复合体空间，采用多元化、艺术化和高新技术的场景营造手段，建设乡土美学生活体验中心，注重乡村本土节日的挖掘，从而推动文化创意赋能乡村可持续发展。根据这段文字，作者最有可能认同（ ）。", "src": "2026广东省考真题 第25题", "hit": true, "ans": "D", "opts": ["A.乡村公共文化服务是推动乡村全面振兴的重要动力", "B.村字头的文体活动是乡村公共文化服务的典型代表", "C.复合体空间的主要价值在于合理利用乡村空间资源", "D.挖掘乡村本土文化资源有利于推动乡村可持续发展"], "solve": "材料后半段全是「做法」，落脚在「**从而**推动……可持续发展」，**做法→目的**即中心，选与「挖掘本土文化资源→可持续发展」同义的 D。", "analysis": "**核心规律**：**片段阅读·中心理解**（主旨概括/「最可能认同」型，抓对策与目的的落脚点）\n**易混·易错链**：①**偷换主体**（把「新业态」换成「公共文化服务」）；②**无中生有**（强加「典型代表」等定性）；③**以偏概全/曲解**（把做法细项当作中心，臆造其价值）", "img": ""}, {"q": "要坚持以人民为中心的发展思想，畅通多元化、立体化技能成才路径。持续优化职教高考制度，完善中职、高职、职业本科纵向贯通的培养体系，打破技能人才学历提升壁垒，为不同禀赋学习者提供多次选择、多元成才的机会。深耕终身教育服务，面向农民工、退役军人、下岗职工、新型职业农民等重点群体，开发普惠化、定制化技能培训项目，推行线上线下融合、送教入企下乡的灵活办学模式，助力劳动者技能提升、转岗增收。持续优化社会舆论环境，广泛宣传技能成才、技能报国先进典型，完善技能人才薪酬、职称、落户等配套保障政策，破除社会偏见，营造人人皆可成才、人人尽展其才的良好生态。", "src": "26年省考34季 第22题", "hit": false, "ans": "B", "opts": ["A.聚焦育人适配，以类型化改革夯实德技并修人才培养根基", "B.聚焦民生适配，以贯通成才通道满足群众多元化发展期盼", "C.聚焦产业适配，以产教深度融合对接现代化产业体系需求", "D.聚焦战略适配，以开放协同服务国家战略与区域发展大局"], "solve": "首句以人民为中心＋畅通技能成才路径即主旨，唯B全命中民生+成才通道+群众多元", "analysis": "体系定位：言语理解与表达 → 片段阅读（主旨概括）→ **总分结构**；体系位置：上位「片段阅读·主旨概括（据行文结构定重点）」→ 本题「总分结构·首句总起」→ 下级变式「分总结构／总分总结构／并列结构（无明显总起句）」\n识别信号：题干作\"作者认为……应/意在说明/主要讲/概括\"，且材料**首句是\"要坚持/要……\"式观点句**、后跟多个并列举措（\"持续优化/深耕/不断\"）\n本质：在\"总说＋分说\"材料里用**首句**锚定作者观点，再剔除只抓某一段细节的干扰项——考的是\"**抓大不抓小**\"\n通式：①读设问定\"取总\" → ②找总起句（首句提观点）→ ③压缩总句成关键词 → ④选项比对\"关键词重合度\"，全覆盖者选\n易混·易错链：最像 **并列结构**（三段貌似平列）——区别：有明确总起句就取首句（本题），无总起句才需全面概括各并列项；常见撞坑：被某段细节词（\"产教融合\"\"德技并修\"）带偏，选了只对应局部一段的选项", "img": ""}, {"q": "本土文化资源与文旅业态打造联系密切、高度关联。文旅项目的生命力根植于丰厚的文化资源储备，一旦本土文化内容单薄、特色不足，文旅业态打造就容易陷入同质化内卷，难以吸引大众。短视频、直播等视频传播形式的兴起，则可以把深藏于乡野、博物馆里的文化资源推向大众，拉动文化IP开发、衍生产品销售，助推本土文化资源盘活。当本土文化资源持续被发掘、价值不断被释放后，文旅业态打造也能拥有源源不断的创作养料，实现长期稳定的迭代更新。这段文字意在说明：", "src": "26年省考35季 第27题", "hit": true, "ans": "D", "opts": ["A.文旅项目的存续状态取决于文化资源的储备情况", "B.本土文化资源的利用是文旅业态持续打造的重要依托", "C.本土文化资源与文旅业态打造之间存在着紧密的联系", "D.视频传播推动本土文化资源开发与文旅业态打造双向增益"], "solve": "首句只提出\"资源与业态关联\"这一**话题**，作者真正要讲的机制是\"**视频传播 → 盘活资源 → 反哺业态**\"这条链，须选**动因＋两端**都收的==视频传播推动本土文化资源开发与文旅业态打造双向增益==。", "analysis": "- 体系定位：言语理解与表达 → 片段阅读（主旨概括）→ 总分结构（清单原名）；上位\"主旨概括（总分/分总/总分总…）\"→ 本题\"**总分·话题句＋机制共集**\"→ 下级变式\"分总/转折/因果结构\"。\n- 识别信号：问句\"这段文字意在说明\"＋首句为**并列短语式话题**（\"X 与 Y 联系密切\"）→ 不能只抄首句，要抓后文**如何**关联。\n- 本质：剥掉\"本土文化/文旅\"外壳，考的是**主旨须概括\"分\"的部分的共集**——首句只搭台，真意在台后（谁在推动、哪两端受益）。\n- 通式：`判结构（总分/分总/…）→ 若首句仅提话题 → 取分述共集为主旨 → 选项须含全部关键要素`；同类判别条件：**首句只说\"有关联/很重要\"时，正确答案往往就是那个\"不能只复述首句\"的选项**。\n- 易混·易错链：最像\"分总结构\"——分界：**总分是首句提话题、后文展开**，分总是**尾句下结论**。常见撞坑链：直接抄首句选 C（笼统）→ 只抓\"资源→业态\"单向选 B → 被\"取决于\"的绝对化表述吸引选 A。", "img": ""}]}]}, {"name": "分总结构", "star": false, "children": [{"name": "尾句结论/总结为重点，主旨取尾句", "star": false, "examples": [{"q": "当前，中国经济已转向高质量发展阶段，旧的生产函数组合方式已经难以持续，不可能像高速增长阶段那样主要依靠要素投入驱动经济增长，必须转向更多依靠科技创新和全要素生产率的提高。面对新一轮科技革命和产业变革深入发展，中国既要摆脱传统增长方式下粗放扩张、低效发展的生产力发展路径，又要拓展先进生产力发展空间。以科技创新为核心，培育和发展新质生产力，才能为高质量发展开辟新路径、注入新动力。这段文字主要讲了（ ）。", "src": "2026广东省考真题 第21题", "hit": false, "ans": "B", "opts": ["A.重大技术变革驱动中国经济高速增长", "B.高质量发展离不开培育和发展新质生产力", "C.每一次科技革命都会带来生产力质的飞跃", "D.科技创新是培育和发展新质生产力的核心"], "solve": "**看尾句结论句**——\"**以科技创新为核心，培育和发展新质生产力，才能为高质量发展开辟新路径、注入新动力**\"，全文核心概念是\"**高质量发展 ↔ 新质生产力**\"，四个选项中只有 B 同时扣住这两个核心、且概括全文，直锁 B。", "analysis": "**核心规律**：片段阅读·中心理解（主旨概括）：**抓尾句结论句、概括全文核心关系**，主旨须覆盖\"高质量发展\"这一目的，忌选局部细节。\n**易混·易错链**：①**偷换概念**（A 把\"高质量发展\"换成\"高速增长\"）；②**无中生有/过度推断**（C 的\"每一次……都会\"凭空拔高）；③**以偏概全**（D 只取\"科技创新为核心\"的手段细节、遗漏全文目的）。", "img": ""}]}]}, {"name": "总分总结构", "star": false, "children": [{"name": "首尾呼应，主旨取首句与尾句的共集", "star": false}]}, {"name": "转折结构", "star": false, "children": [{"name": "转折词（但/然而）之后是重点", "star": false, "examples": [{"q": "甲醛释放是一个长达3年至15年的缓慢过程，其主要源于板材内部的胶黏剂。“除醛魔盒”可依靠被动接触来吸附空气中的游离甲醛，也可通过缓慢释放氧化剂与甲醛反应，但其作用范围极其有限，往往只能覆盖盒子周围极小的区域，其实际去除效果微乎其微，难以从根本上解决问题。许多消费者在使用后感觉没味道了，是因为产品中添加的香精掩盖了装修异味，或者是心理作用，并不代表室内的甲醛浓度真的降至安全标准。从化学性质上来讲，甲醛是一种无色、有强烈刺激性气味的气体。然而，在低浓度（一般低于0.08毫克/立方米）下，许多人难以闻到其气味，因此不能仅靠嗅觉判断甲醛是否超标。这段文字主要反驳了下列哪一观点？", "src": "26年省考34季 第28题", "hit": true, "ans": "B", "opts": ["A.消费者可以通过闻气味来判断室内甲醛是否安全达标", "B.“除醛魔盒”通过吸附和化学反应能够有效去除室内甲醛", "C.“除醛魔盒”中添加的香精能从根本上消除装修异味", "D.甲醛在低浓度下无色无味，对人体健康没有危害"], "solve": "文段在“但”处一转，转折后直陈除醛魔盒效果微乎其微、难从根本上解决问题，驳的正是B“能有效去除甲醛”。", "analysis": "**体系定位**：言语理解与表达 → 片段阅读 → 主旨概括 → 转折结构 → 转折词（但/然而）之后是重点（均为清单原名：模块“片段阅读”、题型“主旨概括”、子类“转折结构”、方法“转折词（但/然而）之后是重点”）＋ 体系位置：上位＝片段阅读行文结构类 → 本题＝用“转折结构”定主旨并反推被驳观点 → 下级变式＝因果结构／总分结构／反面论证同类题型。\n**识别信号**：题干出现“这段文字主要反驳了……哪一观点”“主要说明／意在强调”，且文中带“但／然而／其实／事实上”等转折标志词。\n**本质**：剥掉“除醛魔盒”的外壳，内核是“**先定行文结构 → 取转折后的核心句 → 反推／转述成被驳或被强调的观点**”（原判分点：转折词“但／然而”之后是重点）。\n**通式**：`被驳观点 = 否定(转折后主旨句)`；即“但＋否定现状”时，答案取“肯定现状”的对立面（此处“无效”↔“有效”）——可用行内码记作 `被驳观点 = ¬(转折后句)`。\n**易混·易错链**：最像“因果结构”（判分点：结论词“因此／可见”之后是重点）＋ 常见撞坑链：把末段补充论据（A“嗅觉”、C“香精”）误当主旨 → 掉入以偏概全，忽视题干“**主要**”二字。", "img": ""}]}]}, {"name": "因果结构", "star": false, "children": [{"name": "结论词（因此/可见）之后是重点", "star": false}]}, {"name": "必要条件", "star": false, "children": [{"name": "\"只有…才/应该/需要\"的必要条件是重点", "star": false}]}, {"name": "并列结构", "star": false, "children": [{"name": "无重点标志→需全面概括各并列项，忌偏一项", "star": false, "examples": [{"q": "造纸术和印刷术的发明，为文学提供了物质载体与传播媒介，催生了图书出版业，电气技术使得记录影像和声音成为可能，带动广播、电影、电视等的发展，在新一轮科技革命和产业变革加快孕育的今天，人工智能、5G、区块链等新技术得到普及应用，科技进步对文化创新\n## 四. 数量关系：", "src": "2026广东省考真题 第29题", "hit": true, "ans": "C", "opts": ["A.文化创新与科技革命始终深度融合", "B.文化产业发展为科技创新带来澎湃动力", "C.文化领域的发展变革与科技进步息息相关", "D.科技进步充分激发大众文化创新创造活力"], "solve": "**C. 文化领域的发展变革与科技进步息息相关**", "analysis": "**识别信号**：多个\"技术→文化\"例证并列，无转折/结论强标志\n**核心规律**：并列结构主旨＝**全面概括各并列项共义**，忌偏一项、忌拔高；打法：提炼\"共性关系\"→找**覆盖全篇、程度恰当**的选项\n**易混·易错链**：并列概括 vs 转折重点（本文无转折）；\"息息相关\"(中性适度) vs \"始终深度\"(绝对化)", "img": ""}, {"q": "褪黑素是人体松果体分泌的内源性激素，分泌节律受光照调控，夜间分泌水平上升，助力人体进入睡眠状态。临床上，褪黑素仅对延迟性昼夜节律失调引发的失眠有效。市面上作为膳食补充剂的外源性褪黑素，定位是生物节律调节剂，并非普适安眠药。对于焦虑、躯体病变诱发的失眠，补充褪黑素不仅难以起效，还可能产生不良反应。长期、过量摄入外源性褪黑素，会负向抑制人体自身褪黑素合成，骤然停药后，内源分泌水平短时间内难以恢复，容易诱发反弹失眠，甚至形成药物依赖。这段文字主要回答了下列哪一问题？", "src": "26年省考35季 第28题", "hit": false, "ans": "A", "opts": ["A.外源性褪黑素作为助眠产品是否安全有效", "B.如何正确理解内源性褪黑素和外源性褪黑素的作用", "C.外源性褪黑素在临床上用来治疗哪些类型的失眠", "D.为何不能长期、过量服用外源性褪黑素治疗失眠"], "solve": "\"主要回答哪一问题\"→把文段当答案反推问句：文段既说\"仅对特定失眠有效、并非普适安眠药\"（**有效性**），又说\"不良反应、药物依赖\"（**安全性**）→ 问句必是==外源性褪黑素作为助眠产品是否安全有效==。", "analysis": "- 体系定位：言语理解与表达 → 片段阅读（主旨概括）→ 并列结构（清单原名）；上位\"主旨概括（总分/分总/…并列…）\"→ 本题\"**问题式主旨·并列全面概括**\"→ 下级变式\"总分/分总/转折结构\"。\n- 识别信号：问句变体\"**主要回答了哪一问题／意在回答**\"＋文段**无明显重点标志、分几个方面铺陈** → 把文段当答案，反推能覆盖**全部方面**的问句。\n- 本质：剥掉\"褪黑素\"外壳，考的是**问句的外延是否＝文段各分述方面的并集**——答句只覆盖一层（有效 or 安全）即为漏项。\n- 通式：`切分文段层次 → 判是否并列多面 → 反推\"覆盖全部方面\"的问句 → 选项范围＝并集才对`；同类判别条件：**看到\"主要回答/意在回答哪一问题\"，先数文段讲了几面，再挑两面都收的选项**。\n- 易混·易错链：最像\"细节题（针对某句提问）\"——分界：**主旨问题式**答案覆盖全文（多面），**细节问题**只对应一句。常见撞坑链：只抓末句\"长期过量危害\"选 D → 只抓\"临床有效类型\"选 C → 被\"内源/外源对比\"带偏选 B。", "img": ""}]}]}, {"name": "反面论证", "star": false, "children": [{"name": "把\"否则/如果不\"反面句反推成正向观点", "star": false}]}]}, {"name": "意图判断", "star": false, "children": [{"name": "问题+对策", "star": false, "children": [{"name": "文中指出问题→意图为提出对策（应/必须/需要）", "star": false, "examples": [{"q": "近年来，多地鼓励市民通过“随手拍”反映市政设施损坏、不文明行为等城市治理问题。作为庞大复杂的有机体，城市运转涉及经济、文化、民生等多个领域和部门，规划、政策、制度等即便再完善细密也难以穷尽城市治理的每一个细节、每一处角落。城市理想蓝图与现实场景之间的微小“空白”，特别需要广大市民主动作为、共同“填补”。看似简单的市民“随手拍”，反映出市民变被动接受公共服务为主动参与城市治理的积极意识。上述文字意在说明（ ）。", "src": "2026广东省考真题 第24题", "hit": false, "ans": "C", "opts": ["A.城市文明建设人人有责", "B.城市运转体系庞大且复杂", "C.城市治理需要市民主动参与", "D.城市理想蓝图需要全民共绘"], "solve": "**抓尾句观点句**——\"看似简单的市民'随手拍'，反映出市民……**主动参与城市治理**\"，全文落点就是\"**市民主动参与城市治理**\"，四选项中只有 **C（城市治理需要市民主动参与）** 直接对应，直锁 C。", "analysis": "**核心规律**：片段阅读·意图判断（中心理解）：**锁定关键句/尾句观点、概括核心意图**，主旨须覆盖\"市民主动参与城市治理\"，忌取背景细节或泛化话题。\n**易混·易错链**：①**以偏概全**（B 只取\"城市体系庞大复杂\"的背景）；②**偷换话题/泛化**（A 把\"城市治理\"泛化成\"城市文明建设人人有责\"）；③**偷换概念·扩大主体**（D 把\"市民主动参与\"换成\"全民共绘蓝图\"）。", "img": ""}, {"q": "文化重在化人，但能否真正用文化引导人们坚定理想、塑造灵魂、涵养品德、砥砺人格等，要看“化”的水平。如何使以文化人“化”得合情理、“化”得受欢迎、“化”得效果好，考验着我们的文化工作水平。习近平总书记强调：“要润物细无声，运用各类文化形式，生动具体地表现社会主义核心价值观，用高质量高水平的作品形象地告诉人们什么是真善美，什么是假恶丑，什么是值得肯定和赞扬的，什么是必须反对和否定的。”根据这段文字，作者意在强调：", "src": "2026广东省考真题 第27题", "hit": false, "ans": "C", "opts": ["A.文化工作的目的和意义", "B.文化工作水平的重要性", "C.以文化人要注重文化传播的方式方法", "D.以文化人要坚持社会主义核心价值观"], "solve": "抓「**如何**使以文化人'化'得合情理、'化'得受欢迎、'化'得效果好」这一疑问/对策句，再配引言「**润物细无声、运用各类文化形式、用高质量高水平的作品**」——全在讲「**怎么化 / 方式方法**」，直锁 **C**。", "analysis": "**核心规律**：片段阅读·**意图判断**：抓疑问/对策句（\"如何…\"）与引言指向，重心＝\"**怎么做**（方式方法）\"，而非\"是什么/为什么\"。\n**易混·易错链**：① 以局部词（文化工作水平）当主旨（B）；② 把引文内容的宾语（社会主义核心价值观）误当中心，忽略\"怎样表现\"（D）；③ 把背景话题（目的意义）当强调点（A）；④ 只看到\"重要性\"而漏掉文段的**对策/方法**意图。", "img": ""}]}]}, {"name": "意在强调", "star": false, "children": [{"name": "抓转折/结论后的核心，转述其深层意图", "star": false}]}, {"name": "寓言寓意", "star": false, "children": [{"name": "由结局与因果提炼普遍道理，勿复述情节", "star": false}]}, {"name": "真实目的", "star": false, "children": [{"name": "抛开字面，取作者立场/目的作答案", "star": false}]}]}, {"name": "细节判断", "star": false, "children": [{"name": "无中生有", "star": false, "children": [{"name": "核对选项信息文中是否提及，未提即错", "star": false}]}, {"name": "偷换概念", "star": false, "children": [{"name": "比对主语/宾语/定语是否被换（张冠李戴）", "star": false}]}, {"name": "偷换时态", "star": false, "children": [{"name": "核对已然/未然/将然（\"已经/将要\"）是否被改", "star": false}]}, {"name": "偷换逻辑", "star": false, "children": [{"name": "核对因果/条件/并列关系是否被倒置或颠倒", "star": false}]}, {"name": "绝对化表述", "star": false, "children": [{"name": "文中为\"有的/可能\"，选项变\"一定/全部\"即错", "star": false}]}, {"name": "混淆范围", "star": false, "children": [{"name": "核对范围大小与数量（部分/整体、数量词）是否被放大缩小", "star": false, "examples": [{"q": "公园功能的拓展，需要规划先行。一方面要精准定位公园的基本功能，充分考虑公园周边居民的功能需求，将周边居民日常生活和工作引入公园。另一方面要强化公众参与的理念，让居民参与到公园建设前、建设中、建设后的全过程。对这段文字理解准确的是（ ）。", "src": "2024广东省考真题 第27题", "hit": false, "ans": "A", "opts": ["A.公园建设过程中应当了解居民的功能需求", "B.公园必须满足全市居民的日常生活和工作需求", "C.公众参与公园建设有助于提升公园建设效率", "D.应根据周边居民的需要不断拓展公园的功能区域"], "solve": "选项逐句回原文对照——原文只说\"充分考虑**公园周边居民**的功能需求\"，A 与之一致；B 把\"周边\"扩成\"**全市**\"（混淆范围＋绝对化\"必须\"），C\"提升效率\"、D\"不断拓展功能区域\"原文均无（无中生有），故唯一准确的是 A。", "analysis": "- 体系定位：言语理解与表达 → 片段阅读 → 细节判断 → 混淆范围（清单原名）｜体系位置：上位＝片段阅读（细节判断 vs 主旨概括）→ 本题＝细节—原文一致性核对 → 下级变式＝无中生有、偷换概念、偷换时态/逻辑、绝对化表述。\n- 识别信号：题干\"对这段文字**理解准确/符合/不正确**的是\"＝**细节判断题**；选项出现\"**全市/所有/必须/一定/不断**\"等范围·绝对词，先回原文核范围。\n- 本质：考**选项与原文的逐句一致性**——不概括、不引申；凡原文没说的（无中生有）、被放大的（范围/程度过强）、被换掉的（偷换概念）都错（判分点：A 与\"周边居民的功能需求\"精确对应；B 范围扩大、C/D 无中生有）。\n- 通式：细节判断三步式：① **读原文划信息点**；② **选项逐句回文比对**（比主体、范围、程度、时间、逻辑）；③ **只认原文有据者**，见\"必/全/都\"等词优先怀疑。\n- 易混·易错链：最像＝**主旨概括**（细节判断问\"是否一致\"，主旨概括问\"主要说什么\"，别把合理引申当细节）；撞坑链：①把\"周边居民\"读成\"全市居民\"（范围）；②把\"公众参与\"脑补成\"提升效率\"（无中生有）；③把\"规划先行\"误读为\"不断拓展\"（偷换/无中生有）。", "img": ""}]}]}, {"name": "与原文相反（表意反向）", "star": false, "children": [{"name": "辨别选项是否把原文意思说反（正话反说 / 态度被颠倒）", "star": false, "examples": [{"q": "城市化进程历史性地改变了基层社会结构，现代都市生活带来一系列社会问题，促使学界重新认识以儒家思想为核心的传统伦理的恒久价值，在城市化的“后半程”，家庭仍然是社会的基本单元。如何发掘传统伦理的现代意义，打造一种新型“东方伦理型生活方式”，不仅是“以人为核心的新型城镇化”的题中应有之义，也将为中国式现代化提供强大的社会基础和道义支撑。根据上述文段，无法得出的是（ ）。", "src": "2025广东省考真题 第28题", "hit": false, "ans": "A", "opts": ["A.在现代基层社会结构中，传统伦理已丧失其价值", "B.在城市化进程中，家庭始终是社会的基本单元", "C.打造“以人为核心的新型城镇化”正当其时", "D.城市化进程极大地改变了基层社会结构"], "solve": "问「无法得出」→ 反向筛选（选没提 / 说反 / 加码者）：A 把原文「重新认识其恒久价值」说成「已丧失价值」——正话反说，选 A。", "analysis": "**体系定位**：言语理解 → 片段阅读 → 细节判断（与原文相反 / 表意反向）\n**识别信号**：问法「无法得出的是 / 不符合文意 / 与原文不相符」→ 一律**反向筛选**（选没提、说反、加码者）\n**本质**：以原文为**唯一标尺**逐项核「是否被文段支撑」——考照相近义核对，不考概括提炼（与主旨/意图题的分水岭）\n**通式**：定位原文句 → 比对表述方向（正/反、同义/换概念）→ 判「支撑 / 相反 / 未提」；同义或弱化＝可得出，**相反·换对象·加码（绝对化）·未提**＝无法得出\n**易混·易错链**：无中生有 → 偷换概念 → 方向反 → 绝对化/程度过强 → 偷换时态；见「始终/已/一定/全部」先起疑，但**优先看语义是否被说反**", "img": ""}]}]}]}, {"name": "词句理解", "star": false, "children": [{"name": "指代词理解", "star": false, "children": [{"name": "用就近原则向上文找最近且逻辑匹配的指代对象", "star": false}]}, {"name": "比喻义还原", "star": false, "children": [{"name": "把比喻/象征还原为本体，取本义", "star": false}]}]}, {"name": "态度观点 / 标题 / 承接", "star": false, "children": [{"name": "态度判断", "star": false, "children": [{"name": "分明确表态（\"我认为\"）与隐含表态（靠转折/修饰词），取作者立场", "star": false}]}, {"name": "新闻标题", "star": false, "children": [{"name": "取导语的核心事件，简洁含对象+事件", "star": false}]}, {"name": "议论/说明/散文标题", "star": false, "children": [{"name": "议论文取观点/落脚句；说明文取对象+特征；散文取形象+情感；警惕引用句当标题与越界限定词（全球/基本/最）", "star": false, "examples": [{"q": "“发展是人类社会永恒的主题”“贫穷是实现人权的最大障碍”······这些朴素而深刻的论断，构成了中国人权观的重要认知基础。正如习近平主席所强调的，对于发展中国家来说，“生存权、发展权是首要的基本人权”，要“在发展中保障和改善民生，保护和促进人权”。离开了发展，其他一切权利的实现便如同空中楼阁、无源之水。正是基于这一根本遵循，中国走出了一条将人权的普遍性原则与本国实际相结合、以发展促进和保障人权的特色道路。以下选项中，最适合作为这段文字标题的是（ ）。", "src": "2026广东省考真题 第26题", "hit": false, "ans": "A", "opts": ["A.以发展之钥，启人权之门", "B.发展：人权治理的全球方案", "C.生存和发展——人类的基本权利", "D.发展权优先：人权保障的基本共识"], "solve": "文段落脚句在「以发展促进和保障人权的特色道路」——找\"发展→人权\"因果/钥匙关系且不越界的项，只有 A 是对仗同义转述。", "analysis": "**核心规律**：片段阅读·标题选择：标题须**涵盖主旨 + 简洁生动**，优先选与结论句（落脚句）同义对仗的表达。\n**易混·易错链**：① 引用句/引证句当标题（C 取\"生存和发展\"）② 扩大范围、加文外信息（B\"全球方案\"）③ 用局部词偷换落脚重心（D\"共识\"）④ 忽略发展与人权的**手段—目的**关系，选并列式标题（C）。", "img": ""}, {"q": "塔黄是蓼科大黄属的草本植物，生长于海拔4000-4800米的高山流石滩与高寒草甸边缘。在开花前，塔黄长得像一棵普通的大白菜，只有翠绿色的大叶子，并不引人注目。可一旦到了开花的那一年，它就会“华丽变身”，迅速长出一根高达2米的花序，成为高寒地带最高的草本植物。更令人惊叹的是，花序外面还包裹着一层层半透明、呈乳黄色的苞片，远看就像一座金灿灿的宝塔，这些苞片如同温室大棚中的玻璃，既能保温又防风雨，为内部脆弱的花朵和种子提供了温暖的环境。最适合做这段文字标题的是：", "src": "26年省考35季 第26题", "hit": false, "ans": "A", "opts": ["A.高原冰天雪地中的“温室植物”", "B.高寒地带的“草本之王”", "C.严酷高原上的“生命奇迹”", "D.一棵“大白菜”的华丽蜕变"], "solve": "抓\"更令人惊叹的是\"后的核心——苞片\"如同温室大棚中的玻璃，既能保温又防风雨\"→全文落在==苞片的温室功能==，标题须含\"温室植物\"。", "analysis": "- 体系定位：言语理解与表达 → 片段阅读（态度观点/标题/承接）→ 议论/说明/散文标题（清单原名）；上位\"标题类（新闻/议论说明散文）\"→ 本题\"**说明文·对象＋特征**\"→ 下级变式\"新闻标题／推断下文\"。\n- 识别信号：问句\"最适合做…标题的是\"＋文体为**说明性介绍** → 抓**说明对象＋核心特征**，且重点常在**递进词（更…／尤其／令人惊叹）之后**。\n- 本质：剥掉\"塔黄\"外壳，考的是**标题是否＝说明对象的本质特征**——甩掉铺垫细节（外形/变身），只留\"最具辨识度的功能特征\"。\n- 通式：`判文体（议论/说明/散文）→ 定对象 → 抓递进或转折后的特征 → 标题＝对象＋特征`；同类判别条件：**看到\"更/尤其/令人惊叹\"等递进词，重点一律取其后**。\n- 易混·易错链：最像\"推断下文\"——分界：**标题**是概括全文（对象＋特征），**推断下文**看尾句话题往后推。常见撞坑链：被开头\"大白菜\"形象带走（误选 D）→ 抓\"最高/草本之王\"的表面之最（误选 B）→ 选空泛的\"生命奇迹\"（误选 C）。", "img": ""}]}]}, {"name": "推断下文", "star": false, "children": [{"name": "看尾句话题，下文承接尾句且不重复已述内容", "star": false}]}, {"name": "话题一致", "star": false, "children": [{"name": "所接内容须与文段核心话题一致，跑题即错", "star": false}]}]}]}, {"name": "语句表达", "star": false, "children": [{"name": "语句排序", "star": false, "children": [{"name": "首句判断", "star": false, "children": [{"name": "下定义/引话题/背景可作首句；含指代词、关联词、结论的不能作首句", "star": false, "examples": [{"q": "将以下句子重新排列，顺序最恰当的是（ ）。①中国倡导平等有序的世界多极化和普惠包容的经济全球化，这两大主张有着极强的现实针对性和战略指导性。②世界多极化是历史发展的大势，也是历史进步的方向。③这两大主张契合大多数国家和各国民众的普遍诉求，为国际社会从变乱交织走向长治久安指明了方向，为推动构建人类命运共同体注入源源不断的动力。④经济全球化是生产力发展的客观要求，也是人类社会前进的必由之路。⑤平等有序的世界多极化强调坚持大小国家一律平等，并确保多极化进程总体稳定和具有建设性，为推动构建更加公正合理的全球治理体系提供了重要路径。⑥普惠包容的经济全球化强调解决好资源全球配置造成的国家间和各国内部发展失衡问题，并支持各国走出符合自身国情的发展道路，携手推进全人类的共同发展。", "src": "2026广东省考真题 第30题", "hit": false, "ans": "D", "opts": ["A.①④⑥②③⑤", "B.①③②⑤④⑥", "C.①③⑤⑥②④", "D.①②⑤④⑥③"], "solve": "①总起\"两大主张\"后，**②⑤说多极化（总→分）、④⑥说全球化（总→分）**，③用代词\"这两大主张\"收束——四项里只有 D「① ②⑤ ④⑥ ③」能拼出完整的\"总—分—总\"。", "analysis": "**核心规律**：语句排序·**总分结构与代词指代链**：按\"定首句（①总起）→ 找捆绑（②→⑤、④→⑥话题一致，代词'这两大主张'回指①）→ 定尾句（③收束）→ 逐项排除\"四步，抓住\"**①的两大主张＝②⑤＋④⑥的分述提纲**\"这条主线。\n**易混·易错链**：① **尾句提前**：把总结句③放到开头（B、C）；② **捆绑错位**：把\"话题一致对\"②⑤、④⑥拆散并插入他句（A）；③ **序内断裂**：收束句③之后再接分述⑤，逻辑倒流（A）。", "img": ""}, {"q": "将以下句子重新排列，顺序最恰当的是（ ）。①近代以来，特别是新中国成立后，我国工业由小到大、由弱到强。②工业文化资源，既包括历史上人类工业活动产生的艺术品和手工艺品、遗址遗迹、文献出版物等，也包括工业化产生的各类人文资源。③这一波澜壮阔的发展历程，催生了实业报国等影响至今的思潮，形成了大量工业遗产，铸就了大庆精神、工匠精神等一批宝贵的精神财富。④回溯既往，从一系列遗址遗迹和古代典籍的记录中，可以窥见中国古代工业文化的一角。⑤如今，我们构建起门类齐全、世界上最完整的现代工业体系。⑥这些工业文化资源，是党团结带领全国各族人民开拓进取、不懈奋斗的生动写照，具有丰富的历史价值、文化价值和艺术价值。", "src": "2024广东省考真题 第30题", "hit": true, "ans": "C", "opts": ["A.①⑤③②④⑥", "B.①⑤④③②⑥", "C.②④①⑤③⑥", "D.②⑥④①⑤③"], "solve": "看首句——②\"工业文化资源，既包括…也包括…\"是**下定义句**、宜作首句（①\"近代以来\"须在④\"古代\"之后、不作首）→ 秒排 A、B；再凭\"④古代→①近代→⑤如今\"**时序**＋\"⑥'这些工业文化资源'总括置尾\"定序 → C。", "analysis": "- 体系定位：言语理解与表达 → 语句表达 → 语句排序（清单单元原名：首句判断、尾句判断、指代词定位）；体系位置：语句填空（补一句）→ **本题（多句重排）** → 下级变式（病句/歧义）\n- 识别信号：题干给带序号的多句、问\"重新排列顺序最恰当\" → 排序题；看到**下定义句/背景句**→ 优先试作首句；看到\"这/这些/其\"→ 该句**不能作首句**、须紧跟其指代对象\n- 本质：语句排序的内核＝\"**句与句的逻辑链（时序、总分、指代）**\"——先抓一条主链（本题为\"古代→近代→如今\"时序＋\"下定义→分述→总括\"），再让其余句对号入座\n- 通式：无固定式，按**首句→尾句→捆绑群**三步：①\"下定义/引话题可作首，含指代词/关联词/结论者不作首\"定首句 ②\"结论/总括/展望作尾\"定尾句 ③把**指代对**（\"这些…\"与其先行词）、**时间对**捆成小单元代入验证\n- 易混·易错链：最像\"语句填空\"——填空是**补一句**（看上下文话题），排序是**排多句**（看句间逻辑）；撞坑链：误把含时间的\"①近代以来\"当首句（忽略其前须有\"古代④\"），或把总括句\"⑥这些…价值\"提前（忽略\"这些\"须收敛到结尾）", "img": ""}, {"q": "①因为这些光场往往存在于真空腔等封闭环境中，探测器难以直接进入②激光光束常被用于操控物质的量子态③但在研究其中很多基础问题时，却长期难以直接观测④在量子技术中，对具有精细结构的光场进行精确控制至关重要⑤而通过透镜远距离观测，又容易因像差导致图像失真⑥例如在中性原子量子计算机中，由激光形成的微小光点阵列和光晶格结构在操控量子比特中起着核心作用将以上6个句子重新排列，语序正确的是：", "src": "26年省考35季 第24题", "hit": false, "ans": "B", "opts": ["A.②③①⑥④⑤", "B.④②⑥③①⑤", "C.②⑥④⑤③①", "D.④①②⑥③⑤"], "solve": "定首句——④\"在量子技术中…对光场精确控制至关重要\"是**引出话题的背景句**，优于只说\"激光\"的②，立排 A/C；再由⑥\"例如\"紧贴②（给激光举例）、③\"但\"转折带出①\"因为\"、⑤\"而…又\"续因 → 锁定==④②⑥③①⑤==。", "analysis": "- 体系定位：言语理解与表达 → 语句表达（语句排序）→ 首句判断（清单原名）；上位\"语句排序（首句/尾句/指代/关联/时序）\"→ 本题\"**首句判断＋指代关联定序**\"→ 下级变式\"尾句判断／时间逻辑顺序\"。\n- 识别信号：题干给出①②…⑥并问\"语序正确的是\"；句中含**指代词（这些/其中）、关联词（但/因为/而/例如）** → 先挑首句，再用指代与关联串链。\n- 本质：剥掉\"量子光场\"外壳，考的是**句间指代与逻辑链能否首尾接得住**——首句不能含无着落的指代/关联词，成对关联词须\"因在前、果在后\"。\n- 通式：`排首句（剔含指代/关联/结论者）→ 找指代对象定相邻 → 关联词配对定序（因为…／但…／例如…）→ 抽读验证顺承`；同类判别条件：**看到句首\"这些/其/例如/但/因为\"就先找它的前文挂靠点**。\n- 易混·易错链：最像\"时间/逻辑顺序\"——分界：**指代关联定序靠\"词眼挂钩\"**，时序靠**时间词或事理先后**。常见撞坑链：误把具体句②当首句（漏看④的总起身份）→ \"①因为这些光场\"前无指代对象就硬排 → 忽略\"⑥例如\"必须紧跟它所举例的②。", "img": ""}]}]}, {"name": "尾句判断", "star": false, "children": [{"name": "结论/总结/展望类易作尾句；含待解释内容的不作尾句", "star": false}]}, {"name": "指代词定位", "star": false, "children": [{"name": "指代词必有前文指代对象，其前必须有对应内容", "star": false}]}, {"name": "关联词配对", "star": false, "children": [{"name": "据关联词配对与逻辑定序（\"因此\"在\"因为\"后）", "star": false}]}, {"name": "时间/逻辑顺序", "star": false, "children": [{"name": "按时间先后或事理逻辑排；概括句在前、具体在后", "star": false}]}]}, {"name": "语句填空", "star": false, "children": [{"name": "话题一致填空", "star": false, "children": [{"name": "填入内容与文段核心话题一致", "star": false, "examples": [{"q": "服务群众，用“家常话”将政策解释清楚只是第一步，更需要读懂群众“家常话”背后的喜怒哀乐。“家常话”里，有群众的关切点，也有推动政策落地的发力点，在这里，“社会救助”不是抽象名词，而是张大爷的医药费有着落；“产业振兴”不只是报告里的概念，而是李大姐柑橘园里的累累硕果。______，服务群众才会更加精准、更有实效。填入上文画横线处的语句，最恰当的一句是（ ）。", "src": "2026广东省考真题 第22题", "hit": true, "ans": "A", "opts": ["A.找准大家的关切事", "B.将群众的需求装心里", "C.多下笨功夫、多啃硬骨头", "D.常进老乡门、常聊家里事"], "solve": "**A. 找准大家的关切事**", "analysis": "**识别信号**：横线在段中/段尾，前后有**\"才会……\"**等推导标志\n**核心规律**：填空须**既承上文关键词、又启下文结论**，跑题即错；打法：横线句 = 上文核心词 + 下文结论的**逻辑桥**；先列上文关键词再比对\n**易混·易错链**：话题一致填空 vs 承上启下（尾句多\"总结式\"、中句多\"过渡式\"）", "img": ""}, {"q": "人工智能时代，互联网文娱产业中的抄袭在未来将会进一步呈现复杂性、隐匿性、成本低的趋势。无论人工智能生成场景抑或是人利用人工智能辅助创作作品，我国法律现在倾向于对输入端较为宽松，积极探索以“合理使用”为核心的生成式人工智能输入著作权作品作为数据训练的合法性路径，但对输出端具有明显“实质性相似”的抄袭作品给予打击。这恰恰是在底线上，向社会明确传递了尊重鼓励原创、抵制抄袭的信号，代表了法律努力保护原创的决心。不过，困难和挑战依然存在，比如有人用大模型检查朱自清《背影》的人工智能率，得到了100%人工智能生成的荒谬结果。因此，      ______                ，将会变成一个更复杂、更艰巨的任务。填入画横线部分最恰当的一句是：", "src": "26年省考34季 第30题", "hit": true, "ans": "A", "opts": ["A.在人工智能时代保护原创", "B.在互联网行业全面落实著作权法", "C.提高公众对人工智能生成内容的辨别能力", "D.在法律层面精准界定“实质性相似”"], "solve": "横线作“任务”主语，全文主旨落在“保护原创”，四选项只有 A 主语=核心话题", "analysis": "体系定位：言语理解与表达 → 语句表达（语句填空）→ 话题一致填空；体系位置＝上位「语句表达（语句填空）」→ 本题「横线在句尾、作主/宾语时，考话题一致」→ 下级变式「承上启下（横线在段中，需两头兼顾）」。\n识别信号：题干出现\"填入画横线部分最恰当的一句\"＋一处横线 → 先判**横线位置**：在段尾且作主/宾语 → 直接查「话题一致」；在段中 → 先查「承上启下」。看到\"因此/所以\"→ 横线多半承接结论，主语须落在文段主旨词上。\n本质：剥掉\"AI＝法律＝《背影》\"这层外壳，内核只有一句话——**横线内容必须与文段核心话题（保护原创）保持一致**；考的是\"话题跑没跑题\"，不是\"这句话本身对不对\"（判分点：填入内容与文段核心话题一致）。\n通式：`横线句 = 保持核心话题（对象＋动作方向）一致`；检验式＝\"把选项的主语拎出来，看它是否等于文段反复出现/主旨句点名的那个词\"，不等即划掉。\n易混·易错链：最像的考点是「承上启下」——若横线在句**中间**必须既接上文又启下文，而本题横线在句尾、后接\"将会变成……任务\"，只需话题一致、不必启下，据此二者分界；常见撞坑链：被紧邻的\"实质性相似/著作权法\"局部名词带跑 → 误选 D/B。", "img": ""}, {"q": "______。一方面，破除照本宣科的传统宣讲模式，适配短视频、图文推文、直播科普等新媒体传播形态，转换话语体系，把晦涩的法律条文和安全规范，转化为通俗易懂的网言网语、贴近生活的场景案例。另一方面，聚焦群众高频关切，瞄准反诈防骗、消防安全、邻里纠纷、未成年人保护等民生热点，打造轻量化、生活化的普法内容，让群众在碎片化浏览中学法懂法。同时，兼顾传播温度与权威性，依托主流媒体、政务新媒体平台联动发声，及时澄清网络谣言、纠正片面解读，在解疑与释惑中增进群众认同，凝聚共识，让正能量充盈网络空间。填入画横线部分最恰当的一项是：", "src": "26年省考35季 第21题", "hit": false, "ans": "C", "opts": ["A.善用传播载体，持续拓宽法治宣传的覆盖面", "B.立足民生关切，使普法内容贴近生活实际", "C.调整传播形式与内容，让法治宣传接地气、入人心", "D.综合运用多种传播渠道，让法治传播掷地有声"], "solve": "横线在**段首总起**，下文用\"一方面（形式）…另一方面（内容）…\"两项并列 → 总括句须**同时覆盖形式与内容**，唯==调整传播形式与内容，让法治宣传接地气、入人心==兼收两面。", "analysis": "- 体系定位：言语理解与表达 → 语句表达（语句填空）→ 话题一致填空（清单原名）；上位\"语句填空（话题一致／承上启下）\"→ 本题\"**段首总起·话题一致**\"→ 下级变式\"承上启下（中间横线）\"。\n- 识别信号：横线位于**段首**，后接冒号或\"**一方面…另一方面…**\"\"同时…\"等**并列分述** → 该空必是**总括句**，须覆盖全部并列项。\n- 本质：剥掉\"普法宣传\"外壳，考的是**总括句的外延是否等于下文各分述项的并集**——多一项尚可，少一项（漏并列项）必错。\n- 通式：`判空位（段首/段中/段尾）→ 数下文并列项 → 求各分述的并集 → 选项外延＝并集才选`；同类判别条件：**看到\"一方面…另一方面…\"就选同时涵盖两面的选项**。\n- 易混·易错链：最像\"承上启下\"——分界：**段首总起只覆盖下文**，承上启下**上下两头都要顾**。常见撞坑链：只抓\"一方面\"的形式项（误选 A/D）→ 只抓\"另一方面\"的内容项（误选 B）→ 忘记\"并列必全\"而漏项。", "img": ""}, {"q": "“____________”。近年来，一大批有知识、有抱负的青年人选择扎根乡土，他们有的深耕现代农业，用科技手段让传统种植养殖提质增效；有的投身乡村文旅，把绿水青山、古村老宅变成增收致富的“金山银山”；有的扎根基层治理，在走村入户、排忧解难中成为乡亲们的贴心人。他们不惧条件艰苦，不怕道路曲折，在日复一日的坚守中把时光沉淀在耕耘中，把青春安放在田野间，让乡村焕发出前所未有的生机与活力。填入画横线部分最恰当的一项是：", "src": "26年省考35季 第30题", "hit": false, "ans": "B", "opts": ["A.纸上得来终觉浅，绝知此事要躬行", "B.千淘万漉虽辛苦，吹尽狂沙始到金", "C.问渠那得清如许？为有源头活水来", "D.少年辛苦终身事，莫向光阴惰寸功"], "solve": "横线在段首作引句，后文\"不惧条件艰苦，不怕道路曲折…在坚守中…焕发生机\"＝**历经艰辛终有所成** → 只有==千淘万漉虽辛苦，吹尽狂沙始到金==同时含\"辛苦磨砺→终得真金\"两意。", "analysis": "- 体系定位：言语理解与表达 → 语句表达（语句填空）→ 话题一致填空（清单原名）；上位\"语句填空（话题一致／承上启下）\"→ 本题\"**段首引句·话题一致**\"→ 下级变式\"承上启下（中间横线）\"。\n- 识别信号：横线在**段首作引语（常为诗句/名言）**，后接\"近年来…\"式解释 → 引句义须**等于后文内核**，即\"过程＋结果\"是否都对得上。\n- 本质：剥掉\"青年扎根乡村\"外壳，考的是**引句与文段内核同义**——须拆出引句的\"过程义\"与\"结果义\"，逐项与文段对照。\n- 通式：`定空位（段首引句）→ 提炼后文内核（过程＋结果）→ 拆解各诗句义项 → 两头齐备者选`；同类判别条件：**看到段首一句诗＋后文铺陈，就先问\"这诗讲过程还是结果，文段要的是哪个\"**。\n- 易混·易错链：最像\"承上启下\"——分界：**段首引句只领起下文**，承上启下**上下都要接**。常见撞坑链：误把\"躬行（实践）\"\"活水（学习）\"当主题 → 只抓\"辛苦\"却忽略\"始到金\"的结果义 → 被 D\"少年努力\"的表面\"辛苦\"迷惑。", "img": ""}]}]}, {"name": "承上启下", "star": false, "children": [{"name": "该句须既接上文又启下文，两头都兼顾", "star": false, "examples": [{"q": "在中华文明滋养的神州大地上，______。袁隆平院士一生扎根稻田，用“粒粒皆辛苦”的执着培育出杂交水稻；“时代楷模”张玉滚坚守深山小学二十余载，以“桃李不言”的奉献点亮山村孩子的未来；“大国工匠”高凤林焊接火箭发动机，用“毫厘不差”的精准诠释工匠精神；“人民楷模”王继才32年坚守开山岛，用“孤岛不孤”的信念诠释守岛人的担当······一位位先进典型、一次次精神洗礼，不断激发全社会的思想认同、情感共鸣和效仿意愿，营造出崇德向善、见贤思齐、德行天下的浓厚氛围。据材料内容，填入横线处最合适的句子是（ ）。", "src": "2026广东省考真题 第28题", "hit": false, "ans": "A", "opts": ["A.处处可见光彩绽放的职业道德之花", "B.职业道德建设开创新局面、展现新气象", "C.“敬事而信”“鞠躬尽瘁”的敬业精神代代相传", "D.每个行业都践行着用心钻研、追求极致的工匠精神"], "solve": "横线在**段首＝总起句**，须概括下文**四个不同行业的先进典型**并呼应尾句\"**崇德向善**\"——只有 A「处处可见…**职业道德**之花」能统领全篇。", "analysis": "**核心规律**：语句填空·**段首总起句**：按\"位置定功能（总起）→ 概括下文共性（各行业敬业奉献）→ 核对主体范围与概括度\"三步，选能统领全段、**不外扩也不缩小**的句子。\n**易混·易错链**：① **范畴过大**：把\"职业道德\"上升为\"职业道德建设…开创新局面\"（B）；② **片面缩小**：只扣单例或单一精神（D\"工匠精神\"）；③ **无中生有/脱节**：强加\"代代相传\"等文中不存在的语义（C）。", "img": ""}, {"q": "构建高质量充电基础设施体系，首要在于______，更好满足不同领域、不同场景充电需求。城际之间应打造有效满足新能源汽车中长途出行需求的城际充电设施系统。农村地区应确保充电基础设施在适宜使用新能源汽车的区域有效覆盖。部分城市中心城区公共充电基础设施服务半径已与加油站相当，但城市周边、热门公园景区等依然需要加强建设力度。以下句子填入画横线处，最恰当的是：", "src": "2024广东省考真题 第28题", "hit": true, "ans": "D", "opts": ["A.加强技术研发攻关", "B.全面扩大覆盖区域", "C.增加充电设施数量", "D.优化完善网络布局"], "solve": "看后文——\"城际打造设施系统、农村确保覆盖、城区已够、城市周边需加强\"，四句全在讲**各区域怎么摆设施**，即**网络布局**；只有\"优化完善网络布局\"能**总领下文**。", "analysis": "- 体系定位：言语理解与表达 → 语句表达 → 语句填空（清单单元原名：承上启下、话题一致填空）；体系位置：语句排序（炼首尾句）→ **本题（段首总起句·承上启下）** → 下级变式（话题一致型填空）\n- 识别信号：横线后紧跟**分述/并列举例**（如\"城际…；农村…；城区…\"）→ 判为**总起句·承上启下**；看到\"首要在于/总的说\"＋后文并列分述 → 答案必是**能总领下文的高概括度句**\n- 本质：语句填空的内核＝\"填入句与上下文**话题一致、概括度匹配**\"——总起句要能**罩住下文所有分述**，分述句只能对应其一\n- 通式：无固定式，按**先定位置→再定功能**：①横线在总起→选**能概括全部下文**的项（覆盖面最广又不跑题）②横线在中间→\"承上＋启下\"两顾 ③用\"总括度/话题\"逐项淘汰\n- 易混·易错链：最像\"话题一致填空\"——总起句看**总括度（能否罩住全下文）**，中间句看**承上启下两头**；撞坑链：被\"A技术\"\"C数量\"这类**局部词**吸引（下文边缘提到\"建设\"），忽略全文核心是\"区域布局\"", "img": ""}]}]}]}, {"name": "病句 / 歧义", "star": false, "children": [{"name": "搭配不当", "star": false, "children": [{"name": "查动宾/主宾/修饰语与中心语是否搭配", "star": false}]}, {"name": "成分残缺", "star": false, "children": [{"name": "查是否缺主语/宾语/中心语（滥用介词易致缺主语）", "star": false}]}, {"name": "结构混乱", "star": false, "children": [{"name": "查句式杂糅（两套句式套叠）、中途易辙", "star": false}]}, {"name": "不合逻辑", "star": false, "children": [{"name": "查自相矛盾、两面对一面、否定不当（多重否定算清层数）", "star": false}]}, {"name": "语义重复", "star": false, "children": [{"name": "查句中近义成分赘余（\"大约…左右\"）", "star": false}]}, {"name": "歧义句", "star": false, "children": [{"name": "查指代不明/一词多义/停顿不同是否可作两种解释", "star": false}]}]}]}]}, "资料分析": {"color": "indigo", "modules": {"增长": "indigo", "比重": "emerald", "平均数与倍数": "fuchsia", "百分点与结构": "amber", "其他综合": "sky"}, "root": {"name": "资料分析", "signal": "先读问题找数据 → 列式速算 → 估算排选项；增速/比重/平均数三大件"}, "branches": [{"name": "增长", "star": false, "children": [{"name": "增长量", "star": false, "children": [{"name": "增长量：Δ=现期−基期=基期×r=现期×r/(1+r)", "star": false, "examples": [{"q": "2024年中国炭素行业会员企业工业总产值约比去年减少：", "src": "26年省考34季 第76题", "hit": true, "ans": "A", "opts": ["A.64亿元", "B.46亿元", "C.64万元", "D.46万元"], "solve": "先卡**单位量级**——总量是**亿元**级，C、D 的「万元」当场出局；再比「现期−基期」取负，首数为 **6**，==A（64亿元）==。", "analysis": "- 体系定位：资料分析 → 增长 → 单元**「增长·增长量」**；上位＝增长主概念（量/率/基期现期），本题＝**同比减少量（负增长量）**，下级变式＝「增长·减少率/降幅」（问百分点而非金额）。\n- 识别信号：题干出现**「比…减少/增加多少（亿元）」**→ 增长量；带**「约」**→ 提示可用截位估算；选项出现**同数不同单位（亿/万）**→ 先卡量级。\n- 本质：内核即「**两期同指标相减求差**」，与增长率无关；判分点＝选对基期、现期并做对减法符号。\n- 通式：`减少量 = 基期 − 现期`；等价 `Δ = 现期 − 基期`（负）；速算用 `减少量 ≈ 现期 × r/(1−r)`（已知降幅 r 时）。\n- 易混·易错链：最像「增长·减少率/降幅」（问「降了百分之几」=百分点，是率不是金额）；撞坑链：①量级误判（亿↔万）→ ②基期现期颠倒 → ③相邻行取错指标。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/zl/1-9823739d0a.png"}]}, {"name": "增长量速算：r≈1/n 时，Δ≈现期/(n+1)（减少用现期/(n−1)）", "star": false, "examples": [{"q": "2025年1-6月，北京市接待外国入境游客量同比增量约是中国香港的多少倍？", "src": "26年省考35季 第73题", "hit": false, "ans": "A", "opts": ["A.18", "B.14", "C.12", "D.8"], "solve": "两个增速都接近单位分数（51.2%≈**1/2**、19.7%≈**1/5**），用 Δ≈现期/(n+1) 得外国≈**68万**、香港≈**3.9万**，68÷3.9≈**17.5**→**18**。", "analysis": "- 体系定位：资料分析 → 增长 → 增长量（清单原名「增长量」）｜上位：同比增长量计算 → 本题：两量增量倍比 → 下级变式：增量为负、多几倍、增量占比\n- 识别信号：看到「同比增量…是…的多少倍」→ 先各算增量再相除；看到 r 接近 1/n → 立刻用 现期/(n+1) 速算\n- 本质：考「增长量速算＋量级估算」，用单位分数把除法变成心算，不追求精确值（判分点＝能定性选出量级）\n- 通式：`Δ≈现期/(n+1)`（r≈1/n，减少用 /(n−1)）；倍数 `≈[现期₁/(n₁+1)]÷[现期₂/(n₂+1)]`；同类判别条件：看到「增量是…的几倍」就套此式\n- 易混·易错链：与「增长率比较」混（比增量看 Δ 绝对值、比增速看 Δ/基期）；撞坑链：1-6 月/6 月列看反 → 增量取错 → 比值翻车", "img": "data:image/png;base64,"}, {"q": "若保持2024年同比增量不变，则到哪一年广东包装专用设备产量将首次超过200万台？", "src": "26年省考35季 第78题", "hit": false, "ans": "D", "opts": ["A.2027", "B.2026", "C.2029", "D.2028"], "solve": "广东 2024 增量 `≈748133×75.4%/175.4%`≈**32.2 万**，保持该增量，`(200−74.8)/32.2`≈3.9→需 **4 年**，即 **2028** 年首破 200 万。", "analysis": "- 体系定位：资料分析 → 增长 → 增长量（清单原名「增长量」）｜上位：同比增长量 → 本题：恒定增量外推年份 → 下级变式：保持增速外推、反求达标年份/达标增量\n- 识别信号：看到「保持（同比）增量不变，到哪年首次超过/达到 X」→ 恒定增量外推 `现期+Δ×n≥目标`\n- 本质：考「恒定增量累加的年数推算」——先算步长 Δ，再用 (目标−现期)/Δ 定年数（判分点＝年数向上取整 + 首破判断）\n- 通式：`n=⌈(目标−现期)/Δ⌉`，`Δ≈现期×r/(1+r)`；同类判别条件：看到\"保持增量不变…哪年超 X\"就套此式\n- 易混·易错链：与「保持增速不变」混——增量是等差累加(+Δ)、增速是等比(×1+r)，年份结果不同；撞坑链：年数取 n 还是 n+1、区间取错", "img": "data:image/png;base64,"}]}, {"name": "年均增长量：年均增长量=(末期−初期)/间隔年数（注意是否含首年）", "star": false}, {"name": "日均换算增长量：总量=日均量×当月天数（各月天数不同），Δ=本期日均×本天数−上期日均×上天数", "star": false}]}, {"name": "增长率", "star": false, "children": [{"name": "增长率（主式）：r=增长量/基期=(现期−基期)/基期=现期/基期−1", "star": false, "examples": [{"q": "2024年，全国集中养育孤儿基本生活保障平均标准同比增速比社会散居孤儿：", "src": "26年省考34季 第87题", "hit": false, "ans": "C", "opts": ["A.高不到1个百分点", "B.高1个百分点以上", "C.低不到1个百分点", "D.低1个百分点以上"], "solve": "选项全是「高/低不到1个百分点」→ 只判**两增速差的正负＋是否≥1个百分点**，估到0.1就可停 → ==C（低不到1个百分点）==。", "analysis": "- 体系定位：资料分析 → 增长 → 单元**「增长·增长率比较」**；上位＝增长主概念（率/量），本题＝**两指标增速作差判「高/低几个百分点」**，下级变式＝「比重·升降判断」（比的是两部分增速大小）。\n- 识别信号：题干出现**「增速比…高/低几个百分点」**→ 两增速作差；选项给**「不到/以上1个百分点」区间**→ 只估量级，不必精算。\n- 本质：内核＝「**两个率相减，先判正负再判量级**」，考的是增速口径与「百分点」表述（是率差不是倍数）。\n- 通式：`r = (现期−基期)/基期`；`差值 = r₁ − r₂`（正=高，负=低；「个百分点」=两率直接相减的差）。\n- 易混·易错链：最像「增长·间隔增长率」（两期叠加，用 r=r₁+r₂+r₁r₂）——本题是**横向两对象比较**，不是纵向跨期；撞坑链：①主客颠倒 → ②用增长量差代替增速差 → ③把「个百分点」当「%」。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/zl/2-eb0161a407.png"}, {"q": "材料：2021年，各地区各部门全面落实党中央、国务院关于实现数字乡村发展战略的决策部署，积极引入社会资本投资建数字乡村。2021年全国用于县域农业农村信息化建设的社会资本投入为954.6亿元，县均社会资本投入3588.8万元、乡村人均社会资本投入135.2元，分别比上年增长17.2%和24.0%。分区域看，东部地区社会资本投入562.4亿元，占全国社会资本投入58.9%；中部地区社会资本投入193.8亿元；西部地区社会资本投入198.4亿元。问：2019-2021年，全国县域农业农村信息化建设县均社会资本投入的年均增率约为（ ）。", "src": "2024广东省考真题 第86题", "hit": true, "ans": "C", "opts": ["A.10%", "B.21%", "C.32%", "D.43%"], "solve": "2019→2021 间隔 **n=2**，年均增长率 r 满足 `(1+r)²=末期/初期`；把四选项的 (1+r)² 估出（1.21 / 1.46 / 1.74 / 2.04），与表中「2021÷2019」比量级，只有 ≈**1.74** 对上 **32%**。", "analysis": "- 体系定位：资料分析 → **增长·年均增长率**（清单原名）；上位＝增长 → 本题（年均增长率）→ 变式＝年均增长量、间隔增长率。\n- 识别信号：问「n 年间平均每年增长百分之几 / 年均增速」⇒ 年均增长率；**先数间隔年数 n**。\n- 本质：内核＝把「总倍数」开 n 次方还原成每年的复利增速，即 `(1+r)ⁿ=末期/初期`。\n- 通式：`r=(末期/初期)^(1/n)−1`；实操多用**选项代入**比 (1+r)ⁿ 与 末期/初期 的量级/首数；n＝年份相减（2019→2021 取 2）。\n- 易混·易错链：最像「年均增长量」，分界看问的是**百分比**（`(1+r)ⁿ`）还是**绝对量**（`(末−初)/n`）；撞坑链＝n 多算一年 → 结果偏小选错。", "img": ""}, {"q": "2026年广东省荔枝总产量预计同比下降约：", "src": "26年省考35季 第84题", "hit": true, "ans": "B", "opts": ["A.17.5%", "B.22.8%", "C.27.3%", "D.32.4%"], "solve": "`(168.3−130)/168.3=38.3/168.3`≈**22.8%**（或 `1−130/168.3=1−0.772`）。", "analysis": "- 体系定位：资料分析 → 增长 → 增长率（清单原名「增长率」）｜上位：增长率主式 → 本题：同比减少率 → 下级变式：间隔增长率、年均增长率、降幅比较\n- 识别信号：看到「同比（下降/增长）约百分之几」→ `r=(现期−基期)/基期`，先认明基期是哪年\n- 本质：考「增长率主式的基期认定」——2025 为基期、2026 为现期，方向决定正负（判分点＝分母取对）\n- 通式：`r=(现期−基期)/基期=现期/基期−1`；减少率取绝对值即降幅；同类判别条件：看到\"同比下降约\"就套 主式再取负\n- 易混·易错链：与「减少量」混（减少量是差值 38.3 万吨，减少率才是 %）；撞坑链：分子分母对调、把现期当基期", "img": "data:image/jpeg;base64,"}]}, {"name": "增长率（已知增长量）：r=Δ/基期，或 r=Δ/(现期−Δ)", "star": false}, {"name": "减少率/降幅：下降 r% 与降幅 r% 数值相同、符号相反；降幅=|r|", "star": false}, {"name": "增长率比较：基期不同不能比增长量，比 Δ/基期 或 现期/基期", "star": false}, {"name": "间隔增长率：r=r₁+r₂+r₁r₂；当 r₁、r₂ 均小（乘积<10%）可忽略末项", "star": false}, {"name": "年均增长率：(1+r)ⁿ=末期/初期，估算 r≈(末/初)^(1/n)−1", "star": false}, {"name": "混合增长率：整体增速介于两部分增速之间，且偏向基期量大的一方（线段法/十字交叉）", "star": false}, {"name": "乘积增长率：rA=rB+rC+rB×rC", "star": false}, {"name": "环比增速：r=(本期−上期)/上期；环比=与上一期比、同比=与去年同期比（勿混）；负增速带符号代入", "star": false}]}, {"name": "基期与现期", "star": false, "children": [{"name": "基期量：基期=现期/(1+r)；r 为负时分母<1，结果大于现期；跨两期且中间期缺柱值时连除：初期=末期÷[(1+r₁)(1+r₂)]", "star": false, "examples": [{"q": "若保持2025年同比增量不变，则中国游戏市场实际销售收入首次超过5000亿元的年份是：", "src": "26年省考34季 第83题", "hit": false, "ans": "C", "opts": ["A.2029年", "B.2030年", "C.2031年", "D.2032年"], "solve": "先求**2025同比增量 Δ**，再看缺口 `5000 − 2025值` 需几个 Δ，**上取整**后加2025 → ==C（2031年）==。", "analysis": "- 体系定位：资料分析 → 增长 → 单元**「增长·现期量」**（预测未来期）；上位＝增长主概念，本题＝**按固定增量外推求「跨越阈值年份」**，下级变式＝按固定**增速**预测（末=基×(1+r)ⁿ）。\n- 识别信号：题干出现**「保持…增量不变」「首次超过/达到X」**→ 固定增量外推＋取整；出现**「按年均增长率」**→ 换成 (1+r)ⁿ 模型，走法不同。\n- 本质：内核＝「**用固定步长填缺口，再定位年份**」，考的是「增量不变」的口径识别与**取整方向**。\n- 通式：`N = ⌈(阈值 − 现期值) ÷ 年增量⌉`；`年份 = 现期年 + N`；若给的是增速则 `N = ⌈ln(阈值/现期)/ln(1+r)⌉`。\n- 易混·易错链：最像「增长·年均增长量」——后者只求**平均每年增多少**（不定位年份）；撞坑链：①增量口径按增速误算 → ②缺口方向取反 → ③「超过」未向上取整。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/zl/3-a2781b48b5.png"}, {"q": "材料：2021年，各地区各部门全面落实党中央、国务院关于实现数字乡村发展战略的决策部署，积极引入社会资本投资建数字乡村。2021年全国用于县域农业农村信息化建设的社会资本投入为954.6亿元，县均社会资本投入3588.8万元、乡村人均社会资本投入135.2元，分别比上年增长17.2%和24.0%。分区域看，东部地区社会资本投入562.4亿元，占全国社会资本投入58.9%；中部地区社会资本投入193.8亿元；西部地区社会资本投入198.4亿元。问：2020年，全国用于县域农业农村信息化建设的社会资本投入（ ）（假设2020年县的数量与2021年相同）。", "src": "2024广东省考真题 第87题", "hit": false, "ans": "B", "opts": ["A.不到800亿元", "B.在800亿元到850亿元之间", "C.在850亿元到900亿元之间", "D.超过900亿元"], "solve": "题设**2020县数＝2021**，故全国总投入增速＝县均增速 **17.2%** → 2020总＝`954.6/(1+17.2%)`≈**814亿** → ==B==", "analysis": "- **体系定位**：资料分析 → 增长（清单原名 **「增长·基期量」**）｜ 体系位置：上位「增长·现期量」→ 本题「**基期量（已知现期与增速，反求上一期）**」→ 下级变式「隔期基期、由年均增长率反求初期」\n- **识别信号**：问「**更早某年**的某量是多少」，材料给的是**更晚年份值 + 同比增速** → 调**基期量**；选项全区间 → 估量级即够\n- **本质**：把同比关系**倒推一年**——内核是「现期 =(1+r)×基期」的**逆运算**，r>0 时基期必**小于**现期（除大于1的数会变小）\n- **通式**：`基期 = 现期 ÷ (1+r)`；本题用「**分母量不变 → 比值(县均/人均)的增速＝分子(总量)的增速**」把总量问题转成县均增速问题\n- **易混·易错链**：最像「增长·现期量」——**往前乘(现期)、往回除(基期)**，先认时间方向；常见撞坑：①把 `954.6×(1+17.2%)` 乘反，得≈1119亿而误选 D，②无视「县数不变」去另找数据", "img": ""}, {"q": "2025年9月，中国出口各类镁产品总量较2024年10月约增长：", "src": "26年省考35季 第86题", "hit": false, "ans": "A", "opts": ["A.2.2%", "B.1.1%", "C.-1.1%", "D.-2.2%"], "solve": "9 月=`2.97/(1−31.6%)`=`2.97/0.684`、2024 年 10 月=`2.97/(1−30.1%)`=`2.97/0.699`；增长=`0.699/0.684−1`≈**2.2%**。", "analysis": "- 体系定位：资料分析 → 增长 → 基期与现期（清单原名「基期量」）｜上位：基期=现期/(1+r) → 本题：两个基期口径互比 → 下级变式：跨两期连除、负增速分母 <1\n- 识别信号：看到「某期较（非同基的另一期）增长」且两期都要靠增速回推 → 先各求基期再作比；负增速先记「分母 = 1+r < 1，基期 > 现期」\n- 本质：考「基期量还原＋两基期互比」——负增速把分母变成 (1−r)，两个基期同以现期为分子，公共因子可约掉（判分点＝分母取对、符号取对）\n- 通式：`基期=现期/(1+r)`；比值 `=(1+r₂)/(1+r₁)−1`（r 带符号）；同类判别条件：看到\"较（另一基期）增长\"就套此式\n- 易混·易错链：与「环比增速」混（环比直接 `本期/上期−1` 即可用增速；本题两基期不同期须先还原）；撞坑链：负增速分母误写成 (1+r)>1 使基期<现期、分子分母对调", "img": "data:image/jpeg;base64,"}]}, {"name": "现期量：现期=基期×(1+r)；n 年后=现期×(1+r)ⁿ（保持增长率）", "star": false}]}, {"name": "其他", "star": false, "children": [{"name": "指数：指数/100=相对基期的倍数，增长率=指数/100−1", "star": false}, {"name": "累计求当期：当期值=本期累计−上期累计", "star": false}, {"name": "翻番：翻 n 番=2ⁿ 倍，即末期/初期=2ⁿ", "star": false}]}]}, {"name": "比重", "star": false, "children": [{"name": "现期比重", "star": false, "children": [{"name": "比重=部分量/整体量", "star": false, "examples": [{"q": "材料：2025年3至7月，广东“粤就业”小程序累计组织2.1万家重点企业发布62.5万个岗位，其中年薪10万元以上岗位约26万个、20万元以上超6.5万个、50万元以上超5000个。问：2025年3至7月“粤就业”小程序发布的62.5万个岗位中，年薪10万元以上岗位占比（　　）。", "src": "2026广东省考真题 第73题", "hit": false, "ans": "D", "opts": ["A.在1成到2成之间", "B.在2成到3成之间", "C.在3成到4成之间", "D.在4成到5成之间"], "solve": "选项全是粗区间 → 找锚点：62.5×0.4=**25**，26>25 且 26<半数31.25 → 落 ==4~5成==。", "analysis": "**识别信号**：问「…占比 / 比重 / 占…的百分之几」；选项全是粗成数区间（1成~2成…）；材料塞一堆无关数字。\n**核心规律**：比重＝部分量÷整体量（判分点并入）；核心动作是**先锁定分子（部分）与分母（整体）两个数、屏蔽其余噪音**，再用区间锚点比大小定归属，不需精算。打法：比重＝部分÷整体；**区间型选项 → 锚点法**——先算几成/半数等锚点（62.5×0.4=**25**、62.5×0.5=**31.25**），把分子卡进边界定区间，能不算就不算。\n**易混·易错链**：最像＝**基期比重**（才需按增速 a、b 修正，问「去年占比」才是）；怎么分：给现期数据直接除＝现期比重，出现「同比/去年」才升级。撞坑链：见选项全是粗区间仍去精算/乱括号；把材料里「其中」的其余数字也拉进来乱除；成数换算错（26 与 25、31.25 的区间）。", "img": ""}, {"q": "2024年，表中所列包装专用设备产量排名前5的省市，其产量之和占全国产量的比重约为：", "src": "26年省考35季 第76题", "hit": false, "ans": "B", "opts": ["A.90.2%", "B.93.4%", "C.96.3%", "D.99.1%"], "solve": "取 1-12 月产量前 5 名（广东748133、广西626488、浙江62321、江苏47626、上海39455），和 ≈**152.4 万**，÷全国 163.25 万 ≈**93.4%**；或看反面 1−10.85万/163.25万≈93.4%。", "analysis": "- 体系定位：资料分析 → 比重 → 现期比重（清单原名「现期比重」）｜上位：现期比重=部分/整体 → 本题：多部分之和占比 → 下级变式：单部分占比、占比比较、由占比反求\n- 识别信号：看到「…之和占…的比重」→ 先排序定项、再求和，最后 部分和/整体\n- 本质：考「多项部分和的现期比重」——核心是取数完整（排序不漏不多），不是精算（判分点＝口径对、项数全）\n- 通式：`比重=(Σ部分量)/整体量`；同类判别条件：看到\"前 n 名之和占…比重\"就套此式，可用反面 `1−其他/整体` 交叉校验\n- 易混·易错链：与「比重比较」混（比大小直接看分子，不必算百分数）；撞坑链：漏取/多取一项、把\"表内合计\"当\"全国\"", "img": "data:image/png;base64,"}]}]}, {"name": "基期比重", "star": false, "children": [{"name": "基期比重=[A/(1+a)]÷[B/(1+b)]=A/B×(1+b)/(1+a)", "star": false}]}, {"name": "两期比重差", "star": false, "children": [{"name": "差值=A/B×(a−b)/(1+a)；a>b 上升；|差值|<|a−b|", "star": false, "examples": [{"q": "材料：2022年，全球对外直接投资流量1.5万亿美元，比上年下降14%。其中发达经济体对外直接投资1.03万亿美元，比上年下降17.2%；发展中经济体对外直接投资4589亿美元，比上年下降5.4%。2022年，中国对外直接投资流量1631.2亿美元，与上年历史次高值相比，下降8.8%，占全球份额的10.9%。问：与2021年相比，2022年中国对外直接投资流量在全球中的占比（ ）。", "src": "2024广东省考真题 第77题", "hit": false, "ans": "A", "opts": ["A.增加了不到3个百分点", "B.增加了超过3个百分点", "C.减少了不到3个百分点", "D.减少了超过3个百分点"], "solve": "中国降 **8.8%**、全球降 **14%** → 中国降得慢 → 占比**上升**（排除减少项）；增幅≈10.9%×5.2/91.2≈**0.6个百分点** < 3 → ==A==", "analysis": "- **体系定位**：资料分析 → 比重（清单原名 **「比重·两期比重差」**）｜ 体系位置：上位「现期比重 / 基期比重」→ 本题「**两期比重差（占比变化几个百分点）**」→ 下级变式「升降判断（只判方向、不判幅度）」\n- **识别信号**：题干问「占比/比重 **与去年相比** 升/降 **几个百分点**」→ 立即调**两期比重差**；选项是「增/减 × 不到/超过 N 个百分点」→ **先判方向、再估幅度**，别一头扎进精算\n- **本质**：靠**比较部分增速 a 与整体增速 b** 定占比升降——内核是「部分与整体谁跑得快」的较量：`a>b 升、a<b 降`；幅度 = 现期比重×(a−b)/(1+a)，且 `|幅度| < |a−b|`\n- **通式**：`占比变化 = 现期比重 × (a−b)/(1+a)`（a=部分增速、b=整体增速）；定性口诀「**部分跑赢整体 → 占比升**」，用降幅比较时「谁降得慢谁占比升」\n- **易混·易错链**：最像「比重·基期比重」——问「占比**变化几个百分点/升还是降**」用**两期比重差**，问「**去年**占比是多少」用**基期比重**；常见撞坑：①只判方向忘了估幅度（误选 B「超过3」），②把 `−8.8%` 与 `−14%` 大小比反（降幅小＝降得慢＝占比**升**）", "img": ""}, {"q": "2024年12月，山东包装专用设备产量占全年的比重较上年同期：", "src": "26年省考35季 第77题", "hit": false, "ans": "A", "opts": ["A.下降了不到1个百分点", "B.下降了1个百分点以上", "C.上升了不到1个百分点", "D.上升了1个百分点以上"], "solve": "12 月增速 **21.8%**＜全年增速 **32.0%** → 占比下降；差幅 `≈A/B×(a−b)/(1+a)=10.2%×(−10.2)/121.8`≈**−0.86 个百分点**，降幅不到 1。", "analysis": "- 体系定位：资料分析 → 比重 → 两期比重差（清单原名「两期比重差」）｜上位：现期比重 → 本题：同一子项跨期占比变化 → 下级变式：升降判断、差值定量、多数比重差比较\n- 识别信号：看到「某部分占整体的比重较上年同期上升/下降几个百分点」→ 两期比重差；先比 a、b 定方向，再算幅度\n- 本质：考「部分与整体增速相对大小决定的占比变化」——先定性方向、再定量幅度（判分点＝方向与幅度都对）\n- 通式：`差幅=A/B×(a−b)/(1+a)`；方向 `a>b` 升、`a<b` 降；幅度 `|差幅|<|a−b|`；同类判别条件：看到\"占比较上年升/降…百分点\"就套此式\n- 易混·易错链：与「平均数增长率 (a−b)/(1+b)」混——比重差用 ÷(1+a) 且结果为\"百分点\"，平均数增长率是\"%\"", "img": "data:image/png;base64,"}]}]}, {"name": "升降判断", "star": false, "children": [{"name": "比较部分增速 a 与整体增速 b：a>b 上升，a<b 下降", "star": false}]}, {"name": "由比重反求量", "star": false, "children": [{"name": "部分=整体×比重；整体=部分/比重", "star": false, "examples": [{"q": "材料：党的二十大报告强调，教育、科技、人才是全面建设社会主义现代化国家的基础性、战略性支撑。近年来，广东紧紧围绕制造业当家、聚焦高质量发展，大力实施制造业当家技能人才支撑工程，加快建设一支规模宏大的知识型、技能型、创新型技能人才队伍。2023年，全省技能人才总量达1934万人，其中高技能人才657万人。为推动广东技工与广东制造共同成长，近年来，广东紧紧围绕壮大20个战略性产业集群，紧密对接产业升级和技术变革趋势，开展新产业工人职业技能提升工程，培育掌握新技术的产业新工匠。广东充分发挥经济大省、制造业大省的优势，将产教融合、校企合作融入技能人才培养全过程，打造了全国最大的技工教育体系。2023年，广东共有技工院校148所，实现21个地级以上市技师学院全覆盖；在校生65万人，占全国的七分之一；面向先进制造业、战略性新兴产业、现代服务业建设233个省级重点专业和50个特色专业；与100多家世界500强企业及国内800多家大型企业开展深度合作，实现教学与企业岗位无缝对接，精准培养产业急需人才。技工院校招生人数、教研成果、技能竞赛、就业率等九项主要指标均居全国第一。问：2023年，全国技工院校在校生人数（ ）。", "src": "2024广东省考真题 第72题", "hit": false, "ans": "B", "opts": ["A.小于400万", "B.在400万到500万之间", "C.在500万到600万之间", "D.大于600万"], "solve": "广东在校生 **65万** 占全国 **七分之一**，全国 = 65×7 = **455万**，落在 400万~500万 之间 → ==B==", "analysis": "- **体系定位**：资料分析 → 比重（清单原名 **「比重·由比重反求量」**）｜ 体系位置：上位「比重·现期比重（部分＝整体×比重）」→ 本题「**由比重反求量（整体＝部分÷比重）**」→ 下级变式「已知部分与整体求比重、已知整体与比重求部分」\n- **识别信号**：材料只给「某地**占全国**几分之一 / 百分之几」，题目却问「全国 / 整体**是多少**」→ 立即调「**由比重反求量**」；**选项全是区间（量级界）＝ 只估量级、不动笔**（看到区间先定档，别去精确算）\n- **本质**：把一个**局部量**按它在整体中的**份额**「还原」成**整体量**；内核就是「部分 ÷ 比重」，方向别搞反——除以小于 1 的比重，结果必然**大于**部分量\n- **通式**：`整体量 = 部分量 ÷ 比重`；分数比重直接**倒乘**：`65 ÷ (1/7) = 65 × **7**`。必背特数：`1/7=14.3%`、`1/6=16.7%`、`1/8=12.5%`\n- **易混·易错链**：最像「比重·现期比重（部分＝整体×比重）」——先认问的是**整体**还是**部分**，问整体就**除**、问部分就**乘**；常见撞坑：①把「占七分之一」的乘除方向搞反，②被区间选项诱导去**精确计算**（选项全区间时量级即够）", "img": ""}]}]}, {"name": "比重比较", "star": false, "children": [{"name": "同一整体下占比比大小＝直接比较部分量（分子），无需算百分数；跨整体或口径不同需先求比重（部分/整体）再比", "star": false}]}]}, {"name": "平均数与倍数", "star": false, "children": [{"name": "平均数", "star": false, "children": [{"name": "现期平均数：平均数=总量/份数", "star": false, "examples": [{"q": "材料（2024年末广东省各类体育场地·部分，数量/面积）：田径场地1.64万个/8603.93万㎡；游泳场地0.78万个/849.25万㎡；冰雪运动场地33个/13.16万㎡；健身房0.97万个/505.67万㎡。问：2024年末，广东省下列运动场地单位面积排序正确的是（　　）。", "src": "2026广东省考真题 第84题", "hit": false, "ans": "D", "opts": ["A.冰雪运动场地>田径场地>游泳场地>健身房", "B.田径场地>冰雪运动场地>健身房>游泳场地", "C.田径场地>游泳场地>健身房>冰雪运动场地", "D.田径场地>冰雪运动场地>游泳场地>健身房"], "solve": "单位面积＝面积÷数量：田径8603.93/1.64≈5246＞冰雪13.16/0.0033(33个)≈3988＞游泳849.25/0.78≈1089＞健身505.67/0.97≈521 → ==田径>冰雪>游泳>健身==。", "analysis": "**识别信号**：问「单位面积 / 人均 / 户均 / 单位产值」的排序或最高最低；选项是几条排序链。\n**核心规律**：平均数＝总量÷份数（本题「单位面积」＝面积÷数量）（判分点并入）；凡问「单位 X」一律总量÷数量，别与总量排序混。打法：单位面积＝面积÷数量；比较题用**首数法/一位有效数字**分档，按选项**逐名两两比较、逐个排除**（先定头名 → 再定相邻项）。\n**易混·易错链**：最像＝**总量排序**（问「面积/总量最大」直接比原值）；怎么分：「单位 X／均」＝总量÷数量，「总量最大」＝比原值本身。撞坑链：把「面积总量大」当「单位面积大」；冰雪数量「33 个」不换算成万个（量级差 10⁴）直接除；把 7 类场地全算一遍超时。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/zl/1-8571dc445b.jpg"}, {"q": "2021-2025年，中国移动游戏市场年均实际销售收入约比2020年多多少亿元？", "src": "26年省考34季 第82题", "hit": true, "ans": "A", "opts": ["A.185", "B.197", "C.211", "D.223"], "solve": "选项全在**百亿区间（185~223）**，只算「**5年均值 − 2020年值**」到首两位即可定案 → ==A（185）==。", "analysis": "- 体系定位：资料分析 → 平均数与倍数 → 单元**「平均数·现期平均数」**；上位＝平均数主概念，本题＝**多期均值与单期基值作差**，下级变式＝「平均数·平均数增长率」（问均值同比变化百分之几）。\n- 识别信号：题干出现**「年均…比…多/少多少」**→ 先求均值再作差；出现**「2021-2025」连续n年**→ 立刻警觉分母是**区间年数**。\n- 本质：内核＝「**先平均、再作差**」两步复合，平均数 = 总和÷份数，份数必须与区间年份对齐。\n- 通式：`年均值 = Σ各年值 ÷ 年数`；`差值 = 年均值 − 对比基值`；区间「A-B年」含端点时年数 = B−A+1。\n- 易混·易错链：最像「增长·年均增长量」——后者是 `(末期−初期)/间隔年数`（是**差/年数**），本题是「**均值−基值**」；撞坑链：①分母年数差1 → ②漏抄某年 → ③把单年当均值。", "img": "https://alibbxtbox.oss-cn-guangzhou.aliyuncs.com/mm5/zl/4-a2781b48b5.png"}, {"q": "表中所列省市中，2024年12月包装专用设备产量高于前11个月平均水平的有多少个？", "src": "26年省考35季 第79题", "hit": false, "ans": "B", "opts": ["A.6", "B.7", "C.8", "D.9"], "solve": "条件「12 月 > 前 11 月均」⟺ `12×12月 > 1-12月`（即 12 月 > 月均）；逐省比大小，命中 广东/江苏/上海/山东/广西/安徽/浙江 共 **7** 个。", "analysis": "- 体系定位：资料分析 → 平均数与倍数 → 平均数（清单原名「平均数」）｜上位：现期平均数=总量/份数 → 本题：单期值与月均比较（计数）→ 下级变式：基期平均、平均数增长率、平均数比较\n- 识别信号：看到「某期…高于/低于…平均水平的有多少个」→ 比\"该期值 vs 均/期数\"，用乘法等价式避免逐项除法\n- 本质：考「平均数比较的等价化简」——`12月 vs (总量−12月)/11` ⟺ `12月>总量/12`，比大小即得（判分点＝化简对、计数准）\n- 通式：`单期值>平均` ⟺ `期数×单期值>总量`；同类判别条件：看到\"高于平均水平的个数\"就套此式逐个比大小\n- 易混·易错链：与「求和/占比」混——此处只比大小不求和；撞坑链：硬算\"前 11 月均\"逐项除、漏比或多比一项", "img": "data:image/png;base64,"}, {"q": "2025年10月，中国下列哪一类镁产品出口单价最高？", "src": "26年省考35季 第87题", "hit": false, "ans": "C", "opts": ["A.镁合金", "B.镁粉", "C.锻轧镁", "D.镁制品"], "solve": "单价=金额÷量，只比 4 项：锻轧镁 `69/0.01`=**6900** 最大（镁制品 `347/0.08`≈4338 次之）→ 锻轧镁。", "analysis": "- 体系定位：资料分析 → 平均数与倍数 → 平均数（清单原名「平均数」）｜上位：平均数=总量/份数 → 本题：单价=金额/量 的极大值比较 → 下级变式：基期平均、平均数增长率\n- 识别信号：看到「单价/单位面积/人均…最高/最低」→ 现期平均数，取 金额÷量，只算选项涉及的几项\n- 本质：考「现期平均数（单价）的比较」——单价=金额/量；比大小不必算全表（判分点＝口径对、分母是量不是金额）\n- 通式：`单价=金额/量`；比大小可交叉相乘 `金额₁×量₂ vs 金额₂×量₁` 免除法；同类判别条件：看到\"单价/均值最高\"就套此式\n- 易混·易错链：与「总量比较」混（金额大≠单价高，须除以量）；撞坑链：10 月列与 1-10 月列混用、量单位看错", "img": "data:image/jpeg;base64,"}]}, {"name": "基期平均数：基期平均=[A/(1+a)]÷[B/(1+b)]，A 为总量、a 为其增速，B 为份数、b 为其增速", "star": false}, {"name": "平均数增长率：(a−b)/(1+b)，a=总量增速、b=份数增速（与比重差区分，此处÷(1+b)）", "star": false, "examples": [{"q": "2025年1-10月，中国下列各类镁产品出口单价同比降幅最大的是：", "src": "26年省考35季 第89题", "hit": false, "ans": "B", "opts": ["A.镁合金", "B.镁废碎料", "C.锻轧镁", "D.镁制品"], "solve": "单价同比=`(a−b)/(1+b)`（a=金额增速、b=量增速）；镁废碎料 `(71.8−110.9)/2.109`≈**−18.5%**，降幅最大。", "analysis": "- 体系定位：资料分析 → 平均数与倍数 → 平均数（清单原名「平均数增长率」）｜上位：平均数增长率=(a−b)/(1+b) → 本题：单价同比降幅比较 → 下级变式：基期平均、平均数增长量\n- 识别信号：看到「单价/人均…同比（升/降）」→ 先定 a=金额(总量)增速、b=量(份数)增速，套 `(a−b)/(1+b)`\n- 本质：考「平均数增长率（单价增速）」——单价=金额/量，其同比不直接看金额或量，而看二者增速之差（判分点＝a、b 不搞反）\n- 通式：`单价同比=(a−b)/(1+b)`（a=金额增速、b=量增速）；同类判别条件：看到\"单价同比升降最大\"就套此式，先看 a−b 定方向\n- 易混·易错链：与「比重差 A/B×(a−b)/(1+a)」混——平均数增长率 ÷(1+b)、只与增速有关；撞坑链：a、b 对调致方向相反", "img": "data:image/jpeg;base64,"}]}, {"name": "平均数增长量：现期平均−基期平均=现期平均×(a−b)/(1+a)", "star": false}]}, {"name": "倍数", "star": false, "children": [{"name": "是几倍：A/B（\"是\"含基数）；\"比…多几倍\"则=A/B−1", "star": false, "examples": [{"q": "材料：2021年，各地区各部门全面落实党中央、国务院关于实现数字乡村发展战略的决策部署，积极引入社会资本投资建数字乡村。2021年全国用于县域农业农村信息化建设的社会资本投入为954.6亿元，县均社会资本投入3588.8万元、乡村人均社会资本投入135.2元，分别比上年增长17.2%和24.0%。分区域看，东部地区社会资本投入562.4亿元，占全国社会资本投入58.9%；中部地区社会资本投入193.8亿元；西部地区社会资本投入198.4亿元。问：2021年，东部地区县域农业农村信息化建设社会资本投入约是中、西部地区之和的（ ）倍。", "src": "2024广东省考真题 第88题", "hit": false, "ans": "A", "opts": ["A.1.43", "B.1.64", "C.1.80", "D.1.95"], "solve": "东部 **562.4亿** ÷（中193.8＋西198.4＝**392.2亿**）≈ **1.43** → ==A==", "analysis": "- **体系定位**：资料分析 → 平均数与倍数（清单原名 **「倍数·是几倍」**）｜ 体系位置：上位「平均数」→ 本题「**倍数（A 是 B 的几倍）**」→ 下级变式「多几倍(A/B−1)、基期倍数」\n- **识别信号**：题干出现「**A 是 B 的（约）几倍**」→ 直接 `A/B`；选项为密集小数值 → 保留**两三位有效数字**估算\n- **本质**：两个**同单位量**的**比值**（可>1）；内核＝「是几倍」用**除法**，且分母是**题目指定的组合量**（本题「中+西之和」）\n- **通式**：`倍数 = A/B`；「是…的几倍」`=A/B`（含基数），「比…多几倍」`=A/B−1`\n- **易混·易错链**：与「比重」最像——比重是部分/整体（≤1 或百分数），倍数可任意大；常见撞坑：①**分母漏加**（只除中部或西部），②把「占比 58.9%」当成倍数使用", "img": ""}]}, {"name": "多几倍：(A−B)/B=A/B−1", "star": false}, {"name": "基期倍数：(A/B)×(1+b)/(1+a)", "star": false}]}]}, {"name": "百分点与结构", "star": false, "children": [{"name": "百分点", "star": false, "children": [{"name": "定义与计算：百分点=两个百分数直接相减，不带\"率\"", "star": false}, {"name": "与百分数区分：比率之差用\"百分点\"；量的变化幅度才用\"%\"", "star": false}, {"name": "比重/利润率变化：直接用两期百分比相减，结果单位为百分点", "star": false}]}, {"name": "结构", "star": false, "children": [{"name": "贡献率：贡献率=部分增长量/整体增长量", "star": false}, {"name": "拉动增长：拉动增长率=部分增长量/整体基期量（百分点）", "star": false}]}]}, {"name": "其他综合", "star": false, "children": [{"name": "其他", "star": false, "children": [{"name": "贸易差额：顺差=出口−进口（>0）；逆差<0，取绝对值叙述", "star": false}, {"name": "单位与量级：先统一单位与量级再计算，注意 1 亿=10000 万", "star": false}, {"name": "综合判断（多选一）：逐项验证，先算易算项，警惕\"均\"\"都\"\"逐年\"等绝对表述", "star": false}]}, {"name": "综合", "star": false, "children": [{"name": "能够推出判断：逐项验证、先算易算项；「能够推出」必须由材料数据直接算出，警惕均/都/全部/逐年等绝对表述与时间、单位口径", "star": false, "examples": [{"q": "材料：2021年，各地区各部门全面落实党中央、国务院关于实现数字乡村发展战略的决策部署，积极引入社会资本投资建数字乡村。2021年全国用于县域农业农村信息化建设的社会资本投入为954.6亿元，县均社会资本投入3588.8万元、乡村人均社会资本投入135.2元，分别比上年增长17.2%和24.0%。分区域看，东部地区社会资本投入562.4亿元，占全国社会资本投入58.9%；中部地区社会资本投入193.8亿元；西部地区社会资本投入198.4亿元。问：根据资料，关于县域农业农村信息化建设，以下说法正确的是（ ）。", "src": "2024广东省考真题 第90题", "hit": false, "ans": "D", "opts": ["A.2019年，西部地区乡村人均社会资本投入低于中部地区", "B.2020年，东部地区县均社会资本投入同比增量高于中部地区", "C.2019~2021年，东部地区乡村人均社会资本投入年均增长率高于中部和西部地区", "D.2019~2021年，中部地区县均社会资本投入增速高于全国县均社会资本投入增速"], "solve": "查图1县均——中部 `1150.2→2272.0`(+**97.5%**) ＞ 全国 `2054.6→3588.8`(+**74.7%**) → 中部增速更高 → ==D==", "analysis": "- **体系定位**：资料分析 → 其他综合（清单原名 **「其他综合·综合」**）｜ 体系位置：上位「单一考点(增长/倍数/比重)」→ 本题「**综合分析判断（多考点横向核对）**」→ 下级变式「多选项数据核对 / 排序题」\n- **识别信号**：题干「根据资料，下列说法**正确/错误的是**」→ 综合分析题；四个选项各考一点（时间×区域×指标）→ **先易后难，算到能定真假就停**\n- **本质**：考「**定位取数 ＋ 多考点速判**」的复合能力；内核＝把每个选项翻译成「**查哪张图、哪一行、比什么**」\n- **通式**：无固定式；按「**读选项 → 定图表/指标 → 单点速判**」流程逐项排除：增速比用 `末期/初期−1`，增量比用 `末期−初期`\n- **易混·易错链**：最像「单点计算题」——综合题的解法价值在**排除**，能证伪即淘汰；常见撞坑：①**增速与增量混用**（B 比增量、D 比增速），②把「年均增长率」当成普通总增长率，③**跨图取错行**（县均在图1、乡村人均在图2）", "img": ""}, {"q": "能够从上述材料中推出的是：", "src": "26年省考35季 第75题", "hit": false, "ans": "D", "opts": ["A.2025年1-5月，北京市平均每月接待外国入境游客量约为35万人次", "B.2025年6月，北京市接待外国入境游客量比中国香港多10倍以上", "C.2025年1-6月，北京市接待美国入境游客量占入境游客总量的比重高于上年同期", "D.2024年1-6月，北京市接待中国澳门入境游客量不到1万人次"], "solve": "逐项筛——A(月均 32.6 万≠35 万)、B(10.03 倍＝只多 9 倍)、C(材料无「美国」分项) 全排除；D 澳门基期 `22248/(1+143.4%)`≈**0.91 万**<1 万，唯一成立。", "analysis": "- 体系定位：资料分析 → 其他综合 → 综合（清单原名「综合」）｜上位：综合分析题 → 本题：多选项逐一验证 → 下级变式：能推出／不能推出／求正确项\n- 识别信号：看到「能够从材料中推出的是／不能推出的是」→ 逐项验证、先算易算项，警惕「均／都／逐年／以上」\n- 本质：考「选项真伪的快速筛选」——比的是定位与口径，不是精算（判分点＝口径对得上）\n- 通式：能推出＝必须由材料数据直接算出；同类判别条件：看到选项含**材料未出现的主体**（如\"美国\"）→ 判无据排除；看到\"多 n 倍以上\"→ 算 现期/基期 与 n+1 比\n- 易混·易错链：与「求值计算」混（推断题只判真伪、不需求精确值）；撞坑链：把\"多 10 倍\"当\"是 10 倍\"（差 1 倍）→ B 误选", "img": "data:image/png;base64,"}, {"q": "能够从上述材料中推出的是：", "src": "26年省考35季 第90题", "hit": false, "ans": "C", "opts": ["A.2025年10月，中国镁锭出口量与出口金额均同比下降", "B.2025年1-10月，表格所列中国各类镁产品中出口单价高于上年同期的有1类", "C.2025年10月，表格所列中国各类镁产品中出口量占同年1-10月出口量的比重超过一成的有2类", "D.2024年1-10月，中国各类镁产品累计出口总金额约为11亿元"], "solve": "逐项验证——A(无 10 月分品类同比，不可推)、B(六类单价 a−b 全负，实为 0 类)、D(应为\"亿美元\"非\"亿元\")；C 中 `10月量/1-10月量`>10% 的恰是 镁合金 11.2%、镁制品 14.3% 共 **2 类**。", "analysis": "- 体系定位：资料分析 → 其他综合 → 综合（清单原名「综合」）｜上位：综合分析题 → 本题：多选项逐一验证 → 下级变式：能推出/不能推出/求正确项\n- 识别信号：看到「能够从材料中推出的是」→ 逐项验证、先算易算项，警惕单位(元/美元)、时间(10月/1-10月)、口径陷阱\n- 本质：考「选项真伪的快速筛选」——定位与口径判断优先于精算（判分点＝单位/区间/口径对得上）\n- 通式：能推出＝必须由材料直接算出；同类判别条件：看到选项含**材料未给的维度/单位不符**（如\"10 月分品类同比\"\"亿元\"）→ 直接排除\n- 易混·易错链：与「求值计算」混（推断只判真伪）；撞坑链：把 1-10 月同比当 10 月用、万元与亿元混、a、b 对调", "img": "data:image/jpeg;base64,"}]}]}]}]}}};
